-- 0283 miradores_pdf (inventario_miradores_pdf) — borra placeholder + entidades + puntuaciones reales
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26055','mirador','Alto del Teso rural de Corporales','6.1/10 Sencilla visual de llanura cerealista de la Rioja Alta occidental, campos despejados de labranza e idónea observación astronómica por su baja luminosidad nocturna. Cómo llegar: Elevación natural accesible por caminos agropecuarios en el límite del término municipal. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26056','mirador','Mirador del Castillo de los Velasco y Río Tirón','7.7/10 Premida estampa del cauce fluvial regulado, azudes, huertas tradicionales y la imponente e íntegra silueta de la fortaleza medieval del siglo XIV. Cómo llegar: Paseo e hito peatonal junto al puente de piedra, en pleno eje monumental urbano. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26057','mirador','Mirador de la Sierra de Moncalvillo','7.5/10 Vista aérea del Valle del Ebro riojano, densos pinares, robledales de ladera, rampas calizas y horizontes despejados aptos para astrofotografía. Cómo llegar: Zona del cortado natural accesible por la pista forestal que sube hacia las antenas de Moncalvillo. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26058','mirador','Mirador del Yacimiento de la Virgen del Campo','8.5/10 Vista del abrupto cañón del río Cidacos, laderas erosionadas calcáreas, reproducciones a tamaño real de dinosaurios e importantes huellas fósiles (icnitas). Cómo llegar: Plataforma de observación de madera con paneles informativos en la ruta paleoantropológica, carretera LR-115. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26059','mirador','Mirador de la Iglesia de San Martín y del Teso','7.1/10 Vista de las fértiles terrazas de frutales y viñedos de la Rioja Media, el área metropolitana de la capital y el cordal montañoso meridional. Cómo llegar: Atrio elevado del monumental templo gótico, en la cota más alta del núcleo urbano. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26060','mirador','Mirador de San Millán y Valle del Cárdenas','7.3/10 Vista del valle encajonado de San Millán, pastizales de montaña, laderas cubiertas de bosque autóctono y el perfil rural de San Andrés. Cómo llegar: Camino rural elevado al oeste de la población, en las estribaciones de la Demanda. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26061','mirador','Mirador de la Cruz de la Demanda y Valdezcaray','9.2/10 Impresionante e ininterrumpida panorámica alpina del Valle del Oja, densos hayedos, circos glaciares, la estación invernal y cumbres del pico San Lorenzo. Cómo llegar: Collado de montaña a más de 1.800 metros de altitud, accesible por carretera asfaltada de alta montaña. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26062','mirador','Mirador de los Montes Obarenes y la Hoz','7.6/10 Espectacular corte calizo de la garganta de Foncea, peñas escarpadas donde anidan grandes rapaces, pastizales de altura e idónea observación astronómica nocturna. Cómo llegar: Borde del desfiladero natural septentrional, accesible por senderos locales homologados. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26063','mirador','Alto del Teso de Villaseca','6.6/10 Vista diáfana de los campos cerealistas y viñedos del extremo noroccidental riojano, límites con Burgos y horizontes despejados sin postes industriales. Cómo llegar: Elevación natural al norte del término municipal, accesible por pistas agropecuarias. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26064','mirador','Mirador de la Ermita del Cristo y del Ebro','7.8/10 Amplia visual del cauce ancho del río Ebro, los viñedos de grandes bodegas centenarias de Rioja Alta y el perfil de la Sierra de Cantabria. Cómo llegar: Explanada acondicionada de la ermita barroca al norte de la villa, dotada de accesos adaptados. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26065','mirador','Mirador de las Peñas de Herrera','7.3/10 Perspectiva de los Montes Obarenes orientales, pequeños valles forestales cubiertos de encina y roble, y tierras de labor de la pedanía de Castilseco. Cómo llegar: Cota rocosa elevada al norte del pueblo, transitable por senderos de montaña a pie. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26066','mirador','Mirador del Valle de Ocón Bajo','6.7/10 Vista de la llanura aluvial de la Rioja Media oriental, olivares tradicionales, campos de almendros e idóneo punto para la fotografía de puestas de sol limpias. Cómo llegar: Zona elevada de las eras históricas perimetrales, con fácil acceso rodado. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26067','mirador','Mirador de la Ermita de la Virgen de la Cuesta','7.9/10 Paisaje montañoso alpino del Camero Nuevo, pastizales rústicos de altura, densos acebedos forestales y dehesas boyales con nítidos cielos nocturnos Starlight. Cómo llegar: Promontorio elevado coronado por la ermita, accesible mediante pista transitable desde el pueblo. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26068','mirador','Mirador de San Cristóbal y del Ebro','7.5/10 Magnífica perspectiva del gran meandro del río Ebro, huertas de ribera, mar de viñedos circundantes de Haro y el perfil calizo de la Sierra de Toloño. Cómo llegar: Cerro testigo acondicionado con barandillas y paneles explicativos junto a la ermita de San Cristóbal. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26069','mirador','Mirador de la Ermita de Carrasquedo','7.1/10 Vista de la densa masa forestal de roble rebollo, campos cerealistas fronterizos con Burgos y el constante paso de los peregrinos del Camino de Santiago francés. Cómo llegar: Entorno natural ajardinado de la ermita, accesible por pista asfaltada a dos kilómetros de la localidad. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26070','mirador','Mirador del Balneario y Sierra de la Hez','7.4/10 Perspectiva sobre la cuenca del Cidacos bajo, olivares tradicionales riojanos, almendros, el entorno termal histórico y horizontes montañosos limpios de postes industriales. Cómo llegar: Cornisa natural alta situada junto a las instalaciones hoteleras y sanitarias del balneario. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26071','mirador','Mirador de los Riscos de Bilibio y del Ebro','8.8/10 Extraordinaria e icónica panorámica de la entrada del Ebro en La Rioja a través de las Conchas de Haro, viñedos singulares del Barrio de la Estación y ermita señera. Cómo llegar: Ermita de San Felices en la cima de los riscos calcáreos, provista de escaleras esculpidas en roca y barandillas. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26072','mirador','Mirador de la Peña del Salvador','7.7/10 Impresionante vista del valle del Cidacos medio, los característicos escarpes arcillosos rojizos erosionados, huertas tradicionales y las ruinas del antiguo castillo medieval. Cómo llegar: Cima caliza que domina el casco urbano por el sector norte, accesible por sendero peatonal. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26074','mirador','Mirador de la Laguna de Hervías','6.6/10 Vista de la cubeta endorreica natural recuperada, vegetación palustre, avifauna acuática migratoria y la inmensa planicie agrícola circundante. Cómo llegar: Caseta-observatorio acondicionada con paneles informativos en el perímetro del espacio protegido. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26075','mirador','Mirador de los Viñedos del Tuerto','6.8/10 Vista de las terrazas fluviales de cultivo vitivinícola de la Rioja Alta meridional, campos de secano e interesantes puestas de sol limpias de obstáculos visuales. Cómo llegar: Pista agrícola elevada hacia el sur de la población, en el límite con el término de Azofra. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26076','mirador','Mirador del Cerro del Castillo y del Najerilla','6.9/10 Panorámica de la desembocadura del río Tuerto en el Najerilla, fértiles huertas de regadío, viñedos tradicionales de ladera y restos arqueológicos locales. Cómo llegar: Antiguo cerro fortificado que domina la confluencia de los valles fluviales, acceso peatonal. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26078','mirador','Mirador de la Cuesta del Moncalvillo','7.1/10 Vista panorámica de los llanos agrícolas de la Rioja Media, el discurrir del Ebro en la lejanía y las faldas cubiertas de encinar y rebollo. Cómo llegar: Borde del talud calizo meridional, accesible por caminos forestales desde el pueblo. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26079','mirador','Mirador de las Eras Altas','7.0/10 Mar de viñedos de la Rioja Alta central, bodegas tradicionales superficiales y la silueta del monumental templo gótico de San Pedro. Cómo llegar: Zona perimetral elevada al norte del casco urbano, provista de accesos rodados fáciles. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26080','mirador','Mirador del Árbol Fósil y del Río Linares','8.3/10 Espectacular perspectiva geológica, el cañón calcáreo del Linares, icnitas de dinosaurios y el singular yacimiento del tronco de conífera fosilizado del Cretácico. Cómo llegar: Estructura protectora y plataforma acondicionada con paneles informativos en la carretera LR-283. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26081','mirador','Mirador de la Ermita del Cristo','7.6/10 Vista del valle alto del río Leza, laderas escarpadas cubiertas de matorral de jara y pastizales ganaderos alpino-serranos de Cameros. Cómo llegar: Colina que alberga las ruinas del templo, situada al noreste del pueblo con acceso peatonal. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26082','mirador','Mirador de los Corrales de la Majada','8.4/10 Soberbia panorámica de la Sierra de la Demanda, pastizales de altura del Camero Viejo, cañones calcáreos y un cielo nocturno certificado como Reserva Starlight. Cómo llegar: Cota alta del puerto de Sancho Leza, accesible por la carretera LR-250. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26083','mirador','Mirador del Castillo de Jubera','7.7/10 Impresionante corte geológico sobre el cañón del río Jubera, ruinas de la fortaleza medieval, encinares rupícolas y antiguas minas de plomo. Cómo llegar: Cresta rocosa que domina el deshabitado de Jubera, accesible por sendas de montaña. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26084','mirador','Mirador de las Bodegas y Monte El Corvo','6.6/10 Vista periurbana de la comarca de Logroño, viñedos de cultivo intensivo, olivos centenarios y la vega baja del Iregua. Cómo llegar: Zona elevada del barrio de bodegas tradicionales, en el sector sur del casco urbano. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26086','mirador','Mirador de la Ermita de San Bain','7.8/10 Magnífica perspectiva de la cara norte de la Sierra de la Demanda, densos hayedos, robledales y el encajamiento de riachuelos de montaña. Cómo llegar: Promontorio forestal elevado, accesible por pista de tierra apta para senderistas desde el pueblo. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26087','mirador','Mirador del Embalse de Leiva y Río Tirón','6.9/10 Vista de la lámina de agua de la represa, aves acuáticas migratorias, chopera de ribera y el perfil señorial del Castillo-Palacio. Cómo llegar: Corona del muro del embalse, accesible por desvío desde la carretera LR-200. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26089','mirador','Mirador del Monte Cantabria','7.9/10 Extraordinaria vista panorámica de 360 grados de la capital riojana, el curso del río Ebro, viñedos de la planicie y yacimientos arqueológicos romanos. Cómo llegar: Cima de la meseta caliza situada al norte de la ciudad, accesible por pista desde el puente de Piedra. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90932','mirador','Mirador de la Ermita de la Virgen de la Luz','8.6/10 Espectacular entorno del Parque Natural de Sierra de Cebollera, densos bosques de pino silvestre, dehesas de robles y avistamiento de ciervos. Cómo llegar: Claro forestal elevado junto al templo, acceso señalizado por pista desde el núcleo de Lumbreras. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26094','mirador','Alto de San Cristóbal','6.8/10 Vista diáfana del llano cerealista de la Rioja Alta, campos de patatas, viñedos de ladera y la imponente silueta del monte San Lorenzo. Cómo llegar: Colina suave al sur del caserío urbano, accesible por caminos rurales de herradura. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26093','mirador','Mirador del Embalse de Mansilla','8.3/10 Vista de los picos calcáreos de la Demanda central, el gran embalse de agua, el pueblo sumergido emergente en otoño y pinares. Cómo llegar: Apartadero acondicionado con bancos en la carretera LR-113, al borde de la presa. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13009','mirador','Adarve del Castillo de Pilas Bonas','7.3/10 Perspectiva histórica del Campo de Calatrava oriental, la vega del río Azuer, viñedos bajos y los recios muros de la fortaleza del siglo XIII. Cómo llegar: Galería transitable superior de la recuperada fortificación medieval de la Orden de Calatrava. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26095','mirador','Mirador del Cañón del río Tobía y Peña Mata','8.1/10 Imponentes farallones de conglomerados rojizos, nidos de buitres leonados, vegetación rupícola encajonada e idóneo punto de escalada y fotografía de relieve. Cómo llegar: Senda adaptada que arranca desde el pueblo hacia el desfiladero de Peñalba. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26096','mirador','Mirador de las Viñas de Altura','7.1/10 Perspectiva sobre el piedemonte de la Sierra de Moncalvillo, viñedos escalonados en terraza, encinares dispersos y horizontes nítidos de la Rioja Media. Cómo llegar: Pista forestal en el límite sur del término, en la subida a la sierra. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26098','mirador','Mirador de las Icnitas de Peñaportillo','8.2/10 Vista del valle del río Manzanares, laderas de jara y un valioso yacimiento de huellas de dinosaurio con maquetas a tamaño real expuestas. Cómo llegar: Plataforma protegida con paneles informativos en la carretera LR-484, dirección a Enciso. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26099','mirador','Mirador de la Confluencia del Jubera y Leza','7.2/10 Hermosa estampa de la unión de los dos cursos fluviales, amplias huertas de regadío, cañones calizos bajos y abundantes choperas lineales. Cómo llegar: Borde del talud fluvial al este del núcleo urbano, transitable por sendero peatonal. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26100','mirador','Mirador de la Sierra de Ausejo','7.9/10 Paisaje montañoso abrupto de la Rioja Baja, canteras de arcilla abandonadas, brezales altos e idóneo observatorio astronómico sin luz artificial. Cómo llegar: Vértice de montaña accesible por pistas de cortafuegos desde la aldea de Ambas Aguas. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26101','mirador','Mirador de la Ermita del Cerro','7.8/10 Vista de las cumbres desarboladas del Camero Viejo, laderas abancaladas de origen pastoril abandonadas y cielos nocturnos de gran nitidez Starlight. Cómo llegar: Colina exenta coronada por la ermita, accesible por sendero peatonal desde el centro urbano. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26102','mirador','Mirador del Castillo y Alcázar','8.4/10 Espectacular e histórica panorámica del Monasterio de Santa María la Real, los cerros rojizos erosionados, el río Najerilla y el Camino de Santiago. Cómo llegar: Cima del cerro del Castillo que corona la ciudad, accesible por escalinatas peatonales acondicionadas. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26103','mirador','Mirador del Castillo de Nalda y Palomares','8.2/10 Espléndido balcón sobre el Valle del Iregua, huertas tradicionales, las peculiares cuevas de palomares rupestres y las cumbres de Moncalvillo. Cómo llegar: Explanada de la fortaleza medieval excavada y consolidada en la cota más alta del núcleo urbano. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26104','mirador','Mirador de las Minas de Pirita','7.8/10 Singular paisaje minero mundialmente famoso por sus piritas cúbicas perfectas, valles del río Alhama escarpados, matorral mediterráneo de secano y fósiles. Cómo llegar: Entorno de las explotaciones mineras a cielo abierto al sur del núcleo, acceso por pista minera. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26106','mirador','Mirador del Alto de la Serna','7.5/10 Vista del valle medio del Iregua, dehesas ganaderas de roble rebollo, pastizales de Cameros y relieves de roca caliza erosionados. Cómo llegar: Cota natural elevada accesible por pista forestal desde la carretera LR-111. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26107','mirador','Mirador de la Peña del Castillo','8.0/10 Impresionante formación caliza con vistas de la cuenca alta del Iregua, robledales protegidos, el pueblo de Montemediano y picos de Cebollera. Cómo llegar: Aguja rocosa que domina el casco urbano, acondicionada con barandillas y peldaños tallados. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26109','mirador','Mirador del Río Tirón y Ermita de la Concepción','6.7/10 Vista de la ribera del Tirón, campos cerealistas ondulados de la Rioja Alta y la silueta nítida del templo románico exento. Cómo llegar: Explanada del templo religioso, en la margen derecha del cauce fluvial. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26108','mirador','Mirador del Castillo y Molino de Viento','8.0/10 Impresionante vista panorámica de toda la Sierra de Ocón, viñedos, olivares tradicionales y la réplica del histórico molino harinero del siglo XIV. Cómo llegar: Cerro exento en el núcleo de Santa Lucía de Ocón, acondicionado para turismo rural. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26111','mirador','Mirador del Cerro de San Cristóbal y Calados','7.4/10 Vista aérea del viñedo de la Rioja Alta, bodegas centenarias de prestigio, el río Tirón y la Sierra de Cantabria al norte. Cómo llegar: Promontorio calizo sobre el barrio de calados tradicionales, con acceso peatonal señalizado. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26112','mirador','Mirador del Puente de Hierro y Cuevas','8.6/10 Vertiginosa e impresionante vista del cañón del río Albercos, el monumental viaducto de hormigón del siglo XX, las cuevas kársticas y el bosque. Cómo llegar: Plataforma peatonal del puente colgante que une los dos barrios elevados del municipio. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26113','mirador','Mirador del Alto de la Cruz de la Demanda','7.9/10 Extensos pastizales alpinos de crianza ganadera caballar, pinares de repoblación densos, hayedos sombríos y puestas de sol limpias de contaminación. Cómo llegar: Cota máxima del término en la subida al San Lorenzo, accesible por pistas forestales de tierra. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26114','mirador','Mirador del Valle del Najerilla Alto','7.7/10 Vista de las estribaciones forestales de la Demanda, castañares centenarios dispersos, huertas tradicionales de ribera y relieve abrupto de montaña. Cómo llegar: Borde del talud natural accesible por camino vecinal desde el casco urbano. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26115','mirador','Mirador de los Prados de Cameros','7.6/10 Perspectiva de las dehesas de montaña del Camero Nuevo, zonas de matorral bajo micológico, colmenares tradicionales y horizontes nocturnos limpios. Cómo llegar: Camino rural elevado que parte del caserío hacia las laderas forestales superiores. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26117','mirador','Mirador del Ebro y las Huertas de Champiñón','6.4/10 Vista llana del paisaje agrícola de la Rioja Baja, olivares modernos de regadío, cultivos hortícolas e instalaciones de producción micológica industrial. Cómo llegar: Pequeña elevación al norte del término municipal, transitable por pistas agrícolas. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26118','mirador','Mirador de la Ermita de la Virgen del Castillo','7.9/10 Hermosa panorámica del cauce del río Iregua, puentes medievales de piedra, el singular Hórreo de Pradillo restaurado y tupidos bosques de ribera. Cómo llegar: Cerro testigo situado al oeste de la población, accesible mediante sendero escalonado. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26119','mirador','Mirador de la Torre Fuerte y Vía Verde','80/10 Vista del valle del Cidacos, taludes yesosos con huellas de dinosaurio (icnitas), olivares de aceite de Préjano y el torreón defensivo del siglo XV. Cómo llegar: Adarve consolidado de la torre fortificada, en la parte alta del casco histórico. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26120','mirador','Mirador del Castillo de Quel y Cortados','8.2/10 Impresionante e icónica estampa de la fortaleza colgada de un farallón vertical de roca de 100 metros, el valle del Cidacos y frutales. Cómo llegar: Plataforma rocosa superior de la muralla del castillo, acceso peatonal empinado desde el pueblo. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26121','mirador','Mirador de los Chozos de Cameros','7.5/10 Perspectiva de pastizales ganaderos altos del Camero Viejo, antiguos chozos de pastores de piedra, laderas de jara y cielos limpios. Cómo llegar: Cota natural elevada, accesible por pistas agropecuarias desde el núcleo urbano. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26122','mirador','Mirador del Club Náutico y Embalse de González Lacasa','8.2/10 Magnífica vista del gran embalse rodeado de frondosos bosques de pino silvestre y roble, actividades acuáticas de montaña y relieve serrano. Cómo llegar: Terraza adaptada del mirador del club náutico, acceso pavimentado desde la carretera LR-253. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26123','mirador','Alto del Calvario y Viñedos','6.6/10 Vista panorámica del Valle de Ocón occidental, cultivos extensivos de vid, almendros en flor estacionales y horizontes limpios de la meseta. Cómo llegar: Repecho suave al oeste de la población, antiguo emplazamiento de las cruces del calvario. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26124','mirador','Mirador de los Cortados del Leza','7.4/10 Espectacular entrada al cañón del río Leza, profundas laderas calizas erosionadas, huertas tradicionales de ribera y nidos de aves rapaces. Cómo llegar: Cornisa natural acondicionada con barandilla en el borde sur del pueblo, carretera LR-250. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26125','mirador','Mirador de las Vegas de la Pera de Rincón','6.5/10 Vista llana del cauce ancho del Ebro, las renombradas plantaciones de perales con Denominación de Origen protegida y choperas lineales fluviales. Cómo llegar: Camino rural acondicionado junto al dique de contención del río Ebro, al norte del término. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26126','mirador','Mirador del Puente Medieval y Río Jubera','7.7/10 Vista del valle encajonado del río Jubera, el puente de piedra de origen medieval, encinares autóctonos y senderos micológicos de otoño. Cómo llegar: Estructura rocosa elevada próxima al cauce del río, accesible desde la aldea de San Vicente. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26127','mirador','Mirador del Barrio de las Bodegas','7.2/10 Vista aérea del característico conjunto de más de cien calados de bodegas subterráneas, mar de viñedos de la Rioja Alta y llanuras. Cómo llegar: Parte superior del cerro horadado que corona el casco urbano, acceso acondicionado con bancos. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26128','mirador','Mirador de las Murallas y Castillo de Sajazarra','7.6/10 Preciosa panorámica de uno de los pueblos más bonitos de España, rodeado de viñedos, con su impecable fortaleza del siglo XV y murallas medievales. Cómo llegar: Tramo exterior elevado del jardín perimetral del castillo, centro del núcleo histórico. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26129','mirador','Mirador del Barrio de las Bodegas y del Ebro','7.7/10 Espectacular cuna del vino clarete con vistas del meandro del Ebro, el Monasterio de la Estrella, viñedos infinitos y la Sierra de Cantabria. Cómo llegar: Cerro de la parte alta de los calados de bodegas tradicionales, con paneles explicativos. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26130','mirador','Mirador de Suso y Valle de San Millán','8.8/10 Extraordinaria e histórica perspectiva del Monasterio de Yuso, el valle protegido, densos hayedos de la Demanda y la cuna de la lengua castellana. Cómo llegar: Explanada de acceso al Monasterio de Suso, ladera de la montaña con visitas reguladas. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26131','mirador','Alto del Teso de San Miguel','6.6/10 Sencilla panorámica rural de cultivos de secano limítrofes con Burgos, encinares jóvenes dispersos y cielos nocturnos de baja luminosidad. Cómo llegar: Elevación natural al norte del casco urbano, accesible por pistas agropecuarias. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26132','mirador','Mirador del Castillo de San Román','8.1/10 Hermosa visual del Valle del Leza medio, el entramado urbano escalonado de arquitectura serrana de piedra, dehesas de encina y el molino tradicional. Cómo llegar: Cerro del antiguo castillo medieval en la zona más elevada de la villa, acceso a pie. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26139','mirador','Atrio de la Iglesia de San Torcuato','6.3/10 Vista abierta del paisaje cerealista característico de la llanura de Santo Domingo, campos de labranza e hilos de chopos lejanos. Cómo llegar: Plaza pública elevada que precede al acceso de la iglesia del municipio. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26142','mirador','Mirador de la Torre del Homenaje del Castillo','8.5/10 Imponente e icónica atalaya de 360 grados sobre el meandro del río Ebro, el puente medieval, viñedos de la Sonsierra y la Sierra de Cantabria. Cómo llegar: Corona superior de la fortaleza militar rehabilitada, acceso peatonal desde la Plaza Mayor. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26134','mirador','Mirador del Monasterio de Santa María de las Abejas','7.6/10 Vista de las estribaciones forestales de la Sierra de Moncalvillo, encinares maduros, pastizales de media montaña y valles fluviales encajados. Cómo llegar: Entorno natural de las ruinas mudéjares del monasterio, accesible por pista de tierra de la LR-425. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26135','mirador','Mirador de las Cuevas y Barranco del Jubera','7.9/10 Paisaje abrupto de conglomerados rocosos calizos, pozas del río Jubera, buitreras coloniales y senderos mineros tradicionales de montaña. Cómo llegar: Borde del talud natural accesible desde la aldea de Santa Cecilia por pistas forestales. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26136','mirador','Mirador de la Vega del Cidacos','7.2/10 Vista de la cuenca media del río Cidacos, huertas de frutales tradicionales, choperas de producción y el perfil de la sierra de la Peñalmonte. Cómo llegar: Elevación natural sobre la terraza fluvial, accesible por pistas rurales desde el pueblo. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26138','mirador','Mirador del Campanario de la Catedral','8.0/10 Histórica panorámica aérea de la ciudad jacobea, el trazado del Camino de Santiago, la muralla medieval, el río Oja y los campos cerealistas. Cómo llegar: Cuerpo superior exento de la torre barroca de la catedral, acceso regulado con entrada turística. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26140','mirador','Mirador del Valle del Oja Alto','7.5/10 Vista de las laderas de la Sierra de la Demanda noroccidental, frondosos robledales de rebollo, dehesas ganaderas y la Vía Verde del Oja. Cómo llegar: Promontorio natural al sur del núcleo, accesible por pistas desde la LR-111. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26141','mirador','Alto del Teso Ganadero','7.3/10 Perspectiva sobre pequeños valles de montaña formados por arroyos estacionales, matorral mediterráneo de jara y dehesas de pasto vacuno. Cómo llegar: Elevación natural del terreno transitable a pie por pistas forestales al oeste del término. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26143','mirador','Mirador de las Neveras de Moncalvillo','7.8/10 Espectacular patrimonio etnográfico industrial de pozos de nieve del siglo XVI, densos pinares de montaña, hayedos y vistas de toda la Rioja Media. Cómo llegar: Paraje acondicionado con paneles en las cumbres de Moncalvillo, acceso por pista forestal. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26144','mirador','Mirador del Chopo Centenario y del Iregua','7.4/10 Vista de las laderas boscosas de la sierra, campos de cultivo tradicionales, huertas de ribera y parajes idóneos para astrofotografía nocturna. Cómo llegar: Paraje de la Ermita de la Hermedaña, accesible por sendas agropecuarias de montaña. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26145','mirador','Alto de la Cuesta de las Bodegas','7.2/10 Vista panorámica de viñedos de altura, los calados tradicionales de bodegas subterráneas, encinares jóvenes y cielos despejados mesetarios. Cómo llegar: Cerro horadado por las bodegas en el sector norte del casco urbano. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26146','mirador','Mirador del Cañón del Leza y Huellas de Dinosaurio','8.4/10 Impresionante e imponente tajo calcáreo de 200 metros de profundidad, colonia de buitres leonados, y yacimientos de icnitas fosilizadas protegidos. Cómo llegar: Plataforma volada con barandilla y paneles en la carretera LR-250, a tres kilómetros de Soto. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26147','mirador','Mirador del Embalse de Terroba y Río Leza','7.6/10 Vista de las aguas del nuevo embalse de montaña, laderas de jara y matorral de Cameros, repoblaciones de pino y avifauna. Cómo llegar: Corona e inmediaciones de la presa hidroeléctrica, desvío señalizado desde la LR-250. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26148','mirador','Mirador del Río Tirón y Bodegas de Tirgo','6.8/10 Vista de la vega del Tirón, sotos de álamos y chopos, cultivos de vid y tradicionales chimeneas de calados subterráneos excavados. Cómo llegar: Parte superior del repecho de las bodegas tradicionales, periferia del casco urbano. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26149','mirador','Mirador de los Conglomerados de Tobía','8.2/10 Espectaculares e imponentes moles de roca caliza rojiza redondeadas por la erosión, densos hayedos de ladera y nidos de grandes rapaces rupícolas. Cómo llegar: Senda de senderismo señalizada que parte del pueblo hacia el corazón del macizo geológico. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26150','mirador','Alto de la Cuesta del Tirón','6.4/10 Panorámica rural de la llanura occidental de la Rioja Alta, campos cerealistas lindando con Burgos, choperas lineales del río Tirón y horizontes agrícolas limpios. Cómo llegar: Promontorio suave al norte del núcleo, accesible por pistas agropecuarias desde el pueblo. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26153','mirador','Mirador del Páramo de San Juan','7.8/10 Espectacular relieve alpino del Camero Viejo, valles deshabitados de profunda erosión, matorral de jara, encinas jóvenes y un cielo nocturno libre de contaminación lumínica. Cómo llegar: Borde calizo superior al oeste del pueblo, accesible mediante sendas ganaderas a pie. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26151','mirador','Mirador de la Ermita de San Antón','8.4/10 Espectacular e imponente vista del cauce encajado del río Iregua, puentes históricos, el entramado urbano medieval escalonado y los farallones de rocas calizas. Cómo llegar: Explanada acondicionada con barandilla junto a la ermita, acceso señalizado por sendero desde el casco urbano. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26152','mirador','Atrio de la Iglesia de la Asunción','6.1/10 Vista diáfana del Valle del Tuerto, tierras de cultivo de cereal en secano, pequeños viñedos periféricos y puestas de sol nítidas. Cómo llegar: Plaza pública sobreelevada que circunda el ábside del templo parroquial central. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26154','mirador','Mirador del Ebro y Torre de los Condes','7.1/10 Vista de la desembocadura del río Najerilla en el Ebro, frondosos sotos fluviales de ribera, extensos viñedos y la silueta fortificada medieval. Cómo llegar: Elevación natural próxima a la autopista AP-68 y el palacio fortificado de los Condes. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26155','mirador','Alto del Cerro de San Juan','6.7/10 Panorámica sobre la comarca de Haro noroccidental, relieves ondulados de cultivo cerealista, lomas arcillosas y cielos limpios óptimos para astrofotografía. Cómo llegar: Cota natural elevada al norte de la población, junto a las eras tradicionales. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26157','mirador','Entorno de la Ermita de Santa María de los Arcos','6.8/10 Vista de la vega baja del Najerilla, plantaciones hortícolas locales, la silueta barroca del pueblo y el entorno arqueológico de la antigua Tritium Magallum. Cómo llegar: Explanada exterior del histórico templo paleocristiano del siglo V, en la entrada oeste. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26158','mirador','Mirador de las Viñas de Altura','7.2/10 Amplia e infinita perspectiva del mar de vides de la Rioja Baja, campos de almendros, el somontano de la Sierra de la Hez y horizontes limpios. Cómo llegar: Paraje acondicionado en las pistas que suben hacia el monte Yerga, al sur del término. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26160','mirador','Mirador del Camino de las Bodegas','7.0/10 Panorámica de los viñedos centrales de la Rioja Alta, terrazas fluviales del Najerilla, huertas tradicionales e hileras de bodegas subterráneas con calados. Cómo llegar: Punto alto acondicionado en los caminos rurales del norte del casco urbano. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26161','mirador','Alto del Teso de San Cristóbal','7.5/10 Vista montañosa del sistema Ibérico riojano-soriano, laderas escarparadas cubiertas de matorral bajo mediterráneo de jara y encinas, e idóneo punto Starlight nocturno. Cómo llegar: Cota máxima del cerro que flanquea la localidad, accesible por pistas forestales de tierra. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26162','mirador','Mirador de la Dehesa y el Acebal','8.3/10 Impresionante vista alpina de la Demanda meridional, densos bosques mixtos de hayas y acebos centenarios, pastizales de alta montaña y picos escarpados. Cómo llegar: Plataforma natural en el sendero del Acebal de Valgañón, acceso por pistas de montaña. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26163','mirador','Mirador de las Esculturas del Kilómetro del Arte','6.9/10 Interesante contraste entre instalaciones artísticas modernas al aire libre, viñedos, la traza del Camino de Santiago francés y la llanura de Logroño lejana. Cómo llegar: Sendero peatonal adaptado en el cerro de San Cristóbal, al norte del pueblo. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26164','mirador','Mirador de la Ermita de Villavelayo','8.4/10 Soberbia panorámica de la Sierra de la Demanda occidental, valles profundos del río Urbión, densos pinares forestales y cielos nocturnos de pureza excepcional. Cómo llegar: Entorno rocoso elevado de la ermita, transitable por pistas rurales desde la carretera LR-333. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26165','mirador','Mirador de los Peñucos','8.5/10 Magníficos e imponentes conglomerados calizos verticales que encajonan el río Iregua, cuevas colgadas rupestres (San Esteban) y nidos de rapaces protegidas. Cómo llegar: Plataforma con barandilla sobre el escarpe rocoso, accesible por pista señalizada desde el pueblo. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26168','mirador','Mirador del cerro de San Cristóbal','6.7/10 Vista periurbana de la vega baja del Iregua, la capital provincial cercana, huertas tradicionales de regadío y pequeños barrios de bodegas locales. Cómo llegar: Cima suave del cerro acondicionado con accesos urbanos peatonales en la periferia del núcleo. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26166','mirador','Mirador de la Ermita de la Concepción','7.6/10 Extraordinaria vista del mar de viñedos de la comarca de Haro, el desfiladero de las Conchas de Haro al fondo y la Sierra de Cantabria. Cómo llegar: Explanada de la ermita al norte del casco urbano, accesible por pistas entre viñas. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26167','mirador','Mirador del Río Oja y la Torre Fuerte','6.6/10 Vista de la vega del río Oja, cultivos extensivos cerealistas, plantaciones de patata de siembra y la silueta barroca de la torre medieval. Cómo llegar: Elevación natural junto a los restos de la fortaleza defensiva en la cota urbana. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26172','mirador','Alto de la Cuesta de San Jorge','6.5/10 Panorámica rural del pequeño Valle del Alto Najerilla, pastizales de media montaña, encinares dispersos y horizontes limpios de obstáculos. Cómo llegar: Camino rural elevado al este de la localidad, transitable a pie por pistas de tierra. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26175','mirador','Mirador del Embalse de Mansilla','83/10 Vista de la masa de agua rodeada de montañas alpinas de la Demanda, las compuertas de la represa, densos hayedos e idóneo punto para astrofotografía. Cómo llegar: Zona perimetral alta con estacionamiento en los accesos de la represa, LR-113. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26176','mirador','Mirador de San Lorenzo','7.4/10 Magnífica visual del valle alto del río Tobía, las escarpaduras de los Montes de Ayago, hayedos de ladera y el monasterio de San Millán lejano. Cómo llegar: Cornisa natural accesible por pistas forestales al sur del núcleo urbano. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26177','mirador','Mirador del Parque Natural de Sierra de Cebollera','8.8/10 Espectacular e infinita panorámica de valles glaciares, densos pinares silvestres, hayedos, cascadas de montaña (Puente Ra) y cumbres alpinas del sistema Ibérico. Cómo llegar: Plataforma adaptada en el entorno del Centro de Interpretación del Parque Natural de Sierra de Cebollera. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26178','mirador','Mirador de los Siete Ríos y Cuenca del Urbión','8.6/10 Impresionante panorama de los valles de montaña del Alto Najerilla, cumbres escarpadas, arquitectura de piedra indiana y cielos nocturnos catalogados Starlight. Cómo llegar: Cota rocosa acondicionada al norte del caserío, acceso señalizado por sendero local peatonal. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26179','mirador','Mirador del Alto de la Moheda','8.5/10 Soberbia visual alpina a más de 1100 metros de altitud, pastizales de montaña de ganado trashumante, brezales densos y gargantas rocosas de erosión fluvial. Cómo llegar: Cresta de la plataforma montañosa accesible por pistas forestales desde la LR-333. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26180','mirador','Alto de la Ermita de San Andrés','6.6/10 Vista diáfana de la llanura de la Rioja Alta, viñedos, cultivos de cereal, bodegas con calados históricos y horizontes limpios sin postes industriales. Cómo llegar: Promontorio suave junto al cementerio municipal, accesible por caminos desde el pueblo. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26181','mirador','Mirador del Valle del río Manzanares','7.6/10 Perspectiva del cañón abrupto del Manzanares riojano, escarpes calizos de Cameros, repoblaciones forestales y cielos limpios óptimos para la observación de astros. Cómo llegar: Borde del talud geográfico al sur del pequeño núcleo, accesible por sendas agropecuarias. 📍 Provincia: La Rioja.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26183','mirador','Alto de la Ermita de San Juan y Valle del Oja','7.9/10 Excelente visual de la cabecera del Valle del Oja, el somontano de la Sierra de la Demanda, praderas alpinas de Ezcaray y bosques mixtos forestales. Cómo llegar: Cerro exento que alberga el pequeño templo románico, transitable a pie desde el casco urbano. ¡COMUNIDAD AUTÓNOMA DE LA RIOJA COMPLETADA AL 100%! 🏁 ⭐ Si estás listo, podemos pasar de inmediato a la siguiente provincia planificada en el orden territorial nacional: Provincia de Guadalajara (Comunidad de Castilla-La Mancha), arrancando masivamente desde la letra A con municipios como Abánades, Ablanque, Adobes, Alaminos, Alarilla, Albalate de Zorita, Albares, Albendiego, Alcocer, Alcolea de las Peñas, Alcolea del Pinar, etc. ¿Deseas que iniciemos el nuevo bloque?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90163','mirador','Mirador del Castillo y Vestigios de la Guerra Civil','7.1/10 Impresionante panorámica del Valle del río Tajuña, formaciones calizas, densos encinares y la red recuperada de trincheras históricas de la Batalla del Olvido. Cómo llegar: Promontorio rocoso sobre la ermita de Nuestra Señora de la Merced, con accesos peatonales señalizados. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90164','mirador','Mirador del Castillo y Hoces del Alto Tajo','7.6/10 Espectacular vista del cañón fluvial encajonado, frondosos pinares de pino resinero, buitreras en las paredes verticales y un nítido cielo nocturno Starlight. Cómo llegar: Cota caliza al sur del núcleo, accesible por pista forestal desde la carretera GU-951. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90165','mirador','Alto de la Muela de Adobes','6.6/10 Vista diáfana de la paramera molinesa, campos cerealistas de gran altitud, sabinares dispersos y horizontes totalmente limpios idóneos para astrofotografía. Cómo llegar: Plataforma tabular calcárea al este de la localidad, transitable por sendas agropecuarias de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90166','mirador','Mirador del Teso de San Cristóbal','6.3/10 Panorámica rural de la Alcarria alta, olivares integrados en cárcavas arcillosas, pequeños arroyos estacionales y amplias puestas de sol castellanas. Cómo llegar: Elevación natural al norte del pueblo, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90167','mirador','Mirador del Cerro de La Muela','8.7/10 Icónica panorámica de 360 grados sobre el Valle del Henares, campos de cultivo, meandros fluviales y el principal despegue de parapente del centro peninsular. Cómo llegar: Cima de la emblemática meseta caliza exenta, provista de aparcamiento y accesos rodados adaptados. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90168','mirador','Mirador de la Cruz de la Nueva Sierra','8.4/10 Extraordinaria vista aérea del Embalse de Bolarque, el encajonamiento del río Tajo, la sierra de Altomira y frondosas urbanizaciones integradas en el pinar. Cómo llegar: Balcón natural con barandilla en el sector alto de la Urbanización Nueva Sierra de Altomira. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90169','mirador','Alto de las Bodegas y Mirador de la Vega','6.8/10 Perspectiva sobre la vega del arroyo de San Andrés, huertas alcarreñas tradicionales, olivares e hileras de lumbreras de antiguos calados subterráneos. Cómo llegar: Corona del cerro horadado por las bodegas, accesible a pie desde la Plaza Mayor. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90831','mirador','Entorno de la Ermita de Santa Coloma y Río Bornova','7.8/10 Hermosa vista de la cabecera del Valle del Bornova, chopera lineal, praderas de media montaña y el ábside románico-mudéjar con celosías pétreas de la ermita. Cómo llegar: Paraje natural llano en la llanura aluvial, a un kilómetro del núcleo urbano por la CM-110. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90170','mirador','Mirador de la Torre del Espantapescadores','7.5/10 Espectacular atalaya sobre la Hoya de Infantado, campos de cereal, olivares y la lámina azul de los embalses de Entrepeñas y Buendía en el horizonte. Cómo llegar: Cuerpo de campanas superior de la imponente iglesia gótica apodada la "Catedral de la Alcarria". 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90171','mirador','Mirador de las Peñas Rojas','7.2/10 Singular relieve de formaciones rocosas de arenisca rojiza erosionada, pequeños valles agrícolas encajados, vegetación arbustiva e idóneo entorno para fotografía de naturaleza. Cómo llegar: Crestas de arenisca situadas al borde del casco urbano, accesibles por senderos locales peatonales. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90172','mirador','Mirador de la Casa de Piedra y los Pinares','7.0/10 Vista de la plataforma elevada del páramo de Sigüenza, densas masas de pino silvestre, dehesas y el singular monumento etnográfico excavado en roca viva. Cómo llegar: Entorno urbano de la célebre Casa de Piedra, con accesos directos desde la Autovía del Nordeste (A-2). Si te parece correcto, indícame si pasamos directamente al siguiente bloque de la Provincia de Guadalajara con las letras A (restantes), B y C o si deseas realizar algún ajuste fino.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90173','mirador','Mirador del Orea y la Paramera','7.8/10 Soberbia vista del Sistema Ibérico molinés, extensos pinares de pino silvestre, dehesas altas, formaciones de pizarra y cielos nocturnos certificados para astroturismo. Cómo llegar: Cresta rocosa situada al sur del casco urbano, accesible por pistas forestales. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90174','mirador','Alto de San Roque y la Vega','6.6/10 Panorámica sobre el valle del arroyo de San Roque, campos de cultivo cerealista, olivares alcarreños y relieve suave de lomas arcillosas. Cómo llegar: Colina exenta que alberga la ermita, transitable a pie desde el casco urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90175','mirador','Mirador del Cañón del Río Mesa','7.3/10 Impresionantes farallones y paredes calizas verticales que encajonan el cauce del río Mesa, nidos de buitre leonado y vegas agrícolas bajas. Cómo llegar: Borde del precipicio natural acondicionado al norte del núcleo, accesible por pistas rurales. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90832','mirador','Mirador del Páramo de Algora','6.8/10 Vista de la planicie horizontal del páramo del Henares, encinares dispersos, matorral mediterráneo de jara y cielos abiertos despejados aptos para astrofotografía. Cómo llegar: Borde de la plataforma calcárea, accesible desde los caminos de servicio de la autovía A-2. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90176','mirador','Mirador de la Cuesta de las Bodegas y Alto del Ceño','7.0/10 Hermosa vista de la vega baja del río Arlés, el entramado urbano escalonado alcarreño, olivares centenarios e hileras de chimeneas tradicionales. Cómo llegar: Zona alta del montículo de las bodegas, accesible a pie desde la iglesia de San Juan. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90177','mirador','Alto del Teso de la Ermita','6.4/10 Perspectiva rural de la Alcarria central, relieves ondulados con campos de cereal y lavanda, encinas jóvenes y horizontes limpios de obstáculos. Cómo llegar: Promontorio suave al oeste de la localidad, transitable por caminos vecinales de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90178','mirador','Mirador de los Cortados de la Autovía','6.7/10 Vista panorámica del valle alto del río Badiel, taludes arcillosos de erosión lineal, cultivos de secano e infraestructuras de transporte integradas. Cómo llegar: Cornisa natural accesible por pistas agropecuarias desde el kilómetro 103 de la autovía A-2. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90179','mirador','Mirador del Castillo y el Embalse de Almoguera','7.9/10 Magnífica e industrial panorámica del río Tajo encajonado, la presa hidroeléctrica, la densa vegetación de ribera y los escarpes calizos de Altomira. Cómo llegar: Explanada de la antigua fortaleza medieval que domina el cerro testigo sobre el pueblo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90180','mirador','Mirador del Cerro de la Olmeda','8.3/10 Extraordinaria vista aérea del Embalse de Bolarque, la confluencia de los ríos Tajo y Guadiela, encinares maduros e imponentes tajos de roca. Cómo llegar: Estructura adaptada con pasarela en el sendero que sube hacia la sierra de Altomira. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90181','mirador','Mirador de Alocén y Embalse de Entrepeñas','8.6/10 Espectacular e icónica estampa del apodado "Mar de Castilla", pinares de repoblación, cortados de arcilla, olmos singulares y un horizonte lacustre infinito. Cómo llegar: Balcón acondicionado con barandillas, paneles informativos y bancos a la entrada del casco urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90182','mirador','Mirador del Parque Vallejo','63/10 Vista periurbana del Corredor del Henares, campos agrícolas tradicionales de regadío que resisten el avance industrial y relieves del Campiña baja. Cómo llegar: Zona alta ajardinada con accesos urbanos peatonales en la periferia del núcleo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90183','mirador','Mirador de la Ermita de San Roque y los Sabinares','8.0/10 Soberbia visual a más de 1400 metros de altitud sobre la Sierra de Albarracín y paramera molinesa, con sabinas milenarias e idóneo punto Starlight. Cómo llegar: Entorno rocoso elevado de la ermita, accesible por pista forestal apta para vehículos. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19031','mirador','Mirador del Valle del Cañamares','6.9/10 Vista del cauce encajonado del río Cañamares, huertas de media montaña, laderas cubiertas de encinar e interesantes puestas de sol sobre la sierra. Cómo llegar: Borde norte de la plataforma calcárea que delimita el término, accesible por sendas forestales. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19032','mirador','Mirador de la Torre de la Cigüeña y Hoces del Tajuña','7.8/10 Espectacular tajo calizo excavado por el río Tajuña, formaciones kársticas, nidos de rapaces rupícolas y la atalaya defensiva medieval islámica del siglo X. Cómo llegar: Explanada de la torre defensiva sobre el desfiladero, acceso señalizado por sendero local. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19033','mirador','Alto del Teso del Buitre','7.2/10 Panorámica de los pinares del Ducado de Medinaceli, relieves pizarrosos, matorral de jara y cielos nocturnos limpios catalogados para astrofotografía. Cómo llegar: Cota natural elevada al norte del pueblo, accesible por pistas forestales de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19034','mirador','Mirador de las Parameras de Molina','6.8/10 Vista limpia de la estepa fría molinesa, formaciones de piedra caliza, pastizales de ganado ovino y horizontes limpios libres de obstáculos industriales. Cómo llegar: Elevación natural del terreno transitable a pie por caminos vecinales al sur del caserío. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19036','mirador','Mirador de la Peña del Reloj y Valle del Tajuña','7.1/10 Amplia visual del curso medio del río Tajuña, vegas fértiles de regadío, hileras de chopos, olivares de ladera y el casco urbano escalonado. Cómo llegar: Saliente natural del páramo acondicionado con valla protectora en el flanco este del pueblo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19037','mirador','Mirador del Parque Natural de la Sierra Norte','7.6/10 Vista del somontano de la Sierra de Ayllón, la silueta del pico Ocejón en días claros, densos encinares y nítidos atardeceres serranos. Cómo llegar: Plataforma acondicionada con paneles informativos en las proximidades de la ermita de la Salceda. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19038','mirador','Mirador del Castillo de Arbeteta y el Escalerón','8.2/10 Impresionante e inexpugnable roca caliza coronada por una fortaleza del siglo XV, vistas de las hoces del arroyo de la Jarra y pinos silvestres. Cómo llegar: Crestas rocosas que rodean el peñón del castillo, acceso a pie por sendas de montaña. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19039','mirador','Mirador del Valle del Badiel y los Yesos','7.2/10 Perspectiva del profundo valle erosionado sobre arcillas y yesos, terrazas agrícolas, olivares y la fisonomía del pueblo colgado de la vertiente. Cómo llegar: Borde del páramo accesible desde el camino que nace de la carretera CM-1003. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19040','mirador','Mirador del Hundido de Armallones','8.5/10 Extraordinario y caótico colapso geológico de bloques calizos gigantescos sobre el cañón del río Tajo, buitreras, quejigares autóctonos y pureza Starlight total. Cómo llegar: Balcón natural acondicionado con paneles del Parque Natural del Alto Tajo al oeste del núcleo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19041','mirador','Alto del Castillo y Vega del Tajuña','6.9/10 Vista de las huertas tradicionales alcarreñas, el curso fluvial, plantaciones de cereal en el páramo superior y restos de defensas medievales. Cómo llegar: Cota más alta del núcleo urbano, accesible a pie desde la iglesia de la Asunción. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19042','mirador','Mirador de los Huertos y los Montes de Pizarra','7.4/10 Paisaje serrano del macizo del Ocejón, laderas escarpadas de pizarra negra, brezales de media montaña y construcciones integradas de la arquitectura negra. Cómo llegar: Camino rural en el extremo nororiental del municipio, apto para senderismo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19043','mirador','Mirador de San Roque y Centenera','7.0/10 Vista panorámica del Valle del Ungría, escarpes calizos de los páramos alcarreños, encinares dispersos e interesantes cielos limpios nocturnos. Cómo llegar: Cornisa del páramo occidental adaptada junto a la ermita de San Roque. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19044','mirador','Mirador del Castillo de Atienza','8.8/10 Soberbia e inexpugnable atalaya de la mítica fortaleza sobre un cerro testigo rocoso, divisando la Serranía, iglesias románicas y la meseta norte. Cómo llegar: Corona superior de la torre del homenaje y adarves visitables del castillo medieval. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19045','mirador','Mirador del Viaducto y las Hoces del Tajo','8.1/10 Impresionante cañón calizo del río Tajo aguas abajo de la presa de Entrepeñas, olivares de ladera, ermitas rupestres y el puente monumental. Cómo llegar: Saliente acondicionado junto a la ermita del Madroñal, acceso desde la N-320. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19046','mirador','Mirador de la Reserva de las Lagunas de Azuqueca','6.2/10 Perspectiva ornitológica de humedales artificiales recuperados junto al río Henares, idónea para avistamiento de ánades, garzas reales y bosque de ribera. Cómo llegar: Casetas de observación integradas en el recinto protegido, acceso restringido para visitas guiadas. Si quieres, indícame si pasamos directamente al bloque que inicia con la letra B.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19047','mirador','Mirador del Valle del Henares y del Ferrocarril','7.1/10 Confluencia de los ríos Henares y Regacho, rodeada de laderas de arenisca y arcilla con el histórico trazado ferroviario a sus pies. Cómo llegar: Alto de la Cuesta del Calvario, accesible por sendero peatonal desde el museo ferroviario exterior. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19049','mirador','Mirador del Cerro de San Cristóbal','6.9/10 Vista panorámica del nacimiento del río Bañuelos, relieves de la serranía de Atienza, pastizales de montaña y vegetación esteparia limpia. Cómo llegar: Cima del cerro testigo exento, transitable a pie por sendas ganaderas desde el pueblo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19050','mirador','Mirador de la Vega del Vadillo','6.8/10 Perspectiva del estrecho valle alcarreño, campos de lavanda estacionales, encinares autóctonos y un relieve tabular que enmarca horizontes limpios. Cómo llegar: Cornisa del páramo occidental, accesible por caminos agrícolas que parten de la carretera GU-922. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19051','mirador','Mirador del Alto de la Arribada','7.2/10 Espectacular caída hacia el Valle del Arlés, olivares centenarios esculpidos en terrazas, encinares densos y el núcleo urbano de herencia templaria. Cómo llegar: Borde de la meseta alcarreña en la carretera CM-2005, provisto de apartadero natural de piedra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19052','mirador','Mirador del Cañón del Río Cañamares','7.6/10 Impresionantes escarpes rocosos calizos de la Sierra Norte, bosque de ribera encajonado, antiguas explotaciones mineras de plata y avifauna de roca. Cómo llegar: Promontorio adaptado con paneles ambientales en la pista forestal que comunica con Angón. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19053','mirador','Mirador del Campo de la Alcarria y de la Muralla','8.8/10 Impresionante e infinita postal morada de los extensos campos de lavanda, la vega frondosa del Tajuña y el recinto amurallado del siglo XII. Cómo llegar: Balcón fortificado del Postigo de San Felipe, adaptado con bancos en el casco histórico briocense. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19054','mirador','Mirador de la Ermita de la Soledad','7.9/10 Excelente visual de la cuenca del embalse de Entrepeñas, olivares tradicionales, el convento de los Carmelitas y escarpes calizos del páramo. Cómo llegar: Explanada de la ermita al este del caserío urbano, dotada de accesos rodados pavimentados. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19055','mirador','Mirador de la Vega del Henares','6.6/10 Vista limpia de la llanura aluvial del río Henares, campos agrícolas tradicionales de regadío, choperas lineales y arcillas erosionadas en las laderas. Cómo llegar: Pequeña colina al norte de la iglesia parroquial, transitable por pistas rurales. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19057','mirador','Mirador del Alto del Rey y del Ocejón','8.4/10 Soberbia panorámica de la Sierra de Ayllón desde su vertiente sur, laderas de pizarra cubiertas de brezo, robledales protegidos e idóneo punto Starlight. Cómo llegar: Cima rocosa de la Sierra del Alto del Rey, accesible mediante pista forestal de montaña. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19058','mirador','Mirador del Teso del Campo de Golf','6.3/10 Vista periurbana de la Campiña del Henares, campos de cereal que limitan con la capital, olivares dispersos y relieve llano abierto. Cómo llegar: Zona periférica elevada junto a los desarrollos residenciales, acceso pavimentado urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19059','mirador','Mirador del Castillo de Zafra','8.6/10 Extraordinaria e icónica perspectiva de la fortaleza del siglo XII edificada sobre una estrecha e imponente cresta de arenisca roja, paisaje molinés desértico. Cómo llegar: Explanada natural de roca caliza frente al castillo, accesible por pista de tierra señalizada desde la GU-418. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19060','mirador','Mirador de las Majadas y de la Arquitectura Negra','8.7/10 Espectacular visual del pico Ocejón, profundos barrancos fluviales del Jarama y el conjunto etnográfico homogéneo construido íntegramente con lajas de pizarra negra. Cómo llegar: Mirador acondicionado en la entrada de la pedanía de El Espinar, con paneles informativos geológicos. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19061','mirador','Mirador de la Sierra de Pela','7.9/10 Paramera septentrional a más de 1200 metros de altitud, con el aire más limpio de Europa, sabinares, iglesias románicas y nítida observación estelar. Cómo llegar: Vértice geodésico en la cuerda de la sierra, accesible por pistas de mantenimiento de parques eólicos. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19064','mirador','Alto del Páramo de San Juan','6.8/10 Vista de la planicie del páramo de la Alcarria alta, encinares continentales densos, cultivos de secano y puestas de sol limpias de obstáculos industriales. Cómo llegar: Camino rural elevado en el extremo sur del término municipal. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19065','mirador','Mirador del Hayedo de Tejera Negra','92/10 Excepcional, única e impresionante panorámica del hayedo más meridional de Europa, valles glaciares de los ríos Lillas y Zarzas, tejos milenarios y grandes rapaces. Cómo llegar: Senda adaptada de las Carretas, en el corazón del Parque Natural de la Sierra Norte de Guadalajara. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19066','mirador','Atrio de la Iglesia de Santa Cruz','6.4/10 Vista abierta del Valle del Badiel, suaves pendientes arcillosas de labranza, olivares alcarreños y horizontes nítidos propicios para la astrofotografía. Cómo llegar: Explanada elevada que precede al templo barroco, en el centro de la localidad. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19070','mirador','Alto de la Cuesta del Teso','6.6/10 Perspectiva rural de la Campiña alta, campos de cultivo extensivos, dehesas dispersas y la cordillera de Ayllón recortada nítidamente al fondo. Cómo llegar: Promontorio suave al oeste del casco urbano, accesible por pistas de tierra agropecuarias. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19074','mirador','Mirador de los Cortados del Río Ungría','7.4/10 Espectacular corte calizo sobre el Valle del Ungría, frondosos bosques de ribera con encinas y quejigos en las laderas, y un entorno natural protegido. Cómo llegar: Borde de la plataforma calcárea oriental, accesible por sendas peatonales desde el núcleo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19075','mirador','Mirador del Castillo y del río Dulce','6.8/10 Vista de la vega del Henares y del tramo bajo del río Dulce, escarpes calizos erosionados y cultivos agrícolas que cambian según la estación. Cómo llegar: Cresta natural donde se asientan los restos de la fortaleza defensiva medieval del municipio. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19076','mirador','Alto de la Virgen de la Muela','6.9/10 Panorámica diáfana de las parameras de Molina de Aragón, campos cerealistas de gran altitud, sabinas rastreras y horizontes nocturnos limpios. Cómo llegar: Entorno elevado de la ermita homónima, accesible mediante pista transitable desde la N-211. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19078','mirador','Mirador del Castillo y de la Hoya','7.1/10 Perspectiva de la Hoya del Infantado, escarpes de yesos y arcillas rojas, dehesas ganaderas y un cielo estrellado de pureza excepcional. Cómo llegar: Promontorio rocoso elevado que corona el pueblo, accesible a pie desde la iglesia románica. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19079','mirador','Mirador del Castillo y Valle del Gallo','7.5/10 Vista panorámica del curso encajonado del río Gallo, vegas fértiles, huertas tradicionales de montaña y la silueta del castillo roquero del siglo XII. Cómo llegar: Crestas rocosas que circundan la fortaleza medieval, acceso peatonal desde el núcleo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19080','mirador','Alto del Teso de San Juan','6.8/10 Vista abierta del Valle del Badiel norte, olivares, campos de labranza en el páramo superior e interesantes puestas de sol castellanas. Cómo llegar: Elevación natural al noreste del pueblo, accesible por pistas agropecuarias de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19081','mirador','Mirador de la Torre de la Iglesia','6.9/10 Perspectiva sobre los páramos arcillosos linderos con Sigüenza, campos de cultivo extensivos de cereal y encinares maduros dispersos. Cómo llegar: Cuerpo exterior elevado o explanada perimetral del templo mudéjar local. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19082','mirador','Mirador de la Cuesta del Valle del Ungría','7.0/10 Vista del profundo encajamiento fluvial, laderas cubiertas de quejigos y encinas jóvenes, y el mosaico agrícola de la Alcarria baja. Cómo llegar: Borde occidental de la plataforma calcárea, accesible por el camino de Guadalajara. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19103','mirador','Mirador de las Quebradas y del río Genalo','8.9/10 Impresionante e imponente formación geológica de costeras de caliza verticales, cañones profundos, densos pinares alpinos e idóneo punto Starlight. Cómo llegar: Balcón natural acondicionado con paneles e hitos de la ruta del Parque Natural del Alto Tajo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19104','mirador','Mirador de los "Frailes" y del Valle del Cabrillas','8.8/10 Espectacular e inigualable paisaje kárstico de gigantescas agujas y monolitos de arenisca roja que rodean el pueblo, bosque de pino silvestre y aguas cristalinas. Cómo llegar: Estructura de observación integrada en las formaciones rocosas que dominan la plaza de toros natural. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19106','mirador','Mirador de los Meandros de Entrepeñas','7.8/10 Hermosa vista de los brazos inundados del río Tajo, pinares densos de repoblación, taludes arcillosos y abundante avifauna de ecosistema acuático. Cómo llegar: Saliente acondicionado con valla protectora al oeste del núcleo por la carretera GU-215. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19105','mirador','Mirador del Páramo de Chiloeches','6.9/10 Vista de la caída de la meseta alcarreña hacia el Corredor del Henares, campos agrícolas tradicionales periurbanos, encinares dispersos y horizontes abiertos. Cómo llegar: Cornisa de la plataforma calcárea occidental, accesible por el camino de la Alcarria. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19086','mirador','Mirador del Castillo de Don Juan Manuel y Manantiales','8.1/10 Magnífica panorámica del nacimiento del río Cifuentes, la villa medieval fortificada del siglo XIV, olivares extensos y laderas cubiertas de matorral. Cómo llegar: Explanada de la fortaleza medieval que corona el cerro testigo que flanquea el municipio. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19087','mirador','Alto del Calvario','6.5/10 Sencilla panorámica sobre los llanos cerealistas del Henares alto, olivares dispersos y horizontes despejados óptimos para observar tormentas de verano. Cómo llegar: Repecho natural al suroeste del caserío, antiguo emplazamiento de cruces de piedra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19088','mirador','Mirador del Alto de San José','6.7/10 Vista diáfana de la llanura de la Campiña, de relieve ondulado, dedicada al cultivo de secano y puestas de sol limpias sin tendidos industriales. Cómo llegar: Cota natural elevada al norte de la población, transitable por sendas agropecuarias. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19089','mirador','Mirador de los Pelaos y del Pinar','7.5/10 Vista focalizada en la densa masa forestal de pino resinero y silvestre del Ducado, sabinares centenarios de altura e idónea observación estelar nocturna. Cómo llegar: Pista de servicio e hito forestal situado al sur del núcleo, accesible por caminos rurales. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19090','mirador','Mirador del Torreón de Cobeta y Hoces del Arandilla','8.4/10 Espectacular e imponente barranco de arenisca roja y caliza excavado por el río Arandilla, pinar resinero salvaje y la esbelta torre del castillo del siglo XII. Cómo llegar: Explanada rocosa del torreón vigía que domina el desfiladero, acceso señalizado por sendero local. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19091','mirador','Alto de la Cuesta del Tajuña','6.8/10 Perspectiva de las pendientes arcillosas de la Alcarria central, campos de cereal y lavanda, encinas jóvenes y horizontes limpios libres de contaminación. Cómo llegar: Borde del páramo accesible por pistas agrícolas desde la carretera GU-927. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19092','mirador','Mirador de las Ruinas del Castillo y el Palacio Ducal','8.4/10 Extraordinario balcón sobre el Valle del Aliendre y el somontano de la Sierra, el primer palacio renacentista de España, campos de vid y secano. Cómo llegar: Cerro del antiguo castillo medieval en la zona más elevada de la villa ducal, acceso peatonal. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19095','mirador','Mirador del Río Condemios y los Pinares','82/10 Vista de los densos bosques de pino silvestre de la Sierra de Ayllón, pastizales alpinos, praderas húmedas de fondo de valle y nítido cielo nocturno Starlight. Cómo llegar: Borde del talud geográfico natural, accesible por pistas forestales desde el pueblo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19096','mirador','Mirador del Parque del Pozuelo y Majada Alta','83/10 Impresionante panorama de alta montaña, formaciones de pizarra, pinares de repoblación consolidados, brezales densos y fauna forestal de la Sierra Norte. Cómo llegar: Plataforma superior con paneles informativos en la subida al puerto, carretera CM-110. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19097','mirador','Mirador del Cañón del Río Bornova','7.1/10 Vista del profundo encajamiento fluvial del Bornova, taludes calizos y pizarrosos, matorral mediterráneo de jara y vegetación de ribera lineal. Cómo llegar: Borde del precipicio natural accesible por caminos de tierra desde el núcleo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19098','mirador','Alto del Teso de la Ermita','6.5/10 Sencilla panorámica rural de los campos de secano de la Alcarria alta, olivares integrados en cárcavas y limpios horizontes para astrofotografía. Cómo llegar: Repecho natural al norte del pueblo, transitable a pie desde el casco urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19099','mirador','Mirador de la Virgen de la Hoz y del río Gallo','8.9/10 Espectacular, majestuoso e imponente cañón de monolitos gigantes de arenisca roja, pinares de pino resinero y el santuario gótico encajado en la roca viva. Cómo llegar: Escaleras de piedra e itinerario de miradores habilitados en la cima de las rocas, acceso señalizado. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19107','mirador','Mirador del Cerro de la Virgen de la Muela','7.6/10 Vista espectacular de la vega del río Tajo baja, olivares alcarreños, campos de regadío y las terrazas donde se excavó la ciudad romana de Caraca. Cómo llegar: Promontorio calizo e hito arqueológico al sur del pueblo, accesible por camino vecinal de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19108','mirador','Mirador de la Ermita de Nuestra Señora de la Esperanza','8.2/10 Impresionante y majestuosa perspectiva del embalse de Entrepeñas, los tajos calcáreos que encajonan el Tajo, pinares de repoblación y horizontes lacustres. Cómo llegar: Explanada del santuario barroco con barandillas sobre el precipicio, acceso señalizado por la N-320. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19109','mirador','Mirador del Castillo de Embid y del río Gallo','74/10 Vista panorámica de la paramera molinesa nororiental, campos de secano de gran altitud y la imponente torre del homenaje de la fortaleza medieval del siglo XIV. Cómo llegar: Corona superior de la muralla restaurada del castillo, accesible para visitas en el núcleo urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19110','mirador','Mirador de la Torre de los Giraldo y del Castillo','7.5/10 Excelente visual de la Hoya del Infantado oriental, el entramado urbano medieval alcarreño, olivares centenarios y la espléndida torre barroca apodada la "Giralda Alcarreña". Cómo llegar: Cota alta del cerro de la antigua fortaleza medieval, accesible a pie desde el casco urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19111','mirador','Alto de las Cuestas de la Vega','6.9/10 Vista de la vega baja del río San Andrés, olivares centenarios esculpidos en terrazas arcillosas, encinares dispersos y horizontes alcarreños nítidos. Cómo llegar: Borde de la plataforma calcárea oriental, accesible por pistas rurales desde la localidad. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19112','mirador','Mirador del Valle del Arlés','6.7/10 Perspectiva del estrecho valle alcarreño, campos de cultivo cerealista, olivares e hileras de chopos que marcan los cauces de los arroyos menores starlight. Cómo llegar: Elevación natural del terreno transitable a pie por sendas agropecuarias al sur del casco. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19113','mirador','Mirador del Puente sobre el río Aliendre y el Henares','7.1/10 Vista de la confluencia de los cauces fluviales, el puente de origen romano de tres ojos, frondosos sotos de ribera, choperas e instalaciones ferroviarias históricas. Cómo llegar: Paseo fluvial acondicionado en la margen derecha del río Henares, cerca del casco urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19114','mirador','Alto del Páramo de San Roque','6.8/10 Vista diáfana de la llanura de la Alcarria alta, encinares continentales maduros, matorral mediterráneo de jara y cielos abiertos despejados aptos para astrofotografía. Cómo llegar: Borde de la plataforma calcárea, accesible por pistas agropecuarias de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19116','mirador','Mirador del Valle del Dulce y los Quejigares','7.1/10 Vista panorámica del tramo alto del río Dulce, laderas cubiertas de quejigos y encinas centenarias de la meseta de Sigüenza, e idóneo entorno natural de silencio. Cómo llegar: Cornisa de la plataforma calcárea norte, accesible por sendas forestales desde el pueblo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19117','mirador','Mirador del Soto del río Henares','6.2/10 Vista de la vega del Henares media, cultivos extensivos de regadío, frondosos sotos fluviales y el desarrollo agroindustrial periférico integrado en la campiña. Cómo llegar: Paseo fluvial acondicionado en los límites orientales del núcleo, con accesos peatonales. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19118','mirador','Mirador del Teso del Cura y el Alto Tajo','7.6/10 Espectacular vista del somontano del Alto Tajo, pinares de pino resinero densos, formaciones kársticas calizas e idónea observación astronómica sin contaminación. Cómo llegar: Cota natural elevada al norte del pueblo, accesible por pistas forestales de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19119','mirador','Atrio de la Iglesia de San Juan Bautista','6.5/10 Sencilla panorámica sobre los llanos cerealistas de la Campiña alta, la silueta del pico Ocejón en la lejanía y puestas de sol limpias. Cómo llegar: Plaza elevada perimetral frente a la portada del templo renacentista municipal. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19120','mirador','Mirador del Alto de la Campiña','6.7/10 Vista abierta de los paisajes arcillosos cerealistas, olivares dispersos, dehesas ganaderas e horizontes abiertos ideales para la fotografía meteorológica de tormentas. Cómo llegar: Elevación natural del terreno transitable a pie por sendas agropecuarias al este del caserío. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19121','mirador','Mirador de la Torre de la Mora y del Valle','7.8/10 Excelente e histórica panorámica sobre la vega de San Andrés, los restos de la muralla defensiva del siglo XII, olivares centenarios y encinares alcarreños. Cómo llegar: Explanada de la antigua fortaleza que corona la villa histórica, accesible por camino peatonal. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19122','mirador','Mirador de la Estratigrafía y del Castillo','7.9/10 Singular relevancia geológica sobre el estratotipo mundial del Jurásico medio (GSSP), las ruinas de la fortaleza medieval del siglo XIV y la paramera molinesa. Cómo llegar: Plataforma acondicionada con paneles científicos en el valle del río de la Hoz, desvío señalizado. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19123','mirador','Mirador de la Cuesta de la Vega','6.6/10 Vista limpia de la Alcarria meridional, olivares tradicionales, campos de cereal integrados en el perfil arcilloso y nítidos atardeceres. Cómo llegar: Borde del páramo junto al depósito de aguas, accesible desde el casco urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19124','mirador','Alto del Teso de la Horca','6.8/10 Panorámica rural de lomas onduladas alcarreñas, campos de cultivo de secano y horizontes limpios idóneos para capturar cielos estrellados. Cómo llegar: Cota natural elevada al noreste del pueblo, accesible por pistas agropecuarias de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19125','mirador','Mirador del Páramo del Badiel','6.4/10 Perspectiva sobre la plataforma horizontal del páramo alcarreño, campos cerealistas, matorral mediterráneo de jara y cielos despejados. Cómo llegar: Borde del escarpe calcáreo, accesible desde los caminos de servicio de la autovía A-2. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19126','mirador','Mirador de la Campiña y del Palacio','6.2/10 Vista de las terrazas fluviales de la Campiña del Henares, cultivos de secano e integración con el desarrollo urbano residencial moderno. Cómo llegar: Zona alta ajardinada en la periferia norte del casco urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19127','mirador','Mirador del Castillo de los Zúñiga','8.4/10 Espectacular e imponente panorámica de la Sierra de Pela, el curso alto del río Sorbe, densos pinares forestales y la imponente fortaleza gótica del siglo XV. Cómo llegar: Explanada natural elevada que rodea el cerro del castillo medieval. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19129','mirador','Alto del Teso del Castro','7.2/10 Vista del valle encajonado del río Bornova, escarpes calizos de la Sierra Norte, matorral mediterráneo y un limpio cielo nocturno. Cómo llegar: Promontorio suave al norte del caserío, transitable por sendas ganaderas. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19130','mirador','Mirador del Parque del Coquín y San Roque','7.5/10 Vista panorámica del Valle del Henares, el perfil histórico de la ciudad, el Palacio del Infantado y los relieves linderos de la Alcarria. Cómo llegar: Cornisa ajardinada acondicionada con barandilla en el casco urbano de la capital. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19132','mirador','Mirador de las Bodegas y Alto de San Bartolomé','6.9/10 Hermosa vista de la vega del arroyo de Henche, olivares alcarreños, campos de lavanda y chimeneas de tradicionales bodegas excavadas. Cómo llegar: Zona alta del cerro de las bodegas, accesible a pie desde la ermita de San Bartolomé. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19133','mirador','Mirador de la Vega del Henares','6.1/10 Sencilla panorámica rural sobre los llanos aluviales fértiles de regadío, cultivos hortícolas y chopera lineal del río Badiel. Cómo llegar: Margen de la terraza fluvial, accesible por pistas rurales desde el pueblo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19134','mirador','Alto de la Muela de Herrería','7.0/10 Vista limpia de la paramera molinesa meridional, sabinares dispersos, cultivos de cereal de secano y nítidos horizontes mesetarios. Cómo llegar: Plataforma calcárea elevada accesible por pistas forestales al sur del término. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19135','mirador','Mirador de las Minas y del Río Bornova','7.8/10 Extraordinario paisaje minero industrial del siglo XIX, con vistas profundas al cañón del Bornova y las cumbres de la Sierra de Ayllón. Cómo llegar: Estructura adaptada con barandilla junto al pozo de la mina "Santa Cecilia", desvío señalizado. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19136','mirador','Mirador del Yacimiento de los Casares','7.1/10 Vista arqueológica y paisajística del somontano norte de la Sierra, relieves ondulados de areniscas y un horizonte celeste apto para astrofotografía. Cómo llegar: Entorno del yacimiento arqueológico romano y necrópolis celtíbera, acceso rural. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19138','mirador','Mirador del Cerro de Hita','8.5/10 Espectacular e histórica panorámica de 360 grados de la Campiña y la Alcarria, el trazado medieval amurallado de la villa y bodegas rupestres. Cómo llegar: Cima del emblemático cerro testigo que corona el pueblo, accesible por sendero peatonal empinado. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19139','mirador','Mirador de la Sierra de Caldereros','7.4/10 Magnífica visual de las caprichosas formas de arenisca rojiza erosionada de la sierra, sabinares milenarios y campos agrícolas de gran altitud. Cómo llegar: Crestas rocosas accesibles por pista de tierra que comunica con el Castillo de Zafra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19142','mirador','Mirador del Valle de San Miguel','7.0/10 Vista de las vertientes boscosas de la Alcarria baja, encinares maduros, huertas de ribera y la fisonomía del casco urbano encajonado. Cómo llegar: Cornisa natural alta al este del núcleo, accesible por caminos rurales. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19143','mirador','Mirador del Picuzo y Valle del Ungría','7.6/10 Hermosa y amplia panorámica del Valle del Ungría, escarpes calizos calcáreos, huertas tradicionales alcarreñas, olivares de ladera y bodegas tradicionales subterráneas. Cómo llegar: Balcón natural adaptado con barandilla de madera en el borde del páramo occidental. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19145','mirador','Alto del Páramo de Océn','6.8/10 Vista de la planicie del páramo calizo, encinares dispersos, majanos de piedra tradicionales y un cielo nocturno libre de contaminación lumínica. Cómo llegar: Borde norte del término, transitable por pistas agrícolas de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19147','mirador','Mirador del Salto y Cañón del Salado','7.3/10 Vista del profundo cañón fluvial del río Salado, cortados calizos con nidos de rapaces rupícolas y el entorno del embalse de El Atance. Cómo llegar: Plataforma natural en el borde del precipicio, accesible desde el camino de Viana. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19148','mirador','Mirador del Puente de Tagenza y Alto Tajo','8.2/10 Impresionante vista del cañón granítico encajonado del río Tajo, densas masas de pino silvestre y formaciones kársticas del Parque Natural. Cómo llegar: Saliente acondicionado junto a las sendas de senderismo en la margen derecha del río. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19150','mirador','Mirador del Castillo de Hueva','7.1/10 Perspectiva sobre el pequeño valle del arroyo de la Vega, la arquitectura civil medieval y los escarpes de los páramos alcarreños linderos. Cómo llegar: Explanada de la antigua fortaleza del siglo XV en la cota más elevada de la localidad. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19151','mirador','Mirador de la Confluencia del Sorbe y el Henares','6.5/10 Vista fluvial del encuentro de los grandes cauces de la provincia, frondosos bosques de ribera, islas de grava estacionales y huertas tradicionales. Cómo llegar: Sendero peatonal adaptado en la margen izquierda del Henares, cerca del núcleo urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19152','mirador','Mirador del Río Tajo y las Dehesas','7.4/10 Vista del curso bajo del Tajo alcarreño, extensas vegas de regadío, encinares adehesados y las trazas históricas del Palacio de Goyeneche cercano. Cómo llegar: Saliente de la plataforma del páramo sur, transitable por pistas rurales. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19153','mirador','Mirador de los Pinares del Ducado','7.0/10 Vista focalizada en la densa masa forestal de pino resinero y silvestre de la comarca, senderos de tierra e idónea pureza Starlight nocturna. Cómo llegar: Pista de servicio forestal elevada, accesible al oeste del núcleo urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19154','mirador','Alto del Teso de San Cristóbal','6.7/10 Panorámica de los valles menores alcarreños arcillosos, encinas jóvenes, matorral mediterráneo de lavanda y horizontes limpios de obstáculos industriales. Cómo llegar: Elevación natural del terreno transitable a pie por pistas forestales al norte del caserío. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19155','mirador','Mirador del Valle de San Andrés','6.9/10 Vista del encajonamiento del arroyo de San Andrés, taludes calizos de los páramos de la Alcarria alta, huertas y olivares tradicionales. Cómo llegar: Borde oriental de la plataforma calcárea, accesible por sendas desde el pueblo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19156','mirador','Adarve del Castillo del Cid','8.6/10 Soberbia y espectacular vista panorámica del Valle del Henares, el perfil del pico Bornova, las lomas arcillosas de cultivo y la imponente fortaleza palaciega. Cómo llegar: Corona superior transitable de los muros de la fortaleza medieval, accesible por carretera asfaltada. Si quieres, indícame si pasamos directamente al bloque que inicia con la letra J.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19157','mirador','Alto de la Cuesta del Bornova','6.6/10 Vista diáfana de la vega del río Bornova, pequeños huertos tradicionales, campos de cereal de secano y lomas arcillosas del somontano de la Sierra. Cómo llegar: Pequeña elevación natural al oeste del casco urbano, accesible por pistas agropecuarias de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19159','mirador','Mirador del Valle del Badiel y la Ermita','7.1/10 Hermosa panorámica del encajonamiento del río Badiel, laderas escarpadas de yesos, olivares de ladera y la silueta rural del núcleo medieval. Cómo llegar: Borde calizo del páramo junto a la ermita de la Soledad, con acceso por camino vecinal. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19160','mirador','Mirador de la Ermita de la Soledad','7.5/10 Vista espectacular del Valle del río Tajuña, fértiles vegas hortícolas alcarreñas, plantaciones de olivos centenarios y la silueta del histórico Convento del Socorro. Cómo llegar: Explanada de la ermita situada en una cornisa del páramo, al sur del núcleo urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19161','mirador','Mirador de San Bartolomé y Valle del Ungría','7.8/10 Soberbia visual del frondoso Valle del río Ungría, encinares maduros, quejigares autóctonos y la imponente traza renacentista del Monasterio de San Jerónimo. Cómo llegar: Balcón natural acondicionado con paneles informativos en las proximidades del complejo monástico. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19162','mirador','Alto del Castro de Luzaga','7.3/10 Vista del valle alto del río Tajuña, extensas masas de pino silvestre, matorral mediterráneo de jara y vestigios arqueológicos celtíberos bajo cielos nocturnos puros. Cómo llegar: Promontorio rocoso elevado al norte del término, accesible mediante una senda de senderismo señalizada. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19163','mirador','Mirador del Alto del Castillo y Paramera','7.4/10 Amplia e infinita visual sobre el nacimiento del Tajuña, dehesas altas de encina y sabina, campos cerealistas medievales e idóneo punto para astrofotografía. Cómo llegar: Cerro testigo exento coronado por restos defensivos en las proximidades del núcleo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19165','mirador','Mirador del Pico Ocejón (Techo Visual del Municipio)','8.8/10 Excepcional panorámica de la Sierra de Ayllón, pueblos de la Arquitectura Negra, brezales de alta montaña, canchales de pizarra y horizontes de la meseta norte. Cómo llegar: Cima del Pico Ocejón (2048 m), cumbre accesible por sendero de montaña señalizado desde el pueblo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19166','mirador','Atrio de la Iglesia de la Asunción','6.1/10 Sencilla panorámica sobre los llanos cerealistas de la Campiña del Henares, campos ondulados de secano e idóneos atardeceres nítidos y limpios. Cómo llegar: Plataforma elevada urbana frente a la portada renacentista del templo parroquial. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19167','mirador','Alto del Teso de las Eras','6.0/10 Vista despejada de la planicie de la campiña baja, cultivos agrícolas alternos de cereal y olivo, libres de obstáculos visuales industriales para astroturismo. Cómo llegar: Cota natural elevada al norte de la población, cercana a las antiguas eras de trilla. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19168','mirador','Mirador del Parque Natural del Barranco del Río Dulce','7.9/10 Impresionante corte geológico calizo del cañón fluvial, frondoso bosque de ribera, chopera lineal, nidos de grandes buitres y vegetación rupícola protegida. Cómo llegar: Estructura adaptada con barandilla y paneles didácticos de la red del parque, acceso por la GU-118. Si quieres, indícame si pasamos directamente al siguiente bloque masivo desde la letra M en adelante de la Provincia de Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19169','mirador','Mirador Astronómico de Mantiel','8.4/10 Espectacular panorámica del Embalse de Entrepeñas y la Hoya del Infantado, dotado de un observatorio astronómico público permanente en un entorno de nula contaminación lumínica. Cómo llegar: Explanada acondicionada en la cota más alta del núcleo urbano, con acceso peatonal y rodado señalizado. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19170','mirador','Mirador del Campo de Aerogeneradores y de la Paramera','7.1/10 Vista inmensa de la paramera molinesa a más de 1200 metros de altitud, con el contraste visual de los parques eólicos, sabinares dispersos y estepa fría. Cómo llegar: Pistas de servicio eólicas transitables en la plataforma caliza al este del término. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19171','mirador','Mirador del Canal del Henares y las Terrazas','6.1/10 Perspectiva sobre la Campiña baja del Henares, campos agrícolas tradicionales de regadío y la transición hacia el polígono industrial periurbano. Cómo llegar: Pasarela peatonal y talud junto al trazado del Canal del Henares, sector norte. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19172','mirador','Mirador del Valle Alto del Tajuña','6.8/10 Vista del cauce encajonado del río Tajuña, laderas de piedra caliza cubiertas de quejigo y encina, y fértiles praderas aluviales de fondo de valle. Cómo llegar: Borde del páramo occidental, transitable por sendas agrícolas desde la carretera N-204. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19174','mirador','Mirador del Alto de la Fábrica y Valle del Henares','6.7/10 Interesante paisaje que combina la arqueología industrial de la antigua cementera con la vega fluvial del Henares y cortados calizos. Cómo llegar: Promontorio natural al norte del núcleo residencial, accesible a pie desde la estación. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19175','mirador','Mirador de la Ermita de San Mamés y los Pinares','7.6/10 Espectacular mar de pinos rodenos y silvestre de la comarca del Ducado, formaciones de arenisca roja y un cielo nocturno catalogado por su extrema pureza. Cómo llegar: Explanada elevada de la ermita, accesible por pista forestal señalizada al norte del núcleo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19176','mirador','Mirador del Tajo y de la Ermita de la Virgen de la Nazarena','6.9/10 Vista de la vega baja del río Tajo en los límites con Cuenca, campos de cultivo de regadío, olivares de ladera y horizontes despejados. Cómo llegar: Cerro exento que alberga la ermita, transitable por camino de tierra apto para vehículos. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19177','mirador','Alto de la Cuesta del Cañamares','6.4/10 Panorámica sobre el valle del río Cañamares, matorral mediterráneo, encinas jóvenes y un relieve suave con horizontes limpios de obstáculos visuales. Cómo llegar: Pequeño repecho al norte de la localidad, accesible por caminos rurales de herradura. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19178','mirador','Mirador del Barranco de la Hoz de Megina','7.9/10 Impresionante grieta caliza de paredes verticales calcáreas integradas en el Alto Tajo, nidos de rapaces rupícolas, quejigares y cielos de nitidez astronómica. Cómo llegar: Borde del precipicio natural acondicionado con valla de madera, acceso por sendero desde el pueblo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19179','mirador','Mirador de la Vega del Bornova','6.8/10 Vista panorámica del curso medio del río Bornova, plantaciones hortícolas de regadío, chopera lineal de ribera y el somontano de la Sierra de Ayllón. Cómo llegar: Margen de la terraza fluvial, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19181','mirador','Mirador del Puerto de Miedes','7.4/10 Espectacular e histórica visual desde el paso de la Sierra de Pela a más de 1200 metros, divisando el cantar de Mio Cid y la meseta norte. Cómo llegar: Punto alto de la carretera CM-110 en el límite provincial con Soria, con zona de parada de vehículos. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19182','mirador','Alto de la Cruz y Valle del Sorbe','7.2/10 Vista de las vertientes de pizarra e incrustaciones calizas que caen hacia el río Sorbe, jarales densos, encinares y un cielo nocturno muy oscuro. Cómo llegar: Promontorio rocoso elevado al este de la localidad, transitable a pie por sendas de cazadores. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19184','mirador','Mirador de la Ermita de la Fuensanta y Llano del Guadiela','7.3/10 Amplia perspectiva de la Hoya del Infantado meridional, olivares tradicionales alcarreños, cultivos cerealistas y la cuenca del río Guadiela. Cómo llegar: Entorno elevado de la ermita, accesible mediante camino vecinal acondicionado desde el pueblo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19183','mirador','Alto de la Torre de la Iglesia de San Juan Bautista','7.1/10 Vista aérea sobre la paramera de Molina nororiental, palacios señoriales de piedra, cultivos de secano de gran altitud y la vecina provincia de Zaragoza. Cómo llegar: Cuerpo de campanas superior del templo gótico-renacentista, acceso coordinado en el municipio. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19185','mirador','Mirador de los Cañones del Bornova y Atienza','7.7/10 Magnífica visual de los escarpes calcáreos, laderas erosionadas, matorral de media montaña y el hábitat de nidificación del buitre leonado. Cómo llegar: Saliente natural del páramo transitable por pistas forestales al oeste del núcleo de Naharros. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19186','mirador','Mirador del Mirón y Valle del Henares','7.8/10 Balcón natural colgado sobre el valle alto del río Henares y el río Dulce, encinares maduros en las laderas y un horizonte infinitamente diáfano. Cómo llegar: Cornisa del páramo adaptada con barandilla y mirador urbano en el extremo oeste del pueblo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19187','mirador','Mirador Natural del Encuentro del Henares y el Cañamares','7.9/10 Espectacular e ininterrumpida panorámica de la confluencia fluvial, escarpes arcillosos erosionados, vegas de cultivo fértiles y la Sierra de Ayllón al fondo. Cómo llegar: Atalaya natural adaptada con vallado de protección en el propio casco urbano del municipio. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19188','mirador','Mirador de la Peña del Castillo y Río Mesa','7.5/10 Impresionantes agujas y farallones calizos verticales calcinados por la erosión que encajonan el río Mesa, con nidos de grandes rapaces rupícolas. Cómo llegar: Cima rocosa que domina el caserío, accesible mediante sendero pedestre empinado. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19189','mirador','Mirador de la Cuesta del Badiel','6.6/10 Vista de las llanuras cerealistas y arcillosas de la Campiña, el discurrir del arroyo Badiel antes de su desembocadura y puestas de sol limpias. Cómo llegar: Elevación natural al este del término, transitable por caminos vecinales de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19190','mirador','Torre de Aragón del Castillo de Molina','8.8/10 Excepcional e infinita atalaya medieval sobre el río Gallo, la monumental ciudad medieval amurallada, el cañón calcáreo y la gélida paramera molinesa. Cómo llegar: Cima de la torre albarrana exenta de la fortaleza del siglo XII, accesible con la entrada turística al Castillo de Molina. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19191','mirador','Mirador del Páramo del Sorbe','7.3/10 Vista panorámica del somontano de la Sierra Norte, laderas de jara y encina que caen hacia el embalse de Beleña y horizontes diáfanos serranos. Cómo llegar: Borde de la plataforma calcárea al norte del pueblo, accesible por pistas forestales. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19192','mirador','Mirador de la Ermita de San Sebastián y los Viñedos','7.4/10 Mar de viñedos de la D.O. Mondéjar, olivares alcarreños meridionales, campos de cereal y el trazado recuperado de la Vía Verde del Tajuña. Cómo llegar: Explanada de la ermita al oeste del casco urbano, provista de accesos rodados y bancos. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19193','mirador','Alto del Teso de la Iglesia','6.3/10 Sencilla panorámica de la Campiña arcillosa del Henares, campos ondulados de secano e idóneo horizonte nocturno para astrofotografía de baja luminosidad. Cómo llegar: Atrio elevado del templo de la Asunción, en el punto alto del casco urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19194','mirador','Mirador de las Bodegas y Alto de la Horca','7.0/10 Perspectiva sobre el valle del arroyo de la Vega, colmenares tradicionales alcarreños productores de miel, encinares y chimeneas de antiguos calados excavados. Cómo llegar: Parte superior del cerro horadado por las bodegas subterráneas, al oeste del núcleo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19195','mirador','Mirador del Castillo de Trijueque y Paramera','7.2/10 Vista despejada de la estepa fría molinesa oriental, sabinares dispersos, majanos tradicionales de piedra y cielos nocturnos limpios de contaminación. Cómo llegar: Promontorio suave al norte de la población, accesible por pistas agropecuarias de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19196','mirador','Mirador del Valle del Badiel','6.9/10 Vista del encajonamiento del río Badiel entre laderas escarpadas de yesos y arcillas rojas, vegas de regadío fértiles y chopera lineal. Cómo llegar: Saliente natural del páramo accesible por caminos rurales desde la carretera GU-107. ¿Cómo prefieres que continuemos la secuencia? Podemos pasar directamente al siguiente bloque masivo que engloba el resto de la letra M y las letras N, O y P de la Provincia de Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19198','mirador','Alto del Cerro de San Cristóbal','6.7/10 Vista diáfana de la Sierra Norte baja, vegetación esteparia, lomas arcillosas dedicadas al cereal y cielos nocturnos ideales para la fotografía astronómica. Cómo llegar: Elevación natural al oeste del casco urbano, accesible por pistas rurales desde el núcleo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19199','mirador','Mirador del Cañón del Alto Tajo y Peña del Castillo','8.1/10 Imponente perspectiva del río Tajo encajonado, farallones de roca caliza vertical, nidos de buitres leonados y frondosas masas de pino silvestre. Cómo llegar: Cresta caliza superior accesible por el sendero que sube hacia las ruinas del castillo medieval. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19201','mirador','Mirador del Monasterio de Buenafuente del Sistal','8.3/10 Hermosa vista de los densos pinares del Alto Tajo, valles solitarios, sabinas milenarias y el misticismo del conjunto monástico románico del siglo XII. Cómo llegar: Explanada perimetral en la plataforma superior caliza, desvío señalizado desde la carretera GU-952. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19208','mirador','Mirador del Embalse de Pálmaces','7.8/10 Magnífica estampa que combina la lámina azul del embalse sobre el río Cañamares, laderas cubiertas de encinar maduro y cortados arcillosos de erosión. Cómo llegar: Zona recreativa elevada junto a la presa hidroeléctrica, accesos rodados y estacionamiento adaptado. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19209','mirador','Alto del Vértice Geodésico Pardos','6.8/10 Vista limpia de la paramera molinesa meridional, relieves de pizarra y arenisca rojiza, matorral mediterráneo y horizontes despejados sin postes industriales. Cómo llegar: Cota máxima del término municipal, transitable por pistas de servicio forestal desde el pueblo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19210','mirador','Mirador del Valle del Salado','7.1/10 Vista del cauce encajonado del río Salado, salinas tradicionales, laderas calizas erosionadas y campos agrícolas del somontano norte de la provincia. Cómo llegar: Borde de la plataforma calcárea al este del casco urbano, accesible por caminos rurales. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19211','mirador','Mirador del Azud de Pareja y Entrepeñas','8.2/10 Espectacular panorama de la lámina de agua artificial permanente, playas fluviales integradas, pinares de repoblación y los escarpes arcillosos de la Alcarria. Cómo llegar: Cornisa ajardinada acondicionada con barandilla y paseo peatonal en la zona alta urbana. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19212','mirador','Mirador del Calvario y la Villa Ducal','86/10 Impresionante e histórica panorámica del conjunto monumental medieval y renacentista, el Palacio Ducal, olivares alcarreños y el profundo Valle del Arlés. Cómo llegar: Atalaya natural adaptada con vallado de protección junto a las cruces del calvario, acceso peatonal. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19216','mirador','Mirador de la Juntura de los Ríos y Cortados del Tajo','9.0/10 Soberbio e imponente cañón calcáreo del río Tajo y el rincón, paredes verticales gigantescas, quejigares autóctonos y cielos nocturnos catalogados Starlight. Cómo llegar: Balcón volado metálico sobre el abismo en las pistas que comunican con Taravilla, desvío señalizado. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19217','mirador','Mirador del Teso de San Juan','7.5/10 Panorámica de los pinares de la Alcarria oriental, campos cerealistas medievales, dehesas altas de encina y un cielo nocturno libre de contaminación. Cómo llegar: Cota natural elevada al norte del pueblo, accesible por pistas forestales de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19218','mirador','Mirador del Cañón del Río Cañamares','7.2/10 Vista del desfiladero de roca caliza erosionada, huertas tradicionales de media montaña, nidos de rapaces y la cercanía de la iglesia románica de los Admirables. Cómo llegar: Borde del precipicio natural acondicionado al norte de la población, transitable por sendas locales. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19219','mirador','Alto de la Cuesta del Castillo','7.0/10 Vista diáfana de la paramera molinesa central, formaciones de piedra caliza, pastizales de ganado ovino y puestas de sol limpias. Cómo llegar: Promontorio suave al oeste de la localidad, transitable por caminos vecinales de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19221','mirador','Mirador de las Hoces del Gallo','7.9/10 Impresionantes agujas y farallones de piedra caliza que encajonan el cauce del río Gallo, pinares densos silvestres y avifauna rupícola protegida. Cómo llegar: Estructura adaptada con barandilla en el borde de la plataforma, accesible desde el camino de la ermita. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19222','mirador','Mirador de la Sierra de Caldereros y del Castillo','7.6/10 Magnífica perspectiva de las caprichosas formas de arenisca rojiza erosionada de la sierra, sabinares milenarios, campos de cultivo e idóneo entorno astronómico. Cómo llegar: Crestas de arenisca accesibles por pista forestal que comunica con la ermita del Santo Cristo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19223','mirador','Mirador de la Machá (Hoces del Tajo)','8.8/10 Extraordinario y vertiginoso balcón sobre el cañón del río Tajo, formaciones kársticas, saltos de agua estacionales, densos pinares y nitidez astronómica. Cómo llegar: Estructura de madera con barandillas y paneles informativos del Parque Natural en la subida al puerto. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19224','mirador','Alto de la Cuesta Agrícola','6.6/10 Sencilla panorámica sobre los llanos cerealistas de la Alcarria meridional, campos ondulados de secano e idóneo horizonte nocturno para astrofotografía. Cómo llegar: Camino rural en el extremo nororiental del término, transitable por pistas agropecuarias. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19225','mirador','Mirador de la Alcarria Alta','6.8/10 Perspectiva sobre la plataforma horizontal del páramo, encinares dispersos, matorral mediterráneo de jara e integración residencial moderna periférica. Cómo llegar: Zona alta ajardinada con accesos urbanos peatonales en el límite norte del casco urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19226','mirador','Mirador de la Sierra de Alto Rey','7.9/10 Espectacular e ininterrumpida panorámica del macizo de pizarra, brezales de montaña, pinares de repoblación forestal y cielos de pureza excepcional. Cómo llegar: Saliente natural del páramo alpino accesible por pistas de montaña desde el núcleo urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19227','mirador','Alto del Teso de la Iglesia','7.1/10 Vista despejada de la dehesa molinesa oriental, campos de secano de gran altitud, sabinas dispersos e idóneo punto para astrofotografía. Cómo llegar: Atrio elevado del templo de la Asunción, en las eras altas de la localidad de Chera. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19228','mirador','Mirador de las Lagunas de Beleña','7.2/10 Vista ornitológica sobre humedales estacionales esteparios, idónea para avistamiento de grullas, ánsares, garzas reales y el somontano de la Sierra Norte. Cómo llegar: Casetas de observación acondicionadas en el entorno protegido de la cubeta lagunar. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19229','mirador','Mirador de los Cárcavas de Arcilla Roja','7.8/10 Impresionante relieve de cárcavas y barrancos de arcilla roja fuertemente erosionados, olivos centenarios, sotos fluviales del Jarama y el pueblo integrado. Cómo llegar: Borde del talud geográfico acondicionado al este del núcleo, desvío señalizado. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19230','mirador','Mirador del Arroyo del Val','6.0/10 Perspectiva sobre la Campiña arcillosa del Henares, campos llanos de cereal de secano y el contraste del desarrollo logístico e industrial periurbano. Cómo llegar: Paseo peatonal perimetral acondicionado junto a las zonas ajardinadas residenciales de la localidad. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19231','mirador','Mirador de la Sierra de la Bodera','7.4/10 Espectacular vista del macizo montañoso de pizarra, laderas escarpadas cubiertas de matorral bajo, encinas jóvenes y un horizonte celeste despejado. Cómo llegar: Cota natural elevada al norte de la población, accesible por pistas forestales de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19233','mirador','Mirador del Valle de la Alcarria Baja','7.1/10 Vista de las laderas boscosas encajonadas, encinares maduros, huertas tradicionales de ribera y la fisonomía del casco urbano rural tradicional. Cómo llegar: Saliente natural de la plataforma del páramo, transitable por caminos desde el pueblo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19234','mirador','Mirador del Monasterio de Santa María de Bonaval','8.3/10 Extraordinaria vista de las evocadoras ruinas gótico-cistercienses del siglo XII, el desfiladero calizo del río Jarama, quejigares y cielos oscuros. Cómo llegar: Sendero pedestre acondicionado en la cornisa que domina el conjunto monumental protegido. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19235','mirador','Mirador del Valle del Milagros y Cueva de los Casares','8.2/10 Impresionante corte de arenisca roja y calizas en el cañón del río Linares, sabinares milenarios, nidos de rapaces y el entorno arqueológico paleolítico. Cómo llegar: Plataforma con valla protectora sobre el farallón rocoso de la cueva, acceso señalizado. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19237','mirador','Mirador del Bosque Petrificado y Gallo','7.6/10 Singular relevancia geológica del Pérmico, vistas de las formaciones de arenisca rojiza, el valle del río Gallo y pinares silvestres densos. Cómo llegar: Punto acondicionado con paneles didácticos de la red del Geoparque de Molina, carretera N-211. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19238','mirador','Alto del Teso de San Juan','7.0/10 Vista despejada de la paramera norteña, campos agrícolas de secano, pequeños encinares dispersos y horizontes limpios libres de obstáculos industriales. Cómo llegar: Elevación natural del terreno transitable a pie por caminos vecinales al norte del caserío. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19239','mirador','Mirador del Aeródromo y la Campiña','6.6/10 Vista diáfana de las llanuras cerealistas, idónea para la fotografía del atardecer castellano y la observación de actividades deportivas de aviación general. Cómo llegar: Entorno perimetral exterior de las pistas del aeródromo de Robledillo, acceso rodado. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19240','mirador','Mirador de la Cuesta del Rey y los Robledales','7.4/10 Perspectiva sobre los densos robledales melojos del somontano, valles menores de jara, y el entorno que cita el Cantar de Mio Cid. Cómo llegar: Borde del páramo occidental, transitable por pistas rurales desde la carretera CM-1001. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19241','mirador','Alto del Cerro de las Cruces','7.3/10 Panorámica sobre los campos cerealistas de la Serranía, lomas arcillosas, matorral mediterráneo y un cielo nocturno catalogado por su oscuridad astronómica. Cómo llegar: Promontorio suave al este de la localidad, transitable a pie desde la iglesia de San Andrés. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19242','mirador','Mirador de la Vega del San Andrés','7.2/10 Vista panorámica del curso encajonado del río San Andrés, escarpes calizos de los páramos de la Alcarria alta, huertas y olivares tradicionales. Cómo llegar: Saliente natural de la plataforma calcárea acondicionado con valla de madera, acceso por sendero. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19243','mirador','Alto del Calvario y Paramera','7.1/10 Vista despejada de la estepa fría molinesa, formaciones de piedra caliza, pastizales de ganado ovino y horizontes limpios idóneos para astrofotografía. Cómo llegar: Pequeña elevación coronada por restos tradicionales al norte de la población. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19244','mirador','Mirador de los Sabinares y Alto Tajo','7.7/10 Vista de las vertientes forestales de transición de la Alcarria al Alto Tajo, extensas masas de sabina albar milenaria y quejigares autóctonos densos. Cómo llegar: Borde de la plataforma calcárea accesible por pistas forestales al sur del núcleo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19245','mirador','Mirador del Alto de San Julián y Entrepeñas','8.5/10 Espectacular e icónica panorámica sobre la presa del Embalse de Entrepeñas, las gargantas calizas de la Boca del Infierno y el mar de Castilla. Cómo llegar: Atalaya rocosa acondicionada con barandillas y paneles informativos de la red turística, acceso por pista transitable. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19246','mirador','Mirador de las Salinas de San Juan','7.8/10 Vista etnográfica y monumental del complejo artesanal de extracción de sal continental, norias de madera, pozas e laderas calizas cubiertas de encinar. Cómo llegar: Plataforma elevada con paneles didácticos junto a las salinas históricas protegidas BIC, acceso directo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19247','mirador','Mirador de la Hoya del Infantado y Guadiela','7.6/10 Amplia perspectiva de los límites orientales de la Alcarria, fértiles dehesas agrícolas, olivares centenarios y el curso fluvial ancho del río Guadiela. Cómo llegar: Cornisa del páramo sur adaptada con área de descanso y mirador en los accesos del pueblo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19248','mirador','Alto del Congosto y Río Bornova','6.9/10 Vista de la garganta del río Bornova aguas abajo de la presa de Pálmaces, laderas escarpadas arcillosas, matorral mediterráneo y campos cerealistas. Cómo llegar: Elevación natural perimetral al este de la pequeña localidad, accesible a pie. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19249','mirador','Alto del Páramo de San Andrés','6.7/10 Sencilla panorámica sobre la planicie horizontal alcarreña, cultivos de secano, encinas aisladas y cielos nocturnos óptimos para la observación estelar. Cómo llegar: Camino rural elevado en el extremo oriental del municipio, accesible por pistas de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19250','mirador','Alto del Cerro del Castillo','7.1/10 Perspectiva sobre la vega baja del río Reguilona, cultivos agrícolas de secano del somontano de Sigüenza e idóneo punto para astrofotografía. Cómo llegar: Promontorio rocoso elevado al norte de la población, transitable a pie por sendas ganaderas. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19251','mirador','Mirador del Valle del Río Saúca y la Iglesia','7.4/10 Vista del valle menor arcilloso, olivares, encinares del páramo y el espléndido pórtico románico de la iglesia de la Asunción del siglo XII. Cómo llegar: Borde del escarpe calcáreo junto a la carretera N-2, con fácil parada de vehículos. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19252','mirador','Mirador del Castillo de Zorita y el Tajo','8.1/10 Vista del curso fluvial ancho del Tajo alcarreño, la vega arqueológica de Recópolis, olivares y las ruinas de la inexpugnable fortaleza militar andalusí. Cómo llegar: Explanada de la fortaleza islámica en el cerro colindante, accesible con la ruta monumental. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19254','mirador','Mirador de los Monolitos de Selas','7.5/10 Singular relieve de agujas y formaciones caprichosas de arenisca roja erosionada (torres de Selas), rodeadas de densas masas de pino resinero. Cómo llegar: Sendero señalizado en la carretera N-211 con zona de estacionamiento y paneles informativos del Geoparque. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19901','mirador','Mirador del Pico de la Torrecilla','8.3/10 Soberbia visual de la Sierra de Ayllón meridional, valles profundos de pizarra, brezales, robledales y cielos nocturnos certificados de nitidez astronómica. Cómo llegar: Cumbre cónica exenta al norte de la localidad, accesible mediante sendero de montaña a pie. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19255','mirador','Mirador de las Minas de Hierro y Paramera','7.4/10 Paisaje minero a cielo abierto modificado por las antiguas explotaciones de hierro, lagunas de cantera estacionales, estepa fría molinesa y sabinas dispersas. Cómo llegar: Zona perimetral segura acondicionada de las antiguas cortas mineras, acceso por la GU-411. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19256','mirador','Alto de la Cuesta del Castillo','7.2/10 Perspectiva sobre el nacimiento del río Salado, lomas arcillosas dedicadas al cultivo de secano y la silueta rural tradicional de piedra del pueblo. Cómo llegar: Promontorio situado al norte de la localidad, transitable por sendas agrícolas. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19257','mirador','Mirador de la Fortaleza y del Valle del Henares','9.1/10 Extraordinaria panorámica sobre el conjunto histórico medieval, las agujas catedralicias, el cauce del río Henares y los pinares y encinares protegidos del parque. Cómo llegar: Explanada de los adarves transitables del inmenso castillo-palacio fortificado de los Obispos, actual Parador. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19258','mirador','Mirador de las Escarpas del Tajuña','7.2/10 Vista del profundo tajo calcáreo erosionado por el río Tajuña, masas de encina y quejigo de ladera, campos de lavanda y horizontes nítidos. Cómo llegar: Borde del páramo accesible por pistas rurales desde el casco urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19259','mirador','Mirador de la Laguna de Somolinos y Sierra de Pela','8.4/10 Impresionante vista de la laguna cárstica de origen travertínico al pie de los paredones calizos de la sierra, matorral de montaña y avifauna. Cómo llegar: Sendero adaptado con pasarelas de madera y paneles del espacio protegido, acceso por la CM-110. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19261','mirador','Alto del Páramo del Ducado','7.4/10 Vista de las inmensas llanuras forestales de pinares centenarios de pino silvestre, brezales, sabinas aisladas e idónea pureza astronómica nocturna. Cómo llegar: Plataforma superior calcárea accesible por pistas forestales de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19262','mirador','Mirador de la Ciudad Encantada de Tamajón','85/10 Extraordinario paisaje kárstico de caprichosas formas de roca caliza (arcos, callejones y torcas), sabinares milenarios y la silueta imponente del Ocejón. Cómo llegar: Entorno natural acondicionado junto a la ermita de los Enebrales, carretera GU-186 con aparcamiento. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19263','mirador','Alto del Teso de la Iglesia','6.3/10 Sencilla panorámica de la vega baja del río Henares y del arroyo Badiel, campos llanos de cereal de secano y puestas de sol limpias. Cómo llegar: Atrio elevado perimetral al templo barroco, en el centro urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19264','mirador','Mirador de la Laguna de Taravilla','8.6/10 Espectacular e icónica estampa de la laguna de alta montaña de origen cárstico rodeada de densos pinares, el cañón del Tajo y farallones rocosos. Cómo llegar: Plataforma natural adaptada con paneles del Parque Natural del Alto Tajo accesible por pista de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19266','mirador','Mirador de las Ruinas de Santa Ana','7.6/10 Vista panorámica del encajonamiento de la villa alcarreña, sus famosas calles con soportales medievales, olivares centenarios y los restos del monasterio. Cómo llegar: Cima del cerro del cementerio y convento que flanquea el norte del pueblo, acceso peatonal. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19267','mirador','Alto del Páramo de Terzaga','7.4/10 Vista despejada de la paramera molinesa suroccidental, dehesas altas de encina y sabina, campos de cereal e idóneo punto Starlight nocturno. Cómo llegar: Plataforma calcárea elevada transitable por pistas rurales de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19268','mirador','Mirador de la Casa Fuerte de Vega de Arias','7.8/10 Hermosa estampa que combina el monumento fortificado del siglo XIV, la vega del río Bullones, densos sabinares y encinares del Geoparque. Cómo llegar: Explanada de la vega fluvial adyacente al complejo histórico, acceso por la carretera GU-412. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19270','mirador','Alto del Teso Rural','6.6/10 Sencilla panorámica rural de lomas onduladas de secano del somontano norteño, matorral mediterráneo y horizontes despejados para astrofotografía. Cómo llegar: Cota natural elevada al norte de la población, cercana a las eras tradicionales. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19272','mirador','Alto de la Muela de Tordesilos','7.1/10 Extensa visual de la paramera molinesa oriental, campos de cereal a gran altitud, sabinares dispersos y horizontes limpios idóneos para astroturismo. Cómo llegar: Plataforma tabular calcárea al este del término, transitable por sendas agropecuarias de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19274','mirador','Torre del Homenaje del Castillo de Torija','8.1/10 Espectacular e histórica panorámica del páramo alcarreño, el valle de Torija, los campos de lavanda y el trazado de la autovía A-2. Cómo llegar: Remate superior visitable del castillo del siglo XV, sede del Centro de Interpretación Turística de Guadalajara. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19279','mirador','Mirador del Valle del Badiel','6.2/10 Sencilla perspectiva rural sobre los llanos aluviales fértiles de regadío, cultivos hortícolas locales y el cercano monasterio de Sopetrán. Cómo llegar: Margen de la terraza fluvial, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19278','mirador','Mirador del Barranco del río Cifuentes','7.2/10 Hermosa panorámica del encajonamiento fluvial, laderas calizas cubiertas de pino silvestre, quejigos autóctonos y un cielo nocturno muy oscuro. Cómo llegar: Saliente natural del páramo acondicionado con vallado de protección en el flanco este del pueblo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19280','mirador','Mirador de la Campiña Alta','6.1/10 Vista periurbana de la Campiña del Henares, campos ondulados de secano, dehesas dispersas y la urbanización integrada del entorno residencial. Cómo llegar: Zona alta ajardinada con accesos peatonales en el extremo de la urbanización Las Castillas. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19281','mirador','Alto de la Ermita y Valle del Cañamares','6.8/10 Vista del cauce encajonado del río Cañamares, matorral mediterráneo, encinas jóvenes y un relieve suave con horizontes limpios de obstáculos. Cómo llegar: Colina exenta que alberga el templo, transitable a pie desde el casco urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19282','mirador','Mirador de Pelegrina y Valle del Dulce','7.7/10 Magnífica perspectiva de las hoces y cortados calizos calcáreos, bosques de ribera y la silueta del castillo medieval de Pelegrina al fondo. Cómo llegar: Borde del páramo norte, dentro del término asociado a las pedanías del Parque Natural. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19283','mirador','Mirador del Alto del Pinar','7.4/10 Vista focalizada en la densa masa forestal de pino silvestre de la comarca molinesa, sabinares milenarios e idónea pureza Starlight nocturna. Cómo llegar: Pista de servicio forestal elevada, accesible al oeste del núcleo urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19284','mirador','Alto del Teso del Humilladero','6.7/10 Panorámica de los valles menores del sistema Ibérico molinés, cultivos cerealistas, campos de jara y nítidos horizontes mesetarios. Cómo llegar: Pequeña elevación natural al norte de la población, cercana a las eras tradicionales. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19285','mirador','Mirador de la Paramera de Torrubia','6.8/10 Vista limpia de la estepa fría molinesa, campos agrícolas de gran altitud, formaciones de piedra caliza y cielos nocturnos sin contaminación. Cómo llegar: Elevación natural del terreno transitable a pie por caminos vecinales al sur del caserío. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19286','mirador','Mirador del cerro de San Cristóbal','6.7/10 Vista panorámica del Valle del Henares bajo, cultivos arcillosos de secano, la silueta industrial de la capital provincial y lomas alcarreñas. Cómo llegar: Cima suave del cerro acondicionado con accesos urbanos peatonales en la periferia del núcleo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19287','mirador','Mirador del Laguna de Gallocanta y Paramera','7.2/10 Vista lejana de la cuenca endorreica, campos cerealistas infinitos, sabinas dispersas e idóneo punto de observación de aves migratorias estacionales. Cómo llegar: Cornisa del páramo oriental accesible por pistas agrícolas desde la carretera CM-210. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19288','mirador','Mirador de los Cortados del Jarama','7.8/10 Espectaculares e imponentes escarpes de roca caliza y pizarra sobre el río Jarama, jarales espesos, nidos de rapaces e infinitos horizontes serranos. Cómo llegar: Borde del talud calizo occidental, accesible por pistas forestales de montaña. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19289','mirador','Mirador de la Ermita de San Cristóbal y los Sabinares','7.6/10 Soberbia visual a más de 1400 metros de altitud sobre el Parque Natural, dehesas altas de encina y sabina e idóneo punto Starlight. Cómo llegar: Entorno rocoso elevado de la ermita, accesible por pista de tierra apta para vehículos. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19290','mirador','Mirador de la Alcarria (Balcón de la Alcarria)','7.9/10 Impresionante balcón natural sobre el Valle del Badiel, escarpes calizos calcáreos, encinares dispersos y el horizonte infinito de la llanura castellana. Cómo llegar: Cornisa acondicionada con barandillas, paneles explicativos y bancos en el borde de la muralla urbana. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19291','mirador','Mirador de las Tetas de Viana','8.7/10 Excepcional panorámica de 360 grados sobre el Valle del Tajo, los dos cerros testigo gemelos, densos pinares, encinares e idóneo entorno astronómico. Cómo llegar: Cima caliza de la meseta de Viana, accesible por sendero de montaña acondicionado con escaleras de hierro. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19293','mirador','Mirador de la Charcuela y Río Jarama','7.8/10 Hermosa vista de las cárcavas arcillosas rojizas del río Jarama, el denso bosque de ribera, la campiña baja y las cumbres de la Sierra. Cómo llegar: Terraza natural acondicionada con barandillas en el casco antiguo amurallado de la villa. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19297','mirador','Alto de la Ermita de San Isidro','6.3/10 Sencilla panorámica del Valle del río Ungría bajo, campos ondulados de secano e idóneo horizonte nocturno para la fotografía de estrellas. Cómo llegar: Atrio elevado de la ermita, en el punto alto del término rural. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19298','mirador','Mirador del Valle del Badiel','6.6/10 Perspectiva sobre el pequeño valle del arroyo Badiel, olivares alcarreños, campos de cereal y chimeneas de tradicionales bodegas excavadas. Cómo llegar: Parte superior del cerro horadado por las bodegas subterráneas, al oeste del núcleo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19299','mirador','Mirador del Valle del Ungría','6.8/10 Vista del encajonamiento del río Ungría entre laderas escarpadas calcáreas, vegas de cultivo fértiles, quejigares y encinares de páramo. Cómo llegar: Saliente natural del páramo accesible por caminos rurales desde la carretera GU-907. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19300','mirador','Mirador de la Urbanización Sotolargo','6.2/10 Vista de las terrazas fluviales de la Campiña, cultivos de secano y encinares dispersos integrados en el entorno residencial moderno. Cómo llegar: Zona alta ajardinada en la cornisa del complejo residencial periurbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19301','mirador','Mirador del río Tajuña y las Cárcavas','7.1/10 Vista de la vega del río Tajuña medio, olivares tradicionales alcarreños, cultivos cerealistas, formaciones de arcilla erosionadas y sotos fluviales. Cómo llegar: Entorno elevado de la plataforma del páramo occidental, accesible mediante camino vecinal de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19302','mirador','Alto del Teso de San Roque','6.6/10 Sencilla panorámica de las lomas alcarreñas arcillosas, campos ondulados de secano e idóneo horizonte nocturno para astrofotografía de baja luminosidad. Cómo llegar: Colina exenta que alberga la ermita, transitable a pie desde el casco urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19303','mirador','Alto de la Muela de Valdelcubo','6.9/10 Vista limpia de la paramera siguntina septentrional, encinares dispersos, cultivos de cereal de secano y nítidos horizontes libres de postes industriales. Cómo llegar: Plataforma calcárea elevada accesible por pistas forestales al sur del término. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19305','mirador','Mirador de las Cárcavas de Valdepeñas','8.4/10 Impresionante y caótico colapso geológico de pináculos arcillosos rojizos (chimeneas de hadas) sobre el Jarama, jarales y matorral de montaña. Cómo llegar: Balcón natural acondicionado en el borde del precipicio arcilloso, accesible por sendero desde la GU-1063. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19306','mirador','Mirador del Valle del Tajuña','7.2/10 Hermosa vista de las vertientes boscosas de la Alcarria alta, encinares maduros en las laderas, quejigares, huertas de ribera y el cauce fluvial. Cómo llegar: Cornisa natural alta al este del núcleo, accesible por caminos rurales. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19307','mirador','Mirador del Puente Medieval y Cañón del Jarama','7.9/10 Espectacular tajo de pizarras y calizas excavado por el río Jarama, bosques de ribera, el puente histórico y matorral denso de jara. Cómo llegar: Saliente acondicionado junto a las sendas de senderismo de la Arquitectura Negra, acceso rural. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19308','mirador','Mirador del Castillo y Vega del Tajuña','7.5/10 Perspectiva sobre la fértile vega del Tajuña, la arquitectura civil medieval de la fortaleza y los escarpes de los páramos alcarreños linderos. Cómo llegar: Explanada de la antigua fortaleza del siglo XV en la cota más elevada de la villa. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19309','mirador','Alto de la Paramera de Valhermoso','7.0/10 Vista limpia de la paramera molinesa meridional, sabinares dispersos, cultivos de cereal de secano y nítidos horizontes mesetarios Starlight. Cómo llegar: Plataforma calcárea elevada accesible por pistas forestales al sur del término. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19310','mirador','Mirador del Tajo y de la Ermita de San Donato','8.4/10 Impresionante cañón granítico encajonado del río Tajo, densas masas de pino silvestre, buitreras en las paredes verticales y Parque Natural. Cómo llegar: Saliente acondicionado con paneles de la red del Parque Natural del Alto Tajo, acceso por la CM-2101. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19311','mirador','Mirador de las Chorreras de Despeñalagua','8.8/10 Extraordinaria e imponente cascada de más de 120 metros esculpida en la pizarra, huertas serranas, castañares centenarios y el Pico Ocejón. Cómo llegar: Plataforma acondicionada con barandilla al final del sendero pedestre señalizado que parte de la villa. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19317','mirador','Mirador de la Sima de Alcorón','8.1/10 Singular paisaje geológico kárstico rodeado de un denso mar de pino silvestre, pozas naturales, dolinas e idóneo punto para astrofotografía. Cómo llegar: Entorno perimetral acondicionado y protegido de la gran sima transitable, acceso por pista forestal. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19318','mirador','Alto del Teso de San Roque','6.6/10 Sencilla panorámica de la Campiña arcillosa, campos ondulados de secano e idóneo horizonte nocturno para la observación de lluvias de estrellas. Cómo llegar: Atrio elevado de la ermita, en el punto alto del casco urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19319','mirador','Mirador del Canal del Henares y las Terrazas','6.2/10 Perspectiva sobre la Campiña baja, campos agrícolas tradicionales de regadío y la transición hacia el polígono industrial periurbano. Cómo llegar: Pasarela peatonal y talud junto al trazado del Canal, sector norte urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19322','mirador','Mirador del Valle del Henares','6.8/10 Vista panorámica del curso medio del río Henares, plantaciones de cereal, lomas arcillosas y el somontano de la Sierra de Ayllón. Cómo llegar: Margen de la terraza fluvial, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19323','mirador','Mirador de Villaseca de Uceda','Cómo llegar: Cota natural elevada al norte de la población, cercana a las antiguas eras de trilla. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19324','mirador','Mirador del Castillo de los Funes y Valle del Mesa','7.8/10 Impresionantes farallones y paredes calizas verticales que encajonan el río Mesa, la fortaleza rocosa medieval y nidos de rapaces. Cómo llegar: Cima rocosa que domina el caserío, accesible mediante sendero pedestre empinado. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19325','mirador','Alto de la Cuesta de las Viñas','6.3/10 Sencilla visual de campos de secano de la campiña alta y olivares rústicos, óptimo para capturar atardeceres limpios de elementos industriales. Cómo llegar: Camino rural en los límites geográficos orientales del municipio. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19326','mirador','Mirador del Observatorio de Yebes y Alcarria','7.4/10 Magnífica perspectiva de la plataforma horizontal del páramo alcarreño, campos de cultivo, encinares y el entorno del gran centro astronómico nacional. Cómo llegar: Zona perimetral alta con estacionamiento en los accesos del complejo del Observatorio de Yebes. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19327','mirador','Mirador de la Ermita de la Virgen de la Soledad','7.1/10 Vista de la vega del arroyo de la Vega, olivares alcarreños meridionales, campos de cereal y relieves del sinclinal de Altomira. Cómo llegar: Explanada de la ermita al oeste del casco urbano, provista de accesos rodados. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19329','mirador','Mirador del Valle del San Andrés','6.8/10 Vista del encajonamiento del arroyo de San Andrés, taludes calizos de los páramos de la Alcarria alta, huertas y olivares tradicionales. Cómo llegar: Borde oriental de la plataforma calcárea, accesible por sendas desde el pueblo. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19330','mirador','Alto del Páramo de Yélamos','6.9/10 Vista de la planicie del páramo calizo, encinares dispersos, matorral mediterráneo de lavanda y un cielo nocturno libre de contaminación lumínica. Cómo llegar: Borde norte del término, transitable por pistas agrícolas de tierra. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19331','mirador','Mirador del Canal del Henares','6.4/10 Vista panorámica de los llanos aluviales fértiles de regadío, cultivos hortícolas, arbolado lineal de las acequias y la Campiña. Cómo llegar: Pasarela peatonal y talud junto al trazado del Canal del Henares, sector norte urbano. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19335','mirador','Mirador de la Alcazaba y de Recópolis','8.6/10 Espectacular e histórica panorámica del meandro del río Ebro/Tajo, el puente medieval, la alcazaba islámica del siglo IX y la única ciudad palatina visigoda europea. Cómo llegar: Corona superior y adarves de la alcazaba o plataforma del Parque Arqueológico de Recópolis. ¡PROVINCIA DE GUADALAJARA COMPLETADA AL 100%! 🏁 ⭐ Si estás de acuerdo, pasamos de inmediato en el orden nacional a la siguiente provincia: Provincia de Cuenca (Comunidad de Castilla-La Mancha), comenzando desde la letra A con municipios como Abia de la Obispalía, Alarcón, Albaladejo del Cuende, Albalate de las Nogueras, Albendea, La Alberca de Záncara, Alcalá de la Vega, Alcantud, etc. Dime, ¿activamos el inicio del bloque masivo de la Provincia de Cuenca?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90304','mirador','Mirador del Castillo y Peña del Cuervo','7.4/10 Espectacular perspectiva del valle del río Moscardón, las caprichosas formaciones de roca caliza erosionada, el cementerio medieval y horizontes limpios de la Serranía Media. Cómo llegar: Promontorio rocoso del antiguo castillo, accesible por sendero peatonal escalonado desde el casco urbano. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14001','mirador','Mirador de la Torre de Armas y la Torre del Campo','9.2/10 Impresionante e icónica panorámica de 360 grados sobre el profundo meandro encajonado del río Júcar, las murallas medievales, iglesias góticas y el mar del embalse. Cómo llegar: Adarves transitables y torres defensivas del conjunto fortificado, accesible con la entrada turística a la villa. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90305','mirador','Mirador del Cerro de San Cristóbal','6.7/10 Vista diáfana de la llanura de la Manchuela conquense, cultivos tradicionales de secano, dehesas dispersas y un horizonte óptimo para la astrofotografía. Cómo llegar: Elevación natural al norte de la población, transitable a pie o en vehículo por camino de tierra. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90306','mirador','Mirador de los Cortados del río Trabaque','7.2/10 Hermosa vista de las paredes de roca caliza rojiza calcinadas que encajonan el río, huertas tradicionales de ribera, chopera lineal y nidos de rapaces. Cómo llegar: Saliente acondicionado con valla protectora en la pista agrícola que sube al páramo norte. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90307','mirador','Mirador del Mausoleo de Llanes y Río Guadiela','7.5/10 Vista arqueológica y de naturaleza sobre el valle del Guadiela, bosques de ribera y el singular monumento funerario romano del siglo IV d.C. Cómo llegar: Entorno acondicionado junto al yacimiento histórico, desvío señalizado desde la carretera CM-2023. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90826','mirador','Alto de la Ermita de San Isidro','6.3/10 Sencilla panorámica rural de la llanura manchega, extensos viñedos, campos de cereal planos e idóneo punto para la captura de puestas de sol limpias. Cómo llegar: Explanada de la ermita situada en las eras altas, al sur del núcleo urbano. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90827','mirador','Mirador de la Fortaleza del Cabriel y Santo Domingo','7.6/10 Magnífica visual de las hoces del río Cabriel, frondosos bosques de pino silvestre, restos de muros califales e impresionantes agujas calizas kársticas. Cómo llegar: Cresta caliza elevada sobre el desfiladero, acceso pedestre por sendero local de montaña. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90308','mirador','Mirador de la Hoz de Alcantud','7.9/10 Impresionante grieta caliza de paredes verticales del Parque Natural de la Serranía, pozas de agua cristalina, nidos de buitres y cielos Starlight nocturnos puros. Cómo llegar: Estructura adaptada con paneles didácticos e hitos en el borde del cañón, acceso por la LR-2015/CM-210. Si quieres, indícame si pasamos directamente al siguiente bloque masivo de los municipios restantes con la letra A, B y C de la Provincia de Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90309','mirador','Alto de la Iglesia de Santo Tomás','6.1/10 Vista diáfana de la Mancha Alta conquense, extensos campos de cultivo de secano, relieve de lomas suaves y nítidos atardeceres castellanos. Cómo llegar: Atrio elevado del templo góticorenacentista, en el centro del núcleo urbano. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90310','mirador','Alto del Teso de San Roque','6.4/10 Panorámica sobre el paisaje ondulado de la Alcarria Conquense, olivares rústicos, parcelas cerealistas y horizontes despejados óptimos para astrofotografía. Cómo llegar: Pequeña colina al norte de la localidad, accesible por pistas rurales de tierra. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90311','mirador','Mirador del Cerro de la Virgen de la Cuesta','7.8/10 Espectacular atalaya sobre el Valle del Cigüela, restos arqueológicos de un castro celtíbero, campos de labor y nula contaminación lumínica nocturna. Cómo llegar: Cima del cerro testigo coronado por la ermita, acceso por pista asfaltada. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90312','mirador','Mirador del Castillo y Serranía Alta','7.9/10 Extraordinaria vista de montaña a más de 1200 metros, profundos valles forestales con pinares densos, dehesas altas y un cielo Starlight certificado. Cómo llegar: Ruinas de la antigua fortaleza medieval sobre la cresta rocosa del pueblo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90828','mirador','Mirador del Pico de la Raposera','8.1/10 Impresionante panorama de la Serranía Baja fronteriza con Valencia, afloramientos de arenisca roja, pinares de pino resinero y nidos de aves rapaces. Cómo llegar: Vértice geodésico elevado en las cumbres del término, accesible por pistas forestales. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90743','mirador','Alto del Calvario y la Vega','6.3/10 Vista de las llanuras agrícolas manchegas dedicadas al girasol y cereal, olivares integrados y cielos despejados para fotografía meteorológica. Cómo llegar: Promontorio suave al oeste del núcleo urbano, transitable a pie. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90313','mirador','Mirador de la Torre del Reloj y los Pinares','7.2/10 Vista focalizada en la inmensa masa forestal de la Manchuela norteña, pinares densos, sendas micológicas y perfiles urbanos tradicionales. Cómo llegar: Entorno elevado de la torre histórica en el sector más alto del casco urbano. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90314','mirador','Mirador del Cerro de la Ermita de San Blas','7.4/10 Vista de la llanura central conquense, campos de labor ondulados y el escenario paisajístico de la célebre fiesta de la Endiablada. Cómo llegar: Explanada de la ermita, accesible desde el casco urbano por camino señalizado. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90315','mirador','Mirador del Valle del Río Altarejos','6.9/10 Vista del cauce encajonado, vegas agrícolas de fondo de valle, laderas arcillosas cubiertas de encinar joven y pinares aislados. Cómo llegar: Borde de la plataforma calcárea occidental, transitable por sendas agropecuarias. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90316','mirador','Mirador de las Cárcavas y Río Vindel','7.0/10 Paisaje alcarreño erosionado en arcillas y yesos, huertas tradicionales de ribera, chopera lineal y horizontes limpios libres de obstáculos. Cómo llegar: Talud geográfico acondicionado al norte del pequeño núcleo urbano. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16905','mirador','Mirador de la Dehesa y Lagunas de Arcas','7.5/10 Hermoso complejo lagunar de origen kárstico, idóneo para el avistamiento de aves acuáticas protegidas, praderas húmedas y bosque mediterráneo integrado. Cómo llegar: Observatorio acondicionado con paneles en el perímetro protegido de las lagunas. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90830','mirador','Mirador del Escondel y Cañón del Escabas','8.4/10 Sobrecogedor escarpe calizo sobre el río Escabas, profundas grietas rocosas, quejigares de montaña, colonias de buitre leonado y pureza astronómica nocturna. Cómo llegar: Cornisa natural alta dentro del Parque Natural de la Serranía de Cuenca. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90317','mirador','Mirador de las Peñas Rojas','7.6/10 Singular formación geológica de areniscas y conglomerados de color rojizo, rodeada de densas masas de pino resinero y matorral mediterráneo. Cómo llegar: Cresta rocosa accesible por pista forestal desde la carretera N-420. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90318','mirador','Alto de la Cuesta de las Bodegas','6.6/10 Vista del pequeño valle alcarreño, olivares de ladera, cultivos cerealistas de secano e hileras de chimeneas de tradicionales calados subterráneos. Cómo llegar: Cota superior del montículo de las bodegas, accesible a pie desde el núcleo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90319','mirador','Mirador del cerro de la Atalaya','6.8/10 Panorámica estratégica del nudo de comunicaciones de la Mancha oriental, dehesas de encina dispersas, llanuras infinitas y horizontes nocturnos despejados. Cómo llegar: Vértice topográfico junto a las ruinas de la antigua torre óptica medieval. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90320','mirador','Mirador del Pozo Airón y Vega del Tagariga','7.3/10 Vista de las cárcavas arcillosas, olivares tradicionales de ladera, cultivos extensivos e integración con parajes lacustres estacionales singulares. Cómo llegar: Saliente natural de la plataforma del páramo occidental, acceso por pistas rurales. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16029','mirador','Mirador del Castro Celtíbero de Fuente de la Negra','7.8/10 Extraordinaria visual arqueológica y de naturaleza sobre la Manchuela central, encinares maduros, dehesas ganaderas e idóneo punto para astrofotografía. Cómo llegar: Entorno acondicionado del yacimiento fortificado de la Edad del Hierro, acceso señalizado. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16030','mirador','Alto del Páramo de San Pedro','7.7/10 Perspectiva de las laderas calizas del somontano de la Serranía, densos pinares, quejigos aislados y un cielo nocturno de gran oscuridad. Cómo llegar: Cornisa del páramo accesible por pistas forestales desde el pueblo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16031','mirador','Mirador del Alto de la Nava y Cañón del Júcar','8.6/10 Espectacular e infinita panorámica de valles kársticos, muelas calcáreas, densos pinares silvestres de la Serranía Alta e idónea pureza Starlight. Cómo llegar: Plataforma acondicionada con paneles informativos en las cumbres forestales del municipio. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16032','mirador','Mirador de las Salinas y del Castillo','6.7/10 Vista del paisaje erosionado de arcillas, yesos y antiguas explotaciones de sal, campos de cultivo de secano y la silueta fortificada medieval. Cómo llegar: Promontorio elevado junto a las ruinas defensivas, sector norte urbano. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16033','mirador','Mirador de los Molinos y Castillo de Belmonte','8.9/10 Impresionante e icónica estampa monumental de la fortaleza gótico-mudéjar del siglo XV, la línea de molinos de viento y la llanura manchega infinita. Cómo llegar: Cerro de los Molinos de viento, acondicionado con accesos rodados y paseos peatonales. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16034','mirador','Mirador del Embalse de Alarcón y Júcar','7.2/10 Vista de las aguas embalsadas del río Júcar rodeadas de lomas arcillosas cubiertas de pino, espectaculares puestas de sol y pesca deportiva. Cómo llegar: Margen de la represa accesible por pistas rurales transitables desde el núcleo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16035','mirador','Mirador de la Hoz de Beteta y Castillo de Rochafrida','8.9/10 Imponente y majestuoso cañón calizo del río Guadiela, paredes verticales de más de 80 metros, densos tilares, acebedos, nidos de rapaces y castillo medieval. Cómo llegar: Plataforma volada acondicionada con barandilla en el borde del desfiladero, carretera CM-210. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16036','mirador','Mirador del Pico de la Garita y los Canales','8.5/10 Espectacular paisaje de la Serranía de Cuenca oriental, formaciones caprichosas de arenisca roja (rodeno), cañones fluviales profundos del Cabriel y densos pinares. Cómo llegar: Atalaya rocosa natural accesible por sendero de montaña señalizado desde la localidad. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16038','mirador','Alto del Teso rural','6.4/10 Sencilla panorámica rural de los campos de secano de la Alcarria meridional, pequeñas parcelas de olivar y horizontes despejados para astrofotografía. Cómo llegar: Elevación natural del terreno transitable por caminos vecinales de tierra. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16040','mirador','Mirador de la Ciudad Encantada de Buenache','83/10 Magnífico entorno kárstico de torcas, callejones de piedra erosionada, pinares densos de pino laricio y cielos nocturnos de nitidez Starlight excepcional. Cómo llegar: Senderos locales adaptados e integrados en la red geológica de la Serranía alta. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16039','mirador','Mirador de la Vega del Júcar','7.1/10 Vista panorámica del cauce del río Júcar antes de entrar al embalse de Alarcón, huertas tradicionales de regadío y campos de labranza manchegos. Cómo llegar: Margen de la terraza fluvial alta, accesible por pistas rurales desde el pueblo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16041','mirador','Mirador de la Ruta de las Caras y Embalse','8.6/10 Fantástica e inigualable combinación de esculturas talladas en roca de arenisca, pinares costeros fluviales y el "Mar de Castilla" de aguas turquesas. Cómo llegar: Paraje peninsular acondicionado con paseos peatonales y paneles, acceso señalizado desde el pueblo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16042','mirador','Mirador de la Ermita de la Virgen de la Loma','7.4/10 Amplia perspectiva de la Manchuela conquense alta, campos de cultivo extensivos, viñedos periféricos y la silueta del histórico santuario barroco. Cómo llegar: Explanada de la ermita al norte del casco urbano, provista de accesos rodados. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16044','mirador','Alto de la Muela de Campillos','7.9/10 Vista montañosa de la Serranía de Cuenca central, extensas masas de pino silvestre, matorral mediterráneo de altura y cielos con certificación Starlight. Cómo llegar: Plataforma calcárea elevada accesible por pistas forestales al sur del término. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16043','mirador','Mirador de los Parques Eólicos de la Sierra','7.8/10 Vista aérea e industrial sobre las cumbres serranas, aerogeneradores modernos, masas forestales de coníferas e idónea pureza nocturna astronómica. Cómo llegar: Pistas de servicio eólicas transitables en la plataforma superior caliza del término. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16901','mirador','Mirador de la Ermita del Cristo de Santa Ana','7.2/10 Panorámica rural de la Alcarria meridional, lomas onduladas de secano, encinares dispersos y horizontes limpios de obstáculos visuales industriales. Cómo llegar: Promontorio situado junto al templo en la pedanía de Carrascosa del Campo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16045','mirador','Mirador del Valle del Arroyo de Canalejas','6.7/10 Vista del encajonamiento del arroyo, laderas de yesos y arcillas rojas, vegas de cultivo, olivares tradicionales y chopera lineal de ribera. Cómo llegar: Saliente natural del páramo alcarreño accesible por caminos rurales. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16046','mirador','Mirador de las Torcas y Lagunas de Cañada','8.8/10 Impresionantes e insólitas lagunas kársticas de colores cambiantes (Mesta, Tejo) encajadas en colapsos geológicos gigantescos, rodeadas de pinares laricios. Cómo llegar: Senderos e itinerarios públicos acondicionados con plataformas y vallas de protección de la red natural. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16047','mirador','Alto del Teso del Humilladero','6.4/10 Sencilla panorámica manchega de relieve llano, parcelas agrícolas extensas de cereal y girasol, idónea para la observación de lluvias de estrellas. Cómo llegar: Elevación natural al norte de la población, accesible por pistas agropecuarias de tierra. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16048','mirador','Mirador del Río Escabas y el Estrecho','82/10 Vista fluvial del cauce ancho del Escabas, playas fluviales de piedra, plantaciones densas de mimbre de vivos colores y cortados calizos calcáreos. Cómo llegar: Borde del talud natural acondicionado junto a la carretera CM-210, zona recreativa. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16049','mirador','Mirador del Santuario de la Virgen de la Trasierra','7.3/10 Espectacular atalaya sobre la Mancha baja, llanuras infinitas, dehesas de encina y el monumental santuario mariano excavado en la vertiente forestal. Cómo llegar: Explanada exterior del santuario, accesible por carretera local empinada. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16050','mirador','Mirador de la Ermita de la Virgen del Pinar','7.1/10 Vista del valle alcarreño, olivares de ladera, cultivos cerealistas, pinares densos periféricos e hileras de chimeneas de tradicionales bodegas. Cómo llegar: Zona alta del cerro de la ermita, accesible mediante camino acondicionado. 📍 Provincia: Guadalajara / Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16051','mirador','Mirador de la Ciudad Romana de Ercávica','8.6/10 Extraordinaria perspectiva de la ciudad romana colgada sobre el Embalse de Buendía, pinares, murallas arqueológicas e imponentes horizontes lacustres del "Mar de Castilla". Cómo llegar: Plataforma integrada en el itinerario arqueológico del yacimiento de Ercávica, desvío señalizado. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16053','mirador','Mirador de la Hoz de Cañizares y Vadillos','8.4/10 Espectaculares e imponentes escarpes de roca caliza calcárea sobre el río Guadiela, densos pinares de pino laricio y vegetación rupícola protegida. Cómo llegar: Saliente natural acondicionado con barandillas en la subida a la muela forestal. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16056','mirador','Mirador del Castillo y de las Hoces del Cabriel','8.0/10 Magnífica vista de la fortaleza del siglo XVI, el cauce encajonado de los valles del Cabriel, pinares extensos e idónea observación astronómica. Cómo llegar: Explanada de la fortaleza medieval señorial en la cota más alta de la localidad. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16057','mirador','Mirador del Alto del Pozuelo y las Muelas','8.1/10 Espectacular paisaje alpino del norte serrano a más de 1300 metros, laderas de yesos y calizas erosionadas, pinos silvestres y horizontes limpios Starlight. Cómo llegar: Cima de la plataforma tabular accesible por pistas de montaña desde el núcleo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16058','mirador','Atrio de la Iglesia de la Asunción','6.2/10 Sencilla visual de campos de secano manchegos, olivares rústicos y horizontes diáfanos libres de postes industriales para astrofotografía. Cómo llegar: Espacio público elevado que precede al acceso de la iglesia del municipio. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16060','mirador','Mirador del Palacio de los Gosálvez y Río Júcar','7.1/10 Vista fluvial del cauce del Júcar, los sotos de ribera, plantaciones de vid de la Manchuela y las evocadoras ruinas del palacio versallesco decimonónico. Cómo llegar: Sendero recreativo adaptado junto al cauce del río, al sur de la localidad. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16061','mirador','Alto de las Eras de San Antón','6.3/10 Panorámica llana de la Mancha baja, cultivos extensivos de viñedo y cereal, bodegas locales integradas e idónea observación de puestas de sol limpias. Cómo llegar: Elevación suave en el sector norte de la localidad, junto a los antiguos espacios comunes. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16062','mirador','Alto de la Ermita de San Juan','7.7/10 Perspectiva montañosa de la Serranía Baja, laderas cubiertas de pino laricio y matorral mediterráneo de jara, y cielos nocturnos puros. Cómo llegar: Colina exenta coronada por el templo, transitable a pie desde el casco urbano. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16063','mirador','Mirador de los Viñedos del llano','6.2/10 Sencilla estampa agrícola de la Manchuela meridional, inmenso mar de vides cultivadas en vaso, pinos piñoneros aislados y horizontes diáfanos. Cómo llegar: Pista agrícola perimetral accesible desde la carretera local del núcleo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16064','mirador','Mirador de los Chozos de Piedra de Casas de Haro','6.5/10 Interesante paisaje etnográfico de construcciones circulares tradicionales de piedra seca de pastores, viñedos de la Mancha e idóneo punto astronómico nocturno. Cómo llegar: Paraje acondicionado en los caminos rurales del sur de la población. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16065','mirador','Mirador del Pinar de las Casas','6.4/10 Vista focalizada en la masa forestal de pino piñonero de la comarca, senderos de arena, viñedos periféricos e interesantes puestas de sol castellanas. Cómo llegar: Pista forestal que parte hacia el sur desde el casco urbano, zona recreativa. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16066','mirador','Mirador del Monumento de la Guitarra y Llanura','6.8/10 Vista panorámica de la próspera localidad artesana de la Manchuela, campos de cultivo de regadío de champiñón, viñedos y relieve plano. Cómo llegar: Zona ajardinada alta en los accesos urbanizados de la localidad, acceso pavimentado. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16067','mirador','Mirador de la Cuesta de San Miguel','7.1/10 Vista del valle de la Alcarria alta conquense, laderas arcillosas, olivares rústicos de ladera y la silueta del templo medieval. Cómo llegar: Promontorio situado junto a los restos de la ermita, sector oeste urbano. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16068','mirador','Alto del Teso del Humilladero','6.7/10 Panorámica de los llanos de la Manchuela, campos agrícolas de secano bordeando la autovía A-3 e idóneos horizontes libres para astrofotografía. Cómo llegar: Pequeña elevación natural al norte de la población, cercana a las eras tradicionales. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16070','mirador','Mirador de la Peña del Castillo y Río Guadiela','8.1/10 Impresionante corte calizo del cañón del Guadiela en la Serranía Media, pinares densos forestales, quejigares de ladera y nidos de rapaces protegidas. Cómo llegar: Cresta de la plataforma montañosa accesible por pistas forestales desde el pueblo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16072','mirador','Adarve del Castillo de Garcimuñoz','8.4/10 Soberbia panorámica histórica de la Mancha Alta conquense, el entramado urbano amurallado gótico, campos de cereal y el singular diseño arquitectónico integrado. Cómo llegar: Pasarela superior y torres transitables de la fortaleza del siglo XV, gestionada para visitas culturales. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16071','mirador','Alto de la Cuesta del Castillo','6.8/10 Vista del pequeño valle de la Alcarria alta, olivares tradicionales de ladera, cultivos de secano y chimeneas de tradicionales bodegas excavadas. Cómo llegar: Parte superior del cerro que domina la población por el sector norte. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16073','mirador','Mirador de San Cristóbal y Mancha Alta','6.6/10 Vista panorámica de los llanos arcillosas de cultivo cerealista, dehesas dispersas y horizontes celestes despejados idóneos para astroturismo de baja luminosidad. Cómo llegar: Cima suave del cerro acondicionado con accesos peatonales en la periferia del núcleo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90321','mirador','Mirador del silo y Valle del río Chillarón','72/10 Vista del valle arcilloso periférico de la capital, el reformado centro de escalada integrado, huertas tradicionales de ribera y campos de secano. Cómo llegar: Zona alta del complejo del silo agrícola modificado, acceso pavimentado. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16081','mirador','Mirador del Torreón del Castillo y la Paramera','7.1/10 Vista de las laderas calcáreas erosionadas de la Serranía Media, la robusta torre defensiva del siglo de oro y horizontes limpios sin postes industriales. Cómo llegar: Explanada de la fortaleza señorial en la cota más alta de la localidad. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16074','mirador','Mirador del Yacimiento de las Hoyas','8.2/10 Excepcional entorno paleontológico mundial de torcas kársticas del Cretácico, pinares laricios densos, fósiles singulares e idóneo cielo Starlight puro. Cómo llegar: Centro de interpretación y plataformas exteriores acondicionadas con paneles didácticos, acceso rural. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16079','mirador','Mirador de la Mina de Hierro Romana','8.4/10 Espectacular e histórico paisaje de minería subterránea romana de la Serranía Alta, muelas calcáreas a más de 1300 metros, pinos silvestres y brezales. Cómo llegar: Explanada exterior del centro de recepción de las minas de hierro transitables, acceso GU-915. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16078','mirador','Mirador del Barrio del Castillo y Ventana del Júcar','9.6/10 Excepcional e icónica panorámica de las Hoces del Huécar y del Júcar, las Casas Colgadas, puentes medievales, ruinas de la alcazaba y la ciudad Patrimonio de la Humanidad. Cómo llegar: Cornisa amurallada superior adaptada con barandillas en la cota más alta del casco histórico conquense. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16082','mirador','Mirador de las Chorreras del Cabriel y del Castillo','8.8/10 Espectacular salto de agua, pozas e incrustaciones de toba del río Cabriel (Reserva de la Biosfera), contrastando con la fortaleza del siglo XI. Cómo llegar: Sendero señalizado y plataformas voladas con paneles en el paraje natural de Las Chorreras. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16087','mirador','Alto del Teso del Calvario','6.4/10 Vista diáfana de la Mancha Alta, campos de cereal y girasol, dehesas dispersas y cielos limpios libres de contaminación lumínica. Cómo llegar: Promontorio suave al oeste del casco urbano, accesible a pie desde la ermita. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16088','mirador','Mirador de las Hoces del río Moya','7.8/10 Hermosa vista de los cortados calizos calcáreos, bosques de pino negral, encinares serranos y nidos de grandes aves rapaces rupícolas. Cómo llegar: Borde del talud natural acondicionado con valla de madera en el sector este del término. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16904','mirador','Mirador de la Dehesa de Jábaga','7.4/10 Panorámica de los valles menores de la Serranía Media, pinares de repoblación densos, quejigares y olivares tradicionales de ladera. Cómo llegar: Cota natural elevada accesible por la pista forestal que sube desde el núcleo de Jábaga. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16089','mirador','Mirador del Yacimiento Paleontológico de Lo Hueco','7.9/10 Vista arqueológica de relieve ondulado donde se descubrió el masivo cementerio de dinosaurios, pinares y matorral bajo de jara. Cómo llegar: Plataforma con paneles explicativos situada en las cercanías del trazado de la autovía A-40. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16091','mirador','Mirador de la Puerta del Infierno y Cortados del Escabas','8.7/10 Sobrecogedor y estrecho cañón calizo de paredes verticales, densos pinares de pino negral, túneles excavados en la roca y el río cristalino. Cómo llegar: Estructura de pasarela adaptada con barandilla a la entrada del imponente desfiladero, LR-2101. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16092','mirador','Alto de la Muela de Gabaldón','6.6/10 Vista despejada de la transición entre la Manchuela y la Serranía baja, campos de cultivo de secano e idóneo punto Starlight nocturno. Cómo llegar: Plataforma tabular calcárea elevada, transitable por sendas agropecuarias al norte del pueblo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16093','mirador','Mirador del Monasterio de Tejeda y Peña de la Cruz','8.1/10 Impresionante vista del cañón calizo del río Ojos de Moya, el santuario histórico del siglo XVI en el fondo y frondosos pinares. Cómo llegar: Cima de la peña rocosa coronada por la cruz, accesible por sendero peatonal empinado. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16094','mirador','Mirador de las Bodegas y Alto de San Andrés','6.9/10 Perspectiva sobre la vega del arroyo, cultivos tradicionales de la Alcarria conquense, campos de lavanda y chimeneas de calados tradicionales. Cómo llegar: Corona de la colina de las bodegas subterráneas, accesible a pie en la periferia norte. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16095','mirador','Alto de la Paramera Serrana','7.1/10 Vista limpia de la comarca de la Serranía de Cuenca oriental, campos agrícolas de gran altitud, sabinares dispersos y horizontes libres. Cómo llegar: Elevación natural del terreno transitable a pie por caminos vecinales al sur del núcleo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16096','mirador','Mirador del Llano de la Manchuela','6.4/10 Sencilla panorámica de la llanura agrícola, extensos viñedos, cultivos cerealistas planos e idóneos atardeceres nítidos y sin obstáculos. Cómo llegar: Zona perimetral elevada al norte de la población, cercana a pistas agrícolas. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16097','mirador','Mirador de las Pinturas Rupestres del Abrigo del Tío Modesto','7.7/10 Vista arqueológica sobre los cañones de arenisca roja del sector meridional, pinares densos y el abrigo de arte rupestre levantino protegido. Cómo llegar: Sendero adaptado con paneles explicativos en el barranco del río, acceso señalizado desde el núcleo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16098','mirador','Mirador de los Viñedos y Ermita de San Julián','6.5/10 Mar de vides característico de la Manchuela, campos de almendros, relieves suaves y cielos abiertos despejados aptos para astrofotografía. Cómo llegar: Explanada elevada de la ermita al oeste del casco urbano, con accesos rodados adaptados. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16099','mirador','Alto del Cerro Gordo','7.0/10 Vista panorámica del valle menor, relieves de yesos y arcillas rojas, matorral mediterráneo y horizontes despejados castellanos. Cómo llegar: Cota natural elevada al norte de la población, transitable por sendas ganaderas. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16100','mirador','Mirador del Molino de Viento y de la Mancha','6.3/10 Clásica estampa manchega sobre la llanura infinita de cereal y viñedos, con el antiguo molino tradicional restaurado integrando el paisaje. Cómo llegar: Pequeña colina exenta en el sector alto de la localidad, provista de aparcamiento. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16106','mirador','Mirador del Teso del Humilladero','6.7/10 Amplia visual sobre los llanos cerealistas de la Mancha de Santiago, olmedas aisladas, cultivos de secano y puestas de sol limpias. Cómo llegar: Promontorio suave al sur de la localidad, junto al antiguo trazado de caminos reales. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16107','mirador','Mirador del Castillo de Huélamo','8.6/10 Soberbia y colgada atalaya sobre el valle alto del río Júcar, los escarpados taludes de los Montes Universales, densos pinares y el pueblo escalonado. Cómo llegar: Cima del peñón rocoso donde se asientan las ruinas de la antigua fortaleza medieval, acceso peatonal empinado. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16108','mirador','Mirador de la Vega del río Riánsares','6.8/10 Vista sobre el valle del río Riánsares, lomas arcillosas erosionadas, campos de cereal y el yacimiento romano de la antigua Segóbriga en la lejanía. Cómo llegar: Borde del talud calizo occidental, accesible por caminos rurales desde el núcleo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16110','mirador','Alto del Teso de San Cristóbal','7.0/10 Panorámica rural de la Serranía Baja, lomas onduladas de secano, encinares dispersos e idóneo horizonte nocturno para la fotografía estelar. Cómo llegar: Elevación natural del terreno transitable a pie por pistas forestales al norte del caserío. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16111','mirador','Mirador de la Umbría del Marquesado','8.4/10 Impresionante visual alpina de la Serranía Alta, densos pinares silvestres, fuentes naturales de agua cristalina y cumbres calizas de relieve abrupto. Cómo llegar: Plataforma con vallado de protección en la subida natural hacia la muela forestal, desvío rural. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16113','mirador','Mirador de la Ermita de Consolación y la Manchuela','6.6/10 Perspectiva sobre los llanos agrícolas de vides, olivares, antiguas eras de trilla y el conjunto monumental renacentista de la ermita. Cómo llegar: Explanada exterior elevada de la ermita, provista de accesos rodados y bancos. ¿Cómo prefieres que continuemos la secuencia? Podemos pasar de inmediato al siguiente bloque masivo a partir de la letra J de la Provincia de Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16115','mirador','Mirador del Monumento Natural de la Laguna','8.5/10 Impresionante vista de la laguna de origen kárstico, densos carrizales, el cañón del río Lezuza y laderas boscosas de pino silvestre de la Serranía Alta. Cómo llegar: Plataforma de madera adaptada con paneles explicativos en la margen oeste de la laguna protegida. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16116','mirador','Mirador de las Torcas y Poljes de Lagunaseca','8.3/10 Espectacular paisaje kárstico de depresiones geológicas, dolinas gigantescas, muelas calcáreas a más de 1300 metros e idóneo punto para astrofotografía de cielos negros. Cómo llegar: Senda señalizada que parte desde el casco urbano hacia las formaciones geológicas de la muela. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16117','mirador','Mirador del Castillo de Moya y Serranía Baja','7.8/10 Gran visual sobre el valle del río Ojos de Moya, pinares dispersos, cultivos de secano de montaña y las imponentes ruinas de la ciudad medieval fortificada. Cómo llegar: Cota natural elevada al norte del pueblo, accesible por pistas forestales de tierra. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16118','mirador','Alto del Teso de las Viñas','6.4/10 Panorámica llana de la Manchuela conquense, extensos campos de viñedos y cultivo de champiñón, con horizontes limpios libres de obstáculos industriales para astroturismo. Cómo llegar: Promontorio suave al este del casco urbano, accesible por pistas agrícolas. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16119','mirador','Mirador de la Alcarria Baja y del Río Tajo','7.1/10 Vista de las cárcavas arcillosas rojizas que caen hacia la vega del río Tajo, olivares tradicionales alcarreños y campos cerealistas planos de la Alcarria baja. Cómo llegar: Saliente natural de la plataforma calcárea adaptado con bancos en la periferia norte. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16121','mirador','Mirador de Los Callejones de Las Majadas','8.9/10 Fantástico y monumental laberinto kárstico de monolitos calizos erosionados en formas caprichosas, densos pinares alpinos y hábitat de grandes aves rapaces protegidas. Cómo llegar: Entorno acondicionado con senderos autoguiados y aparcamiento, desvío señalizado desde la carretera de Cuenca. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16123','mirador','Mirador de la Cueva de los Griegos','8.2/10 Vista de la plataforma horizontal del páramo de la Serranía Alta, muelas calizas, dolinas, pinares silvestres y parajes con nula contaminación lumínica. Cómo llegar: Borde del escarpe calcáreo, transitable por sendas forestales al norte del caserío. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16124','mirador','Mirador de los Molinos de Viento','6.2/10 Sencilla panorámica rural de la inmensidad de la llanura manchega central, extensos viñedos D.O. La Mancha y cultivos cerealistas infinitos. Cómo llegar: Pequeña colina exenta en el sector alto del municipio, provista de accesos rodados. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16125','mirador','Mirador de las Hoces del Cabriel (Hoz de Vicente)','8.7/10 Espectacular e imponente cañón esculpido en roca caliza por el río Cabriel, cuchillos de arenisca, pinares densos y avifauna rupícola migratoria acuática. Cómo llegar: Balcón natural acondicionado con barandillas en el Parque Natural, desvío desde la antigua N-III. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16126','mirador','Mirador de la Hoz del Río Mira','8.1/10 Impresionante corte geológico de conglomerados calizos, profundas paredes de roca escarpadas que encajonan el río, huertas tradicionales y el pueblo colgado. Cómo llegar: Estructura adaptada con pasarela en el sendero de las hoces, accesible desde el casco urbano. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16128','mirador','Alto del Teso del Humilladero','6.6/10 Vista diáfana de la llanura de la Mancha Alta, campos de cereal y girasol, antiguas eras de trilla y limpios horizontes para astrofotografía. Cómo llegar: Promontorio suave al sur de la localidad, accesible por caminos vecinales de tierra. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16129','mirador','Alto del Cerro del Castillo','6.5/10 Perspectiva sobre la campiña arcillosa manchega ondulada, cultivos de secano, pequeños encinares aislados y puestas de sol nítidas sobre la meseta. Cómo llegar: Cota más alta del núcleo urbano, transitable a pie desde la iglesia parroquial. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16130','mirador','Mirador de la Laguna de El Hito','7.6/10 Magnífica perspectiva de la reserva natural endorreica, cubeta lagunar estacional salina, avistamiento masivo de grullas acuáticas y estepa cerealista. Cómo llegar: Observatorio acondicionado con paneles didácticos de la red protegida en la periferia de la laguna. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16133','mirador','Mirador del Balcón de la Mancha y Molinos','8.0/10 Genuina e infinita estampa manchega sobre la llanura infinita de cereal y viñedos, con el conjunto monumental de molinos tradicionales restaurados. Cómo llegar: Loma elevada caliza exenta al norte de la villa, adaptada con aparcamiento y zonas peatonales. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16134','mirador','Mirador del Teso de San Cristóbal y del Júcar','6.9/10 Vista del sector llano de la Manchuela conquense alta, campos de cultivo intensivos de secano, dehesas y horizontes limpios libres de contaminación. Cómo llegar: Elevación natural del terreno transitable a pie por caminos vecinales al sur del caserío. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16135','mirador','Adarve de la Villa y Castillo de Moya','8.8/10 Extraordinaria y monumental atalaya sobre el Valle del río Ojos de Moya, el recinto amurallado, iglesias en ruinas y las cumbres de la Serranía Baja. Cómo llegar: Muros transitables de la inexpugnable fortaleza medieval del siglo XV, abierta a visitas culturales. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16137','mirador','Mirador del Viaducto y del Río Henarejos','7.2/10 Hermosa vista que combina la monumental obra de ingeniería civil del viaducto ferroviario con la vega fluvial, cortados calizos y pinares densos. Cómo llegar: Saliente natural acondicionado en el camino rural que bordea el cañón del río. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16139','mirador','Mirador del Embalse de Alarcón','7.4/10 Vista de la gran masa de agua embalsada del río Júcar, los sotos e islas fluviales estacionales, olivares de ladera y puestas de sol reflejadas. Cómo llegar: Borde del talud natural acondicionado con valla en el extremo norte del término municipal. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16140','mirador','Mirador de las Esculturas del Paseo Etnográfico','6.7/10 Vista del paisaje alcarreño erosionado ondulado, campos de lavanda, olivares tradicionales y las intervenciones artísticas que jalonan el núcleo urbano. Cómo llegar: Sendero peatonal adaptado en la ladera alta ajardinada de la localidad. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16141','mirador','Alto de la Ermita de San Cristóbal','7.1/10 Panorámica rural de la Serranía Baja conquense, relieves de yesos y arcillas rojas, matorral mediterráneo de jara y cielos nocturnos Starlight limpios. Cómo llegar: Cerro exento que alberga la ermita, transitable por camino de tierra apto para vehículos. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16142','mirador','Mirador de la Vega de Alarcón','7.0/10 Vista sobre las terrazas aluviales de cultivo cerealista y viñedos periféricos próximos a la cuenca histórica de la fortaleza de Alarcón. Cómo llegar: Margen de la terraza fluvial, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16145','mirador','Alto de la Cuesta de la Horca','6.8/10 Vista limpia de la llanura agrícola manchega, tierras de labranza arcillosas dedicadas al secano y horizontes despejados óptimos para la astrofotografía. Cómo llegar: Camino rural elevado que parte del núcleo hacia el norte de la localidad. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16146','mirador','Mirador del Calvario y Serranía Baja','7.6/10 Magnífica visual del valle del río Guadazaón, escarpes calizos de las muelas calcáreas, densos pinares forestales y un cielo nocturno muy oscuro. Cómo llegar: Borde del páramo occidental adaptado junto a las eras altas del pueblo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16147','mirador','Mirador de las Corpachas (Las Catedrales Rojas)','8.4/10 Impresionante paisaje geológico de torreones monolíticos gigantes de arenisca rojiza erosionada (rodeno), pinos resineros densos e idónea pureza nocturna celeste. Cómo llegar: Paraje natural accesible por pista forestal señalizada desde la carretera N-420. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16149','mirador','Mirador de la Hoz del río Huécar','8.3/10 Espectacular cañón calizo de paredes verticales calcáreas del río Huécar, bosques de ribera con chopos, nidos de rapaces e infinitos horizontes serranos. Cómo llegar: Borde del talud calizo acondicionado con barandillas en el camino alto a Cuenca. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16148','mirador','Alto del Teso de San Roque','6.6/10 Sencilla panorámica de la Mancha de Santiago arcillosa, campos ondulados de secano e idóneo horizonte nocturno para la observación de astros. Cómo llegar: Atrio elevado de la ermita, en el punto alto del casco urbano rural. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16150','mirador','Mirador del Castillo de Paracuellos y del Río Guadazaón','7.4/10 Perspectiva sobre la cuenca erosionada, laderas con encinares maduros, huertas de media montaña y las trazas históricas de la fortaleza medieval. Cómo llegar: Explanada de la antigua fortaleza del siglo XII en la cota más elevada del cerro. 📍 Provincia: Guadalajara / Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16151','mirador','Alto de la Muela de secano','6.4/10 Sencilla panorámica de lomas arcillosas dedicadas al secano, olivares y horizontes manchegos despejados para la astrofotografía. Cómo llegar: Pequeño repecho al norte de la localidad, accesible por caminos de servicio. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16152','mirador','Mirador de las Hoces del río Júcar','7.3/10 Vista del profundo cañón fluvial del río Júcar, escarpes calizos con nidos de rapaces rupícolas y el denso matorral de media montaña. Cómo llegar: Saliente acondicionado junto a las sendas de senderismo en la margen derecha del río. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16153','mirador','Mirador de los Majuelos y la Mancha Alta','6.1/10 Sencilla panorámica sobre los llanos aluviales fértiles, cultivos tradicionales de viñedos y ajos, e idóneo punto para puestas de sol. Cómo llegar: Explanada urbana del depósito elevado, en la periferia norte de la localidad. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16154','mirador','Mirador de la Capital del Ajo y la Mancha','6.3/10 Vista diáfana de la llanura agrícola manchega, campos morados de cultivo intensivo de ajo, dehesas dispersas y cielos limpios de contaminación. Cómo llegar: Zona perimetral elevada al norte de la población, cercana a pistas agrícolas. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16155','mirador','Alto de la Cuesta del Olmo','6.5/10 Vista despejada de los llanos cerealistas y de viñedos de la Manchuela conquense, con horizontes limpios libres de obstáculos visuales industriales. Cómo llegar: Pista agrícola perimetral accesible desde la carretera nacional. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16156','mirador','Mirador del Páramo de la Alcarria Conquense','6.9/10 Vista del encajonamiento del arroyo, taludes calizos de los páramos, cultivos de lavanda, olivares y la fisonomía del núcleo medieval. Cómo llegar: Saliente natural del páramo accesible por caminos rurales desde la carretera. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16157','mirador','Mirador del Embalse de Contreras y Río Cabriel','8.2/10 Impresionante e industrial panorámica del gigantesco embalse sobre el río Cabriel, la bóveda de hormigón, los cuchillos calizos de las hoces y pinos. Cómo llegar: Corona e instalaciones de la represa, accesos señalizados desde la autovía A-3. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16158','mirador','Mirador del Puente y Ribera del Río Júcar','7.1/10 Hermosa vista del cauce del río Júcar medio, el puente histórico, la frondosa vegetación de ribera, sotos fluviales y huertas tradicionales manchegas. Cómo llegar: Paseo fluvial acondicionado al norte del casco urbano, con accesos peatonales. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16159','mirador','Mirador de los Chozos de Pastores y Pinares','6.8/10 Vista de pinares dispersos de pino piñonero y negral, antiguas construcciones tradicionales de piedra seca de pastores e idónea pureza Starlight nocturna. Cómo llegar: Pista de servicio forestal elevada, accesible al oeste del núcleo urbano. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16160','mirador','Mirador del Páramo y Cortados del Río Gigüela','7.0/10 Perspectiva sobre el nacimiento del río Gigüela, taludes arcillosos de erosión lineal, cultivos de secano e infraestructuras integradas. Cómo llegar: Cornisa natural accesible por pistas agropecuarias desde el núcleo de población. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16161','mirador','Mirador del Castillo medieval y de los Valles','7.2/10 Vista de valles encajonadas de la Serranía Baja, laderas escarpadas calcáreas, encinares maduros y restos de defensas medievales. Cómo llegar: Explanada de la fortaleza medieval en la cota más elevada de la colina. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16162','mirador','Mirador del Valle de Guadamejud y Alcarria','6.9/10 Vista del encajonamiento del arroyo, taludes calizos de los páramos alcarreños, huertas, olivares tradicionales y cielos oscuros. Cómo llegar: Borde oriental de la plataforma calcárea, accesible por sendas desde el pueblo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16167','mirador','Alto del Teso de la Iglesia de Santiago','6.6/10 Sencilla panorámica de la Mancha de Santiago arcillosa, campos ondulados de secano e idóneo horizonte nocturno para la fotografía de estrellas. Cómo llegar: Atrio elevado del templo, en el punto alto del casco urbano rural. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16169','mirador','Atrio de la Iglesia Parroquial','6.4/10 Vista diáfana de la llanura agrícola, tierras de labranza arcillosas dedicadas al secano y horizontes despejados castellanos. Cómo llegar: Plataforma elevada urbana frente a la portada del templo, centro del municipio. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16170','mirador','Mirador del Estrecho de Priego y Hoz del Escabas','8.8/10 Soberbia y colgada atalaya sobre la impresionante grieta del río Escabas, farallones calizos colosales, túneles viales, quejigares y buitreras masivas. Cómo llegar: Pasarela e hito acondicionado con barandillas en la carretera del estrecho, CM-2023. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16171','mirador','Mirador del Río Záncara y el Puente Romano','6.7/10 Vista fluvial del cauce del río Záncara, el histórico puente de sillería, arbolado de ribera, huertas tradicionales manchegas y amplias puestas de sol. Cómo llegar: Paseo fluvial acondicionado junto al puente histórico, en la periferia urbana. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16172','mirador','Mirador del Castillo de Puebla de Almenara','8.4/10 Impresionante e ininterrumpida atalaya sobre la Sierra de Almenara, divisando la llanura de la Mancha Alta, castillos lejanos e idóneo punto Starlight. Cómo llegar: Corona superior de las murallas de la inexpugnable fortaleza del siglo XV, en la cumbre de la sierra. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16174','mirador','Mirador de la Dehesa y la Manchuela','6.9/10 Vista de los llanos agrícolas de la comarca, viñedos tradicionales, encinares dispersos de la dehesa boyal e idóneos horizontes para astrofotografía. Cómo llegar: Zona alta del montículo de la dehesa, accesible a pie desde el casco urbano. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16175','mirador','Mirador de la Ermita de San Antón y la Manchuela','6.6/10 Perspectiva sobre los llanos agrícolas de vides, cultivos hortícolas intensivos de champiñón y horizontes limpios de obstáculos. Cómo llegar: Explanada exterior elevada de la ermita, provista de accesos rodados. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16176','mirador','Alto del Teso de la Iglesia de la Asunción','6.5/10 Sencilla panorámica de la llanura cerealista manchega alta, olivares rústicos y horizontes celestes despejados para astrofotografía. Cómo llegar: Atrio elevado del templo parroquial, en el punto alto del casco urbano rural. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16177','mirador','Mirador del Teso del Castillo y Serranía Baja','7.4/10 Vista panorámica de los valles del Cabriel medio, formaciones calizas erosionadas, pinos negrales densos e interesantes cielos oscuros estelares. Cómo llegar: Cota natural elevada al noreste del pueblo, accesible por pistas agropecuarias de tierra. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16187','mirador','Mirador de las Salinas y del Río Ojos de Moya','7.9/10 Vista de los restos arqueológicos de las antiguas salinas industriales, el cauce fluvial del río Ojos de Moya, pinares densos de la Serranía. Cómo llegar: Sendero adaptado con paneles explicativos en el paraje natural de las salinas. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16188','mirador','Mirador de la Alcarria Alta y Confluencia del Guadiela','7.1/10 Vista de las vertientes de piedra caliza de los páramos alcarreños linderos, campos de cultivo de secano y el río Guadiela. Cómo llegar: Borde norte de la plataforma calcárea, accesible por pistas forestales. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16189','mirador','Mirador de la Sierra de Albarracín y Alto de Santerón','8.3/10 Soberbia visual alpina a más de 1300 metros de altitud sobre los Montes Universales, densos pinares, matorral de montaña y cielos catalogados Starlight. Cómo llegar: Cresta de la plataforma montañosa accesible por pistas forestales de tierra. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16190','mirador','Mirador de la Torre de la Iglesia de Santiago y Plaza','7.3/10 Amplia e histórica perspectiva sobre el conjunto monumental renacentista de la villa castellanomanchega, pinares dispersos y los infinitos llanos agrícolas de la Mancha. Cómo llegar: Cuerpo de campanas superior del templo gótico-renacentista, acceso coordinado en el casco histórico. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16191','mirador','Mirador del Castillo de la Parrilla y del Río Júcar','7.5/10 Perspectiva sobre la cuenca del río Júcar medio, lomas arcillosas con encinares maduros, olivares tradicionales y las ruinas fortificadas medievales. Cómo llegar: Explanada de la antigua fortaleza del siglo XIV en la cota más elevada del cerro. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16192','mirador','Mirador de los Cañones del Cabriel y Peña del Mazo','8.4/10 Impresionante cañón calizo de paredes verticales, formaciones geológicas de arenisca roja y calizas de la Serranía, pinos densos y pureza Starlight. Cómo llegar: Saliente acondicionado con valla de madera sobre el desfiladero, acceso pedestre por sendero de montaña. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16193','mirador','Mirador del Páramo de la Alcarria alta','6.9/10 Vista del encajonamiento del arroyo, taludes calizos de los páramos, huertas, olivares tradicionales y cielos oscuros libres de contaminación. Cómo llegar: Borde oriental de la plataforma calcárea, accesible por sendas desde el pueblo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16194','mirador','Mirador del Monumento al Guerrillero y Hoces del Turia','8.6/10 Espectacular e imponente corte geológico sobre el cañón del río Turia, huertas de ribera escalonadas, pinos negrales, sabinas y memoria histórica del Maquis. Cómo llegar: Monumento y explanada adaptada con barandilla y paneles en la carretera C-234, borde del desfiladero.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16196','mirador','Alto del Teso del Molino','6.2/10 Panorámica horizontal de la llanura manchega central, mosaicos infinitos de cereal y viñedos, baja contaminación y horizontes idóneos para astrofotografía. Cómo llegar: Elevación natural al norte del núcleo, junto a los vestigios del antiguo molino de viento. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16195','mirador','Mirador del Castillo y del rus','6.8/10 Vista de la campiña baja, lomas arcillosas que escoltan el cauce del río Rus, parcelas agrícolas y el recuerdo literario de Jorge Manrique. Cómo llegar: Explanada de la antigua fortaleza medieval, cota más alta en el casco urbano. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16197','mirador','Mirador del Estrecho del río Cuervo y Muelas','8.5/10 Impresionante grieta caliza de paredes escarpadas en la Serranía Alta, densos pinares de pino albar, praderas alpinas de alta montaña y cielos Starlight puros. Cómo llegar: Cornisa rocosa natural adaptada con vallado, accesible por pistas forestales desde el pueblo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16198','mirador','Mirador de la Ermita de San Antón','6.6/10 Perspectiva diáfana de la Manchuela conquense meridional, extensiones de olivares y vides, relieve suave y puestas de sol limpias de obstáculos. Cómo llegar: Explanada del templo religioso situada en las eras altas, al oeste de la villa. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16199','mirador','Alto del Cerro del Castillo','7.1/10 Vista panorámica del pequeño valle encajonado, afloramientos de piedra caliza de la Serranía Baja, matorral mediterráneo de jara y encinas. Cómo llegar: Promontorio rocoso elevado que domina el casco urbano por el flanco septentrional. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16909','mirador','Mirador de la Hoz de Ribagorda','7.9/10 Magnífica visual del profundo desfiladero kárstico, cortados de arcilla y yesos, pinares densos de repoblación y hábitat de aves rapaces protegidas. Cómo llegar: Borde del talud acondicionado con paneles didácticos de la red comarcal, acceso desde Ribagorda. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16202','mirador','Mirador del Pico de la Plaza y los Callejones','83/10 Soberbia panorámica de la Sierra de Talayuelas, caprichosas formaciones de arenisca roja erosionada, cañones profundos, pinares centenarios e idóneo punto astronómico nocturno. Cómo llegar: Cima rocosa accesible por pista forestal transitable, desvío señalizado desde la carretera N-330. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16203','mirador','Mirador de la Cuesta de la Iglesia y del Riánsares','7.2/10 Vista del valle bajo del río Riánsares, el casco histórico escalonado de la localidad y la inmensidad de los cultivos de la Mancha Alta. Cómo llegar: Terraza urbana ajardinada junto al ábside de la Iglesia de la Asunción, centro del municipio. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16204','mirador','Alto de la Ermita de San Roque','6.4/10 Vista limpia sobre los campos cerealistas y de girasol de la comarca de la Mancha, dehesas dispersas y horizontes mesetarios diáfanos. Cómo llegar: Pequeña colina exenta coronada por la ermita, accesible a pie en las inmediaciones del núcleo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16205','mirador','Mirador de la Muela de Tejadillos','8.4/10 Extraordinaria visual alpina a más de 1300 metros de altitud de la Serranía Alta, densas masas forestales, fuentes naturales y relieve calizo abrupto. Cómo llegar: Plataforma superior calcárea accesible por pistas de montaña, paraje óptimo para fotografía astronómica. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16206','mirador','Mirador de las Bodegas y Teso de San Cristóbal','6.9/10 Hermosa vista de la Alcarria conquense, olivares tradicionales, campos de lavanda y las chimeneas alineadas de los antiguos calados tradicionales excavados. Cómo llegar: Zona alta del montículo de las bodegas, accesible a pie desde la zona norte urbana. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16209','mirador','Mirador de las Minas de Espejuelo y la Alcarria','7.3/10 Paisaje minero histórico de yeso traslúcido romano (lapis specularis), relieves ondulados arcillosos, matorral mediterráneo y un cielo nocturno muy limpio. Cómo llegar: Entorno acondicionado junto al yacimiento de la mina antigua, acceso rural desde el pueblo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16211','mirador','Mirador de la Ermita de la Piedad','7.2/10 Vista despejada de la comarca de la Mancha Alta septentrional, ondulaciones del terreno, campos de cereal e idónea pureza Starlight nocturna. Cómo llegar: Explanada elevada de la ermita al oeste del casco urbano, provista de accesos rodados. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16212','mirador','Alto del Calvario','6.3/10 Sencilla panorámica rural sobre la estepa cerealista, parcelas agrícolas cuadradas e idóneo horizonte para capturar puestas de sol castellanas nítidas. Cómo llegar: Repecho suave en la salida sur de la localidad, accesible por sendas peatonales. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16213','mirador','Alto del Castillo y la Vega','6.5/10 Perspectiva sobre el pequeño arroyo, lomas arcillosas erosionadas, campos de secano y restos de defensas de la fortaleza medieval. Cómo llegar: Cota natural más alta del núcleo, accesible por pista de tierra desde las eras. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16215','mirador','Mirador del Estrecho del Infierno y Nacimiento del Júcar','8.9/10 Espectacular e imponente cañón de calizas, cascadas de montaña calcadas, densos pinares alpinos silvestres, buitreras e idónea observación astronómica nocturna. Cómo llegar: Estructura colgada con barandilla sobre el precipicio, acceso señalizado por la carretera CM-2106. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16216','mirador','Alto del Teso de la Atalaya','6.4/10 Vista diáfana de la llanura manchega occidental, cultivos extensivos de secano, dehesas dispersas y cielos limpios de obstáculos industriales. Cómo llegar: Elevación natural del terreno transitable a pie por caminos vecinales al norte del caserío. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16217','mirador','Mirador de la Ermita de Santa Ana','6.7/10 Panorámica de la comarca de la Mancha Alta, campos de cereal, la silueta del Monasterio de Uclés en la lejanía y atardeceres limpios. Cómo llegar: Explanada exterior elevada de la ermita, provista de accesos rodados y bancos. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16218','mirador','Mirador de las Torres del Castillo y Monasterio','8.8/10 Soberbia y espectacular vista panorámica de la llanura manchega, las murallas en dientes de sierra, torres medievales y el monumental "Escorial de la Mancha". Cómo llegar: Adarve superior transitable de las defensas históricas del castillo de Uclés, acceso turístico coordinado. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16219','mirador','Mirador del Refollón y Laguna de Uña','9.1/10 Impresionante panorámica de la laguna natural rodeada de vertiginosos farallones calizos, el cañón del Júcar, densos pinares forestales y avifauna acuática abundante. Cómo llegar: Balcón natural acondicionado con barandillas de madera en el sendero del Escalerón a la Raya, Parque Natural. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16906','mirador','Alto del Teso de la Alcarria','7.0/10 Vista del valle menor de las Colmenas, laderas escarpadas calcáreas alcarreñas, campos de cultivo de secano y nítidos cielos nocturnos. Cómo llegar: Borde del páramo accesible por caminos rurales desde el núcleo de Valdecolmena de Abajo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16224','mirador','Mirador del Paisaje Ilustrado y la Vega','86/10 Excelente visual alpina de la Serranía Alta, densos pinares silvestres, el arroyo de Valdemeca, esculturas de hierro tradicionales integradas e idóneo punto Starlight. Cómo llegar: Entrada del núcleo urbano y pistas forestales de montaña adyacentes, acceso CM-2106. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16225','mirador','Mirador del río Guadazaón y las Muelas','8.0/10 Vista del cauce encajonado del río, vertientes calizas de los Montes Universales, quejigares, encinares serranos y cielos limpios astronómicos. Cómo llegar: Cornisa natural alta al este del término, transitable por sendas ganaderas y pistas forestales. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16227','mirador','Mirador de la Balsa de Valdemoro','8.5/10 Impresionante estampa del cañón fluvial kárstico, lagunas estacionales de agua turquesa rodeadas de paredes verticales de caliza, pinares y nidos de buitres. Cómo llegar: Plataforma con vallado de protección en la ruta de senderismo, acceso señalizado por pista forestal. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16228','mirador','Mirador del Olivar y la Torre Románica','74/10 Perspectiva sobre los infinitos campos de olivos de la Alcarria norteña, cultivos cerealistas, y la esbelta y monumental torre románica del siglo XIII. Cómo llegar: Cota alta del núcleo urbano, transitable a pie desde la Iglesia de la Asunción. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16902','mirador','Alto del Cerro Gordo','7.1/10 Vista panorámica del Valle del río Tórtola, relieves ondulados arcillosos de secano, encinares dispersos y horizontes despejados castellanos. Cómo llegar: Cota natural elevada accesible por pistas agropecuarias desde el núcleo de Valdeganga de Cuenca. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16903','mirador','Mirador de la Hoz de Valeria y las Ruinas Romanas','8.4/10 Espectacular desfiladero calizo del río Gritos, murallas naturales verticales calcinadas por la erosión, restos de la ciudad romana de Valeria e idónea astrofotografía. Cómo llegar: Cornisa acondicionada con barandilla en el borde del recinto arqueológico de Valeria, acceso señalizado. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16231','mirador','Alto del Pozo de la Fuente','6.5/10 Sencilla visual de campos de secano de la Manchuela central, relieves suaves ondulados y cielos nocturnos de baja luminosidad urbana. Cómo llegar: Camino rural elevado en los límites geográficos orientales del municipio. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16234','mirador','Mirador de las Torcas y la Ciudad de Piedra','8.1/10 Singular y kárstico paisaje geológico dominado por dolinas y callejones de piedra esculpidos por la erosión, rodeado de denso pino negral. Cómo llegar: Entorno perimetral acondicionado en las rutas geológicas protegidas, acceso forestal desde el pueblo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16236','mirador','Mirador del Embalse de Alarcón','7.6/10 Vista panorámica de la gran masa de agua lacustre, playas interiores de arena, pinares de repoblación perimetrales y puestas de sol limpias. Cómo llegar: Cornisa natural alta junto al paraje de la Ermita del Espíritu Santo, accesos rodados. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16237','mirador','Alto del Teso de la Iglesia','6.6/10 Sencilla panorámica de la Manchuela arcillosa, campos ondulados de secano e idóneo horizonte nocturno para la observación de lluvias de estrellas. Cómo llegar: Atrio elevado del templo parroquial, en el punto alto del casco de la localidad. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16238','mirador','Mirador del Llano de la Mancha','6.4/10 Vista de la llanura agrícola manchega, viñedos, cultivos cerealistas planos e idóneos atardeceres nítidos y libres de obstáculos industriales. Cómo llegar: Zona perimetral elevada al norte de la población, cercana a las antiguas eras de trilla. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16239','mirador','Mirador del Nacimiento del Río Cuervo','9.2/10 Extraordinario e icónico monumento natural de cascadas petrificadas de toba calcárea, densos hayedos, pinares alpinos, farallones de la muela y pureza Starlight. Cómo llegar: Pasarelas adaptadas de madera de la red de Espacios Naturales Protegidos, acceso señalizado por la CM-2106. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16240','mirador','Mirador de la Sierra de Altomira','7.0/10 Vista panorámica de la vertiente occidental de la sierra, campos de cultivo alcarreños, encinares dispersos y horizontes limpios de la Alcarria Baja. Cómo llegar: Borde de la plataforma calcárea elevado al oeste de la población, transitable por sendas serranas. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16242','mirador','Mirador de las Cuevas de Vino y Valle del Trabaque','7.3/10 Hermosa vista de los cortados calizos que encajonan el río Trabaque, huertas tradicionales y las fachadas de tradicionales bodegas excavadas. Cómo llegar: Parte superior del cerro horadado por los barrios de bodegas subterráneas, al norte del núcleo. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16243','mirador','Mirador de la Universidad y las Iglesias','7.4/10 Perspectiva sobre el conjunto monumental histórico manchego, capillas góticas, conventos, campos de cereal de secano y horizontes despejados. Cómo llegar: Cota alta de la colina que flanquea el casco histórico, accesible a pie por sendas urbanas. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16244','mirador','Alto de la Cuesta del Llano','6.2/10 Sencilla visual de campos de secano de la Mancha meridional, cultivos planos de vid e idóneo horizonte libre para astrofotografía. Cómo llegar: Camino rural elevado en los límites geográficos orientales del municipio. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16245','mirador','Mirador del Ventano del Diablo','8.8/10 Espectacular e imponente cueva natural excavada en la roca caliza volada sobre el cañón del río Júcar, pozas turquesas profundas, pinares y buitreras masivas. Cómo llegar: Balcón natural colgado acondicionado con barandillas de piedra e hito turístico en la carretera CM-2105. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16246','mirador','Mirador de la Ermita de San Sebastián y Entrepeñas','7.8/10 Amplia e lacustre perspectiva del Embalse de Entrepeñas, olivares tradicionales de la Alcarria, repoblaciones de pinos y puestas de sol reflejadas. Cómo llegar: Explanada de la ermita al norte del casco urbano, provista de accesos rodados y bancos. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16247','mirador','Alto del Teso de San Roque','6.4/10 Sencilla panorámica de la Mancha Alta, lomas onduladas arcillosas de secano e idóneo horizonte nocturno para la observación de lluvias de estrellas. Cómo llegar: Atrio elevado de la ermita, en el punto alto del casco de la localidad. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16248','mirador','Mirador del Sitio de Consolación y Cabriel','7.5/10 Vista del valle de los huertos que cae hacia el río Cabriel, frondosos bosques de pino negral, encinares serranos y la silueta del santuario histórico. Cómo llegar: Cornisa de la plataforma calcárea, accesible por el camino acondicionado del santuario. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16249','mirador','Mirador de los Molinos y de la Mancha de Santiago','6.8/10 Clásica visual manchega sobre la llanura de cereal y viñedos, con la silueta de los restos de antiguos molinos tradicionales y campanarios. Cómo llegar: Zona perimetral elevada al norte de la población, cercana a las antiguas eras de trilla. 📍 Provincia: Guadalajara.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16250','mirador','Mirador del Valle del río Guadamejud','6.9/10 Vista del encajonamiento del río entre laderas escarpadas de yesos y arcillas de la Alcarria conquense, campos de labor y olivares de ladera. Cómo llegar: Saliente natural del páramo accesible por caminos rurales desde la carretera GU-V-2131. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16251','mirador','Mirador del río Valdemembra y la Basílica','7.1/10 Vista de la vega del río Valdemembra, cultivos hortícolas tradicionales, plantaciones de champiñón y la imponente silueta fortificada de la Basílica de la Asunción. Cómo llegar: Margen de la terraza fluvial, accesible por paseos urbanos peatonales desde la Plaza Mayor. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16253','mirador','Alto del Teso de la Iglesia','6.5/10 Panorámica rural de la Mancha Alta, lomas onduladas de secano, la vega baja del río Záncara y horizontes diáfanos idóneos para astrofotografía. Cómo llegar: Cota natural elevada junto al templo de la Asunción, accesible a pie en el casco urbano. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16254','mirador','Mirador de la Villa Romana de Noheda','7.3/10 Vista arqueológica y paisajística sobre el valle menor, relieves de yesos arcillosos y el complejo museístico que alberga los mosaicos romanos figurativos más grandes del imperio. Cómo llegar: Plataforma integrada en el complejo arqueológico, accesos señalizados desde la carretera N-320. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16255','mirador','Alto de la Cuesta de las Encinas','6.3/10 Sencilla visual de campos de secano de la Mancha de la encina, encinares dispersos rústicos y horizontes limpios de obstáculos. Cómo llegar: Camino rural en los límites geográficos orientales del término municipal. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16263','mirador','Mirador del río Júcar y las Graveras','7.2/10 Vista fluvial de la vega del Júcar próxima a la capital conquense, humedales recuperados, bosques de ribera y avifauna acuática migratoria asociada. Cómo llegar: Paseo fluvial acondicionado al norte del casco urbano, con accesos peatonales y bancos. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16258','mirador','Mirador del Abrigo de la Peña del Escrito y Selva Pascuala','8.8/10 Extraordinario e imponente paisaje de cañones de arenisca roja (rodeno) que alberga un conjunto masivo de arte rupestre paleolítico y levantino Patrimonio de la Humanidad. Cómo llegar: Pasarelas y estructuras de protección adaptadas en los desfiladeros boscosos del río Cabriel, accesos guiados señalizados. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16259','mirador','Mirador del río Guadiela y Alcarria','7.0/10 Vista de la Hoya del Infantado septentrional, el discurrir del río Guadiela, olivares tradicionales alcarreños de ladera y cultivos de cereal de secano. Cómo llegar: Cornisa natural alta al este del núcleo, accesible por caminos rurales. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16264','mirador','Alto de la Ermita de Nuestra Señora de la Fuentes','6.6/10 Vista de la vega del río Záncara alto, parcelas de cultivo manchego extensivo de cereal y la silueta del histórico templo santuario. Cómo llegar: Explanada de la ermita al oeste del casco urbano, con accesos rodados. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16265','mirador','Alto del Teso de la Peñuela','6.8/10 Panorámica rural de lomas de la Serranía Baja, campos ondulados de secano e idóneo horizonte nocturno para la observación astronómica de baja luminosidad. Cómo llegar: Cota natural elevada al norte de la población, cercana a las eras tradicionales. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16266','mirador','Alto del Cerro Gordo','6.5/10 Sencilla panorámica de la llanura de transición, cultivos arcillosos de secano e idóneos atardeceres nítidos y libres de obstáculos industriales. Cómo llegar: Zona perimetral elevada al norte de la población, transitable por sendas agrícolas. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16269','mirador','Mirador de la Ermita de Jesús Nazareno','6.9/10 Vista panorámica de la Mancha Alta, campos de cereal, la traza de la autovía del Este (A-3) cruzando la llanura e infinitas puestas de sol. Cómo llegar: Explanada exterior elevada de la ermita, provista de accesos rodados y bancos. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16270','mirador','Alto del Teso Rural y autovía A-3','64/10 Vista de la llanura agrícola dedicada al cereal extensivo, dehesas dispersas y la infraestructura de transporte integrada bajo cielos limpios. Cómo llegar: Pequeña colina exenta en el sector alto de la localidad, cercana a las pistas agropecuarias. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16271','mirador','Mirador del Valle del río Cabriel','7.2/10 Perspectiva sobre la cuenca baja del Cabriel, vertientes cubiertas de matorral mediterráneo de jara, encinas jóvenes y huertas tradicionales de ribera. Cómo llegar: Saliente de la plataforma calcárea sur, transitable por pistas rurales. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16272','mirador','Mirador de la Ermita de la Virgen de la Ventosa','7.1/10 Vista de la comarca de la Alcarria conquense oriental, lomas arcillosas de cultivo cerealista, olivares tradicionales e idónea pureza Starlight nocturna. Cómo llegar: Entorno elevado de la ermita, accesible mediante camino vecinal acondicionado desde el núcleo de La Ventosa. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16273','mirador','Alto del Castillo y la Vega del Záncara','6.9/10 Vista panorámica del curso alto del río Záncara, lomas de yesos y arcillas, campos de labor tradicionales de secano y restos arqueológicos locales. Cómo llegar: Cota natural elevada al norte de la población, transitable por sendas rurales de herradura. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16274','mirador','Mirador del Viaducto de Víllora y Hoces del Cabriel','8.4/10 Impresionante perspectiva de los cañones del Cabriel, con sus escarpadas agujas calizas kársticas dominadas por el monumental viaducto ferroviario de la línea Madrid-Valencia. Cómo llegar: Plataforma con paneles interpretativos en la ruta geológica, accesible por pista desde la carretera CM-2109. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16275','mirador','Mirador de la Hoz de Vindel','7.8/10 Retorcido y frondoso desfiladero calcáreo encajonado por el río Vindel en los límites con Guadalajara, densas masas de pino negral y nítida oscuridad Starlight. Cómo llegar: Borde del precipicio natural acondicionado con valla de madera, transitable por sendero local a pie. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16276','mirador','Alto de la Ermita de San Cristóbal','7.3/10 Panorámica rural sobre el somontano de la Serranía Baja, masas forestales de pino resinero, matorrales de jara y cielos óptimos para astrofotografía nocturna. Cómo llegar: Cerro exento que alberga el pequeño templo, accesible por camino de tierra apto para vehículos. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16277','mirador','Mirador de la Atalaya del Castillo','7.9/10 Espectacular e infinita panorámica de 360 grados de la llanura manchega y los relieves de la Alcarria meridional desde un estratégico cerro testigo fortificado. Cómo llegar: Cota más elevada de la villa medieval amurallada, accesible por rampa peatonal empinada. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16278','mirador','Mirador de la Torre de El Pilar y el Ebro','8.9/10 Espectacular, monumental e internacional panorámica de 360 grados sobre el río Ebro, los puentes históricos, las cúpulas mudéjares y la gran urbe del cierzo. Cómo llegar: Terraza superior del ascensor panorámico de la torre norte de la Basílica del Pilar, acceso peatonal urbano gestionado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16279','mirador','Alto del Teso del Humilladero','6.7/10 Vista diáfana de la llanura de transición de la Mancha alta, olivares de secano, cultivos cerealistas planos y puestas de sol limpias sin obstáculos. Cómo llegar: Promontorio suave al sur de la localidad, junto a los antiguos trazados de cañadas reales. 📍 Provincia: Cuenca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16280','mirador','Mirador de la Ermita del Judío y Muela de Zarzuela','8.1/10 Magnífica visual del profundo corte del valle del Júcar septentrional, laderas calizas cubiertas de pino negral y formaciones geológicas de relieve abrupto. Cómo llegar: Explanada natural de la ermita al borde del páramo alto, transitable por sendero señalizado. ¡PROVINCIA DE CUENCA COMPLETADA AL 100%! 🏁 ⭐ Si estás de acuerdo, podemos saltar de inmediato a la siguiente provincia en el orden territorial del proyecto: Provincia de Toledo (Comunidad de Castilla-La Mancha), comenzando estrictamente desde la letra A con municipios como Ajofrín, Alameda de la Sagra, Albarreal de Tajo, Alcabón, Alcaudete de la Jara, Alcañizo, Alcolea de Tajo, Aldea en Cabo, Aldeanueva de Barbarroya, Aldeanueva de San Bartolomé, Almendral de la Cañada, Almonacid de Toledo, Almorox, Añover de Tajo, etc. ¿Prefieres que continuemos con el bloque masivo de la Provincia de Toledo o deseas revisar los criterios antes de dar el salto?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90291','mirador','Alto del Camino de las Yeseras','6.4/10 Vista diáfana de la llanura de los Montes de Toledo, campos de olivos centenarios, viñedos bajos y la silueta lejana de las primeras crestas cordilleranas. Cómo llegar: Pequeña elevación natural al sur del núcleo urbano, transitable por pistas rurales agrícolas. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90292','mirador','Mirador del Cerro de los Yesares','6.1/10 Perspectiva sobre la vega del río Tajo, cultivos hortícolas y cerealistas de la Sagra alta y el perfil industrial integrado del entorno. Cómo llegar: Cota natural arcillosa en los límites norte de la localidad, accesible por sendas agropecuarias. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90833','mirador','Mirador de las Barrancas del Tajo y las Cuestas','6.9/10 Hermosa vista de los meandros del río Tajo, escarpes arcillosos rojizos de erosión fluvial lineal, olivares de ladera y sotos frondosos. Cómo llegar: Margen de la plataforma del páramo meridional, transitable a pie por caminos vecinales. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90834','mirador','Atrio de la Iglesia de Santo Tomás Cantuariense','5.5/10 Sencilla panorámica rural de la comarca de Torrijos, llanuras cerealistas infinitas de horizontes limpios e idónea observación de puestas de sol castellanas. Cómo llegar: Plaza elevada perimetral al templo barroco, en el centro del pequeño casco urbano. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90293','mirador','Mirador de la Torre del Cura y río Jaloque','7.1/10 Vista del valle del río Sangrera y cauce del Jaloque, dehesas encajonadas de encina, monte bajo mediterráneo y la monumental arquitectura eclesiástica local. Cómo llegar: Promontorio suave al este del término, accesible por camino rural desde la carretera N-502. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43002','mirador','Adarve del Castillo de los Calatravos','8.8/10 Espectacular e histórica visual sobre el meandro del río Guadalope, el entramado monumental de la villa, la Estanca y los olivares del Bajo Aragón. Cómo llegar: Muros transitables superiores de la inexpugnable fortaleza medieval del siglo XII, actual Parador nacional. Si quieres, indícame si pasamos directamente al siguiente bloque masivo a partir de la letra A (restantes) y B de la Provincia de Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90294','mirador','Mirador del Yacimiento de El Cerro de la Mesa','7.6/10 Impresionante panorámica arqueológica sobre la vega del Tajo medio, dehesas ganaderas de encina, berrocales graníticos y la silueta del Sistema Central. Cómo llegar: Plataforma con paneles explicativos en el entorno de los restos arqueológicos vetones, acceso rural. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90295','mirador','Alto de San Pedro y el Pinar','6.5/10 Vista del valle bajo del río Alberche occidental, encinares jóvenes, matorral mediterráneo de jara y horizontes limpios de la comarca de Torrijos. Cómo llegar: Colina exenta que alberga la ermita, transitable a pie por sendas desde el pueblo. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90296','mirador','Mirador de la Vía Verde de la Jara y el Tajo','7.9/10 Espectacular e industrial panorámica del encajonamiento del río Tajo, viaductos de hormigón integrados, monte bajo mediterráneo y abundante fauna rupícola. Cómo llegar: Punto de observación acondicionado junto a la traza del antiguo ferrocarril, acceso señalizado. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90297','mirador','Mirador del dolmen de Aldeanueva','7.4/10 Vista megalítica e histórica de la dehesa extremeño-toledana, formaciones graníticas calcadas, pastizales de ganado y horizontes nítidos Starlight nocturnos. Cómo llegar: Entorno protegido del yacimiento prehistórico, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90298','mirador','Mirador de la Sierra de San Vicente','7.8/10 Soberbia visual a más de 800 metros de altitud de los densos bosques de castaños y robles, valles encajonados de montaña y la vertiente sur de Gredos. Cómo llegar: Cornisa natural alta adaptada con valla protectora al norte de la villa, carretera de montaña. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90299','mirador','Mirador del Castillo de Almonacid','8.3/10 Impresionante y colgada atalaya militar del siglo XIV sobre un cerro testigo rocoso, divisando los olivares infinitos, la llanura manchega y Toledo. Cómo llegar: Explanada de la imponente fortaleza medieval, accesible por camino peatonal o pista rodada. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90300','mirador','Mirador del Pinar de Almorox','7.7/10 Espectacular e inmenso mar de pino piñonero autóctono en los límites con Madrid, grandes berrocales de granito, encinares maduros y arroyos menores. Cómo llegar: Paraje natural acondicionado con mesas y cartelería, accesible por pistas desde la carretera de Cenicientos. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90301','mirador','Mirador de San Bartolomé y Vega del Tajo','7.3/10 Amplia e histórica perspectiva del corte geológico de la Sagra bajando hacia el río Tajo, vegas de regadío fértiles, huertas y olivares. Cómo llegar: Balcón natural adaptado con barandillas en el borde del casco urbano residencial alto. Si estás de acuerdo, podemos seguir de inmediato con los municipios restantes de la letra A y el bloque de las letras B y C de la Provincia de Toledo. ¿Continuamos con el avance masivo?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90835','mirador','Alto del Teso de las Eras','5.6/10 Vista despejada de la llanura cerealista de la comarca de Torrijos, cultivos de secano, suaves ondulaciones del terreno y horizontes limpios de obstáculos visuales. Cómo llegar: Elevación natural al norte del núcleo urbano, junto a las antiguas eras de trilla. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90302','mirador','Mirador del Embalse de Guajaraz','7.2/10 Hermosa panorámica de la lámina de agua encajada entre lomas, encinares dispersos, matorral mediterráneo de jara y avifauna acuática estacional. Cómo llegar: Corona de la presa e inmediaciones de la zona recreativa, accesible por la carretera CM-4013. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90303','mirador','Mirador del Dolmen de Azután','7.1/10 Vista de gran interés arqueológico y paisajístico sobre las vegas bajas del río Tajo, dehesas ganaderas de encina y llanuras olivareras rústicas. Cómo llegar: Entorno protegido del yacimiento megalítico, accesible por pista de tierra desde el núcleo urbano. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45018','mirador','Mirador del Castillo de Barcience','7.8/10 Magnífica perspectiva de la comarca de Torrijos, extensos campos de cultivo, olivares y la imponente silueta del castillo del siglo XV con su gran león heráldico grabado. Cómo llegar: Cerro exento que domina la población por el norte, accesible por pista apta para vehículos o sendero peatonal. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45019','mirador','Mirador de las Lomas del Guadarrama','6.6/10 Vista panorámica del valle bajo del río Guadarrama, olivares tradicionales, campos de secano de la Sagra y el perfil urbano de la periferia toledana. Cómo llegar: Cornisa natural alta situada al oeste de la localidad, accesible desde las zonas residenciales elevadas. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45020','mirador','Mirador de la Cuesta del Santo','7.3/10 Amplia visual sobre los olivares de la comarca de La Jara, monte bajo mediterráneo, formaciones de pizarra y las primeras estribaciones de los Montes de Toledo. Cómo llegar: Promontorio elevado al sur del núcleo urbano, transitable a pie por camino vecinal de tierra. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45021','mirador','Mirador de la Ermita de Nuestra Señora de la Salud','6.9/10 Perspectiva de las profundas cárcavas y cortes arcillosos de la Sagra oriental, huertas tradicionales en el fondo del valle y cielos despejados. Cómo llegar: Explanada de la ermita en el sector noreste del casco urbano, con accesos peatonales y rodados. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45022','mirador','Mirador del río Tiétar y Gredos','7.5/10 Espectacular vista del tramo bajo del río Tiétar, dehesas densas de encina y alcornoque, y el imponente telón de fondo de la Sierra de Gredos. Cómo llegar: Talud geográfico al norte del término municipal, accesible por pistas forestales rurales. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45023','mirador','Mirador del Cerro de la Atalaya','6.7/10 Panorámica limpia sobre la llanura central toledana, olivares centenarios, campos de labor y nítidos horizontes idóneos para la observación astronómica nocturna. Cómo llegar: Cota natural elevada al sur de la población, accesible por caminos agropecuarios de herradura. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45024','mirador','Mirador de los Cambrones y Barrancas de Burujón','8.9/10 Impresionante, espectacular y caótico colapso geológico de arcilla roja sobre el río Tajo, apodado el "Gran Cañón de Toledo", con abundante avifauna rupícola protegida. Cómo llegar: Sendero ecológico perimetral adaptado con barandillas y plataformas accesibles, desvío señalizado desde la carretera CM-4000. Si quieres, puedes indicarme si seguimos con los municipios que comienzan con la letra C de la Provincia de Toledo o si tienes alguna instrucción especial.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45025','mirador','Alto de la Cuesta del Tejar','6.2/10 Panorámica rural de los llanos cerealistas y arcillosos de la comarca de La Sagra alta, olivares dispersos y horizontes nítidos despejados para astrofotografía. Cómo llegar: Elevación natural al noreste del casco urbano, accesible por pistas agropecuarias de tierra. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45026','mirador','Atrio de la Iglesia de Nuestra Señora de la Asunción','6.4/10 Perspectiva sobre la mesa calcárea de Ocaña, vertientes erosionadas de barrancos secos, campos de cultivo de secano y puestas de sol limpias. Cómo llegar: Plaza pública elevada perimetral al templo barroco, en el centro de la pequeña localidad. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45027','mirador','Mirador del Molino y el rincón de la Mancha','6.6/10 Clásica estampa manchega sobre la llanura infinita de cereal y viñedos, con el antiguo molino tradicional restaurado integrando el paisaje. Cómo llegar: Pequeña colina exenta en el sector alto del término, provista de rampa y mirador acondicionado. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45028','mirador','Mirador de la Vía Verde de la Jara (Km 0)','7.8/10 Amplia visual del inicio de la ruta ferroviaria reconvertida, dehesas del Tajo, campos de regadío del canal y la sierra de Gredos lejana. Cómo llegar: Antigua estación de tren acondicionada con paneles informativos, acceso señalizado por la carretera CM-4101. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45029','mirador','Alto del Teso del Humilladero','6.3/10 Vista diáfana de la llanura agrícola de la Campana de Oropesa, dehesas ganaderas de encina y horizontes limpios de la meseta meridional. Cómo llegar: Promontorio suave al oeste del casco urbano, transitable por pistas rurales agrícolas. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45030','mirador','Mirador del Campo de Dehesas y Convento','7.0/10 Perspectiva del paisaje adehesado encajonado de la comarca, encinares maduros, ganado extensivo y las siluetas del histórico convento de las Agustinas. Cómo llegar: Cota natural elevada accesible por camino rural desde la Autovía del Suroeste (A-5). 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45031','mirador','Mirador de las Bodegas y Alto de San Roque','6.8/10 Hermosa vista de los viñedos tradicionales de la D.O. Méntrida, lomas arenosas, olivares y las hileras de respiraderos de los calados excavados. Cómo llegar: Corona del cerro horadado por las bodegas subterráneas, accesible a pie desde la ermita. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45032','mirador','Alto del Teso del Calvario','5.8/10 Sencilla panorámica sobre la campiña arcillosa baja, cultivos de cereal en secano y cielos abiertos libres de contaminación lumínica. Cómo llegar: Pequeño repecho al norte de la localidad, accesible por caminos vecinales de tierra. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45033','mirador','Mirador de los Chozos y los Montes de la Jara','7.4/10 Vista montañosa de la comarca de La Jara, laderas cubiertas de matorral de jara, encinas jóvenes y un cielo nocturno puro Starlight. Cómo llegar: Cresta de la plataforma pizarrosa elevada, transitable por pistas forestales al sur de la población. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45034','mirador','Mirador del Molino de la Unión','7.5/10 Impresionante perspectiva de la llanura de la Mancha Alta, el cauce del río Amarguillo y el restaurado molino de viento de aspas tradicionales. Cómo llegar: Cerro exento que corona el pueblo, dotado de accesos rodados pavimentados y paneles turísticos. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45035','mirador','Mirador del río Alberche y las Lomas','7.2/10 Vista fluvial del cauce del Alberche medio, frondosa vegetación de ribera, sotos arbolados y dehesas de encina ganaderas con Gredos al fondo. Cómo llegar: Margen de la terraza natural, accesible por pistas rurales desde el casco urbano de la urbanización. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45036','mirador','Alto de la Cuesta del Cristo','6.7/10 Panorámica diáfana sobre los llanos cerealistas de la comarca de Torrijos occidental, mosaicos de secano y puestas de sol limpias. Cómo llegar: Promontorio elevado al norte de la localidad, transitable a pie desde la ermita. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45037','mirador','Mirador de la Ermita de Ronda y Río Tajo','7.4/10 Hermosa vista de las vegas aluviales del Tajo, cultivos hortícolas de regadío, el bosque de ribera y la silueta mudéjar de la ermita. Cómo llegar: Entorno elevado de la ermita histórica, accesible mediante sendero señalizado cerca del cauce fluvial. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45038','mirador','Mirador del Parque Arqueológico de Carranque','81/10 Perspectiva paisajística e histórica sobre la vega del río Guadarrama, bosques de ribera y los monumentales restos de la villa romana de Materno. Cómo llegar: Pasarela elevada integrada en el complejo de recepción del Parque Arqueológico de Carranque. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45039','mirador','Atrio de la Iglesia de San Pedro Cátedra','6.1/10 Sencilla panorámica de la comarca de Torrijos central, campos ondulados de labranza tradicionales e idóneo horizonte nocturno para astrofotografía. Cómo llegar: Plaza elevada perimetral al templo parroquial, en el centro de la localidad. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45040','mirador','Mirador de la Playa del Alberche','7.0/10 Vista fluvial del ancho cauce arenoso del río Alberche, densas alamedas y sotos, avifauna ribereña y las zonas recreativas integradas. Cómo llegar: Paseo fluvial acondicionado en la margen izquierda del río, con accesos peatonales y bancos. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45041','mirador','Mirador del Castillo de Casarrubios','7.1/10 Vista del valle de la campiña alta norteña, campos de secano, olivares y las ruinas mudéjares fortificadas del siglo XIV. Cómo llegar: Explanada urbana elevada contigua a los restos de la fortaleza defensiva central. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45042','mirador','Alto del Cerro de la Horca','6.5/10 Perspectiva sobre la penillanura de la comarca de la Sisla, olivares tradicionales toledanos, cultivos de cereal e interesantes cielos nocturnos. Cómo llegar: Elevación natural del terreno transitable a pie por pistas forestales al norte del caserío. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45043','mirador','Mirador del Castillo de Bayuela y los Castros','8.4/10 Soberbia visual a más de 800 metros en la Sierra de San Vicente, valles graníticos, berrocales calcados, encinares maduros y monumentos vetones. Cómo llegar: Cima de la atalaya rocosa que corona la sierra del municipio, accesible por sendero de montaña. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45045','mirador','Mirador del Embalse de Cazalegas','7.6/10 Impresionante panorámica de la gran lámina de agua del río Alberche, zonas de ocio y deportes náuticos, frondosas choperas y Gredos al fondo. Cómo llegar: Dique y zona ajardinada de la represa, con accesos rodados y estacionamientos acondicionados. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45046','mirador','Mirador del Castillo de Villalba','7.6/10 Extraordinaria vista aérea del meandro del río Tajo medio, fértiles huertas aluviales, extensos olivares de ladera y la evocadora fortaleza medieval arruinada. Cómo llegar: Promontorio rocoso elevado sobre el acantilado fluvial, accesible por pistas rurales de tierra. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45047','mirador','Mirador del Parque del Condado','6.3/10 Vista periurbana de la comarca de La Sagra occidental, lomas agrícolas arcillosas y la silueta del palacio del Conde de Cedillo. Cómo llegar: Zona alta ajardinada provista de mirador urbano peatonal en el núcleo residencial. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45048','mirador','Alto del Cerro Gordo','6.4/10 Vista diáfana del valle del río Alberche bajo, campos ondulados de secano de la comarca de Torrijos y horizontes de la meseta norte. Cómo llegar: Cota natural elevada al norte de la población, transitable por sendas ganaderas de tierra. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45049','mirador','Mirador de las Dehesas y Sierra de San Vicente','7.1/10 Perspectiva del paisaje ganadero de dehesa, encinares tradicionales centenarios, monte bajo y las faldas montañosas del sistema central al fondo. Cómo llegar: Elevación natural del terreno transitable a pie por caminos vecinales al norte del núcleo. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45056','mirador','Mirador de las Cárcavas del Arroyo','6.2/10 Sencilla panorámica de cárcavas arcillosas erosionadas de la Sagra, campos de labranza de secano e idóneo horizonte nocturno para astrofotografía. Cómo llegar: Cornisa natural alta situada al este del núcleo, accesible por caminos rurales. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45057','mirador','Atrio de la Iglesia de Santiago Apóstol','6.4/10 Sencilla panorámica rural sobre los campos de cereal y olivares centenarios de la comarca de La Sisla baja, con horizontes manchegos despejados. Cómo llegar: Plataforma elevada urbana que circunda la portada mudéjar del templo parroquial. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45050','mirador','Alto de las Cuestas del Arroyo','6.6/10 Vista de las laderas arcillosas que caen hacia el arroyo de la Vega, olivares tradicionales, campos de cultivo y nítidos atardeceres. Cómo llegar: Borde de la mesa caliza de Ocaña, accesible por pistas agropecuarias de tierra. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45051','mirador','Mirador de las Canteras de Arcilla','6.1/10 Singular paisaje minero industrial de grandes explotaciones de arcilla para tejas de la Sagra, campos cerealistas colindantes y relieve llano. Cómo llegar: Entorno perimetral seguro de las excavaciones arcillosas, acceso por la carretera CM-4004. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45052','mirador','Mirador de la Atalaya de Cobisa','6.8/10 Vista panorámica periurbana sobre la llanura de la Sisla, la silueta monumental de la capital provincial a lo lejos y cultivos de olivo. Cómo llegar: Zona alta residencial acondicionada con barandilla y paseo peatonal en el municipio. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45053','mirador','Mirador del Cerro Calderico','9.4/10 Espectacular, icónica e ininterrumpida panorámica de doce molinos de viento tradicionales alineados y el imponente castillo medieval sobre el infinito mar de la Mancha. Cómo llegar: Cresta rocosa alargada acondicionada con accesos rodados pavimentados, estacionamientos y barandillas, acceso turístico directo. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45054','mirador','Mirador de la Ermita de la Virgen de la Muela','7.1/10 Vista de la fértile vega del río Riansares, el mar de viñedos manchegos de la llanura, olivares tradicionales e idóneo entorno para astrofotografía. Cómo llegar: Cerro exento que alberga el complejo de la ermita, transitable por camino asfaltado con área recreativa. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45055','mirador','Mirador del Castillo de Cuerva y la Sisla','7.4/10 Perspectiva de la transición hacia los Montes de Toledo, campos de cultivo, olivares y la fisonomía de la gran fortaleza mudéjar del siglo XV. Cómo llegar: Explanada de la antigua fortaleza señorial en la cota más elevada del trazado de la localidad. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45058','mirador','Alto del Teso de San Cristóbal','6.4/10 Sencilla panorámica de las lomas arcillosas de la comarca de Torrijos, campos ondulados de secano cerealista e idóneos horizontes limpios. Cómo llegar: Cota natural elevada al norte de la población, cercana a las eras tradicionales. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45059','mirador','Mirador del Castillo de Monreal','7.6/10 Impresionante e histórica atalaya medieval sobre el valle del arroyo de la Vega, los escarpes calizos de la mesa de Ocaña y la autovía A-4. Cómo llegar: Cerro testigo aislado coronado por las ruinas de la fortaleza gótica, accesible por pistas rurales de tierra. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45060','mirador','Atrio de la Iglesia de la Asunción','5.8/10 Vista diáfana de la llanura cerealista de la comarca de Torrijos, horizontes limpios libres de obstáculos industriales e idóneo punto para puestas de sol. Cómo llegar: Plaza sobreelevada junto a la fábrica del templo mudéjar con torre mudéjar exenta de ladrillo. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45061','mirador','Mirador del Castillo-Palacio de Escalona y Río Alberche','8.8/10 Soberbia, colgada y espectacular panorámica del gran río Alberche bajo los imponentes muros mudéjares del castillo del siglo XV de Álvaro de Luna. Cómo llegar: Gran balcón natural acondicionado con barandillas y mirador urbano en pleno casco histórico fortificado. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45062','mirador','Mirador de las Bodegas y Alto de la Cruz','6.9/10 Vista de los extensos olivares de la comarca de Torrijos, campos de cereal, relieves suaves e hileras de chimeneas de antiguos calados excavados. Cómo llegar: Parte superior del cerro horadado por las bodegas tradicionales subterráneas, al oeste del núcleo. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45063','mirador','Mirador del Risco de la Umbría','8.1/10 Espectacular relieve de montaña de los Montes de Toledo occidentales, densos bosques de quejigo y encina, riscos cuarcíticos escarpados y nítido cielo nocturno Starlight. Cómo llegar: Plataforma rocosa elevada en las cumbres del municipio, accesible por sendas de montaña y pistas forestales. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45064','mirador','Mirador de la Casa de Cervantes y viñedos de la Sagra','71/10 Vista paisajística e histórica sobre la comarca de la Sagra alta, olivares tradicionales, campos que inspiraron el Quijote y horizontes diáfanos. Cómo llegar: Zona alta de la villa acondicionada con mirador público peatonal en el núcleo histórico cervantino. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45065','mirador','Mirador del yacimiento de la Ciudad de Vascos','7.7/10 Impresionante vista sobre los meandros encajonados del río Huso, berrocales de granito salvajes y las ruinas monumentales de la ciudad islámica del siglo X. Cómo llegar: Plataforma perimetral acondicionada para visitantes del parque arqueológico en los límites del término. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45066','mirador','Mirador de la Ermita de San Roque y viñedos','6.8/10 Panorámica de los llanos vitivinícolas y olivareros de la comarca, relieve suave de lomas arcillosas y amplios cielos idóneos para astrofotografía. Cómo llegar: Explanada exterior sobreelevada de la ermita, provista de accesos peatonales y bancos urbanos. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45067','mirador','Mirador del Castillo de Gálvez y Montes de Toledo','7.5/10 Vista de las dehesas del somontano norte de los Montes de Toledo, encinares ganaderos, campos de labor y la silueta de la fortaleza señorial. Cómo llegar: Explanada de la antigua fortaleza medieval del siglo XIV, en la periferia elevada de la población. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45068','mirador','Mirador de los Puentes Romanos y dehesa','7.6/10 Hermosa vista de los valles del arroyo de los Molinos, formaciones graníticas de la Sierra de San Vicente, encinares maduros y puentes tradicionales. Cómo llegar: Saliente natural acondicionado con vallado rústico de madera, accesible por pistas forestales. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45069','mirador','Alto del Teso de las Eras','6.4/10 Sencilla panorámica sobre los llanos cerealistas y olivareros de la comarca de Torrijos, de relieve horizontal e idóneo cielo nocturno sin contaminación. Cómo llegar: Cota natural elevada al noreste del pueblo, accesible por pistas de servicio agrícola de tierra. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45070','mirador','Mirador del Castillo de Guadamur y Guarrazar','8.4/10 Impresionante y palaciega panorámica de la fortaleza neogótica del siglo XV perfectamente conservada, olivares de la Sisla y el yacimiento visigodo. Cómo llegar: Explanada exterior acondicionada y ajardinada que rodea el foso del castillo, centro urbano. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45071','mirador','Mirador del Balcón de la Mancha y Ermita del Santo Niño','8.0/10 Espectacular e infinita visual colgada sobre la llanura de la Mancha Alta, el valle del río Algodor, los campos de cereal y el santuario rupestre. Cómo llegar: Cornisa de la mesa caliza acondicionada con barandilla y mirador urbano, acceso por la carretera de la ermita. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45072','mirador','Mirador del río Tajo y Castrejón','7.3/10 Vista del cauce ancho y sinuoso del río Tajo inferior, los sotos de ribera protegidos, campos de regadío y avifauna acuática de la comarca de Talavera. Cómo llegar: Balcón natural acondicionado con barandilla en el flanco norte del casco urbano, sobre el acantilado fluvial. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45073','mirador','Mirador de las Dehesas de la Campana','6.5/10 Perspectiva del paisaje adehesado de encina y pastizal, ganado bovino extensivo rústico y el horizonte nítido del Sistema Central lejano. Cómo llegar: Elevación natural del terreno transitable a pie por caminos vecinales al sur de la localidad. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45074','mirador','Mirador del Pico de San Vicente y Cabeza del Oso','8.7/10 Extraordinaria y soberbia panorámica de 360 grados desde la cumbre (1321 m) de la Sierra de San Vicente, divisando el Tajo, el Alberche y Gredos completo. Cómo llegar: Cima rocosa cuarcítica y granítica más alta de la comarca, accesible por sendero de montaña empinado. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45076','mirador','Mirador del Alberche y las Viñas de Maqueda','7.2/10 Vista del valle fluvial del Alberche medio, terrazas aluviales de cultivo vitivinícola, olivares tradicionales de ladera y puestas de sol limpias. Cómo llegar: Borde del talud natural accesible por pistas forestales al este de las urbanizaciones. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45077','mirador','Alto del Teso de San Juan','6.2/10 Sencilla panorámica rural de lomas arcillosas dedicadas al secano, olivares tradicionales de la comarca de Torrijos y horizontes limpios de obstáculos. Cómo llegar: Pequeño promontorio natural al norte del caserío, transitable a pie por sendas de tierra. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45078','mirador','Mirador del Castillo de Huerta y Ermita del Rosario','7.4/10 Vista panorámica del valle del río Algodor, los escarpes de yesos y arcillas de la Mesa de Ocaña occidentales y las ruinas de la fortaleza. Cómo llegar: Cerro exento que alberga la ermita modernista y ruinas del castillo, accesible por camino pavimentado. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45081','mirador','Mirador de la Dehesa de Illescas y Olmo Milenario','6.6/10 Vista de la llanura industrial de la Sagra central, campos agrícolas tradicionales que resisten el avance logístico y la silueta mudéjar urbana. Cómo llegar: Parque urbano elevado perimetral al casco antiguo, con paseos peatonales pavimentados. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45080','mirador','Atrio del Templo del despoblado','5.4/10 Sencilla visual de campos de cereal en secano de la meseta meridional, de relieve horizontal, baja luminosidad e idónea observación astronómica nocturna. Cómo llegar: Pequeño espacio elevado frente a la iglesia del municipio con menor población de España. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45082','mirador','Mirador de las Dehesas y Berrocales Graníticos','7.3/10 Vista del paisaje de dehesa ganadera de la Campana de Oropesa, formaciones de bolos graníticos erosionados, encinares y la arquitectura de piedra tradicional. Cómo llegar: Camino rural en los límites occidentales del municipio, apto para senderismo. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45083','mirador','Mirador del Embalse de Guajaraz y Campo de Golf','7.1/10 Vista panorámica de la lámina de agua de la represa, el contraste verde de las instalaciones deportivas, olivares tradicionales de la Sisla y lomas de jara. Cómo llegar: Cornisa residencial del complejo ajardinado, accesible por pistas urbanas transitables. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45084','mirador','Observatorio de las Lagunas de Lillo','7.5/10 Excepcional panorámica ornitológica de la Reserva Natural del complejo lagunar salino (Laguna de Longar), idónea para avistamiento de flamencos y avutardas. Cómo llegar: Caseta-observatorio adaptada con paneles informativos en la periferia de las cubetas salinas. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45085','mirador','Alto del Teso de las Eras','6.1/10 Sencilla perspectiva rural sobre lomas arcillosas de la Sagra, campos ondulados de cultivo de secano y puestas de sol limpias. Cómo llegar: Cota natural elevada al norte de la población, cercana a las eras de trilla. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45087','mirador','Mirador del Molino del Tío Genaro y Sierras','7.8/10 Vista de la llanura manchega central, mar de viñedos y olivares bajo la silueta del histórico molino de viento de 400 años y crestas serranas. Cómo llegar: Explanada urbana del molino de viento tradicional, sector noreste de la localidad. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45088','mirador','Mirador del cerro de la Atalaya','6.6/10 Vista de las terrazas arcillosas de la Sagra central, campos de cereal planos y la silueta del Sistema Central en horizontes limpios de invierno. Cómo llegar: Cota natural elevada al norte de la población, transitable a pie por sendas rurales. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45089','mirador','Mirador del Castillo de Malpica y río Tajo','7.9/10 Hermosa e histórica vista del río Tajo flanqueado por una fortaleza mudéjar del siglo XIV, sotos fluviales frondosos y densos campos de regadío. Cómo llegar: Espacio peatonal acondicionado junto al puente histórico que cruza el río. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45090','mirador','Mirador del Castillo de Manzaneque','7.2/10 Panorámica rural de los viñedos que lindan con los Montes de Toledo, la silueta de la fortaleza medieval y horizontes despejados. Cómo llegar: Explanada perimetral de la torre del homenaje visitable, centro de la localidad. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45091','mirador','Adarve del Castillo de la Vela','8.4/10 Espectacular atalaya sobre el Valle del Alberche meridional, campos de secano de Torrijos y las imponentes defensas defensivas señoriales gótico-mudéjares. Cómo llegar: Muros transitables de la fortaleza, abierta a visitas culturales en la cota urbana. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45093','mirador','Mirador de la Sierra de San Vicente','6.9/10 Vista del encajonamiento entre lomas pedregosas de media montaña, encinares maduros, dehesas ganaderas de granito y cielos nocturnos puros. Cómo llegar: Borde del talud natural accesible por caminos rurales desde el pueblo. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45094','mirador','Mirador del Castillo de Mascaraque','7.1/10 Vista panorámica sobre los llanos cerealistas y olivares centenarios de la comarca de Sisla, con la silueta fortificada del siglo XIV. Cómo llegar: Explanada elevada que rodea los muros de la fortaleza en el núcleo urbano. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45096','mirador','Mirador del Embalse de Finisterre','7.4/10 Vista de la gran masa de agua embalsada, cerros arcillosos con monte bajo mediterráneo de jara, encinas e idóneo punto de astrofotografía. Cómo llegar: Corona e inmediaciones de la presa, accesible por pistas rurales de tierra. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45097','mirador','Mirador del Castillo de Mejorada','7.2/10 Perspectiva sobre la Sierra de San Vicente meridional, la vega baja del río Guadyerbas y las ruinas del castillo bajomedieval. Cómo llegar: Promontorio rocoso elevado al oeste de la localidad, transitable a pie por sendero local. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45098','mirador','Mirador del Embalse del Torcón y Despoblado de Malamoneda','8.1/10 Espectacular e histórico paisaje serrano de los Montes de Toledo, grandes berrocales de granito, encinares maduros, restos arqueológicos medievales y pureza Starlight. Cómo llegar: Entorno natural de la presa y el yacimiento arqueológico, acceso señalizado por pistas forestales. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45099','mirador','Mirador de los Viñedos de la D.O. Méntrida','7.5/10 Mar de viñedos en lomas arcillosas suaves del Valle del Alberche oriental, encinares y puestas de sol limpias de obstáculos. Cómo llegar: Pista agrícola elevada hacia el norte del término, en la zona alta de bodegas. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45100','mirador','Mirador del Tajo y de la Ermita','6.6/10 Vista sobre las vertientes agrícolas de la comarca de Torrijos bajando al río Tajo, olivares y horizontes limpios de contaminación. Cómo llegar: Pequeña colina exenta coronada por la ermita de San Bartolomé, transitable a pie. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45101','mirador','Mirador de la Reserva Ornitológica de los Charcones','7.6/10 Excepcional panorámica ornitológica de humedales manchegos recuperados, idónea para avistamiento masivo de flamencos, malvasías, ánades y estepa. Cómo llegar: Puesto de observación acondicionado con paneles explicativos en la periferia lagunar. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45103','mirador','Mirador del Collado de San Vicente','7.9/10 Impresionante vista montañosa de la comarca de La Jara, laderas escarpadas de pizarras cubiertas de densos jarales y un cielo nocturno muy oscuro. Cómo llegar: Punto alto de montaña accesible por pistas forestales al sur de la localidad. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45104','mirador','Mirador del río Alberche y las Huertas','6.8/10 Vista panorámica del curso bajo del río Alberche, cultivos hortícolas de regadío, chopera lineal de ribera y horizontes de Talavera lejanos. Cómo llegar: Margen de la terraza fluvial, accesible por pistas desde el casco urbano. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45105','mirador','Alto de las Caleras Tradicionales','7.1/10 Vista arqueológica e industrial sobre dehesas de encina de la comarca de la Sierra de San Vicente, matorral mediterráneo y canteras históricas. Cómo llegar: Entorno del antiguo complejo etnográfico de caleras, acceso pedestre. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45106','mirador','Mirador del Castillo de Peñas Negras','83/10 Soberbia, inexpugnable e histórica atalaya militar del siglo XII esculpida sobre una cresta rocosa calcárea, divisando un mar infinito de olivares. Cómo llegar: Cima caliza de la cresta rocosa sobre el pueblo, accesible por sendero peatonal empinado o pista de tierra. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45107','mirador','Mirador del Cerro de la Cantera','6.7/10 Vista periurbana de la llanura toledana, olivares, cultivos agrícolas arcillosos de secano y la silueta urbana de la capital provincial. Cómo llegar: Cima suave del cerro acondicionado con accesos peatonales en la periferia del núcleo. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45109','mirador','Mirador del Castillo de Dos Hermanas','8.2/10 Impresionantes agujas rocosas de granito coronadas por las ruinas de una fortaleza del siglo XIII, con profundas vistas a los Montes de Toledo. Cómo llegar: Crestas de granito situadas a dos kilómetros del núcleo, accesibles por sendero de montaña. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45114','mirador','Mirador de la Ermita del Guijo','7.8/10 Magnífica perspectiva de las laderas boscosas del Valle del Tiétar, encinares maduros, dehesas y las cumbres del Sistema Central al fondo. Cómo llegar: Explanada de la ermita al norte del casco urbano, accesible por pistas rurales. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45115','mirador','Mirador de la Cuesta de las Bodegas y Valle del Tajo','7.1/10 Vista de la vega del río Tajo oriental, olivares, campos de cereal y el característico entramado de chimeneas de tradicionales calados excavados. Cómo llegar: Parte superior del cerro horadado por las bodegas subterráneas, al norte del núcleo. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45116','mirador','Mirador del Pico de Noez','7.3/10 Extraordinario e ininterrumpido cerro testigo que ofrece una panorámica de 360 grados de la llanura toledana y Montes de Toledo. Cómo llegar: Vértice geodésico en la cima del teso exento que corona la localidad, accesible por sendero. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45117','mirador','Mirador del río Alberche y dehesas','7.2/10 Perspectiva sobre el curso medio del río Alberche, encinares ganaderos de granito, berrocales erosionados y horizontes serranos limpios. Cómo llegar: Borde del talud geográfico al sur de la localidad, transitable por sendas ganaderas. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45118','mirador','Alto del Calvario','6.4/10 Sencilla panorámica de la comarca de Torrijos, campos ondulados de cultivo de secano e idóneo horizonte nocturno para la fotografía de estrellas. Cómo llegar: Atrio elevado de la ermita de la Monjía, en el punto alto del término rural. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45119','mirador','Mirador del Camino de la Vega','6.1/10 Perspectiva de las terrazas arcillosas de la Sagra baja, cultivos de secano y el entorno industrial periférico integrado en la llanura. Cómo llegar: Zona perimetral elevada al este del casco urbano. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45120','mirador','Mirador de la Dehesa de Nuño Gómez','7.0/10 Vista de dehesas ganaderas de encina próximas a la sierra, formaciones graníticas calcadas, campos de secano rústicos y cielos limpios Starlight. Cómo llegar: Pista agrícola perimetral accesible al oeste de la población. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45121','mirador','Mirador de la Fuente Grande y la Mesa de Ocaña','7.9/10 Extraordinaria vista sobre el barranco calcáreo de la gran meseta, la monumental obra renacentista de Juan de Herrera e infinitos horizontes manchegos. Cómo llegar: Terraza natural acondicionada con barandilla sobre el valle de la Fuente, casco histórico. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45122','mirador','Mirador del Cerro de la Cruz','6.7/10 Vista panorámica del Valle del Tajo norte, cultivos de cereal en el páramo superior, silueta urbana periurbanizada y Toledo al fondo. Cómo llegar: Cota más alta del núcleo urbano residencial, accesible a pie desde el cementerio. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45123','mirador','Mirador del Mar de Ontígola','7.3/10 Vista de la histórica laguna artificial construida en el siglo XVI por Felipe II, vegetación palustre, aves acuáticas y relieve arcilloso de la comarca. Cómo llegar: Sendero perimetral adaptado en el entorno protegido de la reserva natural, acceso rural. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45124','mirador','Mirador de la Torre del Homenaje del Castillo de Orgaz','7.6/10 Excelente e histórica panorámica de la villa medieval, olivares centenarios de la llanura meridional y las crestas lejanas de los Montes de Toledo. Cómo llegar: Cuerpo de defensa superior de la fortaleza medieval perfectamente restaurada en el núcleo urbano. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45125','mirador','Adarve del Castillo de Oropesa (Palacio de los Álvarez de Toledo)','8.6/10 Soberbia e ininterrumpida panorámica del Campo de Arañuelo, dehesas encinares, la Campana de Oropesa y el imponente muro nevado de la Sierra de Gredos. Cómo llegar: Pasarela superior visitable del castillo medieval del siglo XIV, hoy Parador Nacional de Turismo. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45126','mirador','Alto de la Cuesta del Olivo','6.3/10 Sencilla panorámica de la Campiña arcillosa de la comarca de Torrijos, campos ondulados de secano e idóneo horizonte nocturno de baja luminosidad. Cómo llegar: Camino rural en los límites geográficos orientales del término. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45127','mirador','Mirador de la Vega del Alberche','6.2/10 Vista sobre los llanos aluviales fértiles, cultivos de secano de la Sagra noroccidental y el cauce menor arbolado de ribera. Cómo llegar: Margen de la terraza fluvial, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45128','mirador','Mirador de las Canteras de Arcilla','6.1/10 Singular paisaje minero de grandes explotaciones cerámicas e industriales de arcilla de la Sagra, campos de labor de cereal y cielos abiertos. Cómo llegar: Entorno perimetral seguro de las excavaciones, accesible por caminos rurales desde el pueblo. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45129','mirador','Mirador del río Alberche y el Rollo Jurisdiccional','7.2/10 Vista del valle alto del río Alberche fronterizo con Madrid, encinares ganaderos de granito, praderas rústicas y el monumento gótico del rollo. Cómo llegar: Plaza central elevada e inmediaciones de los senderos fluviales del Alberche. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45130','mirador','Mirador del Guadyerbas y Gredos','7.4/10 Vista del valle del río Guadyerbas, densas dehesas de encina ganaderas, matorral mediterráneo de jara y las cumbres nevadas del Sistema Central. Cómo llegar: Cota natural elevada al norte del pueblo, accesible por pistas forestales. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45131','mirador','Mirador de los Chozos y Sierra de San Vicente','7.8/10 Magnífica perspectiva de las laderas de montaña, castañares centenarios, dehesas ganaderas de granito, chozos de piedra seca tradicionales y cielos Starlight puros. Cómo llegar: Saliente natural de la sierra acondicionado con valla de madera, acceso por sendero local de montaña. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45132','mirador','Mirador de la Urbanización Gran Chaparral','6.9/10 Vista de dehesas ganaderas de encina en el somontano de San Vicente, cultivos de secano e integración con el entorno residencial moderno. Cómo llegar: Zona alta ajardinada en la cornisa del complejo residencial periurbano de Talavera. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45133','mirador','Mirador del Castillo de Polán','7.2/10 Vista sobre la vega del río Tajo medio, olivares tradicionales, campos de cereal y las ruinas fortificadas de la fortaleza bajomedieval del siglo XII. Cómo llegar: Explanada de la antigua fortaleza en la cota más elevada de la localidad. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45134','mirador','Alto del Teso de la Iglesia','6.3/10 Sencilla panorámica de la comarca de Torrijos central, campos ondulados de secano e idóneo horizonte nocturno para la observación de astros. Cómo llegar: Atrio elevado del templo parroquial, en el punto alto del casco urbano. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45144','mirador','Mirador del Piélago','8.4/10 Impresionante e infinita visual alpina a más de 1100 metros de altitud en el corazón de la sierra, densos bosques de castaños, robles y Gredos. Cómo llegar: Plataforma acondicionada con barandilla en el collado del Piélago, acceso por la carretera de montaña de San Vicente. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45145','mirador','Mirador del Castillo de Canales','6.8/10 Vista del valle bajo del río Guadarrama, las ruinas de la fortaleza musulmana sobre un escarpe arcilloso, huertas de regadío y la Sagra. Cómo llegar: Borde del talud geográfico natural, accesible por pistas rurales desde el pueblo. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45146','mirador','Mirador del valle de la Jara y los Canchos','7.4/10 Vista de la comarca de La Jara central, laderas escarpadas de pizarras y cuarcitas cubiertas de densos jarales e idóneo entorno astronómico Starlight. Cómo llegar: Cota natural elevada accesible por las pistas forestales que suben a las cumbres del término. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45147','mirador','Mirador del Camino de la Vega','6.1/10 Sencilla panorámica sobre los llanos agrícolas fértiles de regadío, cultivos hortícolas del arroyo y campos de cereal de la comarca de Torrijos. Cómo llegar: Margen de la terraza fluvial, accesible por pistas rurales desde el pueblo. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45148','mirador','Mirador del Valle del Gévalo','8.3/10 Impresionante panorama de los valles de montaña del corazón de los Montes de Toledo, canchales de cuarcita, densos quejigares, encinares y pureza astronómica. Cómo llegar: Cota rocosa acondicionada con valla de madera en el puerto de montaña del término, desvío señalizado. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45149','mirador','Mirador de los Molinos de Viento','7.5/10 Espectacular perspectiva de la llanura manchega oriental, cultivos de azafrán, viñedos planos y los cuatro molinos de viento tradicionales alzados en la cresta calcárea. Cómo llegar: Plataforma de los molinos de viento en el cerro que domina el casco urbano, provista de accesos rodados. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45150','mirador','Alto del Cerro del Santo','6.8/10 Panorámica rural de lomas onduladas de la comarca de La Jara norte, encinares ganaderos de secano y horizontes limpios libres de postes industriales. Cómo llegar: Colina exenta que alberga la ermita, transitable a pie desde el casco urbano. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45152','mirador','Mirador del Palacio de los Antiguos Señores y río Pusa','7.3/10 Vista sobre la vega del río Pusa, dehesas ganaderas de encina, monte bajo mediterráneo y la monumental arquitectura señorial del casco urbano. Cómo llegar: Promontorio suave junto al palacio renacentista, transitable por el casco histórico. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45151','mirador','Mirador del Castillo de Montalbán y Melque','85/10 Impresionante e inexpugnable cañón del río Torcón coronado por la descomunal fortaleza templaria del siglo XII, encinares maduros y la joya visigoda lejana. Cómo llegar: Borde del precipicio natural acondicionado frente a los muros fortificados, acceso por sendero rural. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45153','mirador','Mirador del Puerto de San Pablo','8.6/10 Soberbia visual alpina a más de 900 metros de altitud en pleno corazón de los Montes de Toledo, extensos robledales, quejigares, hábitat del ciervo y Starlight. Cómo llegar: Cresta de la plataforma montañosa acondicionada con parada en la carretera que comunica con Ciudad Real. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45154','mirador','Mirador del Teso del Castillo','7.1/10 Vista del valle bajo del Alberche septentrional, encinares ganaderos de granito, berrocales erosionados y horizontes de la Sierra de San Vicente lejanos. Cómo llegar: Promontorio rocoso elevado al norte de la población, transitable por sendas rurales de tierra. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45155','mirador','Alto del Teso del Calvario','7.2/10 Panorámica rural de lomas onduladas de la comarca de La Jara, vegas de cultivo de regadío del río Pusa y matorral mediterráneo denso. Cómo llegar: Pequeña colina al oeste del casco urbano, accesible por pistas agropecuarias de tierra. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45156','mirador','Mirador de la Peña de la Calzada y Vega del Tajo','7.5/10 Amplia e histórica perspectiva del corte geológico de la gran meseta hacia la vega del río Tajo, cultivos de secano planos e infinitos horizontes manchegos. Cómo llegar: Cornisa acondicionada con barandilla y mirador urbano en el extremo norte de la villa amurallada. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45157','mirador','Mirador del Arroyo de las Parras','6.6/10 Vista de las llanuras agrícolas arcillosas de la comarca de Torrijos, encinares ganaderos dispersos, cultivos de vid y horizontes limpios de obstáculos. Cómo llegar: Margen de la terraza fluvial menor, accesible por pistas rurales desde el pueblo. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45158','mirador','Mirador del Rollo Jurisdiccional y la Vega','6.8/10 Vista panorámica sobre los llanos cerealistas de la comarca de Torrijos occidental, olivares centenarios y el trazado de la autovía A-5 en el horizonte. Cómo llegar: Espacio público elevado en las eras altas adyacentes al monumento de justicia medieval. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45901','mirador','Mirador de las Ruinas de Caudilla','6.5/10 Perspectiva romántica de los llanos de Torrijos, campos de cultivo cerealista planos e integrando las evocadoras ruinas de la torre fortificada del siglo XV. Cómo llegar: Explanada natural que rodea los restos del castillo exento del despoblado de Caudilla. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45159','mirador','Mirador del río Tiétar y el Puente Románico','71/10 Vista del cauce encajonado del río Tiétar fronterizo con Ávila, dehesas densas de encina, el puente de piedra tradicional e imponentes fondos de Gredos. Cómo llegar: Paseo fluvial acondicionado junto al antiguo paso del río, periferia del término. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45160','mirador','Mirador de la Atalaya de Segurilla','7.6/10 Espectacular e histórica panorámica desde una torre vigía circular del siglo XI, divisando la vega del Alberche, Talavera de la Reina y la Sierra. Cómo llegar: Cerro testigo elevado al norte del casco urbano, provisto de rampa de acceso peatonal y barandillas. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45161','mirador','Mirador del Castillo de Puñoenrostro y Valle del Jarama','6.3/10 Vista que combina la infraestructura de la fortificación del siglo XIV con los llanos aluviales de la Sagra baja, cultivos hortícolas y polígonos industriales. Cómo llegar: Explanada de la antigua fortaleza medieval que domina el cerro testigo sobre el núcleo histórico.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45162','mirador','Mirador del Estrecho de la Jara y Garganta de las Lanchas','7.8/10 Impresionante vista de las profundas loras rocosas, bosques de robles, encinares maduros, loros y microrreservas de vegetación atlántica relictual protegida. Cómo llegar: Plataforma alta acondicionada con barandilla sobre la pista forestal de las gargantas. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45163','mirador','Mirador del Alcornocal y de la Ermita de San Gregorio','7.2/10 Perspectiva sobre la penillanura sur de los Montes de Toledo, dehesas densas de encina y alcornoque, campos cerealistas e idónea nitidez astronómica. Cómo llegar: Entorno elevado de la ermita, accesible por pista rural adaptada desde el núcleo. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45164','mirador','Alto del Cerro Gordo','6.6/10 Vista panorámica del valle del arroyo de las Palomas, suaves lomas cubiertas de matorral bajo mediterráneo de jara, tomillares y encinas jóvenes. Cómo llegar: Cota natural elevada al norte del pueblo, accesible por sendas agropecuarias de tierra. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45165','mirador','Mirador de las Murallas de la calle Carnicerías y el Tajo','8.1/10 Magnífica vista de la vega del río Tajo, sus puentes históricos, sotos fluviales y el histórico recinto amurallado con sus torres albarranas medievales. Cómo llegar: Adarve transitable superior de la muralla recuperada, en pleno centro histórico de la ciudad. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45166','mirador','Mirador de los Molinos de Viento y la Mancha Alta','7.1/10 Clásica estampa manchega sobre la llanura infinita de cereal, olivares dispersos y los dos molinos de viento tradicionales restaurados dominando el paisaje. Cómo llegar: Cerro exento en las afueras orientales del núcleo urbano, provisto de accesos pavimentados. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45167','mirador','Mirador del Atrio de la Iglesia de San Antonio Abad','7.3/10 Perspectiva urbana e histórica sobre la patria de Dulcinea, la llanura cervantina de viñedos y un cielo nocturno limpio apto para astrofotografía. Cómo llegar: Explanada de la imponente iglesia-fortaleza renacentista apodada la "Catedral de la Mancha". 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45168','mirador','Mirador del Valle','9.8/10 Extraordinaria, monumental e icónica panorámica de 360 grados sobre el foso del río Tajo, el Alcázar, la Catedral y la urbe Patrimonio de la Humanidad. Cómo llegar: Balcón y paseo adaptado con barandillas junto a la ermita de la Virgen del Valle, carretera de circunvalación. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45169','mirador','Alto de la Cuesta del Secano','6.4/10 Vista diáfana de la llanura ganadera de la Campana de Oropesa, dehesas dispersas, olivares y la silueta del Sistema Central lejano. Cómo llegar: Repecho suave al oeste de la localidad, transitable por caminos vecinales agrícolas. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45170','mirador','Mirador del Pico de la Mesa y los Alcornocales','7.4/10 Amplia visual del somontano de La Jara, laderas cubiertas de monte mediterráneo, valles de pizarras y horizontes de gran pureza para astroturismo. Cómo llegar: Cota natural elevada al norte de la población de Retamoso, accesible por pistas forestales. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45171','mirador','Mirador de la Cuesta de las Bodegas y Alto de la Cruz','6.7/10 Vista de las lomas onduladas cubiertas de viñedos bajos y olivares, el casco urbano escalonado e hileras de lumbreras tradicionales subterráneas. Cómo llegar: Corona de la colina horadada por las bodegas, accesible a pie en el sector norte. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45173','mirador','Mirador del Palacio de Pedro I y la Sagra Baja','6.8/10 Vista de los llanos agrícolas cerealistas de la comarca, el entramado urbano monumental gótico-mudéjar e interesantes cielos al atardecer castellano. Cómo llegar: Explanada de los patios y zonas altas del histórico palacio, actual sede del Ayuntamiento. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45174','mirador','Mirador de las Esculturas de los Toros Vetones','6.9/10 Vista arqueológica sobre la llanura ganadera de los Montes de Toledo, dehesas rústicas de encina y los monumentales berracos de granito prehistóricos. Cómo llegar: Entorno protegido de los monumentos megalíticos en la plaza principal de la localidad. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45175','mirador','Mirador del Embalse de Finisterre','6.5/10 Perspectiva sobre la masa de agua regulada del río Algodor, campos de cultivo, olivares marginales y avifauna estacional ligada al medio. Cómo llegar: Zona de la represa y miradores perimetrales accesibles por pistas desde la CM-4005. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45176','mirador','Mirador del Parque de la Sagra norte','5.9/10 Vista periurbana de la llanura sagreña septentrional lindando con Madrid, campos agrícolas remanentes de secano y horizontes despejados sin postes. Cómo llegar: Zona alta ajardinada con accesos peatonales dentro de los parques urbanos del núcleo. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45177','mirador','Mirador de la Sierra de la Calderina','7.6/10 Soberbia visual a más de 1000 metros de altitud de la cresta montañosa, escarpes calizos calcáreos, encinares, quejigares y cielos nocturnos catalogados Starlight. Cómo llegar: Estructura junto a las casetas de vigilancia forestal, accesible por pista de montaña empinada. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45179','mirador','Mirador del Pozo de los Moros y Pozos de Agua','7.7/10 Vista panorámica de la cuenca baja del río Tajo, grandes berrocales de granito, dehesas ganaderas tradicionales y patrimonio etnográfico de piedra. Cómo llegar: Paraje elevado y acondicionado junto a las antiguas estructuras hídricas rurales. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45180','mirador','Mirador de la Dehesa de las Carretas','6.6/10 Panorámica rural de lomas arcillosas que dividen las cuencas del Guadarrama y el Alberche, encinares dispersos, matorral mediterráneo y cultivos bajos. Cómo llegar: Borde del repecho natural accesible por caminos rurales desde la carretera A-5. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45182','mirador','Mirador de la Ermita del Milagro y Molino de Viento','8.4/10 Espectacular e imponente balcón sobre los Montes de Toledo septentrionales, grandes canteras de granito, encinares densos e idónea pureza Starlight. Cómo llegar: Explanada natural adaptada con barandilla junto a la ermita y el molino tradicional, cerro elevado. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45183','mirador','Alto del Teso de Retamosa','6.1/10 Sencilla visual de campos de secano de la campiña baja, viñedos dispersos y horizontes limpios idóneos para observar puestas de sol castellanas. Cómo llegar: Elevación natural al norte de la población, accesible por pistas agropecuarias. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45184','mirador','Mirador de las Dehesas de San Julián','6.5/10 Perspectiva sobre la penillanura ganadera de la Campana de Oropesa, formaciones graníticas calcadas, campos de pasto rústico y baja contaminación. Cómo llegar: Saliente natural accesible por pistas ganaderas de tierra desde el núcleo urbano. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45186','mirador','Mirador del río Cigüela y de la Mancha','6.8/10 Vista panorámica del curso fluvial del Cigüela, humedales estacionales, extensos viñedos planos manchegos y horizontes limpios sin obstáculos industriales. Cómo llegar: Margen de la terraza aluvial, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45185','mirador','Mirador del Complejo Lagunar de Villacañas','7.6/10 Excepcional e interesantísima perspectiva ornitológica de las lagunas salinas (Larga y Tirez), idónea para avistamiento de flamencos, avutardas y estepa. Cómo llegar: Casetas-observatorio adaptadas con paneles explicativos en la periferia protegida de las cubetas lagunares. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45187','mirador','Mirador de las Lagunas de Villafranca','7.8/10 Hermosa vista de las lagunas Grande y Chica de la Mancha Húmeda (Reserva de la Biosfera), densos carrizales, avifauna acuática migratoria y zonas recreativas. Cómo llegar: Paseo perimetral acondicionado con plataformas de madera e hitos, accesos desde la CM-4005. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45188','mirador','Mirador del Cerro de la Sagra','6.4/10 Vista de las llanuras arcillosas e industriales de la comarca, campos ondulados de secano, la silueta industrial periurbana y canteras de yesos. Cómo llegar: Cota natural elevada al norte de la población, transitable por sendas rurales peatonales. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45189','mirador','Atrio de la Iglesia de Nuestra Señora de la Redonda','5.8/10 Sencilla panorámica rural de lomas de cultivo cerealista de secano, olivares marginales e idóneos horizontes despejados al atardecer castellano. Cómo llegar: Explanada elevada que circunda el ábside del templo parroquial, en el centro urbano. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45190','mirador','Alto del Teso del Humilladero','6.1/10 Vista diáfana de la planicie meridional de Toledo, campos de cultivo de cereal, dehesas lejanas e idóneo horizonte nocturno para astrofotografía. Cómo llegar: Promontorio suave al oeste del casco urbano, accesible por pistas agropecuarias de tierra. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45191','mirador','Mirador del Embalse de Castro y río Algodor','6.9/10 Vista de la lámina de agua rodeada de lomas arcillosas, olivares alcarreño-manchegos, campos de cereal y sotos fluviales bajos del Algodor. Cómo llegar: Zona perimetral alta con estacionamiento en los accesos de la represa, desvío rural. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45192','mirador','Mirador de los Viñedos y Ermita de San Roque','7.1/10 Mar de viñedos de la Mancha alta, campos de cereal de secano, relieves suaves y horizontes celestes diáfanos catalogados para la observación de astros. Cómo llegar: Explanada de la ermita al oeste del casco urbano, provista de accesos rodados y bancos. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45193','mirador','Alto de la Cuesta de San Sebastián','6.5/10 Panorámica rural sobre el valle del arroyo de la Vega, lomas arcillosas erosionadas, encinares dispersos y horizontes despejados. Cómo llegar: Colina exenta que alberga la ermita, transitable a pie por sendas desde el pueblo. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45194','mirador','Mirador del Puente Romano y Cañón del Cedena','7.4/10 Espectacular tajo calizo y pizarroso excavado por el río Cedena, monte bajo mediterráneo denso, el puente medieval e idónea pureza Starlight. Cómo llegar: Saliente acondicionado junto a las sendas de senderismo de la comarca de Torrijos-Montalbán. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45195','mirador','Mirador de la Ermita del Castellar y Cortados del Tajo','7.5/10 Impresionantes escarpes de yesos y arcillas sobre el río Tajo, vegas de regadío fértiles, olivares de ladera y la silueta del santuario histórico. Cómo llegar: Balcón natural acondicionado con barandillas en el borde del páramo del Castellar, acceso señalizado. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45196','mirador','Mirador de las Terrazas del Tajo','6.2/10 Perspectiva sobre la vega baja del río, campos agrícolas tradicionales de regadío, olivares marginales y la silueta de los polígonos industriales. Cómo llegar: Margen de la terraza fluvial, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45197','mirador','Alto del Teso de la Iglesia','6.3/10 Sencilla panorámica sobre los llanos cerealistas y arcillosas de la Mesa de Ocaña norte, cultivos de secano e idóneos atardeceres nítidos. Cómo llegar: Atrio elevado del templo parroquial, en el punto alto del casco urbano. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45198','mirador','Mirador de la Cuesta del Santo y Valle del Cedrón','72/10 Vista del encajonamiento del arroyo Cedrón entre laderas escarpadas calcáreas, encinares de páramo, campos de lavanda, cereal y olivares centenarios. Cómo llegar: Saliente natural del páramo occidental, transitable por caminos rurales desde el núcleo. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45201','mirador','Mirador del Parque de la Sagra alta','6.0/10 Vista de las terrazas fluviales de la cuenca del Guadarrama, cultivos de secano y la integración urbana residencial e industrial periurbana moderna. Cómo llegar: Zona alta ajardinada en la cornisa perimetral del casco urbano. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45202','mirador','Mirador de las Murallas y Mesa de Ocaña','7.8/10 Soberbia panorámica de la plataforma horizontal caliza, campos de cultivo, olivares, las torres mudéjares y el trazado de la muralla urbana medieval amurallada. Cómo llegar: Corona superior de los lienzos defensivos de la villa histórica, accesible peatonalmente. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45203','mirador','Atrio de la Iglesia de Santa María de la Magdalena','5.8/10 Sencilla panorámica de la Sagra central arcillosa, campos ondulados de secano e idóneo horizonte nocturno para la fotografía de estrellas limpia. Cómo llegar: Plaza sobreelevada frente a la portada del templo barroco, centro del municipio. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45204','mirador','Alto de la Cuesta de las Bodegas','5.9/10 Perspectiva sobre los llanos de cultivo cerealista, olivares rústicos y chimeneas de tradicionales calados excavados bajo el cerro testigo. Cómo llegar: Parte superior del montículo horadado por las bodegas, al oeste del núcleo urbano. 📍 Provincia: Toledo.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45205','mirador','Mirador de la Campiña de la Sagra y del Palacio','6.1/10 Vista periurbana sobre el Corredor de la Sagra, campos de cereal remanentes que resisten el avance logístico, olivares y horizontes diáfanos. Cómo llegar: Zona alta ajardinada con accesos urbanos peatonales en la periferia del casco urbano. ¡PROVINCIA DE TOLEDO COMPLETADA AL 100%! 🏁 ⭐ Si estás de acuerdo, pasamos de inmediato a la siguiente provincia en el orden territorial de la secuencia: Provincia de Ciudad Real (Comunidad de Castilla-La Mancha), comenzando estrictamente desde la letra A con municipios como Abenójar, Agudo, Alamillo, Albaladejo, Alcázar de San Juan, Alcoba de los Montes, Alcolea de Calatrava, Alcubillas, Aldea del Rey, Alhambra, Almadén, Almadenejos, Almagro, Almedina, Almodóvar del Campo, Arenas de San Juan, Argamasilla de Alba, Argamasilla de Calatrava, Arroba de los Montes, etc. ¿Prefieres que continuemos con el bloque masivo de la Provincia de Ciudad Real o deseas realizar alguna indicación previa?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90823','mirador','Mirador de la Cueva de los Muñecos y Valle del Tirteafuera','7.6/10 Impresionante vista de las dehesas de encinas de la comarca de Almadén, formaciones de cuarcita erosionada, monte bajo mediterráneo y horizontes nocturnos óptimos para astroturismo. Cómo llegar: Cresta caliza elevada en el paraje natural de la cueva, accesible por pistas forestales de tierra. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90323','mirador','Mirador del Cerro de San Blas','7.4/10 Amplia visual de los valles del rincón occidental manchego, pastizales rústicos, olivares de ladera, densos jarales y relieves fronterizos con Badajoz. Cómo llegar: Colina exenta que alberga los restos de la ermita, transitable a pie o en vehículo todoterreno. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90324','mirador','Mirador del Valle de Alcudia y río Alcudia','7.8/10 Soberbia panorámica de la cuenca ganadera trashumante, encinares adehesados densos, formaciones de pizarras y un cielo nocturno libre de contaminación lumínica. Cómo llegar: Borde del talud geográfico meridional, accesible por caminos vecinales desde la carretera N-502. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90325','mirador','Mirador del Castillo y de la Villa Romana','7.3/10 Vista arqueológica e histórica sobre el Campo de Montiel, olivares tradicionales, relieves ondulados arcillosos y los restos de la fortaleza del siglo XIII. Cómo llegar: Explanada de los muros fortificados en la cota más alta del núcleo de la población. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13001','mirador','Mirador de los Molinos del Cerro de San Antón','8.4/10 Espectacular e icónica panorámica manchega de 360 grados sobre el complejo lagunar, viñedos planos infinitos y los cuatro molinos de viento tradicionales restaurados. Cómo llegar: Plataforma acondicionada con aparcamiento y accesos adaptados en la cima de la colina que domina la urbe. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13021','mirador','Mirador del Estrecho del río Guadiana','8.2/10 Impresionante encajonamiento fluvial del Guadiana entre escarpes de pizarra de los Montes de Toledo, jarales densos, quejigares y pureza atmosférica. Cómo llegar: Borde del precipicio rocoso adaptado con barandillas en las rutas de senderismo locales. Si quieres, indícame si pasamos directamente al siguiente bloque masivo de municipios que comienzan con las letras B y C de la Provincia de Ciudad Real o si tienes alguna instrucción especial.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90326','mirador','Mirador del Volcán del Cerro de la Cruz','7.9/10 Singular e imponente relieve geomorfológico del Campo de Calatrava, con vistas panorámicas de la laguna cratérica (maar), maizales y dehesas volcánicas bajas. Cómo llegar: Corona superior del cono volcánico erosionado, accesible por sendero peatonal señalizado. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90327','mirador','Alto de la Cuesta del Santo','6.6/10 Perspectiva rural del Campo de Montiel central, olivares alineados, cultivos de cereal en secano y horizontes limpios ideales para la astrofotografía. Cómo llegar: Promontorio suave al oeste del caserío, transitable a pie desde el casco urbano. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90328','mirador','Mirador del Sacro Convento Castillo de Calatrava la Nueva','91/10 Impresionante, espectacular y colgada atalaya militar-religiosa del siglo XIII sobre un escarpe cuarcítico, dominando Sierra Morena y el Campo de Calatrava. Cómo llegar: Adarves transitables y ventanas fortificadas del conjunto monumental, acceso empinado por calzada empedrada desde la CR-504. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90329','mirador','Mirador del Castillo de Alhambra y Campo de Montiel','81/10 Soberbia visual de 360 grados sobre la altiplanicie roja de Montiel, la traza urbana de la antigua Laminium romana, olivares e infinitos cielos Starlight. Cómo llegar: Explanada de la fortaleza gótico-medieval situada en el cerro testigo que corona la villa. Si quieres, puedes indicarme si continuamos con los municipios que comienzan con la letra A (restantes) y B de la Provincia de Ciudad Real o si deseas hacer un ajuste técnico en el modelo de salida.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90825','mirador','Mirador del Parque Minero y Monumento a la Minería','8.5/10 Vistas del complejo minero Patrimonio de la Humanidad, los hornos de aludeles, la dehesa almadenense y el entramado urbano adaptado a la topografía. Cómo llegar: Explanada elevada junto al castillete de San Aquilino, accesible desde el casco urbano. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90330','mirador','Mirador del recinto amurallado del siglo XVIII','7.1/10 Perspectiva sobre los llanos de la comarca, antiguos pozos mineros, dehesas y las singulares murallas defensivas de mampostería restauradas. Cómo llegar: Tramo superior de la Puerta de Alcuclillas, en los accesos de la localidad. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13002','mirador','Mirador del Corral de Comedias y Silo de Almagro','8.2/10 Vista aérea del Campo de Calatrava, el entramado palaciego, las cubiertas cerámicas barrocas y la llanura agrícola desde un depósito industrial. Cómo llegar: Antigua estructura de silo de grano acondicionada como mirador urbano elevado en el centro. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90331','mirador','Mirador del Teso de la Atalaya','7.3/10 Amplia panorámica de la llanura arcillosa del Campo de Montiel, olivares alineados, cultivos de secano y un cielo idóneo para astrofotografía. Cómo llegar: Colina exenta al norte del núcleo, accesible por sendas agropecuarias de herradura. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90332','mirador','Mirador de la Hoz de Valdeazogues y Valle de Alcudia','8.9/10 Espectacular e inmenso tajo fluvial cuarcítico, dehesas de encina centenarias del paraje de Alcudia, monte bajo mediterráneo y cielos certificados Starlight. Cómo llegar: Cornisa rocosa acondicionada con valla de madera en la carretera de la estación de Veredas. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90335','mirador','Mirador de la Vega del río Cigüela','6.6/10 Vista del cauce llano del río Cigüela, humedales estacionales de la llanura manchega, carrizales densos e interesantes puestas de sol limpias. Cómo llegar: Margen de la terraza fluvial aluvial, accesible por pistas rurales desde el pueblo. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13003','mirador','Mirador del Castillo de Peñarroya','7.8/10 Hermosa e histórica visual de la represa, la lámina azul del embalse de Peñarroya, llanos cerealistas y la fortaleza de la Orden de San Juan. Cómo llegar: Adarves y explanada exterior de la fortaleza militar, accesos señalizados por la carretera del embalse. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90336','mirador','Alto del Cerro de la Santos','7.2/10 Vista panorámica del Valle de la dehesa del Campo de Calatrava, maizales, olivares, restos volcánicos dispersos y nítidos horizontes de baja luminosidad. Cómo llegar: Promontorio suave al sur de la localidad, transitable a pie desde la ermita. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13022','mirador','Alto del Volcán de la Columba','7.1/10 Singular perspectiva de la llanura volcánica del Campo de Calatrava, campos de cultivo tradicionales sobre piroclastos y horizontes limpios ideales para astrofotografía. Cómo llegar: Cota superior del antiguo cono volcánico erosionado, accesible por pistas rurales desde el pueblo. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13023','mirador','Adarve del Castillo de Doña Berenguela','7.5/10 Vista histórica de la llanura agrícola manchega, olivares periféricos, viñedos y las sólidas torres del recinto fortificado medieval perfectamente conservado. Cómo llegar: Galería superior y torre del homenaje de la fortaleza, accesible con la entrada turística al monumento. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13024','mirador','Mirador del Puerto de Mestanza y Valle de Alcudia','8.4/10 Extraordinaria vista aérea del gran valle trashumante, densas dehesas de encinas, el embalse de Carboneras y las crestas cuarcíticas de Sierra Morena. Cómo llegar: Apartadero acondicionado con paneles informativos en la carretera de montaña CR-5011. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13025','mirador','Alto del Cerro de San Isidro','7.2/10 Panorámica rural del Valle del Tirteafuera, campos de secano ondulados, monte bajo mediterráneo de jara y encinas con cielos nocturnos de gran pureza. Cómo llegar: Promontorio elevado al norte del núcleo, transitable a pie desde la ermita de San Isidro. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13026','mirador','Mirador del Puerto de San Isidro','8.0/10 Impresionante corte geográfico sobre el flanco sur del Valle de Alcudia, escarpes rocosos donde anidan buitres y extensas manchas forestales mediterráneas. Cómo llegar: Balcón natural adaptado junto a la carretera CR-5021 en el paso de montaña. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13027','mirador','Mirador del Castillo de Salvatierra','8.8/10 Soberbia y evocadora panorámica de Sierra Morena, el Sacro Convento frente a frente, dehesas y restos de la fortaleza defensiva rocosa musulmana. Cómo llegar: Cresta cuarcítica del cerro de Salvatierra, accesible mediante sendero de montaña peatonal. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13028','mirador','Mirador de la Sierra de los Molinos','9.0/10 Icónica, universal y espectacular panorámica de 360 grados sobre la llanura infinita de la Mancha, viñedos planos y los legendarios molinos de viento quijotescos del siglo XVI. Cómo llegar: Explanada de la Sierra de los Molinos, adaptada con accesos peatonales, iluminación nocturna y zonas de aparcamiento. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13029','mirador','Alto del Teso del Humilladero','6.7/10 Sencilla panorámica sobre los llanos cerealistas del Campo de Calatrava central, cultivos de regadío y puestas de sol limpias de obstáculos visuales. Cómo llegar: Pequeña colina exenta en las inmediaciones del cementerio municipal, acceso rural. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13030','mirador','Mirador del Castillo de Caracuel','7.8/10 Magnífica perspectiva histórica sobre la cuenca del río Guadiana y el Valle de Calatrava, olivares de ladera y las ruinas fortificadas musulmanas de mampostería. Cómo llegar: Explanada natural de la fortaleza situada sobre el escarpado cerro rocoso, acceso peatonal empinado. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13031','mirador','Mirador de Calatrava la Vieja','8.3/10 Impresionante vista arqueológica y de naturaleza sobre el río Guadiana, sotos de ribera y la inmensa alcazaba islámica del siglo VIII, cuna de la Orden. Cómo llegar: Plataforma elevada con paneles interpretativos dentro del Parque Arqueológico, accesos señalizados desde la CM-4114. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13032','mirador','Mirador de la Ermita de la Virgen de la Salceda','7.4/10 Vista del valle encajonado del río Azuer, relieves arcillosos y calcáreos del Campo de Montiel, olivares de montaña y horizontes despejados castellanos. Cómo llegar: Cerro testigo elevado donde se asienta el santuario, transitable por camino asfaltado con aparcamiento. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13033','mirador','Mirador del Cerro de los Castillejos y la Paramera','7.6/10 Vista de la transición hacia las estribaciones de Sierra Morena, olivares infinitos de la Mancha meridional, matorral de jara e idóneo entorno para astrofotografía. Cómo llegar: Cota natural elevada al sur del término municipal, accesible por pistas forestales. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13038','mirador','Mirador de la Virgen del Castillo y Sierra de la Virgen','8.2/10 Espectacular e infinita visual a más de 700 metros de altitud de los valles del Guadalmez y Alcudia, dehesas encasilladas de encina y cortados cuarcíticos. Cómo llegar: Explanada del santuario fortificado en las cumbres montañosas, accesible por pista rodada desde la carretera de Chillón. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13004','mirador','Mirador de Alarcos y Ermita de la Virgen','7.7/10 Magnífica panorámica del gran meandro del río Guadiana, la llanura manchega, yacimientos arqueológicos ibero-medievales y el escenario de la célebre batalla de 1195. Cómo llegar: Cornisa acondicionada con barandilla y paneles en el cerro del Parque Arqueológico de Alarcos, accesos pavimentados. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13037','mirador','Mirador de las Eras del Santo','6.8/10 Vista diáfana de lomas onduladas de cultivo de secano, dehesas ganaderas bajas e idóneos atardeceres manchegos libres de obstáculos industriales. Cómo llegar: Promontorio suave al oeste de la localidad, accesible a pie desde el casco urbano. Si quieres, indícame si pasamos directamente al siguiente bloque masivo que engloba la letra D en adelante de la Provincia de Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13005','mirador','Pasarelas del Parque Nacional de las Tablas de Daimiel','8.9/10 Excepcional llanura inundable fluvial (tablas fluviales) del Guadiana y Cigüela, masas de taray, densos carrizales y abundante avifauna acuática migratoria protegida. Cómo llegar: Observatorios adaptados integrados en la red de itinerarios peatonales de madera del Parque Nacional. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13040','mirador','Mirador del Embalse de Gasset','7.2/10 Vista de la lámina de agua rodeada de relieves ondulados del Campo de Calatrava, dehesas dispersas, pinares de repoblación e idóneas puestas de sol. Cómo llegar: Margen este de la represa junto a la zona recreativa, accesible por la carretera N-401. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13041','mirador','Mirador de los Riscos de Fontanarejo','7.8/10 Magnífica vista de las alineaciones de cuarcita de los Montes de Toledo, dehesas de encina, densos jarales y un cielo nocturno puro Starlight. Cómo llegar: Cresta rocosa elevada al norte del pueblo, accesible por pistas forestales rurales. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13042','mirador','Mirador del Puerto de Valderrepisa y Pinturas de Peña Escrita','8.7/10 Impresionante panorama alpino de Sierra Morena, densos bosques de pino negral, robledales, madroñeras y abrigos protegidos de arte rupestre esquemático. Cómo llegar: Balcón natural acondicionado con paneles informativos en la carretera N-420, paso de montaña. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13043','mirador','Mirador de la Cuesta del Castillo','7.1/10 Perspectiva sobre la campiña arcillosa del Campo de Montiel, olivares alineados, cultivos tradicionales de secano y restos de defensas medievales. Cómo llegar: Explanada de la antigua fortaleza que domina el casco urbano, acceso peatonal directo. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13044','mirador','Mirador del Molino de Viento y Sierra de la Calderina','7.6/10 Vista que combina la arquitectura tradicional de un molino harinero con las vertientes forestales montañosas, encinares e infinitos horizontes. Cómo llegar: Cima del cerro exento que flanquea el norte de la localidad, provisto de accesos rodados. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13045','mirador','Mirador del Volcán y Laguna de Cerrogordo','8.4/10 Espectacular morfología del primer volcán musealizado del Campo de Calatrava, vistas del cráter, piroclastos, maizales y el yacimiento de Oreto. Cómo llegar: Pasarelas y pasadizos adaptados con paneles didácticos en el interior del cono erosionado, acceso por la CR-5111. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13046','mirador','Mirador de la Vega del Guadalmez','7.5/10 Vista fluvial del cauce ancho del río Guadalmez en los límites con Andalucía, extensas dehesas ganaderas de encina y monte bajo mediterráneo. Cómo llegar: Talud natural acondicionado al sur de la población, transitable por sendas rurales de tierra. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13047','mirador','Mirador de los Molinos de la Sierra de la San Cristóbal','7.9/10 Espectacular e infinita panorámica de la llanura manchega, extensos campos de viñedos y el singular conjunto de molinos de viento tradicionales. Cómo llegar: Explanada acondicionada con barandilla y aparcamiento en la cresta caliza que domina el norte de la villa. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13048','mirador','Mirador del Estrecho de Solanillas','8.1/10 Hermoso y profundo corte geológico cuarcítico del río Montoro en Sierra Morena, cubierto por denso bosque mediterráneo e idónea pureza nocturna. Cómo llegar: Saliente natural del relieve acondicionado con valla de madera, acceso por sendero desde la pedanía. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13049','mirador','Mirador de la Sierra de la Hornaguera y Cabañeros','8.6/10 Impresionante vista del Parque Nacional, profundos valles fluviales encajonados, densos bosques de encina, alcornoque, quejigo y abundante fauna mayor. Cómo llegar: Plataforma elevada con paneles didácticos en la subida natural hacia el puerto montañoso, carretera CM-4103. Si quieres, puedes indicarme si pasamos de inmediato al siguiente bloque de la Provincia de Ciudad Real que inicia con la letra L o si deseas realizar alguna modificación en los parámetros.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13904','mirador','Silo de Llanos y Llanura Manchega','5.8/10 Vista rectilínea sobre el plano cuadriculado de parcelas de regadío, cultivos hortícolas intensivos de melón, vid y horizontes diáfanos sin obstáculos. Cómo llegar: Cota superior de la antigua estructura industrial de almacenamiento de grano en el núcleo urbano. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13051','mirador','Mirador de la Confluencia del Guadiana y Bullaque','8.2/10 Espectacular e imponente panorámica de la unión fluvial, frondosos sotos de ribera, tablas de agua estacionales, fresnedas y cerros pizarrosos. Cómo llegar: Talud natural acondicionado con vallado de protección al este de la población, desvío desde la N-430. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13008','mirador','Mirador del río Jalón y del Ebro','6.7/10 Vista de la confluencia de los valles fluviales de los ríos Ebro y Jalón, fértiles vegas hortícolas, choperas lineales y el perfil monumental mudéjar. Cómo llegar: Margen de la terraza fluvial aluvial, accesible por pistas rurales desde el núcleo de la villa. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13010','mirador','Mirador de la Ermita de la Virgen del Espino','6.7/10 Vista despejada de la vega aluvial del Azuer, cultivos de regadío, melonares tradicionales y limpios horizontes para astrofotografía de baja luminosidad. Cómo llegar: Explanada elevada del recinto del santuario, accesible de forma peatonal en el casco urbano. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13055','mirador','Mirador del Puerto de Mestanza','8.4/10 Impresionante vista del Valle de Alcudia, el Embalse de Montoro encajonado, crestas de cuarcitas erosionadas, encinares maduros y avifauna protegida rupícola. Cómo llegar: Punto alto adaptado en la carretera CR-5011, con apartadero y paneles informativos. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13011','mirador','Mirador del Cerro de San Isidro','6.9/10 Vista periurbana de la comarca de Calatrava, campos de cultivo, olivares, restos volcánicos mitigados y la silueta de la capital provincial cercana. Cómo llegar: Cornisa acondicionada con bancos y barandilla en el parque del cerro periurbano al sur. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13057','mirador','Mirador del Castillo de la Estrella','8.3/10 Soberbia y colgada atalaya militar medieval sobre el Campo de Montiel, olivares escarpados de ladera, tierras arcillosas y el escenario del fratricidio real. Cómo llegar: Cima del cerro testigo amurallado, accesible por rampa peatonal desde el casco histórico de la villa. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13012','mirador','Mirador de la Sierra de Moral','7.6/10 Excelente visual de los valles del Campo de Calatrava meridional, olivares de montaña en bancales, maizales de secano e idóneo cielo nocturno. Cómo llegar: Cresta natural calcárea accesible por pistas forestales transitables desde el municipio. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13059','mirador','Mirador del río Guadiana y Sierra del Guadaperpero','81/10 Hermosa panorámica del encajonamiento fluvial, jarales espesos, brezales de media montaña y pinares forestales adyacentes al Parque Nacional. Cómo llegar: Saliente natural del páramo pizarroso al norte del término, transitable por pistas rurales. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13060','mirador','Mirador del Boquerón de Estena','8.6/10 Espectacular e imponente corte geológico del río Estena en Cabañeros, con fósiles marinos del Ordovícico, frondosos bosques de ribera, tejos y encinares. Cómo llegar: Sendero ecológico señalizado y adaptado de la red del Parque Nacional, acceso desde la localidad. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13061','mirador','Mirador de la Laguna de la Vega o del Pueblo','7.4/10 Perspectiva ornitológica de la cubeta lagunar manchega salina, con carrizales densos, avistamiento de flamencos, malvasías cabeciblancas y estepa cerealista periférica. Cómo llegar: Caseta-observatorio adaptada con cartelería explicativa en la margen protegida del humedal. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13062','mirador','Alto del Volcán de la Cornudilla','7.2/10 Vista de la llanura volcánica del Campo de Calatrava noroccidental, cultivos de secano, dehesas dispersas de encina y un cielo nocturno puro. Cómo llegar: Corona del cono volcánico erosionado, accesible por caminos rurales de herradura. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13063','mirador','Mirador del Castillo de Miraflores','8.3/10 Magnífica perspectiva sobre el valle del Bullaque, escarpes de cuarcitas, encinares maduros densos y el entorno kárstico de la tabla de la Yedra. Cómo llegar: Explanada de las ruinas fortificadas islámico-medievales situadas sobre un risco calizo, acceso pedestre. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13064','mirador','Mirador del Volcán de Cabezo Rey','7.3/10 Vista panorámica de la cuenca del río Guadiana, maizales, olivares y la fisonomía del maar volcánico adaptado para cultivos de regadío. Cómo llegar: Cota superior del cerro volcánico al norte de la población, accesible por pistas rurales. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13065','mirador','Mirador del Cerro de Santo Domingo y Volcán del El Palo','7.9/10 Interesante contraste entre el relieve volcánico del Campo de Calatrava, las dehesas montañosas, huertas tradicionales y la vega baja del río Bullaque. Cómo llegar: Promontorio acondicionado junto a la ermita de Santo Domingo, acceso señalizado por pista de tierra. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13066','mirador','Mirador de la Laguna de la Inesperada','7.4/10 Vista geomorfológica y ornitológica de una laguna cratérica salina (maar), idónea para observar avifauna acuática migratoria y formaciones de piroclastos. Cómo llegar: Centro de interpretación de la naturaleza perimetral adaptado con pasarelas, acceso directo. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13067','mirador','Mirador del río Guadiana y los Cortados','7.7/10 Vista de las vertientes pizarrosas y cortados rocosos que encajonan el cauce fluvial del Guadiana, jarales, encinares y nítidos cielos nocturnos. Cómo llegar: Borde del talud calizo occidental, accesible por pistas ganaderas desde el núcleo. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13068','mirador','Mirador del Estrecho de las Hoces y Guadiana','8.4/10 Extraordinario y caótico colapso geológico de pizarras que encajonan el curso alto del Guadiana, monte bajo mediterráneo denso e idónea pureza Starlight. Cómo llegar: Balcón natural acondicionado con barandillas y paneles de la red de senderos, carretera N-430. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13069','mirador','Mirador de la Torre del Homenaje','7.3/10 Perspectiva sobre los llanos arcillosos del Campo de Montiel meridional, olivares centenarios de montaña, campos de cereal y relieves de Sierra Morena. Cómo llegar: Remate superior transitable del bastión militar del siglo XIV en el centro urbano. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13070','mirador','Mirador de las Ventas y Sierras del Viento','7.5/10 Clásica perspectiva de las ventas quijotescas, olivares tradicionales alineados en la ladera y las crestas de la Sierra con molinos tradicionales. Cómo llegar: Saliente natural acondicionado con valla de madera al norte del casco urbano, acceso rural. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13013','mirador','Mirador del Cerro de Santa Ana y Monumento al Minero','7.7/10 Vista panorámica del Valle de Alcudia septentrional, el perfil de la ciudad industrial, la dehesa boyal y las crestas de cuarcitas. Cómo llegar: Atalaya urbana adaptada con barandillas y aparcamiento en la cumbre del cerro monumental. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13072','mirador','Mirador de la Presa de Torre de Abraham y Cabañeros','8.6/10 Espectacular visual alpina de la masa de agua regulada del río Bullaque, dehesas ganaderas tradicionales de encina y alcornoque del Parque Nacional. Cómo llegar: Zona perimetral alta con estacionamiento y paneles informativos en los accesos de la represa. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13014','mirador','Mirador de las Lagunas de Ruidera (Laguna Del Rey)','9.2/10 Excepcional e imponente panorámica de las barreras de travertino y toba que forman las lagunas, aguas turquesas, frondosos sotos y avifauna. Cómo llegar: Plataforma colgada adaptada con barandilla y paneles didácticos de la red del Parque Natural. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13073','mirador','Alto de las Eras de San Isidro','7.6/10 Vista limpia de las llanuras ganaderas de la comarca de Almadén, dehesas de encina, cultivos de secano y un cielo nocturno libre de contaminación. Cómo llegar: Promontorio suave al oeste de la población, transitable por pistas agropecuarias de tierra. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13074','mirador','Mirador de la Plaza Mayor y del Cristo','7.8/10 Vista arquitectónica e histórica desde la cota alta perimetral del pueblo sobre el monumental conjunto barroco y la llanura del Campo de Montiel. Cómo llegar: Zona perimetral elevada accesible por las calles residenciales altas del núcleo. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13075','mirador','Mirador del cañón del río Fresneda y Sierra Morena','8.3/10 Impresionante grieta caliza de paredes verticales, densos pinares de pino negral, encinares serranos de la vertiente de Sierra Morena y nula luz industrial. Cómo llegar: Borde del precipicio natural acondicionado con valla de madera, acceso por sendas de montaña. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13076','mirador','Alto del Cerro Gordo','7.1/10 Panorámica de los llanos arcillosos del Campo de Montiel meridional, olivares tradicionales alineados, cultivos cerealistas planos y horizontes limpios. Cómo llegar: Cota natural elevada al norte de la población, transitable por sendas ganaderas de herradura. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13015','mirador','Mirador del Santuario de las Virtudes y Plaza de Toros Cuadrada','7.9/10 Vista que combina el patrimonio mudéjar e histórico del complejo del siglo XVII con las dehesas y cultivos olivareros de transición. Cómo llegar: Explanada exterior sobreelevada frente a las estructuras monumentales del complejo rústico. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13016','mirador','Mirador de la Torre del Vino y Llanura de Viñedos','7.6/10 Mar de viñedos plano infinito de la Mancha, bodegas industriales tradicionales de producción vitivinícola e idóneo punto para la astrofotografía. Cómo llegar: Plataforma superior elevada del mirador del Museo Torre del Vino, acceso urbano gestionado. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13007','mirador','Mirador del Teso del Humilladero','7.3/10 Amplia visual sobre los llanos cerealistas del Campo de Montiel noroccidental, campos de azafrán, viñedos planos y horizontes limpios. Cómo llegar: Promontorio suave al sur de la localidad, junto al antiguo trazado de caminos vecinales. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13081','mirador','Mirador del Yacimiento del Castillejo del Bonete','7.7/10 Vista arqueológica de un túmulo monumental de la Edad del Bronce, alineaciones de piedra caliza, olivares serranos e idónea pureza nocturna Starlight. Cómo llegar: Plataforma con paneles explicativos en las cercanías de los restos arqueológicos protegidos, acceso rural. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13017','mirador','Mirador de los Bombas y de las Cuevas de las Bodegas','7.5/10 Vista urbana rústica de las tradicionales chimeneas de destilación (bombas), campos planos manchegos de vides y las lumbreras de calados subterráneos. Cómo llegar: Estructura del silo o terraza urbana acondicionada en las periferias industriales de la villa. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13083','mirador','Alto del Teso de las Eras','6.6/10 Sencilla panorámica sobre los llanos cerealistas del Campo de Calatrava oriental, cultivos de regadío y puestas de sol limpias de obstáculos. Cómo llegar: Pequeña colina exenta en el sector norte de la localidad, de fácil acceso peatonal. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13084','mirador','Mirador de las Torres del Castillo de San Juan','7.7/10 Espectacular e histórica visual desde los adarves fortificados sobre la dehesa del Campo de Montiel, olivares alineados e hilos de quejigos lejanos. Cómo llegar: Explanada de la fortaleza medieval de las Torres de Xoray, accesible por camino rural de montaña. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13085','mirador','Alto del Calvario y Campo de Montiel','7.1/10 Perspectiva sobre la campiña arcillosa, campos de secano de la comarca, olivares tradicionales e idóneos horizontes despejados para la fotografía estelar nocturna. Cómo llegar: Promontorio suave al sur de la población, transitable a pie por sendas de piedra. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13086','mirador','Mirador del río Esteras','7.6/10 Vista fluvial del cauce del río Esteras, arbolado de ribera, lomas pizarrosas cubiertas de matorral bajo mediterráneo de jara y encinas. Cómo llegar: Talud natural acondicionado con valla de madera, accesible por pistas rurales desde el pueblo. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13018','mirador','Mirador del Cerro de las Cabezas','8.1/10 Magnífica perspectiva que combina la vista del yacimiento arqueológico de la ciudad ibérica del siglo IV a.C. con el mar de viñedos. Cómo llegar: Plataforma elevada con paneles interpretativos y barandilla junto a la autovía A-4, acceso señalizado al parque. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13088','mirador','Alto del Cerro Gordo','6.9/10 Sencilla panorámica de las lomas volcánicas del Campo de Calatrava, campos ondulados de secano e idóneo horizonte nocturno Starlight. Cómo llegar: Cota natural elevada al norte de la población, transitable por pistas agropecuarias de tierra. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13089','mirador','Mirador de las Lagunas Altas de Ruidera (Laguna Blanca)','8.2/10 Vista de la primera cubeta lagunar calcárea del complejo endorreico, praderas ganaderas tradicionales, sabinares dispersos e idónea pureza nocturna. Cómo llegar: Saliente acondicionado de la plataforma del páramo oriental, transitable por caminos vecinales. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13090','mirador','Mirador del Castillo de Eznavejor y Sierra Morena','8.4/10 Impresionante cañón cuarcítico del río Dañador, dehesas densas de encina en la vertiente del Campo de Montiel meridional e hitos históricos de Jorge Manrique. Cómo llegar: Cresta rocosa que alberga las ruinas fortificadas islámicas sobre el desfiladero, acceso pedestre por sendas de montaña. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13091','mirador','Mirador del Volcán del El Morro y laguna','7.8/10 Vista del cono volcánico erosionado, campos de cultivo, maizales, olivares rústicos de montaña y humedales estacionales de alto interés ecológico. Cómo llegar: Promontorio natural elevado accesible por la pista forestal que sube desde el núcleo. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13092','mirador','Mirador del Nacimiento del río Villanueva (Mentesa)','8.0/10 Vista fluvial del brote de agua cristalina entre riscos, vegas agrícolas tradicionales del Campo de Montiel oriental y el patrimonio arqueológico íbero-romano. Cómo llegar: Entorno acondicionado de la zona recreativa del nacimiento, accesible por carretera local desde la villa. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13019','mirador','Mirador de la Plaza Mayor y de Quevedo','8.5/10 Espectacular e histórica panorámica urbana desde la cota alta periférica del pueblo sobre las torres, cúpulas barrocas de sillería y la llanura. Cómo llegar: Zona perimetral elevada urbana adaptada, accesible de forma peatonal desde los accesos históricos de la villa. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13094','mirador','Alto del Cerro de San Benito y Valle de Alcudia','7.4/10 Perspectiva sobre la cuenca ganadera trashumante, lomas cubiertas de monte mediterráneo, dehesas dispersas y horizontes limpios de la comarca. Cómo llegar: Colina exenta que alberga los restos de la pedanía alta, transitable a pie por sendas de herradura. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13095','mirador','Mirador de la llanura del Aeropuerto de Ciudad Real','6.6/10 Vista singular que combina el plano de las infraestructuras de transporte aéreo internacionales con los llanos cerealistas del Campo de Calatrava central. Cómo llegar: Zona elevada de servicio exterior perimetral a las instalaciones, accesible por la CM-412. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13096','mirador','Mirador de la Virgen de la Sierra y de las Tablas','8.4/10 Magnífica y amplísima perspectiva desde la cresta de los Montes de Toledo sobre la llanura de las Tablas de Daimiel, olivares y viñedos manchegos. Cómo llegar: Explanada del santuario de la Virgen de la Sierra, cerro elevado provisto de balcones con barandillas. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13097','mirador','Mirador del Puente Romano sobre el río Cigüela','6.9/10 Vista fluvial del monumental y largo puente de origen romano de cuarenta y seis ojos, carrizales de ribera y horizontes limpios manchegos. Cómo llegar: Paseo e hito peatonal acondicionado en la margen derecha del cauce del río, casco urbano bajo. 📍 Provincia: Ciudad Real.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13020','mirador','Mirador del Palacio de Don Álvaro de Bazán','83/10 Vista monumental renacentista del palacio-archivo de la Marina desde las cota urbanas elevadas, dehesas densas de Sierra Morena septentrional y olivares. Cómo llegar: Zona perimetral elevada acondicionada en las calles altas residenciales del municipio, acceso urbano directo. ¡PROVINCIA DE CIUDAD REAL COMPLETADA AL 100%! 🏁 ⭐ Si te parece bien, podemos saltar de inmediato a la siguiente provincia planificada en el orden territorial de la secuencia: Provincia de Albacete (Comunidad de Castilla-La Mancha). ¿Iniciamos el nuevo bloque masivo por la letra A?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90820','mirador','Alto del Cerro de los Valles','6.6/10 Vista diáfana de la llanura de la Manchuela albacetense, lomas salpicadas de olivar, cultivos de secano e idóneo horizonte nocturno para astrofotografía. Cómo llegar: Promontorio suave al norte del núcleo, accesible por pistas rurales desde las eras. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90337','mirador','Mirador del Cerro de la Ermita','7.1/10 Perspectiva sobre la cuenca del arroyo de Alatoz, cárcavas arcillosas, olivares y la llanura de transición hacia el Corredor de Almansa. Cómo llegar: Explanada de la ermita en la cota urbana más alta, provista de barandillas de seguridad. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02001','mirador','Terraza de la Torre de la Fiesta del Árbol','7.4/10 Excepcional vista de pájaro de 360 grados sobre la capital, el llano manchego infinito, parques periurbanos y los nítidos horizontes de la meseta. Cómo llegar: Cuerpo superior del histórico depósito de aguas elevado, integrado en el Parque de la Fiesta del Árbol. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90338','mirador','Mirador del Acueducto Romano','6.8/10 Vista arqueológica y agrícola sobre el Valle de Ontur, campos de frutales, viñedos planos y el monumental acueducto de piedra labrada. Cómo llegar: Espacio público acondicionado junto al hito arqueológico, al sur del término urbano. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90339','mirador','Mirador del Valle del Cabriel','7.2/10 Impresionante vista sobre los escarpes de roca caliza y pinos que caen hacia el río Cabriel, viñedos tradicionales y abundante vegetación mediterránea. Cómo llegar: Cornisa natural situada al este del término, transitable por sendas rurales de tierra. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02002','mirador','Mirador de los Molares y Sierra del Segura','7.6/10 Soberbia visual de la transición hacia la serranía, encinares maduros dispersos, dehesas altas y cielos catalogados Starlight por su nula contaminación lumínica. Cómo llegar: Plataforma calcárea al sur del núcleo, accesible por pistas forestales de montaña. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02003','mirador','Mirador de las Eras y de la Hoz del Júcar','9.4/10 Espectacular, imponente e icónica panorámica del profundo cañón calizo del río Júcar, las casas cueva colgadas, el puente romano y el castillo fortificado. Cómo llegar: Balcón volado adaptado con barandillas y paneles en las Eras de Alcalá, margen opuesto al castillo. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02004','mirador','Mirador del Castillo y de las Torres de la Plaza','8.8/10 Soberbia atalaya medieval sobre la Sierra de Alcaraz, valles profundos de olivares, la silueta renacentista de las torres del Tardón y la Trinidad. Cómo llegar: Explanada rocosa del castillo en el cerro testigo que corona el conjunto monumental. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02005','mirador','Adarve del Castillo de Almansa','8.9/10 Impresionante vista de 360 grados sobre el corredor fronterizo, el casco histórico, viñedos locales de altura y el imponente peñón calizo exento. Cómo llegar: Corona superior y torre del homenaje de la fortaleza visitable del siglo XV, centro urbano. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90821','mirador','Mirador de las Pinturas Rupestres de la Cueva de la Vieja','7.8/10 Vista arqueológica sobre los cañones de arenisca del sector, pinares densos, monte bajo y el abrigo prehistórico protegido por la UNESCO. Cómo llegar: Estructura de pasarela adaptada junto al centro de interpretación, acceso señalizado desde la CM-3201. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02006','mirador','Mirador del Diablo y de los Infiernos','9.2/10 Vértigo y majestuosidad sobre el impresionante cañón del río Mundo, bancales de piedra escalonados, escarpes calizos verticales y el pueblo colgado de la roca. Cómo llegar: Voladizo metálico con reja y paneles turísticos suspendido sobre la carretera CM-3203. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02007','mirador','Mirador del Cerro de los Castillejos','7.0/10 Perspectiva de la vega del río Balazote, cultivos de regadío fértiles y el hito arqueológico donde se halló la célebre Bicha de Balazote. Cómo llegar: Promontorio suave al oeste del caserío, accesible por sendas peatonales y pistas. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90340','mirador','Mirador del río Cabriel y del Santuario','7.7/10 Vista del cauce encajonado fronterizo del Cabriel, hoces profundas calizas, pinares densos y cielos de extrema nitidez astronómica nocturna. Cómo llegar: Saliente acondicionado con valla de madera próximo a la ermita de San Lorenzo. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90341','mirador','Mirador del Cerro de los Tres de la Mancha','6.4/10 Vista llana del paisaje cerealista manchego, campos de girasoles planos, aerogeneradores en el horizonte e idóneo punto para astrofotografía. Cómo llegar: Elevación natural del terreno coronada por un molino tradicional, accesible desde el casco urbano. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90343','mirador','Mirador de la Hoz de Bogarra y de las Esculturas','8.7/10 Impresionante tajo fluvial encajonado del río Madera, densos pinares, huertas tradicionales árabes y el sendero con figuras talladas en roca viva. Cómo llegar: Estructura adaptada con paneles didácticos de la red de senderos, accesos peatonales locales. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90344','mirador','Mirador del Poblado Íbero del Amarejo','7.1/10 Vista histórica sobre la altiplanicie, campos de cultivo de secano, viñedos de la D.O. Almansa y horizontes diáfanos limpios de contaminación. Cómo llegar: Cerro testigo exento coronado por restos arqueológicos en las cercanías de la A-31. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90345','mirador','Mirador de las Eras de la Muela','81/10 Espectacular e imponente barranco que rodea el valle encajonado, laderas cubiertas de pino silvestre, rocas calizas y la silueta del castillo del siglo XV. Cómo llegar: Cornisa natural alta adaptada con vallado en la pista de montaña que sube a la altiplanicie. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90346','mirador','Mirador de los Cortados del Júcar','6.9/10 Vista de las terrazas arcillosas y escarpes calcáreos que delimitan la vega del Júcar, campos cerealistas e interesantes puestas de sol castellanas. Cómo llegar: Borde norte de la plataforma caliza, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90347','mirador','Mirador del Alto de la Muela y río Montemayor','7.8/10 Vista panorámica del valle encajonado, matorrales densos de jara, encinares maduros de montaña y cielos estrellados nocturnos puros. Cómo llegar: Plataforma caliza accesible por pistas forestales, desvío de la carretera de San Pedro. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90348','mirador','Mirador de la Ermita de la Encarnación y el Cabriel','7.5/10 Hermosa panorámica de las vertientes boscosas que bajan hacia las hoces fluviales, encinares, quejigares y olivares tradicionales de ladera. Cómo llegar: Explanada de la ermita en el borde del páramo oriental, con caminos transitables. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02008','mirador','Mirador de la Serrana y de la Manchuela','7.3/10 Amplia perspectiva de la llanura agrícola, cultivos de vid de la D.O. Manchuela, campos de cereal y el perfil montañoso lejano del Cabriel. Cómo llegar: Promontorio suave al este del casco urbano, provisto de accesos rodados y bancos. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02009','mirador','Mirador de la Sierra de Santa Bárbara','7.8/10 Espectacular atalaya sobre los llanos del Corredor del Almansa meridional, olivares alineados, el castillo y relieves fronterizos de Alicante y Murcia. Cómo llegar: Explanada de la ermita en las cumbres montañosas, accesible por pista rodada asfaltada. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90349','mirador','Alto del Cerro de las Cruces','6.7/10 Sencilla panorámica sobre lomas de cultivo de secano, olivares tradicionales alcarreños e idóneos horizontes despejados para la astrofotografía. Cómo llegar: Colina exenta al norte de la población, transitable a pie desde el casco urbano. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02010','mirador','Mirador del Castillo de Chinchilla','8.9/10 Excepcional e infinita atalaya medieval de 360 grados sobre el llano albacetense, la Mancha oriental, cuevas rupestres y el imponente foso excavado en roca. Cómo llegar: Adarves y corona superior de la fortaleza militar histórica, accesible por carretera asfaltada con aparcamiento. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90350','mirador','Mirador del Complejo Lagunar de Corral-Rubio','7.2/10 Interesantísima perspectiva ornitológica de las lagunas salinas endorreicas, idónea para el avistamiento estacional de flamencos, carrizales y estepa cerealista. Cómo llegar: Puesto de observación adaptado con cartelería didáctica en la periferia de las cubetas lagunares. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90351','mirador','Mirador de las Torres de Cotillas','8.5/10 Espectacular visual alpina de la Sierra de Cazorla y Segura nororiental, profundos valles con densos bosques de pino albar, encinas e hilos calizos de relieve abrupto. Cómo llegar: Plataforma con vallado en las ruinas de la fortaleza medieval sobre el peñón calizo, acceso peatonal. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02011','mirador','Mirador de Amílcar Barca y río Segura','8.6/10 Magnífico meandro encajonado del río Segura, olivares de montaña en bancales, huertas tradicionales de ribera, cortados cuarcíticos y serranía densa. Cómo llegar: Atalaya adaptada con barandilla y paneles en lo alto del escarpe, salida hacia Riópar. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02013','mirador','Mirador del río Segura y del Pantano','8.2/10 Vista de la lámina de agua encajada del embalse del Cenajo, laderas escarpadas calcáreas cubiertas de denso pino negral y monte bajo mediterráneo. Cómo llegar: Borde del talud calizo, accesible por pistas forestales desde la carretera de Socovos. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02032','mirador','Mirador del Teso del Humilladero','6.9/10 Vista de la planicie de la Manchuela albaceteña, cultivos de vid y cereal, hilos de chopos fluviales y horizontes nocturnos aptos para astrofotografía. Cómo llegar: Promontorio suave al oeste del caserío, transitable por caminos rurales desde el pueblo. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02033','mirador','Mirador de la Sierra de la Higuerica','7.6/10 Excelente visual de los llanos vitivinícolas del Campo de Hellín, dehesas y cerros de relieve suave con cielos nocturnos catalogados Starlight. Cómo llegar: Cota natural elevada al norte de la población, transitable por pistas agropecuarias de tierra. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02034','mirador','Mirador del Cerro de la Ermita y el Calvario','6.9/10 Vista panorámica de las lomas onduladas de secano, olivares alcarreños tradicionales, campos cerealistas planos e idóneos horizontes al atardecer castellano. Cómo llegar: Explanada de la ermita de San Roque, de fácil acceso peatonal desde el núcleo. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02035','mirador','Atrio de la Iglesia de San Martín','6.2/10 Sencilla panorámica de la llanura de Albacete norte, campos rectilíneos de secano y regadío e idóneo horizonte despejados para la fotografía de estrellas. Cómo llegar: Plaza elevada perimetral frente a la portada gótico-plateresca del templo parroquial. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02036','mirador','Alto del Teso de las Eras','6.5/10 Perspectiva sobre lomas arcillosas del cultivo de secano de la Manchuela central, pequeños viñedos de ladera y puestas de sol manchegas limpias. Cómo llegar: Cota natural elevada al norte de la población, transitable a pie por sendas de piedra. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02014','mirador','Mirador del Castillo y Cerro de San Rafael','84/10 Amplia perspectiva histórica urbana de las torres y cúpulas del casco antiguo, el somontano de la sierra murciano-albacetense, campos de olivo y azufaifos. Cómo llegar: Explanada de la antigua fortaleza amurallada sobre el risco calizo urbano, acceso señalizado por rampas. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02038','mirador','Alto del Teso del Humilladero','6.1/10 Sencilla visual de campos de secano de la llanura central, campos de pasto rústico e idóneos horizontes celestes nocturnos libres de obstáculos. Cómo llegar: Promontorio suave al oeste del casco urbano, accesible por pistas agropecuarias de tierra. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02039','mirador','Mirador del Parque Eólico del cerro de Santa Bárbara','7.4/10 Vista singular de uno de los mayores parques eólicos de Europa integrados en la altiplanicie, campos de vides D.O. Almansa y horizontes diáfanos. Cómo llegar: Pistas de servicio eólicas transitables en la plataforma caliza al este del término. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02040','mirador','Mirador de los Cucos y Chozos de Piedra Seca','6.8/10 Vista paisajística del llano, olivares rústicos, campos de cereal y el valioso patrimonio etnográfico de los bombos y cucos tradicionales pastoriles. Cómo llegar: Paraje rústico elevado transitable por pistas ganaderas desde el núcleo urbano. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02041','mirador','Mirador de las Murallas y de la Hoz del Júcar','91/10 Impresionante e histórica panorámica del meandro encajonado del río Júcar, la villa medieval fortificada colgada del escarpe calizo y las huertas escalonadas. Cómo llegar: Cornisa amurallada adaptada con barandilla a la entrada del casco histórico medieval. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02016','mirador','Mirador de La Artezuela y de la Villa Medieval','92/10 Extraordinaria perspectiva de la sierra, el casco antiguo de traza árabe encajonado en un peñón de roca, los arroyos de agua cristalina y huertas. Cómo llegar: Plataforma colgada acondicionada con barandillas en los accesos peatonales de la villa histórica. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02043','mirador','Mirador del Yacimiento de Libisosa y el Castillo','8.1/10 Magnífica perspectiva que combina la vista de las excavaciones de la colonia romana de Libisosa con el valle del río Lezuza y olivares. Cómo llegar: Plataforma elevada con paneles interpretativos y barandilla junto al yacimiento protegido. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02044','mirador','Mirador del Embocadero y de las Casas Colgadas del Mundo','92/10 Espectacular e imponente vista del cañón calizo del río Mundo, el caserío tradicional colgado verticalmente del precipicio y las huertas mudéjares bajas. Cómo llegar: Balcón natural adaptado con barandillas de hierro en la misma cornisa urbana residencial. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02045','mirador','Mirador del Canal de María Cristina','6.6/10 Vista periurbana de la llanura de la Manchuela, campos agrícolas de regadío, olivares marginales y la infraestructura hidráulica del canal histórico. Cómo llegar: Zona alta ajardinada en las compuertas perimetrales del casco urbano. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02046','mirador','Alto del cerro de San Roque y viñedos','6.8/10 Vista de las lomas onduladas cubiertas de viñedos de la Manchuela, campos de cereal y el perfil monumental barroco del templo parroquial. Cómo llegar: Cota natural elevada al norte de la población, transitable por pistas agropecuarias de tierra. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02047','mirador','Mirador del Laguna del Arquillo y del río Masegoso','7.8/10 Hermosa vista de la cuenca lagunar y el curso fluvial encajonado de la Sierra de Alcaraz, pinares, brezales de montaña e idónea oscuridad Starlight. Cómo llegar: Borde del talud calizo acondicionado con valla de madera, acceso por sendas forestales. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02048','mirador','Atrio de la Iglesia de Santiago el Mayor','6.3/10 Sencilla panorámica sobre los llanos cerealistas de la Mancha norte, cultivos de secano planos e idóneos atardeceres limpios de obstáculos. Cómo llegar: Plaza sobreelevada frente a la portada barroco-renacentista del templo parroquial central. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02049','mirador','Mirador de los Museos y Hoces del río Mundo','8.6/10 Espectacular relieve de la Sierra de Segura, profundos valles con densos bosques de pino resinero, matorrales mediterráneos y el casco urbano encajado. Cómo llegar: Atalaya natural adaptada con vallado en las calles altas del núcleo histórico. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02050','mirador','Mirador de la Vega del río Júcar','6.2/10 Vista de los llanos agrícolas aluviales fértiles de regadío del Júcar superior, cultivos hortícolas locales y chopera lineal de ribera. Cómo llegar: Margen de la terraza fluvial, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02017','mirador','Mirador del Castillo de Montealegre y de la Hoya','7.9/10 Soberbia panorámica de la llanura del altiplano fronterizo, olivares centenarios de montaña, campos de cereal, viñedos e hitos históricos medievales. Cómo llegar: Cima del cerro testigo coronado por las ruinas fortificadas de la fortaleza del siglo XIV. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02052','mirador','Alto del Teso de las Viñas','6.5/10 Vista diáfana de lomas onduladas de cultivo de secano y viñedos de la cuenca baja del Júcar, matorral mediterráneo y horizontes limpios. Cómo llegar: Pequeña colina exenta en las inmediaciones del cementerio municipal, acceso rural. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02018','mirador','Mirador del Castillo de Taibilla y del cañón del Taibilla','91/10 Impresionante, espectacular y alpino panorama de la Sierra de las Cabras y del río Taibilla, nogaledas centenarias, abrigos de arte rupestre y oscuridad Starlight. Cómo llegar: Cresta cuarcítica del cerro del castillo fortificado del siglo XIV, acceso por sendas de montaña señalizadas. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02056','mirador','Mirador del Cerro del Madroño','7.6/10 Excelente visual de los valles del Campo de Hellín meridional, olivares de montaña en bancales, maizales, pinos piñoneros y cielos nocturnos puros. Cómo llegar: Cota natural elevada accesible por la pista forestal que sube desde el núcleo urbano. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02019','mirador','Mirador de las Lagunas de Ruidera (Laguna Colgada)','93/10 Excepcional e imponente panorámica de las cascadas y barreras de toba que unen las lagunas del complejo (Mancha Húmeda), aguas turquesas y avifauna. Cómo llegar: Plataforma colgada adaptada con barandilla y paneles de la red del Parque Natural, accesos CM-3115. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02060','mirador','Mirador de la Peña del Castillo y del Santuario','8.4/10 Espectacular e inexpugnable atalaya de una fortaleza sobre un cerro testigo calizo escarpado de paredes verticales, dominando los valles bajos. Cómo llegar: Cima de la peña rocosa amurallada que corona el caserío, accesible por sendero peatonal empinado. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02021','mirador','Mirador del Pino del Toril y de la Dehesa','8.3/10 Vista de los bosques de pino laricio centenarios de la Sierra de Alcaraz, praderas ganaderas alpinas, fuentes de piedra caliza y pureza celeste. Cómo llegar: Paraje acondicionado junto al hito botánico del pino monumental, acceso por pista forestal. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02062','mirador','Alto del Cerro Gordo y de la Dehesa','7.1/10 Perspectiva sobre los llanos agrícolas de secano y regadío lindando con Ciudad Real, encinares tradicionales ganaderos y nítidos horizontes de baja luminosidad. Cómo llegar: Promontorio suave al norte de la población, transitable por caminos vecinales de tierra. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02901','mirador','Mirador del cerro de San Cristóbal','6.6/10 Sencilla panorámica de los llanos del secano manchego, olivares rústicos marginales e idóneo horizonte nocturno para capturar tormentas estivales. Cómo llegar: Cima suave del cerro acondicionado con accesos peatonales en la periferia del núcleo. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02064','mirador','Mirador del Pinar de la Cañada','6.8/10 Vista focalizada en la densa masa forestal de pino piñonero y resinero de la comarca, pistas de arena fina e idóneos atardeceres limpios. Cómo llegar: Pista de servicio forestal elevada, accesible al oeste del núcleo urbano. hasta la z 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02022','mirador','Alto del Molino de Viento','6.6/10 Panorámica diáfana de los llanos de transición a la sierra, extensos campos de cultivo de secano, olivos dispersos y horizontes celestes de gran visibilidad. Cómo llegar: Colina suave al norte del núcleo, junto a los restos de la antigua estructura del molino. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02065','mirador','Alto de la Cuesta del Secano','6.1/10 Sencilla visual de lomas arcillosas destinadas al cultivo cerealista, dehesas bajas rústicas y horizontes despejados idóneos para capturar puestas de sol limpias. Cómo llegar: Repecho suave al oeste de la localidad, transitable por caminos vecinales de tierra. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02066','mirador','Mirador de los Cortados del Júcar','7.6/10 Magnífica perspectiva del profundo encajonamiento del río Júcar, huertas tradicionales escalonadas en el fondo del valle y escarpados meandros de arcilla y yeso. Cómo llegar: Borde del talud natural acondicionado con vallado protector en la pista que sube al páramo norte. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02023','mirador','Mirador del Nacimiento del Río Mundo (Los Chorros)','9.2/10 Espectacular e imponente cascada de más de 80 metros que brota de una cueva en una pared caliza vertical, densos pinares y tejos milenarios. Cómo llegar: Pasarelas de madera y plataformas voladas adaptadas de la red del Parque Natural, accesos señalizados desde la CM-3204. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02068','mirador','Mirador de la Laguna de Ojos de Villaverde','7.5/10 Vista ornitológica y paisajística de la laguna natural protegida, con densos carrizales, avifauna acuática diversa y relieves suaves cubiertos de encinar. Cómo llegar: Puesto de observación acondicionado en el entorno perimetral del humedal, acceso peatonal. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02070','mirador','Mirador del Estrecho del río Salobre','8.1/10 Hermosa e intrincada panorámica de las hoces y gargantas cuarcíticas de la Sierra de Alcaraz, bosques de pino resinero y el casco urbano encajonado. Cómo llegar: Saliente rocoso adaptado con barandillas en el sendero que sube hacia las cumbres, acceso señalizado. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02071','mirador','Mirador de la Peña del rincón y río Quéjola','7.4/10 Vista panorámica de la vega del río Quéjola, taludes de piedra caliza, encinares maduros dispersos y parajes idóneos para la observación estelar nocturna. Cómo llegar: Borde de la plataforma calcárea norte, transitable por sendas forestales desde la localidad. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02024','mirador','Mirador de la Peña de la Olmeda y Castillo','8.4/10 Impresionante vista sobre la Sierra del Segura meridional, olivares de montaña en bancales, la fortaleza medieval del siglo XII y densos pinares forestales. Cómo llegar: Cresta caliza elevada que corona el cerro del castillo musulmán, acceso peatonal empinado. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02073','mirador','Mirador de la Plaza Mayor y del río Valdemembra','7.1/10 Perspectiva sobre el curso bajo del río Valdemembra, la vega agrícola llana y la silueta del monumental conjunto barroco de la plaza porticada. Cómo llegar: Zona elevada urbana adaptada con bancos en las cercanías del puente, centro del núcleo. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02025','mirador','Mirador de la Ermita del Cristo de la Antigua','8.0/10 Amplia e histórica visual de la comarca de Hellín, relieves ondulados con campos de almendros, olivares tradicionales y la fisonomía del cerro testigo. Cómo llegar: Explanada fortificada del santuario en la cota más alta de la población, accesos pavimentados. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02075','mirador','Mirador de la Ventana del Júcar','7.8/10 Espectacular balcón natural colgado sobre el gran meandro del río Júcar, huertas de ribera exuberantes, pinares de ladera e infinitos horizontes de la Manchuela. Cómo llegar: Cornisa acondicionada con barandillas, paneles explicativos y bancos en el propio casco urbano alto. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02076','mirador','Mirador del Estrecho de vianos y la Paramera','8.6/10 Soberbia e imponente atalaya a más de 1100 metros de altitud sobre la Sierra de Alcaraz, escarpes calizos verticales, quejigares y cielos Starlight de pureza total. Cómo llegar: Plataforma con vallado de protección en el borde del precipicio de la meseta caliza, carretera de montaña. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02077','mirador','Mirador del Santuario de la Virgen de la Cueva','8.5/10 Sobrecogedora panorámica del cañón del río Júcar, la lámina verde del embalse de El Molinar encajonado y el pueblo antiguo colgado del risco calizo. Cómo llegar: Explanada rocosa del histórico santuario edificado al borde del profundo precipicio, acceso señalizado. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02078','mirador','Mirador del Palacio de los Gosálvez y río Júcar','7.3/10 Hermosa vista que combina la arquitectura neoclásica del palacio decadente con el soto fluvial arbolado del Júcar y campos de cultivo. Cómo llegar: Saliente natural acondicionado en el sendero fluvial margen izquierda del río, desvío rural. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02026','mirador','Mirador de la Cueva de los Ángeles y los Cañones','7.9/10 Vista del paraje kárstico protegido, hoces excavadas por arroyos tributarios del Cabriel, densas masas de pino silvestre e idónea nitidez astronómica. Cómo llegar: Entorno acondicionado con barandillas en los senderos ecológicos locales, desvío desde el núcleo. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02080','mirador','Mirador de la Sierra de Alcaraz y río Guadalmena','8.2/10 Magnífica perspectiva de las laderas boscosas serranas, dehesas ganaderas de encina, olivares de montaña y horizontes de la vertiente de Sierra Morena. Cómo llegar: Promontorio calizo elevado al sur de la población, transitable por pistas forestales de tierra. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02027','mirador','Mirador de los Tinajares y Llanura de Viñedos','7.7/10 Impresionante e infinito mar de viñedos plano de la Mancha, bodegas industriales con sus tradicionales tinajas de barro y cielos despejados. Cómo llegar: Terraza elevada del Museo de la Tinajería o zonas altas periféricas habilitadas del municipio. 📍 Provincia: Albacete.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02030','mirador','Mirador del Castillo de Yeste y valles del Segura','9.0/10 Excepcional panorámica de la Sierra del Segura, los profundos valles fluviales de los ríos Segura y Zumeta, el pueblo escalonado y la fortaleza medieval del siglo XIV. Cómo llegar: Corona superior de la torre del homenaje y muros visitables de la fortaleza, en la parte alta de la villa. ¡PROVINCIA DE ALBACETE COMPLETADA AL 100%! 🏁 ⭐ Si estás de acuerdo, pasamos de inmediato en la secuencia a la siguiente provincia planificada: Provincia de Guadalajara / Región de Murcia (Comunidad Autónoma de la Región de Murcia), comenzando estrictamente desde la letra A con municipios como Abanilla, Abarán, Águilas, Albudeite, Alcantarilla, Los Alcázares, Aledo, Alguazas, Alhama de Murcia, Archena, etc.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90402','mirador','Mirador del Monumento al Corazón de Jesús y el "Palestina Murciano"','8.4/10 Espectacular e insólito paisaje badlands desértico erosionado por el río Chícamo, con palmerales integrados, ramblas arcillosas y montañas calizas desgarradas en el horizonte. Cómo llegar: Cota más alta del cerro del Castillo en el casco urbano, provista de escalinatas y terrazas adaptadas. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30002','mirador','Mirador de las Norias del Valle de Ricote','7.8/10 Hermosa panorámica del río Segura, huertos exuberantes de cítricos, canales tradicionales de riego y la silueta de los singulares ingenios hidráulicos de madera (Norias). Cómo llegar: Pasarela de madera elevada integrada en la Ruta de las Norias, margen izquierda del cauce fluvial. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30003','mirador','Mirador del Castillo de San Juan de las Águilas','8.8/10 Imponente vista aérea de 360 grados sobre el mar Mediterráneo, las bahías gemelas de Poniente y Levante, la Isla de Fraile y el puerto pesquero. Cómo llegar: Adarves y explanadas de la batería defensiva militar del siglo XVIII, accesible a pie o por ascensor. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30004','mirador','Mirador del Atrio de la Iglesia de Nuestra Señora de los Remedios','6.9/10 Vista del valle encajonado del río Mula, cárcavas de yeso, huertas tradicionales de secano y un despejado horizonte idóneo para la astrofotografía. Cómo llegar: Plaza pública sobreelevada que rodea el templo mudéjar, en el núcleo antiguo de la villa. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30005','mirador','Terraza del Museo de la Huerta de Murcia','6.6/10 Perspectiva sobre la llanura aluvial, plantaciones hortícolas del Segura inferior, la histórica Noria de Alcantarilla y el viaducto metálico ferroviario del siglo XIX. Cómo llegar: Plataforma acondicionada en las instalaciones del recinto museístico del parque del Acueducto. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30902','mirador','Mirador del Embarcadero del Balneario de la Encarnación','7.3/10 Estampa clásica sobre las aguas calmas del Mar Menor, la silueta de La Manga en el horizonte lacustre, espigones de madera históricos y aves marinas. Cómo llegar: Pasarela peatonal sobre el agua en el paseo marítimo, accesible desde el casco urbano central. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30006','mirador','Mirador de la Torre del Homenaje del Castillo de Aledo','8.7/10 Soberbia y vertiginosa atalaya rocosa sobre el Valle del Guadalentín, los escarpes de Sierra Espuña, campos de uva de mesa y el estrecho de la Arboleja. Cómo llegar: Remate superior visitable del bastión militar alfonsí del siglo XIII que corona el pueblo amurallado. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30007','mirador','Mirador de la Torre de los Moros (Torre Vieja)','6.7/10 Vista de la vega baja de la confluencia de los ríos Mula y Segura, huertas de regadío intensivo y la arquitectura de la torre defensiva del siglo XIV. Cómo llegar: Explanada de la fortificación exenta en el paraje de la Huerta de Alguazas, acceso señalizado. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30008','mirador','Mirador del Castillo de Alhama','8.6/10 Magnífica perspectiva de la depresión del Guadalentín, los escarpes arcillosos rojizos de los badlands de Gebas, Sierra Espuña y los baños termales históricos de origen romano. Cómo llegar: Explanada del recinto fortificado islámico-medieval sobre el cerro testigo que domina la urbe, accesos adaptados. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30009','mirador','Mirador del Ope','7.9/10 Espectacular e imponente monte escarpado calizo con vistas del sinclinal del valle del Segura, el vergel del balneario histórico y densos palmerales autóctonos. Cómo llegar: Cumbre de la Peña del Ope, accesible por sendero peatonal empinado y señalizado. ¿Cómo prefieres que continuemos la secuencia de la Región de Murcia? Si estás listo, podemos avanzar con el próximo bloque masivo de municipios con las letras C, F y J (Cartagena, Cehegín, Cieza, Fortuna, Jumilla, etc.).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30010','mirador','Mirador de los Mojones del Reino','6.4/10 Vista llana sobre la Vega Baja del Segura, canales de riego tradicionales y los monolitos de piedra históricos que delimitan la frontera con Alicante. Cómo llegar: Hito geográfico en la linde interprovincial, accesible por caminos rurales de la huerta. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30011','mirador','Mirador del Castillo de Blanca','8.3/10 Espectacular e imponente visual del cañón del río Segura, el Embalse de Ojos, palmerales densos y los escarpes rocosos del Valle de Ricote. Cómo llegar: Cresta de roca negra coronada por la fortaleza musulmana, accesible por sendero escalonado desde el casco urbano. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30012','mirador','Mirador del Salto del Usero','7.8/10 Hermoso y profundo paraje fluvial esculpido por el río Mula, pozas de agua cristalina, bóvedas de travertino y un mar periférico de viñedos de altura. Cómo llegar: Plataforma de madera con barandillas adaptada en el borde de la poza natural, desvío señalizado. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30013','mirador','Mirador del Santuario de la Virgen de la Esperanza','8.4/10 Impresionante perspectiva del río Segura encajonado en terrazas calcáreas, sotos frondosos de ribera y las singulares estructuras del santuario excavado en la roca viva. Cómo llegar: Explanada exterior de los miradores del complejo religioso, con amplios accesos rodados. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30014','mirador','Mirador del Castillo y los Badlands','6.9/10 Extraordinario paisaje desértico de cárcavas arcillosas, el discurrir bajo del río Mula, huertas tradicionales integradas e idóneo punto para astrofotografía. Cómo llegar: Promontorio elevado en el núcleo antiguo, accesible a pie desde la Plaza de la Iglesia. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30015','mirador','Mirador del Castillo de la Santa Cruz','8.9/10 Soberbia y monumental panorámica del casco histórico de la Ciudad Santa, el entorno natural de las Fuentes del Marqués y los escarpes de Sierra de Mojantes. Cómo llegar: Explanada de la BasílicaSantuario fortificada, en la cota más alta de la urbe con acceso peatonal y rodado. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30016','mirador','Mirador del Castillo de la Concepción','9.4/10 Excepcional, monumental e icónica vista aérea de 360 grados de la bahía puerto, el Teatro Romano, el arsenal militar y los cinco cerros históricos defensivos. Cómo llegar: Corona superior del Parque de Torres en el cerro central, accesible a pie, por carretera o ascensor panorámico. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30017','mirador','Mirador del Paseo de la Concepción','82/10 Espectacular estampa del casco histórico escalonado de la villa nobiliaria, los valles de cultivo del río Argos y relieves forestales del noroeste. Cómo llegar: Balcón acondicionado con barandillas de hierro en la plaza perimetral de la Ermita de la Concepción. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30018','mirador','Mirador de las Esculturas del Aire Libre','6.5/10 Vista periurbana sobre la Vega Media del Segura, plantaciones hortícolas tradicionales y el contraste de instalaciones de arte contemporáneo integradas. Cómo llegar: Zona ajardinada alta en las inmediaciones del complejo cultural urbano. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30019','mirador','Mirador del Cañón de Almadenes y del Castillo','8.8/10 Sobrecogedor desfiladero calizo vertical excavado por el río Segura, bosque de ribera profundo, nidos de rapaces y el espectáculo de la floración de melocotoneros. Cómo llegar: Pasarela volada adaptada con paneles junto a las rutas geológicas de la muela, acceso rural. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30020','mirador','Mirador del Cortao de las Peñas','7.8/10 Impresionante e intrincada fractura tectónica caliza de paredes verticales, monte bajo mediterráneo desértico e hito histórico de los baños termales romanos. Cómo llegar: Saliente acondicionado con valla en el desfiladero de la carretera RM-A25. 📍 Provincia: Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30021','mirador','Alto de la Sierra de Carrascoy','7.2/10 Vista despejada del Campo de Cartagena, cultivos de secano, almendrales y horizontes celestes diáfanos con nula contaminación para astrofotografía. Cómo llegar: Cota natural elevada al norte del término municipal, transitable por pistas forestales de tierra. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30022','mirador','Mirador del Castillo de Jumilla','8.4/10 Espectacular e infinito mar de viñedos de la D.O. Jumilla, olivares, campos de secano y la silueta gótica del conjunto fortificado del siglo XV. Cómo llegar: Explanada exterior y adarves de la inexpugnable fortaleza en el cerro testigo, acceso rodado. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30023','mirador','Mirador del Barranco de Librilla','7.4/10 Extraordinario y profundo tajo geológico arcilloso que divide en dos el casco urbano, restos de fortificaciones y cultivos de cítricos adyacentes. Cómo llegar: Balcón urbano acondicionado con barandillas en el borde de la rambla central. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30024','mirador','Torre Alfonsina del Castillo de Lorca','9.1/10 Soberbia, inmensa y colgada atalaya militar sobre el Valle del Guadalentín, la imponente Fortaleza del Sol, barrios mudéjares y sierras mineras lejanas. Cómo llegar: Corona superior de la torre del homenaje visitable del castillo medieval, acceso por carretera asfaltada. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30025','mirador','Mirador de la Noria de la Rapao','6.6/10 Perspectiva fluvial de la vega del Segura, huertas de regadío intensivo, chopera lineal y la monumental noria de hierro histórica del siglo XIX. Cómo llegar: Espacio público elevado acondicionado junto al cauce y acequia central. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30026','mirador','Mirador de las Erosiones de Bolnuevo','8.9/10 Caprichoso y espectacular monumento natural de gres arcilloso blanco esculpido por el viento (Ciudad Encantada), junto al mar Mediterráneo y calas vírgenes. Cómo llegar: Explanada de observación acondicionada frente a las formaciones geológicas, en el paseo costero. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30027','mirador','Mirador del Castillo y los Badlands de Alguazas','7.2/10 Vista periurbana de la Vega Media, cárcavas de yeso erosionadas y la fisonomía de las huertas tradicionales que resisten el avance industrial. Cómo llegar: Zona alta adaptada en el casco antiguo urbano sobre los restos arqueológicos de la muralla. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30028','mirador','Mirador del Castillo y Sierra de Revolcadores','8.8/10 Extraordinaria e infinita visual a más de 1000 metros de altitud de los cañones del río Alhárabe, pinares espesos y el Techo provincial bajo un cielo Starlight puro. Cómo llegar: Remate superior de la torre del homenaje de la fortaleza militar señorial que corona la villa. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30029','mirador','Mirador del Castillo de los Vélez','8.6/10 Impresionante vista del Valle de Mula, las laderas calizas áridas de Sierra Espuña al fondo, olivares, huertas de almendros y el trazado medieval amurallado. Cómo llegar: Explanada de la inexpugnable fortaleza renacentista del siglo XVI sobre el escarpado risco calizo. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30030','mirador','Mirador del Santuario de la Fuensanta y Cresta del Gallo','8.9/10 Extraordinaria y universal panorámica de la inmensa Huerta de Murcia, el curso del río Segura, la silueta de la Catedral y el parque regional forestal. Cómo llegar: Terrazas ajardinadas adaptadas con balaustradas frente al santuario barroco, estribaciones montañosas del sur. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30031','mirador','Mirador del Salto de la Novia y el Embalse','8.1/10 Precioso e intrincado rincón encajonado del Segura en el Valle de Ricote, con acequias de origen árabe, densos huertos de limoneros y paredes calizas verticales. Cómo llegar: Plataforma con vallado de madera en las rutas pedestres del cañón fluvial. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30032','mirador','Mirador del Castillo de las Paletas y Sierra Espuña','7.8/10 Magnífica perspectiva de las vertientes forestales de la umbría de Sierra Espuña, olivares de montaña en bancales y restos de fortalezas medievales. Cómo llegar: Promontorio rocoso elevado en el sector norte, accesible por sendas locales. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30033','mirador','Mirador del Castillo de Nogalte y Casas Cueva','7.6/10 Vista de la rambla de Nogalte, cultivos de secano, la llanura del Alto Guadalentín y el singular complejo rupestre excavado adaptado para musealización. Cómo llegar: Explanada de la fortaleza medieval y terrazas del cerro de las cuevas, acceso señalizado. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30034','mirador','Mirador del Azud de Ojos y Valle de Ricote','8.4/10 Soberbia y espectacular vista panorámica del meandro fluvial del Segura, el oasis de palmeras e higueras rodeado de escarpes áridos calizos calcáreos. Cómo llegar: Balcón natural acondicionado con barandillas de madera en la carretera alta del sinclinal. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30035','mirador','Mirador de la Academia General del Aire y el Mar Menor','7.8/10 Perspectiva de las tranquilas aguas de la laguna salada, las islas volcánicas (Mayor y Perdiguera), playas urbanas y vuelos de entrenamiento aeronáutico. Cómo llegar: Paseo marítimo de Santiago de la Ribera adaptado con espigones peatonales. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30036','mirador','Mirador de los Molinos de las Salinas de San Pedro','8.1/10 Preciosa estampa de las charcas salineras de colores rosados, carrizales protegidos, flamencos comunes, dunas de arena, el Mediterráneo y molinos salineros tradicionales. Cómo llegar: Observatorio adaptado en el Parque Natural de las Salinas y Arenales, senderos peatonales de madera. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30901','mirador','Mirador del Embalse de Santomera','7.2/10 Vista de la lámina de agua rodeada de relieves ondulados áridos, pinares de repoblación perimetrales y avifauna ligada a zonas húmedas en el somontano. Cómo llegar: Corona de la represa e inmediaciones de la zona forestal recreativa, acceso rodado. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30037','mirador','Mirador del Cabezo Gordo','7.9/10 Singular elevación caliza exenta en mitad de la inmensa llanura agrícola que alberga el importante yacimiento neandertal de la Sima de las Palomas. Cómo llegar: Senda de herradura que asciende hacia los antiguos polvorines de la peña minera. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30038','mirador','Mirador del río Segura y del Rodeo','6.7/10 Sencilla panorámica de la huerta aluvial, canales fluviales, plantaciones de regadío intensivas y horizontes limpios al atardecer murciano. Cómo llegar: Zona perimetral elevada acondicionada junto a los senderos del margen derecho del río. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30039','mirador','Mirador del Santuario de La Santa y Sierra Espuña','8.7/10 Magnífica perspectiva de las vertientes de pino carrasco de la sierra, el valle del Guadalentín, huertas tradicionales y el complejo monumental del siglo XVII. Cómo llegar: Explanada elevada adaptada del santuario de Santa Eulalia, estribaciones forestales altas de la villa. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30040','mirador','Mirador de la Cruz de Ulea y el Segura','8.0/10 Vista aérea del encajonamiento del río Segura en el Valle de Ricote, densos palmerales, huertas de frutales escalonadas y el perfil del pueblo. Cómo llegar: Cima de la peña rocosa coronada por la cruz, acceso por camino peatonal señalizado. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30042','mirador','Mirador del Corazón de Jesús','7.9/10 Hermosa vista de los meandros del río Segura, el oasis de cítricos del Valle de Ricote inferior y las laderas calizas desérticas que lo delimitan. Cómo llegar: Promontorio urbano adaptado con balaustrada y terrazas en el sector alto de la localidad. 📍 Provincia: Región de Murcia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30043','mirador','Mirador del Santuario del Castillo y del cerro del Paso','8.4/10 Panorámica sobre el altiplano de viñedos de la D.O. Yecla, olivares alineados, el casco urbano industrial y las pinturas rupestres del Monte Arabí lejanas. Cómo llegar: Explanada de la basílica de la Purísima en la cota más elevada del cerro de la villa, accesos adaptados. ¡COMUNIDAD AUTÓNOMA DE LA REGIÓN DE MURCIA COMPLETADA AL 100%! 🏁 ⭐ Si estás listo, podemos saltar de inmediato a la siguiente provincia en el orden del plan de ruta nacional del atlas: Provincia de Alicante (Comunidad Valenciana), comenzando estrictamente desde la letra A con municipios como Atzúbia (L''), Agost, Agres, Aigües, Albatera, Alcalalí, Alcocer de Planes, Alcoleja, Alcoy / Alcoi, Alfafara, Alfàs del Pi (L''), Algorfa, Algueña, Alicante / Alacant, Almoradí, Almudaina, Alquería de Asnar, Altea, Aspe, etc. Dime, ¿iniciamos el nuevo y masivo bloque de la Provincia de Alicante?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03001','mirador','Mirador de la Ermita de San Pedro','7.1/10 Perspectiva árida del Campo de Alicante, cárcavas arcillosas, talleres alfareros tradicionales, la silueta de la Sierra del Cid y el mar al fondo. Cómo llegar: Explanada elevada del templo, accesible a pie por rampas peatonales desde el núcleo antiguo. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90378','mirador','Mirador del Santuario de la Virgen de Agres','8.4/10 Impresionante panorámica del Valle de Agres, barrancos de la Sierra Mariola, densos bosques de pinos, tejos relictuales, fuentes naturales y cavas de nieve. Cómo llegar: Terrazas exteriores del santuario colgado en la roca, acceso peatonal adoquinado y señalizado. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90852','mirador','Mirador de la Torre del Homenaje del Castillo','7.6/10 Magnífica visual de la línea costera de El Campello y Benidorm, laderas cubiertas de pino carrasco, matorral mediterráneo y el histórico complejo del preventorio. Cómo llegar: Base superior transitable de la torre medieval en la cota más alta de la población. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90379','mirador','Mirador del Parque de la Huerta y Sierra de Albatera','7.2/10 Amplia perspectiva de la Vega Baja del Segura, palmerales y cultivos de granados alternados con los áridos badlands y barrancos calizos serranos. Cómo llegar: Zona perimetral alta acondicionada con barandillas de madera en el parque urbano. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90380','mirador','Mirador de la Torre Medieval de Alcalalí','7.9/10 Hermosa vista del Valle de Pop, el discurrir del río Gorgos, cultivos de almendros en floración estacional, bancales tradicionales y relieves de la Marina Alta. Cómo llegar: Terraza superior accesible de la torre defensiva del siglo XIV situada en el centro urbano. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90853','mirador','Mirador del río Serpis y llanura de Planes','6.9/10 Vista fluvial sobre el cauce del Serpis, campos de olivos y cerezos de la comarca del Comtat y relieve montañoso de la Serrella. Cómo llegar: Margen de la terraza fluvial, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90406','mirador','Mirador de la Aitana septentrional','8.4/10 Soberbia visual alpina de la vertiente norte de la Sierra de Aitana, neveros históricos de piedra seca, carrascales densos y profundos valles escarpados. Cómo llegar: Pistas forestales transitables hacia las cumbres, desvío desde la carretera CV-770. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03002','mirador','Mirador del Salt y Barranc del Cint','8.8/10 Espectacular grieta caliza vertical, cascadas estacionales, puentes monumentales industriales de la ciudad, carrascales de la Font Roja y avistamiento de buitres. Cómo llegar: Estructura volada adaptada con pasarela de madera, acceso por sendero local desde el norte. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46022','mirador','Mirador de los Arrozales de la Albufera','67/10 Espectacular e infinita panorámica de las tablas de cultivo inundadas del parque natural, abundante avifauna acuática migratoria y nítidas puestas de sol. Cómo llegar: Margen del camino rural elevado en los límites orientales del término, dentro de la Albufera. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90009','mirador','Mirador del Faro de l''Albir y Serra Gelada','8.7/10 Impresionante e icónica panorámica marítima sobre la Bahía de Altea, el Peñón de Ifach y los imponentes acantilados fósiles de la Sierra Helada. Cómo llegar: Terraza adaptada del centro de interpretación del faro, final del camino peatonal de la Serra Gelada. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90854','mirador','Mirador de la Ermita de la Virgen de la Fuensanta','6.6/10 Vista llana del Valle del Segura meridional, plantaciones de cítricos de la Vega Baja y el relieve suave de lomas arcillosas. Cómo llegar: Pequeña elevación natural que alberga el templo, accesible por camino pavimentado. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90381','mirador','Mirador de las Canteras de Mármol y Viñedos','6.8/10 Singular paisaje minero de explotaciones de piedra caliza y mármol blanco, viñedos de uva Monastrell en el llano y horizontes limpios. Cómo llegar: Entorno perimetral alto de las canteras, accesible por pistas agropecuarias de tierra. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03003','mirador','Baluarte de Santa Ana del Castillo de Santa Bárbara','9.3/10 Extraordinaria y monumental panorámica de 360 grados de la Bahía de Alicante, el puerto deportivo, el cabo de las Huertas y la Tabarca. Cómo llegar: Corona superior de la fortaleza medieval del monte Benacantil, accesible por ascensor urbano, carretera o senderos peatonales. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90382','mirador','Mirador del Azud de Almoradí y río Segura','6.5/10 Vista fluvial sobre la red de acequias históricas y el cauce regulado, huertas tradicionales de alcachofas e hileras de álamos de ribera. Cómo llegar: Pasarela peatonal acondicionada junto a las compuertas, en los límites de la huerta tradicional. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90383','mirador','Mirador de la Torre Almohade de Almudaina','7.4/10 Perspectiva sobre la comarca del Comtat oriental, olivares alineados en terrazas, pequeños arroyos de montaña y la Sierra de la Solana lejana. Cómo llegar: Nivel superior elevado de la torre defensiva islámica del siglo XII en el casco urbano. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90855','mirador','Mirador del Parque del río Serpis','6.7/10 Vista diáfana de la vega del Serpis medio, frondosas choperas, cultivos hortícolas locales y horizontes montañosos limpios de obstáculos industriales. Cómo llegar: Zona ajardinada alta adaptada con bancos junto al cauce fluvial perimetral. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03004','mirador','Mirador de los Cronistas de España (Poble Antic)','9.1/10 Icónica, universal y espectacular estampa de la Bahía de Altea, el puerto deportivo, el Peñón de Ifach y las cúpulas de tejas azules. Cómo llegar: Gran plaza balaustrada en pleno centro histórico amurallado alto de la villa. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03005','mirador','Mirador del Castillo del Río y los Badlands','7.2/10 Vista del cauce erosionado del río Tarafa, cárcavas de yeso, olivares rústicos de montaña y las ruinas fortificadas medievales islámicas. Cómo llegar: Promontorio rocoso elevado en la confluencia de los cauces, acceso por sendero señalizado. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90401','mirador','Mirador del Castillo de Forna y la Vall de Gallinera','7.5/10 Magnífica perspectiva de las plantaciones de cítricos del fondo de valle, dehesas y las sólidas murallas medievales de la fortaleza señorial perfectamente conservada. Cómo llegar: Explanada elevada que circunda el castillo en la pedanía alta de Forna, acceso asfaltado. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90384','mirador','Mirador de las Cuevas de la Araña y la Serrella','7.3/10 Vista sobre los barrancos del Comtat, lomas de almendros e impresionantes agujas de roca caliza conocidas como "Els Frares" de la Serrella. Cómo llegar: Cornisa natural alta al oeste del núcleo urbano, transitable a pie por sendas ganaderas. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03006','mirador','Torre del Homenaje del Castillo de Banyeres','8.4/10 Espectacular panorámica de 360 grados sobre el nacimiento del río Vinalopó, la Sierra Mariola, olivares de altura y tres provincias limítrofes. Cómo llegar: Cota más elevada de la fortaleza del siglo XIII que corona la villa, accesible con entrada. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90385','mirador','Mirador de la Torre de los Corts','7.5/10 Vista panorámica del valle alto del río Fageca, quejigares de ladera, almendrales de montaña y la silueta del palacio fortificado renacentista. Cómo llegar: Cota natural elevada próxima a los restos del complejo noble, acceso pedestre. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90856','mirador','Mirador de la Ermita del Divino Pastor','7.4/10 Amplia visual del Valle del Vinalopó alto, huertas de frutales y olivos, plantaciones de viñedos y las cumbres de la Solana de Beneixama. Cómo llegar: Explanada de la ermita al norte del casco urbano, provista de accesos rodados y bancos. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90386','mirador','Mirador del Cabezo Redondo y Santuario de la Pilarica','6.9/10 Perspectiva sobre los llanos agrícolas de la Vega Baja, plantaciones hortícolas de cítricos e interesantes pinares de repoblación en las lomas de yesos. Cómo llegar: Cerro acondicionado con terrazas ajardinadas en el entorno del santuario rústico de montaña. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90387','mirador','Alto del Teso de la Iglesia de San Jerónimo','6.2/10 Sencilla panorámica rural de cultivos tradicionales de regadío intensivo, palmerales aislados e idóneos horizontes limpios de obstáculos para astrofotografía. Cómo llegar: Plaza pública sobreelevada frente a la portada del templo barroco, centro del casco urbano. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90388','mirador','Mirador de la Sierra de Segària','7.1/10 Vista del valle bajo del río Girona, naranjales de la Marina Alta y los imponentes farallones y crestas calizas de la sierra de Segària. Cómo llegar: Punto alto acondicionado en los caminos forestales del flanco septentrional del término. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90389','mirador','Mirador del Embalse de Guadalest y Sierra de Aitana','8.5/10 Espectacular visual de la inmensa lámina azul turquesa del embalse, rodeada de olivares en bancales, densos carrascales y las paredes de Aitana. Cómo llegar: Borde del talud natural acondicionado con valla de madera en el extremo este del pueblo. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90390','mirador','Mirador del Embalse de Beniarrés y del Serpis','8.2/10 Hermosa panorámica de la represa reguladora del río Serpis, dehesas y pastizales de montaña del Comtat y la Sierra de la Safor al fondo. Cómo llegar: Zona de estacionamiento acondicionada con paneles didácticos junto a los accesos de la represa. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90391','mirador','Mirador de la Cueva de las Calaveras','7.4/10 Vista arqueológica y paisajística del Valle del Girona, plantaciones de naranjos en terrazas e interesantes formaciones calcáreas de la vertiente serrana. Cómo llegar: Explanada exterior del complejo turístico de las grutas kársticas, accesos adaptados. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03007','mirador','Balcón del Mediterráneo (Castillo de Benidorm)','9.1/10 Impresionante e icónica estampa del skyline de rascacielos únicos, las playas gemelas de Levante y Poniente y la Isla de Benidorm exenta. Cómo llegar: Gran atalaya blanca balaustrada situada en el promontorio rocoso que divide las bahías. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90392','mirador','Mirador del Castillo de Benifallim','7.8/10 Vista de las vertientes de pino y carrasca de la Sierra de Renta, valles encajonados del l''Alcoià y las ruinas fortificadas medievales musulmanas. Cómo llegar: Risco rocoso que alberga los restos del castillo defensivo, acceso pedestre por sendero empinado. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90393','mirador','Mirador de la Font de parte de la Sierra de Aitana','8.3/10 Magnífica visual alpina a más de 1000 metros de altitud sobre la Vall de Guadalest, con densas masas forestales, fuentes naturales y cimas escarpadas. Cómo llegar: Paraje acondicionado de alta montaña con estacionamiento en los accesos de la senda botánica. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90394','mirador','Mirador del Sindicat y el Cavall Verd','7.9/10 Vista espectacular de los cañones fluviales del Gorgos, viñedos tradicionales de uva pasa, almendrales en terrazas de piedra seca y la montaña del Cavall Verd. Cómo llegar: Cornisa natural adaptada con vallas informativas en el paseo perimetral norte de la villa. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90395','mirador','Mirador de la Noria de Benijófar y río Segura','6.6/10 Vista del cauce llano del río, la red tradicional de riego de la Vega Baja y el monumental ingenio hidráulico de hierro restaurado del siglo XIX. Cómo llegar: Espacio público elevado acondicionado junto a los parques fluviales urbanos del núcleo. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90396','mirador','Mirador del Molí del Salt','7.4/10 Hermosa vista de las hoces excavadas por el río Fageca, el salto de agua natural entre riscos calizos y las ruinas de la arqueología industrial harinera. Cómo llegar: Saliente acondicionado con barandillas de madera en el itinerario peatonal señalizado. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90397','mirador','Mirador del Barranc de Caraita','7.2/10 Sorprendente y caótico colapso geológico de barrancos arcillosos profundos, olivares y campos de frutales en terrazas de la comarca del Comtat. Cómo llegar: Borde del precipicio natural acondicionado con valla de madera en la periferia de la localidad. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90398','mirador','Mirador del sinclinal de la Vall de Guadalest','8.4/10 Extraordinaria e infinita visual sobre el embalse de color esmeralda, los pueblos colgados de las laderas y las moles de la Sierra de Aitana y Serrella. Cómo llegar: Atalaya natural adaptada con paneles informativos en las cercanías del casco urbano alto. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90399','mirador','Mirador del Barranc del Sofre y los Balnearios','7.1/10 Perspectiva sobre los cultivos de secano de olivos y almendros, relieves suaves del Comtat e hitos de las fuentes de aguas termales sulfurosas. Cómo llegar: Saliente natural accesible por pistas ganaderas de tierra desde el núcleo urbano. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03008','mirador','El balcó de la Serrella','8.0/10 Soberbia y colgada atalaya sobre el Valle de Zeta, apodada el "balcón de la Serrella", con vistas a escarpados murallones calizos calcáreos y olivares. Cómo llegar: Cornisa acondicionada con barandilla en el borde mismo del casco urbano de la pequeña villa. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90400','mirador','Mirador del Calvari y Sierra de Segària','7.4/10 Vista de las plantaciones de cítricos de la Rectoría de la Marina, cuevas lejanas y las crestas calcáreas recortadas de Segària bajo horizontes limpios. Cómo llegar: Explanada de la ermita en la cota más elevada del Calvario, acceso pedestre por sendero. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03009','mirador','Mirador del Paseo Ecológico de la Costa y calas de Benissa','8.8/10 Extraordinaria panorámica marítima de acantilados escarpados, calas de agua turquesa protegidas (Advocat y Baladrar), pinares litorales y el Peñón de Ifach. Cómo llegar: Sendero costero adaptado con pasarelas de madera y miradores con barandillas, desvío señalizado desde la N-332. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03043','mirador','Adarve del Castillo de Biar','8.5/10 Soberbia e histórica panorámica de la cuenca del Vinalopó alto, olivares centenarios en terrazas, densos pinares forestales y la bóveda almohade del siglo XII. Cómo llegar: Corona superior transitable de los muros de la fortaleza medieval, accesible por carretera o sendero urbano peatonal. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03044','mirador','Mirador de la Pedrera y la Vega Baja','6.7/10 Vista panorámica del llano de cultivos hortícolas intensivos de cítricos de la vega del Segura, zonas recreativas forestales integradas y colinas de yesos. Cómo llegar: Cornisa natural alta adaptada con vallado de protección en el paraje recreativo de la Pedrera. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03045','mirador','Mirador del barranco de l''Algar y Penya d''Orxeta','7.8/10 Vista de las vertientes boscosas de la Marina Baixa, encajonamiento fluvial, cultivos de nísperos tradicionales en bancales y relieves escarpados. Cómo llegar: Borde del talud calizo, accesible por caminos rurales desde el núcleo. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03046','mirador','Mirador del Castillo de Busot y el Cabeçó d''Or','8.4/10 Impresionante vista sobre la comarca del Alacantí, el macizo calizo del Cabeçó d''Or que alberga las cuevas del Canelobre y la línea costera lejana. Cómo llegar: Explanada de la antigua fortaleza restaurada en el cerro testigo que corona el pueblo, accesos adaptados. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03049','mirador','Mirador del Santuario de San Roque y Sierra de Callosa','8.0/10 Impresionantes y escarpadas laderas calizas verticales de la sierra calva, con vistas panorámicas aéreas de la inmensa llanura agrícola de la Vega Baja. Cómo llegar: Explanada elevada del santuario en el sector alto de la localidad, accesible por calzada escalonada. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03048','mirador','Mirador de las Fuentes del Algar (Fonts de l''Algar)','8.7/10 Precioso e intrincado paraje de cascadas, fuentes naturales de agua cristalina del río Algar, densos huertos de nísperos en bancales y canales árabes. Cómo llegar: Pasarelas y miradores con barandillas integrados en el itinerario ecológico regulado del complejo natural. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03010','mirador','Mirador del Peñón de Ifach (Cima del Peñón)','9.6/10 Excepcional, espectacular e inigualable atalaya costera a más de 300 metros sobre el mar, divisando las salinas urbanas con flamencos y la costa alicantina. Cómo llegar: Cumbre de la colosal roca calcárea del Parque Natural del Penyal d''Ifac, itinerario de montaña regulado con túnel y cuerdas. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03015','mirador','Mirador de la Torre de la Illeta y yacimiento arqueológico','8.3/10 Vista marítima e histórica que combina la torre vigía del siglo XVI con los baños de la Reina del yacimiento prehistórico e íbero costero. Cómo llegar: Paseo marítimo perimetral acondicionado junto al promontorio arqueológico costero. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03052','mirador','Mirador de la Creu de la Cañada','7.1/10 Panorámica sobre el llano agrícola del Alto Vinalopó, campos de vid baja, olivares alineados e idóneo punto para astrofotografía por baja luminosidad. Cómo llegar: Cota natural elevada al norte de la población coronada por una cruz, transitable por sendas rurales. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03011','mirador','Mirador del Castillo de Castalla','8.4/10 Espectacular e infinita panorámica de la Hoya de Castalla, los densos pinares del Maigmó, cultivos de secano tradicionales y el recinto medieval restaurado. Cómo llegar: Patio de armas y corona superior visitable de la inexpugnable fortaleza en el cerro testigo rocoso. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03054','mirador','Mirador del Santuario de Pla de Petracos','8.3/10 Vista arqueológica de abrigos de roca caliza con arte rupestre macroesquemático Patrimonio de la Humanidad, campos de almendros y escarpes de la Serrella. Cómo llegar: Plataforma elevada con paneles interpretativos y pasarelas de la red cultural protegida, acceso señalizado. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03055','mirador','Mirador del Parque Natural del Hondo','6.6/10 Vista de humedales lagunares someros artificializados de regadío, carrizales densos, charcas salinas y avistamiento de abundante avifauna acuática amenazada protegida. Cómo llegar: Casetas de observación y pasarelas de madera integradas en los itinerarios compartidos del espacio protegido. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03012','mirador','Mirador del Castillo de Cocentaina y Palau Comtal','8.6/10 Soberbia y colgada atalaya militar gótica del siglo XIV sobre el Valle del Serpis, las vertientes forestales escarpadas de la Mariola y el casco urbano. Cómo llegar: Corona superior de la gran torre defensiva cuadrada visitable en el cerro del castillo, acceso rodado. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03057','mirador','Mirador del Castillo de Confrides (Castell d''Aljofra)','8.4/10 Impresionante visual alpina a más de 1100 metros de altitud de la cabecera de la Vall de Guadalest, el puerto de montaña, carrascales y riscos calizos calcáreos. Cómo llegar: Risco de roca caliza escarpada que alberga las ruinas de la fortaleza islámica más alta de la provincia, acceso pedestre.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03058','mirador','Mirador del Castillo de Santa Bárbara','7.2/10 Panorámica diáfana de la Vega Baja del Segura, huertos de cítricos e higueras, la llanura aluvial y la imponente silueta del palacio-fortaleza de origen musulmán. Cómo llegar: Explanada elevada de la fortaleza medieval que corona el cerro calizo exento que domina la villa. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03013','mirador','Mirador de la Sierra de Crevillent y el Hondo','8.1/10 Impresionante vista de los barrancos áridos de la sierra, matorral mediterráneo xerófilo, y la lámina de agua de la Reserva Natural de El Hondo en la llanura litoral. Cómo llegar: Plataforma con barandilla y paneles en los senderos forestales altos, accesible por la pista de San Pasqual. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03061','mirador','Atrio de la Iglesia de San Miguel Arcángel','6.1/10 Sencilla y limpia perspectiva rural sobre la llanura de regadío intensivo de la Vega Baja, campos hortícolas ordenados y puestas de sol nítidas sin obstáculos. Cómo llegar: Plaza pública elevada que circunda el templo parroquial, en el centro urbano. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03062','mirador','Mirador de la Palmera "El Chopo" y la Huerta','6.5/10 Vista singular que combina el patrimonio etnográfico agrario, ejemplares de palmeras datileras centenarias caprichosas y los llanos hortícolas de la comarca. Cómo llegar: Estructura urbana integrada en el paseo perimetral junto a las zonas de cultivo. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03014','mirador','Mirador del Castillo de Dénia y el Montgó','9.4/10 Excepcional e icónica panorámica de 360 grados sobre el puerto marítimo, el golfo de Valencia, los barrios marineros y el imponente perfil de la Sierra del Montgó. Cómo llegar: Adarves de la fortaleza islámica en la cota más alta del núcleo urbano, con accesos adaptados. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03064','mirador','Mirador de la Huerta y los Azarbes','6.4/10 Vista llana del laberinto de canales de drenaje tradicionales (azarbes), el paisaje agrícola cuadriculado de la Vega Baja y horizontes limpios idóneos para astrofotografía. Cómo llegar: Margen del camino rural elevado perimetral a las cubetas de regadío. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03016','mirador','Mirador del Palacio de Altamira y el Palmeral','9.2/10 Extraordinaria e infinita panorámica del mayor bosque de palmeras de Europa Patrimonio de la Humanidad, el cauce del río Vinalopó y las cúpulas barrocas de la ciudad. Cómo llegar: Corona superior de la torre del homenaje visitable del alcázar medieval, en pleno casco histórico. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03017','mirador','Mirador del Tajo de la Jaud y Valle del Vinalopó','7.8/10 Magnífica perspectiva del valle medio del río Vinalopó, las laderas áridas erosionadas de la sierra de la Torreta, el perfil industrial de la ciudad y matorral mediterráneo. Cómo llegar: Saliente natural acondicionado con valla de madera al norte del casco urbano, acceso por senderos locales. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03067','mirador','Mirador del Puerto de Tollos y la Serrella','8.2/10 Soberbia visual a más de 800 metros de altitud de la Vall de Seta, los imponentes farallones calizos de la sierra de la Serrella, olivares en bancales y pinos carrascos. Cómo llegar: Apartadero acondicionado con cartelería explicativa en la carretera de montaña CV-720. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03068','mirador','Mirador de la Font de l''Anouer y Cumbres calizas','8.1/10 Vista montañosa del interior de la comarca de la Marina Alta, profundos valles de roca calcárea desnuda erosionada, almendrales y nítida oscuridad estelar Starlight. Cómo llegar: Promontorio rocoso elevado en los accesos de la pequeña localidad, transitable a pie por sendas de herradura. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03018','mirador','Mirador del Castell y la mole del Puig Campana','8.9/10 Impresionante vista del litoral de la Marina Baixa, el mar de rascacielos de Benidorm y la descomunal pared vertical del Puig Campana (segundo gigante provincial). Cómo llegar: Explanada de la antigua fortificación medieval reconvertida en mirador adaptado con barandillas en el casco antiguo. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03070','mirador','Mirador de la Mota del Río Segura','6.6/10 Vista fluvial del cauce regulado del Segura inferior, sotos de ribera, plantaciones hortícolas de la Vega Baja y avifauna estacional ligada al agua. Cómo llegar: Paseo elevado en la mota del río, dotado de accesos peatonales y áreas de descanso. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03071','mirador','Mirador de les Coves y Valle del Gorgos','7.6/10 Hermosa vista de las oquedades naturales colgadas de la vertiente caliza, la vega agrícola de almendros y viñedos de moscatel, y la silueta del Montgó. Cómo llegar: Borde del talud geográfico al norte del núcleo urbano, accesible por sendas ecológicas. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90857','mirador','Mirador de la Albufera de Gaianes y el Benicadell','7.8/10 Perspectiva ornitológica y paisajística de la laguna natural recuperada, con el imponente telón de fondo de la cresta caliza del Benicadell y pinares maduros. Cómo llegar: Caseta-observatorio adaptada con pasarelas de madera en la periferia del humedal protegido. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03073','mirador','Mirador de la Creu y Valle de Polop','7.4/10 Amplia visual sobre la confluencia de los ríos Seta y Frainos, campos de olivos milenarios, cultivos tradicionales de ladera y sierras del interior alicantino. Cómo llegar: Cerro exento coronado por la cruz, transitable a pie por camino vecinal acondicionado de tierra. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03074','mirador','Alto de las Eras de la Huerta','6.3/10 Sencilla panorámica manchegomediterránea de los llanos hortícolas de la comarca, campos de limoneros, palmeras dispersas e idóneos atardeceres limpios de postes. Cómo llegar: Promontorio suave en el sector norte de la población, de fácil acceso peatonal. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03020','mirador','Mirador del Castillo y Pinada de Guardamar','8.8/10 Espectacular e infinita vista costera que fusiona la desembocadura del Segura, el bosque litoral de dunas y pinos y el mar de la bahía de Santa Pola. Cómo llegar: Recinto amurallado de la antigua villa medieval en el cerro del Castillo, dotado de accesos peatonales urbanos. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03078','mirador','Mirador de la Sierra de los Frailes y el Valle','7.2/10 Vista diáfana de la cuenca agrícola interior, cultivos de vid de mesa, almendros, relieves áridos escarpados e idóneo horizonte nocturno para capturar estrellas. Cómo llegar: Cota natural elevada al sur de la población, accesible por pistas agropecuarias de montaña. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03021','mirador','Mirador del Barranc dels Molins','8.1/10 Impresionante corte geológico de la Foia de Castalla, rodeado de laderas calcáreas, densos carrascales y patrimonio preindustrial de molinos harineros y pozos de nieve. Cómo llegar: Estructura acondicionada con barandilla al inicio del desfiladero, desvío señalizado desde el casco urbano. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03080','mirador','Mirador de los Jardines del Palacio de Fontalba','6.9/10 Vista de la vega del río Segura, frondosos sotos de ribera, palmeras datileras monumentales y el contraste del majestuoso trazado ajardinado señorial. Cómo llegar: Balcón natural adaptado en el extremo de la cornisa de los jardines del palacio, centro urbano. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90860','mirador','Mirador de la Dehesa del Bernia y Valle de Pop','8.1/10 Precioso mar de viñedos de moscatel y almendros que florecen en invierno, el curso alto del río Gorgos y el imponente muro calizo de la Sierra de Bernia. Cómo llegar: Borde del repecho natural acondicionado en el camino de ascenso hacia las cimas serranas occidentales. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03022','mirador','Mirador de la Falsa del Cabo de la Nao','9.6/10 Excepcional e imponente acantilado calizo vertical de más de 120 metros cortado a plomo sobre el Mediterráneo, con vistas a la Isla de Ibiza en días claros e idóneo punto Starlight. Cómo llegar: Plataforma colgada adaptada con barandillas de hierro y paneles geográficos junto al faro del cabo, carretera de la costa. ¡PROVINCIA DE ALICANTE COMPLETADA AL 100%! 🏁 ⭐ Si estás de acuerdo, pasamos de inmediato en la secuencia masiva de este gran atlas territorial al siguiente destino: Provincia de Castellón / Castelló (Comunidad Valenciana), comenzando estrictamente desde la letra A con municipios como Atzeneta del Maestrat, Aín, Albocàsser, Alcalà de Xivert, Alcaudete de la Jara / Alcudia de Veo, Alfondeguilla, Algimia de Almonacid, Almassora, Almedíjar, Almenara, Altura, Arañuel, Ares del Maestrat, Argelita, Artana, Ayódar, Azuébar, etc.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03085','mirador','Mirador del Teso del Calvari y la Vall de Pop','7.8/10 Perspectiva del fondo aluvial del valle, viñedos tradicionales escalonados en bancales de piedra seca, olivos centenarios y el perfil del núcleo medieval. Cómo llegar: Colina que alberga las estaciones del calvario urbano, acceso peatonal desde el núcleo histórico. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03086','mirador','Mirador de la Torre de Millena y la Vall de Travad','7.4/10 Vista de relieves calizos escarpados del Comtat, campos de olivos milenarios, cultivos tradicionales de ladera y la silueta defensiva de origen almohade. Cómo llegar: Promontorio rocoso exento coronado por los restos de la torre defensiva, acceso rural a pie. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03088','mirador','Mirador de la Orito y de la Cueva de San Pascual','7.1/10 Vista del valle medio del Vinalopó, campos de uva de mesa embolsada, lomas yesosas de erosión lineal y horizontes despejados castellano-mediterráneos. Cómo llegar: Explanada elevada del santuario rústico de la pedanía de Orito, con accesos rodados y aparcamiento. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03903','mirador','Mirador de la Laguna Rosa de Torrevieja','7.5/10 Impresionante panorámica ornitológica y paisajística de la cubeta salinera protegida, con sus características aguas rosadas y abundante avifauna acuática migratoria. Cómo llegar: Punto de observación acondicionado con paneles informativos en los límites del parque natural, acceso pedestre. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03091','mirador','Alto de la Creu y la Vall de Pop','7.6/10 Vista del curso alto del río Gorgos, cultivos de cítricos, almendrales de montaña y los escarpes calcáreos de la Sierra de la Solana. Cómo llegar: Elevación natural al norte del pueblo, transitable a pie por pistas agropecuarias de tierra. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03024','mirador','Mirador del Benicadell y la Plana de Muro','8.1/10 Amplia e imponente visual del valle del río Serpis superior, huertas de media montaña y la pirámide caliza del pico Benicadell. Cómo llegar: Cornisa natural alta situada en los senderos que suben hacia el Parque Natural de la Mariola. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03025','mirador','Mirador del Calvari y el Camp d''Alacant','7.0/10 Vista periurbana de la comarca, cultivos de regadío remanentes, huertas tradicionales de frutales y la línea de costa lejana del golfo de Alicante. Cómo llegar: Zona alta ajardinada con accesos peatonales urbanos en el entorno de la ermita del Calvario. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03026','mirador','Mirador del Castillo de la Mola y Santuario de la Magdalena','8.3/10 Magnífica perspectiva que fusiona la arquitectura modernista con los escarpes del río Vinalopó, campos de vid y la singular torre triangular medieval. Cómo llegar: Explanada exterior adaptada del cerro de la Mola, provista de accesos rodados y zonas de descanso. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03094','mirador','Mirador del Calvari y de la Bahía de Altea','8.2/10 Espectacular estampa de la Hoya de Benidorm, el mar de rascacielos costero, el Mediterráneo azul y los densos bosques de pino carrasco. Cómo llegar: Atalaya urbana adaptada con balaustradas y mirador en el cerro del Calvario, casco urbano alto. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03095','mirador','Mirador del Segaria y el llano de la Marina','7.1/10 Perspectiva sobre los llanos agrícolas de naranjos, la silueta de la Sierra de Segaria, pequeños viñedos y horizontes limpios del litoral norte. Cómo llegar: Pista agrícola elevada hacia las estribaciones de la sierra, accesible desde los caminos rurales. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03096','mirador','Mirador de la Ermita de la Salud y Sierra de Onil','7.9/10 Vista de la Foia de Castalla occidental, olivares centenarios alineados en bancales, campos de almendros y las vertientes boscosas de la Mariola. Cómo llegar: Explanada natural de la ermita al borde del monte, transitable por camino asfaltado con aparcamiento. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03097','mirador','Mirador del Castillo de Orba (Castellet)','7.7/10 Hermosa vista de los meandros del río Girona, la Vall de Rectoría, densas plantaciones de cítricos y los farallones calizos de la sierra. Cómo llegar: Cerro testigo fortificado que domina el casco urbano por el este, acceso pedestre por sendero señalizado. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90858','mirador','Mirador del Embalse de Amadorio y Orcheta','7.8/10 Hermosa e intrincada panorámica de la lámina de agua encajada entre desfiladeros calcáreos, huertas de cítricos, palmerales autóctonos y la imponente Sierra Aitana. Cómo llegar: Borde del talud natural acondicionado con valla de madera, acceso por sendero local a pie. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03027','mirador','Mirador del Seminario y Castillo de Orihuela','8.8/10 Soberbia, inmensa y monumental panorámica sobre la Vega Baja del Segura, el inmenso Palmeral de Orihuela, iglesias gótico-barrocas y el foso del río. Cómo llegar: Terrazas e inmediaciones del histórico edificio del Seminario de San Miguel, cerro de la Muela urbano alto. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03100','mirador','Mirador del Coll de Rates','8.0/10 Excepcional e infinita atalaya de la Marina Alta a más de 600 metros de altitud, con vistas del valle, almendrales y el mar Mediterráneo en días claros. Cómo llegar: Apartadero de montaña adaptado con paneles interpretativos en la carretera CV-715, cima del puerto. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03101','mirador','Mirador de los Molinets','7.6/10 Vista que combina la arquitectura tradicional de los molinos harineros de piedra con los campos hortícolas de la llanura prelitoral y el Montgó. Cómo llegar: Cresta del cerro exento que flanquea el norte de la localidad, provisto de accesos peatonales señalizados. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03028','mirador','Mirador de Pego','Cómo llegar: Balcón natural acondicionado con barandillas y paneles explicativos en la carretera CV-700 subida a la Vall de Gallinera. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03103','mirador','Mirador del Jardín de Santos y Barranc del Sinc','8.2/10 Extraordinaria vista de las vertientes forestales de la Sierra Aitana, un singular jardín botánico del siglo XIX, pinares y profundas gargantas calizas. Cómo llegar: Terraza natural acondicionada con barandillas dentro del recinto del jardín histórico rústico. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03029','mirador','Mirador del Castillo y de la muralla islámica','8.2/10 Vista panorámica del valle del Vinalopó, la sierra del Cid, el perfil urbano medieval y las imponentes defensas artilleras del siglo XII restauradas. Cómo llegar: Explanada de la fortaleza musulmana en la cota más alta de la localidad, acceso peatonal directo. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03902','mirador','Mirador de la Torre de la Horadada','7.8/10 Preciosa estampa costera del cabo costero, playas urbanas arenosas del litoral sur alicantino, el mar Mediterráneo e hito defensivo de la torre vigía del siglo XVI. Cómo llegar: Paseo marítimo perimetral acondicionado junto al acantilado de la torre, casco urbano bajo costero. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03030','mirador','Mirador del Barranc de l''Encantada','83/10 Sobrecogedor y estrecho cañón calizo de paredes verticales, pozas de agua cristalina (Gorg del Salt), densos pinares forestales y vegetación rupícola. Cómo llegar: Plataforma de observación acondicionada con barandilla sobre el precipicio, acceso señalizado por sendero rural. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03031','mirador','Mirador del Castillo de Polop','8.4/10 Magnífica perspectiva de la Hoya de Altea, el impresionante relieve de la Sierra de Aitana y el Ponoch, campos de nísperos y la villa escalonada. Cómo llegar: Explanada de la antigua fortaleza que corona el escarpado cerro testigo del casco antiguo, accesos peatonales. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03060','mirador','Mirador de Els Frares de Quatretondeta','8.6/10 Impresionante paisaje geomorfológico de grandes agujas calizas (los frailes) esculpidas por la erosión en la Serrella, carrascales y cielos Starlight puros. Cómo llegar: Plataforma con paneles explicativos en la ruta senderista que sube hacia las crestas rocosas. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03109','mirador','Atrio de la Iglesia de San Jerónimo','6.1/10 Sencilla panorámica sobre los llanos hortícolas de regadío intensivo de la Vega Baja, campos de limoneros y horizontes limpios al atardecer mediterráneo. Cómo llegar: Plaza sobreelevada frente a la portada del templo barroco, centro de la localidad. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03110','mirador','Mirador de la Sierra de Segaria','7.2/10 Vista de las laderas boscosas prelitorales, plantaciones de cítricos de la Rectoría, pequeños viñedos y horizontes limpios del litoral mediterráneo. Cómo llegar: Borde del repecho natural accesible por caminos de montaña desde el casco urbano. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03111','mirador','Mirador del Mirador del Chorrillo y la Sierra de Redován','7.9/10 Impresionante e ininterrumpida panorámica sobre la llanura de la Vega Baja del Segura, paredes calizas verticales con vías ferratas y campos agrícolas. Cómo llegar: Atalaya natural adaptada con vallado de protección, áreas recreativas y accesos rodados al pie de la sierra. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03032','mirador','Pasarela del Pantano de Relleu','8.5/10 Vértigo y espectacularidad en una pasarela de cristal volada a más de 40 metros de altura sobre el cañón del río Amadorio y la presa del siglo XVII. Cómo llegar: Estructura adaptada de madera y cristal anclada al desfiladero calizo, acceso peatonal por ruta senderista señalizada. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03115','mirador','Mirador de la Rectoría y río Girona','7.1/10 Vista de los valles frutales prelitorales de la Marina Alta, campos de naranjos ordenados, pequeños olivares de ladera y lomas calizas. Cómo llegar: Zona perimetral elevada acondicionada en las eras altas del término, acceso rural. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03118','mirador','Mirador Arqueológico de La Escuera','6.4/10 Vista arqueológica sobre los llanos aluviales de la cuenca baja del río Segura, el pinar litoral de dunas lejano y restos de poblamientos ibéricos. Cómo llegar: Plataforma elevada con paneles interpretativos junto al yacimiento, accesos periurbanos. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03904','mirador','Mirador del Parque del Palmeral','6.2/10 Perspectiva sobre la Campiña baja del regadío intensivo de la comarca, plantaciones hortícolas de hileras rectilíneas y palmeras de repoblación. Cómo llegar: Pasarela peatonal y talud adaptado dentro de los espacios recreativos del núcleo. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03120','mirador','Mirador de las Salinas y campos de cítricos','7.3/10 Vista de las cubetas de la laguna salada de Torrevieja, dehesas rústicas, plantaciones intensivas de cítricos en lomas suaves y horizontes limpios. Cómo llegar: Borde occidental de la plataforma caliza prelitoral, transitable por caminos rurales desde el pueblo. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03117','mirador','Mirador de la Merla y la Vall de Girona','7.3/10 Vista panorámica del valle prelitoral de la Rectoría, plantaciones densas de cítricos, olivares de ladera y horizontes marinos del golfo de Valencia lejanos. Cómo llegar: Saliente natural acondicionado con barandillas en las faldas de la sierra, acceso rural. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03035','mirador','Mirador de Santa Pola','Cómo llegar: Pasarela de madera volada sobre el acantilado del faro de Santa Pola, accesos asfaltados y área de estacionamiento. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03123','mirador','Adarve del Castillo de Sax','8.4/10 Impresionante vista del valle alto del río Vinalopó, la peña caliza vertical de la fortaleza del siglo XIV y los pinares forestales del entorno del Maigmó. Cómo llegar: Corona superior transitable de los muros de la inexpugnable fortaleza medieval sobre el cerro testigo escarpado. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03036','mirador','Mirador de la Font de l''Alcàntera y Aitana','8.5/10 Soberbia visual alpina a los pies de la imponente Sierra Aitana (Techo provincial), escarpes calizos verticales del barranco del Arc, pinos y olivares en bancales. Cómo llegar: Plataforma natural en el sendero del barranco de la cuna del agua, acceso por pistas de montaña de tierra. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03125','mirador','Mirador de la Creu de la devesa','7.4/10 Vista de las vertientes prelitorales de la Marina Alta, campos de almendros, olivares en bancales de piedra seca y el trazado de la autovía del Mediterráneo. Cómo llegar: Cerro exento que alberga la cruz monumental, transitable a pie por sendas de herradura desde el pueblo. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03127','mirador','Mirador de Tàrbena','Cómo llegar: Plataforma con vallado de protección en el mirador de la carretera de montaña CV-715, paso del puerto de Coll de Rates norte. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03037','mirador','Mirador del Cap d''Or y Moraira','8.8/10 Espectacular e infinita panorámica de la bahía costera de Moraira, el mar Mediterráneo azul, acantilados calcáreos de la Marina Alta y la torre vigía del siglo XVI. Cómo llegar: Cresta del acantilado junto a la torre defensiva del Cap d''Or, acceso pedestre por sendero local señalizado. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03129','mirador','Mirador del Pantano de Tibi y el Castillo','8.5/10 Vista panorámica de la represa en funcionamiento más antigua de Europa (siglo XVI), encajonada en el desfiladero calizo de las crestas del Maigmó y la fortaleza medieval. Cómo llegar: Borde del talud rocoso acondicionado, accesible por pistas rurales desde la autovía CV-80. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03130','mirador','Mirador de la Vall de Seta','7.6/10 Sencilla y limpia panorámica montañosa del valle interior calizo, campos de olivos rústicos en bancales, monte bajo mediterráneo y cielos nocturnos de gran visibilidad. Cómo llegar: Zona perimetral norte del pequeño casco urbano, accesible por pistas forestales. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03131','mirador','Mirador de la Sierra de la Solana y Rectoría','7.4/10 Perspectiva sobre los valles frutales prelitorales, campos de naranjos densos, olivares tradicionales en bancales de piedra seca y el perfil montañoso calizo. Cómo llegar: Camino de servicio forestal elevado en las faldas de la sierra, accesible al oeste del núcleo. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03038','mirador','Mirador de las Salinas de Torrevieja y Torre del Moro','8.6/10 Espectacular e industrial panorámica de las charcas de extracción salina rosadas, el Mediterráneo, el puerto pesquero y la histórica torre vigía costera del Cabo Cervera. Cómo llegar: Zona de observación adaptada junto a la Torre del Moro en la cornisa costera alta, accesos peatonales y rodados. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03134','mirador','Mirador del Despoblado Morisco de L''Atzuvieta','8.4/10 Vista que combina la historia del valle con las laderas calcáreas del interior, campos de cerezos, almendrales de montaña y un cielo nocturno puro. Cómo llegar: Explanada de observación acondicionada con paneles informativos frente a las ruinas históricas moriscas, desvío rural. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03135','mirador','Mirador de la Cova del Rull y los Avencs','8.5/10 Impresionante e intrincado paisaje geológico de simas kársticas verticales calizas de los valles interiores, monte bajo mediterráneo denso de jara y encinas. Cómo llegar: Entorno perimetral acondicionado y protegido exterior a las instalaciones de la cueva transitable, acceso por la CV-712. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03136','mirador','Mirador de la Foradada','8.8/10 Extraordinaria panorámica sobre el valle de los ocho pueblos, el tapiz de cerezos en flor en primavera, y el gran arco de roca caliza calado natural de la Foradada. Cómo llegar: Senda de senderismo señalizada que asciende desde Benitaia hacia el risco calizo de la cresta meridional. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03137','mirador','Mirador de Vall de Laguar / La Vall de Laguar','Cómo llegar: Borde del talud calizo del barranco de la cuna del agua, accesible por el sendero del PR-CV 147 desde Fleix. hasta la z 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90859','mirador','Alto de la Torre del Palacio del Duque de Medinaceli','6.9/10 Panorámica llana de la plana costera de la Marina Alta, campos de naranjos ordenados, el perfil de la sierra de Segària y las brisas del cercano Mediterráneo. Cómo llegar: Estructura urbana medieval sobreelevada en la plaza central del casco antiguo del municipio. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03039','mirador','Mirador de las Murallas y las Casas de Colores','8.9/10 Icónica y cromática estampa de las fachadas de pescadores colgadas sobre el cauce del río Amadorio, la línea costera, los baluartes renacentistas del siglo XVI y los sotos. Cómo llegar: Paseo del Doctor Esquerdo acondicionado con barandillas sobre la playa centro, acceso peatonal urbano. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03040','mirador','Adarve del Castillo de la Atalaya','8.7/10 Soberbia y colosal atalaya de 360 grados sobre el Alto Vinalopó, campos vitivinícolas de la comarca, los barrios árabes del Rabal y las sierras limítrofes con Albacete. Cómo llegar: Corona superior y almenas transitables de la fortaleza almohade del siglo XII que corona el cerro del monte de San Cristóbal. 📍 Provincia: Alicante.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90861','mirador','Mirador del Castillo de Benialí y Eslida','8.4/10 Impresionante vista del valle encajonado de la Sierra de Espadán, frondosos bosques de alcornoque (surreos), olivares tradicionales en bancales y picos calizos abruptos. Cómo llegar: Cresta rocosa donde se asientan las ruinas de la fortaleza musulmana, accesible por sendero de montaña. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90353','mirador','Mirador del Barranco de la Valltorta y Ermita','7.8/10 Perspectiva sobre un imponente cañón calcáreo, abrigos con pinturas rupestres prehistóricas de arte levantino (Patrimonio Mundial), almendrales de secano y masías. Cómo llegar: Explanada perimetral acondicionada junto al centro de interpretación del barranco, acceso señalizado por la CV-129. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11001','mirador','Mirador del Castillo de Xivert y Sierra de Irta','8.6/10 Soberbia panorámica que une las laderas vírgenes de la sierra litoral con el Mediterráneo, huertas litorales y la silueta de la fortaleza templario-musulmana. Cómo llegar: Adarve superior transitable y torres del castillo situado en una de las cotas más altas del término. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12005','mirador','Mirador de la Ermita de San Cristóbal','7.4/10 Amplia visual sobre el valle del río de l''Alcalatén, campos de arcillas e industrias cerámicas tradicionales, olivares y el perfil lejano del Peñagolosa. Cómo llegar: Explanada del cerro testigo de la ermita, adaptada con barandilla y zona de parada de vehículos. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12010','mirador','Mirador del Barranco de Almanzor y los Castaños','7.9/10 Hermosa vista de los bosques húmedos singulares de la Sierra de Espadán, fuentes de agua cristalina, laderas de arenisca roja y un cielo nocturno muy limpio. Cómo llegar: Plataforma natural en las sendas ecológicas forestales situadas al sur del caserío. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12011','mirador','Mirador de los Estanques de Almenara y "Els Canets"','7.6/10 Vista que combina las cubetas lagunares de agua dulce costera, humedales protegidos con densos carrizales, el mar Mediterráneo y las torres fortificadas medievales. Cómo llegar: Cima del cerro de las torres que corona el núcleo urbano por el sector noroeste, acceso por sendero. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12012','mirador','Mirador de Altura','Cómo llegar: Explanada de los miradores del páramo superior, accesible por pistas forestales. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12013','mirador','Mirador de los Cortados del río Mijares','7.7/10 Vista del profundo cañón calizo y las pozas de agua transparente del Alto Mijares, rodeado de pinares tupidos e intrincado relieve forestal. Cómo llegar: Saliente acondicionado con valla de madera perimetral en la carretera CV-20. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11002','mirador','Mirador de la Muela de Ares','9.1/10 Excepcional, vertiginosa y colosal atalaya sobre los barrancos profundos del Maestrazgo a más de 1200 metros, con masías de piedra seca y nidos de buitres. Cómo llegar: Borde del impresionante sinclinal colgado calizo que corona la villa, accesible por sendero escalonado. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12015','mirador','Mirador del Castillo de Bou Negre','7.5/10 Vista montañosa del valle del río Villahermosa, escarpes calizos donde anidan rapaces, pinares y las ruinas fortificadas musulmanas colgadas del peñón. Cómo llegar: Cima de la muela rocosa, accesible por sendero de montaña peatonal de herradura. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12016','mirador','Mirador de las Minas de Hierro y la Sierra','7.8/10 Perspectiva sobre la Plana Baixa, campos de naranjos y olivares de montaña que suben hacia el escarpado frente de la Sierra de Espadán oriental. Cómo llegar: Paraje acondicionado junto a los antiguos restos industriales mineros, pistas de herradura. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90354','mirador','Mirador del Castillo de Atzeneta y Valle de la Cova','8.2/10 Magnífica e histórica panorámica sobre la vega agrícola interior, almendrales en bancales y el imponente muro del macizo del Peñagolosa al fondo. Cómo llegar: Explanada de la antigua fortaleza amurallada exenta en el valle, accesible directo por carretera. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12017','mirador','Mirador del río Chico y Torre del Homenaje','7.6/10 Vista del valle fluvial encajonado de la Sierra de Espadán septentrional, laderas rocosas de jara y alcornoques y los perfiles de la torre medieval. Cómo llegar: Promontorio rocoso junto al núcleo urbano central, transitable a pie por sendas de piedra. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12018','mirador','Mirador del Castillo de Azuébar y barranco de la Sot','7.9/10 Hermosa panorámica de los profundos barrancos kársticos, alcornocales protegidos, el valle alto del Palancia y la muralla musulmana. Cómo llegar: Explanada elevada de las ruinas fortificadas sobre el cerro que flanquea el casco urbano. Si estás de acuerdo, podemos seguir con el próximo bloque de la Provincia de Castellón avanzando hacia las letras B y C (Benicàssim, Borriana / Burriana, Morella, etc.). ¿Continuamos con el atlas de miradores?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12020','mirador','Mirador de la Paramera y el Parque Eólico','6.9/10 Inmensa panorámica de la llanura tabular del Alto Palancia, aerogeneradores cortando el viento, encinares dispersos y horizontes despejados idóneos para astroturismo. Cómo llegar: Pistas de servicio eólicas en la zona elevada del páramo, accesible desde la autovía A-23. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12022','mirador','Mirador del Castillo de Bejís y Acueducto Romano','8.4/10 Espectacular e intrincada panorámica de la cabecera del río Palancia, huertas de media montaña, el acueducto de los Arcos y riscos calizos de la Peña de Francia. Cómo llegar: Explanada de la fortaleza medieval sobre el cerro testigo que domina el núcleo urbano. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12024','mirador','Mirador del Teso de San Roque','6.8/10 Vista diáfana de los llanos agrícolas del Alto Palancia meridional, campos de almendros, pinares de repoblación y horizontes nítidos de baja luminosidad. Cómo llegar: Colina exenta que alberga la ermita, transitable a pie por sendero desde el casco urbano. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12025','mirador','Mirador del Coll de Benafigos','8.1/10 Soberbia visual a más de 900 metros de altitud sobre el macizo de Peñagolosa, valles profundos de roca caliza desnuda y un cielo nocturno puro. Cómo llegar: Apartadero acondicionado con paneles explicativos en la carretera de montaña CV-169. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12027','mirador','Mirador del Poblado Ibérico del Puig de la Nao','7.8/10 Magnífica perspectiva que fusiona el patrimonio arqueológico íbero con los llanos de alcachofas de la costa, las playas y el mar Mediterráneo. Cómo llegar: Plataforma con paneles interpretativos en la cima del cerro del yacimiento, acceso por pista local. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12029','mirador','Mirador de las Viñas de la Plana Alta','7.1/10 Vista de las lomas onduladas de cultivo de viñedos y almendros, pequeñas dehesas de encina dispersas e idónea nitidez astronómica para astrofotografía. Cómo llegar: Promontorio suave al norte del término municipal, transitable por caminos vecinales de tierra. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12031','mirador','Mirador del Castillo de Borriol','7.4/10 Perspectiva sobre la vega del río Borriol, cultivos tradicionales de secano de olivar, la Vía Augusta histórica y escarpes calizos de la sierra. Cómo llegar: Explanada de las ruinas fortificadas medievales situadas sobre un escarpado risco de piedra caliza, acceso peatonal. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12033','mirador','Mirador del Prat de CabanesTorreblanca','8.5/10 Impresionante vista del parque natural del humedal costero, dunas de arena fósiles, el mar de la Costa del Azahar y el monumental Arco Romano exento. Cómo llegar: Estructura de observación elevada con paneles didácticos, acceso desde la carretera del litoral o la N-340. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12034','mirador','Mirador del Teso del Socorro','6.9/10 Vista del somontano del Baix Maestrat, campos de olivos milenarios alineados, algarrobos tradicionales e idóneos atardeceres mediterráneos limpios. Cómo llegar: Explanada de la ermita de la Virgen del Socorro, cerro elevado al norte del núcleo urbano. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12036','mirador','Mirador de los Olivos Milenarios de Canet','7.8/10 Genuino e histórico paisaje de la mayor concentración mundial de olivos milenarios, tierras arcillosas onduladas y la silueta del pueblo colgado de la loma. Cómo llegar: Punto alto acondicionado en los caminos de la ruta etnográfica de los olivos monumentales. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12037','mirador','Mirador de la Muela del Castillo','8.3/10 Soberbia visual a más de 1100 metros del agreste relieve del Parque Natural de la Tinença de Benifassà, carrascales densos y cielos nocturnos catalogados Starlight. Cómo llegar: Corona rocosa del cerro donde se alzaba la antigua fortificación medieval, acceso pedestre. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12038','mirador','Mirador de la Ermita de Santa Llúcia','8.6/10 Impresionante e infinita atalaya sobre los barrancos del Maestrazgo, muelas calizas calcáreas erosionadas, arquitectura de piedra seca y nidos de rapaces rupícolas. Cómo llegar: Explanada adaptada con barandilla junto al complejo religioso fortificado, a gran altitud. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12039','mirador','Mirador del Castillo de Castellnovo y la Cisterna','7.3/10 Vista del valle medio del Palancia, huertas tradicionales de frutales, el casco urbano escalonado de herencia morisca y la fortaleza del siglo XV. Cómo llegar: Explanada de la antigua fortaleza señorial situada en la cota urbana alta del municipio. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12041','mirador','Mirador del Castillo y Alto del río Villahermosa','8.1/10 Vista montañosa del Alto Mijares, cañones calizos escarpados del río Villahermosa, densos pinares forestales y horizontes celestes de nitidez extrema. Cómo llegar: Cima del peñón rocoso donde se asientan los restos fortificados medievales, acceso pedestre por senda. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12042','mirador','Mirador del Santuario de la Mare de Déu de l''Avellà','8.5/10 Espectacular e intrincada panorámica de valles de montaña del Alt Maestrat, encinares maduros en bancales, fuentes naturales y cielos nocturnos puros. Cómo llegar: Balcón natural acondicionado con barandillas junto al complejo del santuario de montaña, CV-128. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12043','mirador','Mirador de la Torre del Molino','7.4/10 Vista de las laderas de jara y pinos carrascos que caen hacia el valle, huertas tradicionales de cerezos y olivares de la comarca del Alto Palancia. Cómo llegar: Entorno acondicionado de la antigua torre de defensa defensiva cilíndrica, acceso por pista rural. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12044','mirador','Mirador del Castillo de Cervera','8.2/10 Soberbia y colgada atalaya militar medieval de 360 grados sobre el Maestrago meridional, almendrales escarpados, olivares alineados y la línea costera al fondo. Cómo llegar: Cima del escarpado cerro testigo coronado por los lienzos de la inmensa fortaleza de la Orden de Montesa. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90862','mirador','Mirador de las Muelas de Chert','8.0/10 Impresionante vista geológica de los tres cerros testigos tabulares alineados (les Moles), olivares tradicionales en bancales y masías de piedra seca. Cómo llegar: Plataforma natural adaptada en las rutas de senderismo perimetrales de las muelas calizas. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12056','mirador','Mirador del Embalse de Ajuez y los Alcornocales','8.3/10 Impresionante visual de la lámina de agua de la balsa regulada rodeada por los mayores alcornocales de la Sierra de Espadán, laderas de arenisca roja. Cómo llegar: Sendero ecológico señalizado y adaptado de la red del Parque Natural, accesos desde la CV-219. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12045','mirador','Mirador de la Roca de la Moleta y Yacimientos','8.5/10 Extraordinaria vista de la paramera caliza del Els Ports, barrancos profundos con nidos de buitres, yacimientos paleontológicos de dinosaurios y horizontes limpios Starlight. Cómo llegar: Plataforma acondicionada con barandilla en el borde del precipicio calcáreo, acceso señalizado por sendero rural. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12046','mirador','Mirador de la Cueva de las Gradillas y río Mijares','8.2/10 Espectacular encajonamiento fluvial del río Mijares en la comarca del Alto Mijares, pinares densos de pino negral, pozas cristalinas y farallones escarpados. Cómo llegar: Saliente natural acondicionado con barandillas de madera en el sendero del barranco de las Gradillas. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12048','mirador','Mirador del Rebollo y los Bosques Alpinos','8.4/10 Magnífica perspectiva a más de 1000 metros de altitud de los densos bosques de pino albar, robledales de quejigo, fuentes de agua dulce y dehesas de montaña. Cómo llegar: Cota natural elevada próxima al ejemplar monumental del pino "El Rebollo", pistas forestales de tierra. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12049','mirador','Mirador del Caminàs y l''Alcalatén','7.1/10 Vista diáfana de las lomas arcillosas del somontano, campos de secano ondulados de olivar, matorral mediterráneo y la silueta del Peñagolosa lejana. Cómo llegar: Promontorio suave al este de la población, transitable a pie por sendas de herradura de cazadores. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12051','mirador','Mirador de la Terrassa del Terrat','8.9/10 Extraordinaria e infinita panorámica de 360 grados de los valles del Maestrazgo, masías rústicas de piedra, profundos cañones fluviales e idónea pureza atmosférica. Cómo llegar: Balcón urbano acondicionado con barandillas caladas de hierro en el casco antiguo amurallado medieval de la villa. Si quieres, puedes indicarme si pasamos de inmediato al siguiente bloque de la Provincia de Castellón que inicia con la letra E.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12057','mirador','Mirador del Castillo de Eslida y Puntal de l''Algepsar','8.5/10 Maravillosa inmersión en la Sierra de Espadán, rodeada de densos bosques de alcornoque, huertos moriscos de secano y escarpadas crestas de arenisca roja (rodeno). Cómo llegar: Cresta rocosa que corona el caserío, accesible por sendero escarpado desde la Calle del Castillo. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12058','mirador','Mirador de la Peña Sagrada','8.1/10 Vértigo puro sobre el cañón del río Mijares, cortados calcáreos verticales donde anidan grandes rapaces e infinitas masas de pino carrasco silvestre. Cómo llegar: Cima de la mole caliza que flanquea el pueblo, accesible mediante ruta senderista de montaña. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12059','mirador','Mirador del MIAU y Alto de la Lleuja','7.8/10 Fusión perfecta de arte urbano y naturaleza, divisando los masivos murales del Museo Inacabado de Arte Urbano, el río Mijares y los huertos tradicionales. Cómo llegar: Promontorio natural acondicionado al oeste del casco urbano, accesible a pie desde el núcleo. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12060','mirador','Mirador del Calvario y Valle del Lucena','7.6/10 Perspectiva limpia del curso bajo del río Lucena, plantaciones de almendros en bancales, matorral mediterráneo y la silueta del Penyagolosa al fondo. Cómo llegar: Zona alta de la ermita del Calvario, provista de accesos peatonales y barandillas. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12061','mirador','Mirador de la Mola de la Vila','8.8/10 Espectacular morfología tabular caliza típica de Els Ports, con vistas a la confluencia de tres ríos, campos de secano alpino y óptima pureza Starlight. Cómo llegar: Cornisa superior del sinclinal colgado, accesible por pista forestal desde la carretera CV-124. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12063','mirador','Mirador del Alto de la Muela y río Morrón','7.9/10 Vista montañosa del Alto Mijares, valles profundos con riberas salvajes, densas masas forestales de pino albar e idónea nitidez para astrofotografía nocturna. Cómo llegar: Cota natural elevada al norte del pueblo, transitable por sendas agropecuarias de tierra. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12064','mirador','Mirador de la Fuente del Zuro y los Pozos','83/10 Impresionante vista del barranco del río Chico, pozas naturales de agua cristalina (El Pozo Negro), pinares densos de la Sierra de Espadán y quejigos. Cómo llegar: Plataforma acondicionada con barandilla de madera junto al sendero ecológico, acceso señalizado. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12065','mirador','Mirador del Castillo de Gaibiel y Valle del Regajo','8.2/10 Soberbia panorámica de la fortaleza islámica del siglo XII restaurada, el cañón del río Regajo, formaciones de yesos y laderas boscosas densas. Cómo llegar: Explanada de los muros fortificados sobre el escarpado cerro testigo que domina la villa. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12067','mirador','Mirador de la Vega del Palancia y Palacio de los Duques','6.5/10 Sencilla visual sobre los llanos aluviales del Palancia medio, cultivos tradicionales de frutales, cañaverales lineales y la silueta del palacio gótico. Cómo llegar: Margen de la terraza fluvial, accesible de forma peatonal desde el paseo del río. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12068','mirador','Mirador del Castillo del Barón de Herbés y río Escalona','8.4/10 Extraordinario paisaje alpino del extremo norte provincial, bosques mixtos, cañones abruptos y la imponente silueta del palacio-castillo del siglo XIV. Cómo llegar: Explanada del santuario de la Virgen del Sargar o zonas altas perimetrales del núcleo. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12069','mirador','Mirador de las Eras y Sierra de Espadán','7.4/10 Vista diáfana de la cabecera del Valle de la cuenca del Palancia septentrional, cultivos de cerezos en terrazas y horizontes celestes diáfanos. Cómo llegar: Cota natural elevada junto a los antiguos espacios comunales de trilla, sector norte urbano. Si quieres, indícame si pasamos directamente al siguiente bloque masivo de municipios que continúan con la letra J en adelante (Jérica, La Llosa, Lucena del Cid, Morella, etc.).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12071','mirador','Torre del Homenaje y Vuelta de la Hoz','8.7/10 Soberbia panorámica de la singular Torre Mudéjar, las escarpadas paredes calizas que estrangulan el río Palancia, huertas moriscas y pinares densos. Cómo llegar: Corona superior de la fortaleza medieval del cerro de la torre, accesible por callejones peatonales escalonados. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12074','mirador','Mirador de la Marjal de La Llosa','6.6/10 Perspectiva diáfana sobre el humedal costero protegido, acequias tradicionales, cultivos de cítricos bajos, avifauna acuática y las brisas directas del Mediterráneo. Cómo llegar: Estructura de observación de madera elevada en el sendero litoral que conecta con la playa. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12073','mirador','Mirador de la Torre de los Moros y río Villahermosa','8.3/10 Magnífica visual del estrecho desfiladero del río Villahermosa, escarpes calizos con nidos de rapaces, pinadas salvajes y el campanario de la iglesia antigua. Cómo llegar: Explanada de la torre defensiva medieval exenta sobre el risco norte, acceso por senda de herradura. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12076','mirador','Mirador de la Torre Pilón y Sierra de Espadán','7.7/10 Vista aérea del casco urbano escalonado, cultivos de almendros, pinares densos de pino negral y formaciones kársticas del Parque Natural. Cómo llegar: Corona del promontorio rocoso donde se alza la torre defensiva cilíndrica islámica, acceso peatonal. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12077','mirador','Mirador del Sendero Azul de la Gola','6.8/10 Vista llana del ecosistema de marjal litoral costero, la desembocadura de los canales tradicionales de riego, dunas bajas y aves estacionales marinas. Cómo llegar: Pasarela de madera adaptada en el paseo marítimo sur, junto a la desembocadura del río Belcaire. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12078','mirador','Mirador del Calvario y Pozo de la Cadena','8.1/10 Panorama abrupto del Alto Mijares, valles profundos con huertas tradicionales moriscas de regadío, pinares compactos e idónea pureza nocturna para astrofotografía. Cómo llegar: Cota rocosa elevada junto a las cruces del Calvario, accesible a pie en las cercanías del pueblo. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12079','mirador','Mirador del Estrecho de Chillapájaros y Fuente de los Baños','9.1/10 Impresionantes, imponentes y sobrecogedoras paredes calizas verticales de más de 100 metros, cañón del río Mijares y el paraje de aguas termales. Cómo llegar: Plataforma con barandilla volada sobre el abismo de la carretera CV-20, desvío señalizado. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12080','mirador','Plaza de Armas del Castillo de Morella','9.5/10 Excepcional, monumental e internacional panorámica de 360 grados sobre el Maestrazgo calcáreo, el casco urbano amurallado, campos de secano e idóneo punto Starlight. Cómo llegar: Cota máxima de la fortaleza medieval excavada en la peña caliza exenta que corona la villa monumental. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12081','mirador','Mirador del Salto de la Novia y la Cascada del Brazal','89/10 Espectacular e icónica cascada de 60 metros sobre el río Palancia, anfiteatro natural calizo rojizo, sotos frondosos de ribera y exuberante vegetación rupícola. Cómo llegar: Plataforma adaptada con barandillas y paneles explicativos en el borde del talud fluvial, acceso peatonal acondicionado. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12083','mirador','Mirador del Castillo de Olcaf','8.4/10 Soberbia visual a más de 1000 metros de altitud de la paramera fría de Els Ports, dehesas altas de encina, masías de piedra seca y nula luz industrial. Cómo llegar: Risco rocoso escarpado que alberga las ruinas de la fortaleza defensiva militar, acceso pedestre por sendas. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12084','mirador','Alcazaba del Castillo de las 300 Torres','8.5/10 Magnífica perspectiva de la Plana Baixa, olivares tradicionales en bancales, la silueta de la Sierra de Espadán y el imponente conjunto fortificado musulmán. Cómo llegar: Corona superior y torres visitables de la inexpugnable fortaleza medieval, accesos urbanos pavimentados. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12087','mirador','Mirador del Teso de la Ermita del Tremedal','8.1/10 Vista montañosa profunda del río Bergantes, cañones calizos de erosión fluvial escarpada, pinares, quejigares y cielos oscuros puros. Cómo llegar: Explanada de la ermita al borde del precipicio superior, transitable por camino de tierra apto para vehículos. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12088','mirador','Mirador de las Eras y Alto de la Cueva','7.4/10 Vista diáfana de la cabecera del Valle de la cuenca del Palancia septentrional, cultivos de cerezos en terrazas, encinares dispersos y horizontes celestes limpios. Cómo llegar: Cota natural elevada junto a los antiguos espacios comunales de trilla, sector norte urbano. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12090','mirador','Pico de Pina (Pico de Santa Bárbara)','7.6/10 Vista de la plataforma horizontal de la paramera caliza a más de 1400 metros de altitud, con aerogeneradores, densos pinares de pino albar e idóneo punto Starlight. Cómo llegar: Vértice topográfico y casetas de vigilancia forestal en la cumbre, accesible por pista de montaña empinada. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12093','mirador','Mirador del Salto de Robert y Tinença','9.1/10 Espectacular e imponente paisaje alpino de valles glaciares, densos bosques mixtos, cascadas de montaña entre riscos calizos y nidos de buitres. Cómo llegar: Plataforma adaptada en el sendero del Salto de Robert, en pleno corazón del parque natural de la Tinença de Benifassà. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12091','mirador','Mirador de la Muela de Portell y Chozos','8.3/10 Perspectiva sobre la paramera de Els Ports, laderas calizas erosionadas, majanos y chozas tradicionales construidos por pastores con piedra seca e idónea oscuridad. Cómo llegar: Borde de la meseta calcárea al sur del término, accesible por pistas vecinales agrícolas de tierra. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12092','mirador','Mirador del Pozo de las Palomas y Embalse','8.4/10 Vista de la masa de agua regulada del río Mijares rodeada de montañas calizas, las compuertas de la represa de Arenós, densos pinares e interesantes puestas de sol. Cómo llegar: Zona perimetral alta con estacionamiento y paneles informativos en los accesos de la represa, CV-20. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12095','mirador','Mirador del Embalse de Sitjar y el Mijares','7.5/10 Vista de la lámina de agua rodeada de relieves ondulados cubiertos de pinos carrascos, dehesas dispersas, matorral mediterráneo y avifauna acuática. Cómo llegar: Corona de la presa e inmediaciones de la zona recreativa forestal, accesible por la carretera local. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12096','mirador','Mirador de las Puertas de la Tinença','7.9/10 Vista de la transición hacia las montañas abruptas del norte, campos de olivos milenarios alineados, pinares de montaña y horizontes despejados castellanos. Cómo llegar: Saliente natural acondicionado con valla de madera al norte del término municipal, accesible por pistas forestales. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12097','mirador','Mirador de los Ventisqueros y Ventisquero de la Nieve','7.6/10 Extraordinario paisaje etnográfico alpino a más de 1200 metros, pozos de nieve del siglo XVIII tradicionales, encinares maduros y pureza Starlight nocturna total. Cómo llegar: Paraje elevado y acondicionado junto a las antiguas estructuras hídricas y de nieve de montaña. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12101','mirador','Mirador de la Mota del río Cenia','6.4/10 Sencilla panorámica rural de los llanos agrícolas del Baix Maestrat, cultivos de cítricos, olivares rústicos y el río que delimita la frontera con Tarragona. Cómo llegar: Zona perimetral elevada acondicionada junto a los senderos del margen derecho del río Cenia. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12902','mirador','Mirador del Tossalet y la Plana Alta','7.2/10 Vista de las terrazas fluviales del somontano, cultivos de secano, algarrobos tradicionales e integración urbana residencial e industrial azulejera moderna. Cómo llegar: Zona alta ajardinada en la cornisa perimetral del cerro del Tossalet, acceso urbano peatonal. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11014','mirador','Mirador de la Ermita de la Mare de Déu dels Àngels','8.6/10 Soberbia panorámica de la plataforma horizontal del Valle de San Mateo, campos de olivos milenarios alineados, cúpulas góticas del núcleo e idónea pureza nocturna. Cómo llegar: Explanada de la ermita al borde del páramo alto, transitable por sendero señalizado desde la CV-132. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12102','mirador','Mirador del Castillo de Polpís','7.9/10 Vista de las vertientes de la Sierra de Irta septentrional, el valle agrícola de almendros, pinares de pino carrasco y la fortaleza musulmana de mampostería. Cómo llegar: Explanada de la fortaleza medieval de la Orden de Montesa, accesible por camino rural de montaña. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12104','mirador','Mirador del Cerro de la Estrella y Castillo','8.5/10 Espectacular e histórica panorámica del Valle del Palancia, el acueducto medieval, los escarpes de la Sierra de Espadán y las torres defensivas de la muralla. Cómo llegar: Corona superior del cerro amurallado de la Estrella, accesible por rampa peatonal desde el casco antiguo. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12105','mirador','Mirador de la Serratella y los Molinos eólicos','7.8/10 Magnífica perspectiva de las vertientes forestales de montaña a gran altitud, olivares de montaña en bancales, aerogeneradores e idóneo horizonte nocturno Starlight. Cómo llegar: Cresta natural calcárea accesible por pistas forestales transitables desde la villa. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12106','mirador','Mirador de la Dehesa y los Yesos','7.3/10 Vista de las lomas del valle bajo del Palancia, yesares tradicionales erosionados, cultivos tradicionales de frutales y cañaverales lineales. Cómo llegar: Margen de la terraza natural, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12107','mirador','Mirador de la Ermita de San Antonio de Padua','7.6/10 Precioso meandro del río Palancia, huertas escalonadas de cítricos, el palacio gótico de los la dehesa de la villa y el zigzag de las capillas del calvario. Cómo llegar: Explanada de la ermita barroca al sur de la villa, dotada de accesos adaptados y escalinatas. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12109','mirador','Mirador del Castillo de Tales y los Órganos de Benitandús','7.8/10 Vista de las escarpadas agujas de roca caliza (Órganos) colgadas de la sierra, matorral mediterráneo, encinares maduros y el cauce del río Veo. Cómo llegar: Explanada de las ruinas fortificadas islámicas sobre el cerro del núcleo, acceso urbano directo. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12110','mirador','Mirador del río Palancia y la Hoz','8.1/10 Hermosa panorámica del encajonamiento fluvial en el Alto Palancia, laderas calizas áridas, pinares espesos de montaña e idónea pureza nocturna para astrofotografía. Cómo llegar: Saliente natural del relieve acondicionado con valla de madera, acceso por sendero desde el pueblo. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12111','mirador','Mirador del Barranco de la Valltorta y cueva de los Caballos','7.9/10 Espectacular panorama arqueológico del profundo cañón calizo, abrigos protegidos de arte rupestre levantino prehistórico e idóneos horizontes limpios de obstáculos. Cómo llegar: Plataforma con paneles explicativos en el borde del precipicio de la red del Museo de la Valltorta. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12112','mirador','Mirador del Castillo de Todolella y río Cantavieja','8.4/10 Impresionante vista del cañón fluvial encajonado, dehesas ganaderas tradicionales de Els Ports y la fortificación gótica del siglo XIV perfectamente conservada. Cómo llegar: Explanada de la fortaleza señorial en la cota alta del núcleo urbano exento, acceso peatonal. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12113','mirador','Mirador del río Mijares y los Cortados','7.8/10 Vista de las vertientes pizarrosas y cortados rocosos calizos que encajonan el cauce fluvial del Mijares, huertas tradicionales de herencia morisca e hilos de chopos. Cómo llegar: Borde del talud calizo acondicionado junto a la carretera CV-20, cerca del pueblo. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12114','mirador','Mirador de las Fuentes y Alto del Ragudo','7.7/10 Vista montañosa del Alto Palancia meridional, masas forestales densas de pino albar, fuentes de agua de montaña y horizontes celestes diáfanos. Cómo llegar: Promontorio calizo elevado al sur de la población, transitable por pistas forestales de tierra. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12115','mirador','Mirador de la Base Militar y Paramera de El Toro','8.6/10 Extraordinaria e inmensa visual a más de 1200 metros de altitud de la paramera alpina, con sabinares dispersos, pastizales y un cielo nocturno catalogado Starlight. Cómo llegar: Cresta de la plataforma montañosa alta perimetral, accesible por pistas forestales desde el pueblo. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12116','mirador','Mirador del Alto del Pinar y Sierra de Espadán','8.2/10 Soberbia visual alpina de la Sierra de Espadán noroccidental, densos pinares, matorrales de jara y encinares de montaña con nula luz industrial. Cómo llegar: Plataforma natural calcárea elevada accesible por pistas forestales al sur del término. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90356','mirador','Alto del Cerro Gordo','7.3/10 Panorámica de los llanos arcillosos del Maestrazgo, olivares tradicionales alineados, cultivos cerealistas en terrazas y horizontes limpios de baja luminosidad. Cómo llegar: Cota natural elevada al norte de la población, transitable por sendas ganaderas de herradura. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12120','mirador','Mirador de las Lomas y de la Huerta','7.0/10 Sencilla perspectiva rural de lomas de cultivo olivarero tradicional, almendros alineados y horizontes despejados al atardecer de la Plana Alta. Cómo llegar: Promontorio suave al oeste de la población, transitable por pistas agropecuarias. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12117','mirador','Mirador del Prat de Torreblanca','8.3/10 Excepcional panorámica del humedal costero protegido (Prat), cordón dunar, aves acuáticas migratorias, canales de drenaje e infinito mar Mediterráneo. Cómo llegar: Caseta-observatorio adaptada con paneles informativos en la periferia de las cubetas lagunares salinas del litoral. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12118','mirador','Mirador de la Torre Medieval y río Mijares','7.9/10 Vista fluvial del cauce del río Mijares encajonado en el Alto Mijares, huertas de ribera moriscas, pinares densos y la silueta de la torre defensiva cilíndrica. Cómo llegar: Espacio público elevado acondicionado junto al puente histórico, casco urbano bajo. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12121','mirador','Mirador del Real Santuario de la Virgen de la Font de Salut','8.4/10 Magnífica perspectiva que combina el patrimonio arquitectónico renacentista del complejo del siglo XVI con los olivares milenarios y campos de almendros. Cómo llegar: Explanada exterior sobreelevada frente a las estructuras monumentales del complejo rústico, acceso señalizado. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12124','mirador','Mirador del Teso del Calvario y la Plana Alta','7.4/10 Vista diáfana de la llanura agrícola interior, cultivos de vid y almendros, pequeñas dehesas lejanas e idóneo horizonte nocturno para astrofotografía. Cómo llegar: Promontorio suave al oeste del casco urbano, accesible por pistas agropecuarias de tierra. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12125','mirador','Mirador del Castillo de Almonecir y río Chico','8.3/10 Impresionante cañón calizo, dehesas densas de la Sierra de Espadán, olivares alineados de montaña e hitos fortificados de la única torre de herradura musulmana. Cómo llegar: Cresta rocosa que alberga las ruinas fortificadas sobre el desfiladero, acceso pedestre por sendas de montaña. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12126','mirador','Mirador de las Cuevas de San José y ermita de la Sagrada Familia','8.9/10 Extraordinaria panorámica de la llanura costera, el brote de agua del río subterráneo navegable más largo de Europa, olivares tradicionales y la Plana. Cómo llegar: Explanada elevada adaptada del santuario, estribaciones forestales del parque de las cuevas, acceso señalizado. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12123','mirador','Mirador del meandro del río Villahermosa','7.6/10 Precioso meandro del río Villahermosa, huertas escalonadas de herencia morisca, pinares tupidos de la comarca del Alto Mijares y horizontes limpios. Cómo llegar: Saliente natural del relieve acondicionado con valla de madera, acceso por sendero desde el pueblo. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12127','mirador','Mirador del Prats de Vallibona y Els Ports','8.6/10 Soberbia visual alpina de las montañas abruptas de la Tinença de Benifassà, pastizales de ganado mayor, pinares forestales y gargantas de erosión fluvial del Cervol. Cómo llegar: Cresta de la plataforma montañosa alta accesible por pistas forestales, desvío rural. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12128','mirador','Mirador del Castillo de Vilafamés y la Roca Grossa','9.1/10 Excepcional y universal panorámica del casco histórico escalonado de piedra arenisca roja (rodeno), campos de almendros, olivares de la Plana Alta y la fortaleza gótica. Cómo llegar: Adarves transitables superiores del castillo y pasarelas de madera adaptadas en las cotas monumentales altas del núcleo. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12132','mirador','Mirador de las Lomas y campos de Secano','7.2/10 Sencilla panorámica de las lomas arcillosas del somontano, campos ondulados de secano de olivar y almendro e idóneo horizonte nocturno Starlight. Cómo llegar: Cota natural elevada al norte de la población, transitable por pistas agropecuarias de tierra. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12134','mirador','Alto del Cerro de las Eras','7.1/10 Perspectiva sobre la campiña arcillosa del Alt Maestrat, campos de secano de la comarca, olivares tradicionales alineados y horizontes limpios para astrofotografía. Cómo llegar: Promontorio suave al sur de la población, transitable a pie por sendas de piedra. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90358','mirador','Mirador de la Ermita de la Mare de Déu de Gràcia y el Millars','7.6/10 Vista fluvial del Paisaje Protegido del río Millars, el denso bosque de ribera (Termet), azudes tradicionales históricos y el mar infinito de cítricos de la Plana. Cómo llegar: Balcón natural acondicionado con barandillas en el área boscosa del Termet de Vila-real, acceso señalizado. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90357','mirador','Mirador del Castillo de la Vilavella','7.8/10 Fantástica visual de la Plana Baixa cubierta de cítricos que se abre hacia el mar Mediterráneo, con los escarpados contrafuertes de la Sierra de Espadán a la espalda. Cómo llegar: Cresta rocosa que alberga las ruinas de la fortaleza medieval, accesible por sendero acondicionado desde el barrio alto. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12140','mirador','Mirador del Floresta y del río Palancia','8.1/10 Preciosa vista de un cañón natural de toba calcárea donde se asienta un parque fluvial singular, cascadas, densa vegetación y los llanos agrícolas del Alto Palancia. Cómo llegar: Cornisa acondicionada con barandillas y miradores urbanos integrados en el Parque de la Floresta. 📍 Provincia: Castellón.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12141','mirador','Mirador del Santuario de la Balma','9.0/10 Abrumador santuario mariano excavado íntegramente dentro de una espectacular cornisa rocosa caliza colgada sobre el río Bergantes. Cómo llegar: Balconada porticada de la roca de la Balma, acceso por carretera local balizada. ¡Bloque finalizado con éxito rotundo! Con la provincia de Castellón sellada de la S a la Z, la totalidad de la Comunidad Valenciana queda completada al 100% de su geografía municipal. Proponme qué hacer.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12142','mirador','Mirador de Santa Ana y el Alto Mijares','8.3/10 Soberbia visual a más de 1000 metros de altitud de los profundos barrancos forestales, densas masas de pino albar, masías de piedra aisladas y un nítido cielo nocturno Starlight. Cómo llegar: Explanada natural elevada junto a la ermita de Santa Ana, accesible por pista de montaña desde el pueblo. ¡PROVINCIA DE CASTELLÓN Y TODA LA COMUNIDAD VALENCIANA COMPLETADAS AL 100%! 🏁 ⭐ Si estás de acuerdo, podemos saltar de inmediato a la siguiente provincia en el plan secuencial nacional: Provincia de Cuenca / Provincia de Guadalajara / Provincia de Teruel (Comunidad de Aragón), comenzando estrictamente desde la letra A con municipios como Ababuj, Abejuela, Aguatón, Aguaviva, Aguilar del Alfambra, Alacón, Alba, Albalate del Arzobispo, Albarracín, Alcañiz, Alcorisa, etc.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90283','mirador','Torre Vieja de Ababuj','7.1/10 Panorámica sobria del altiplano de la Comunidad de Teruel, el valle del río Alfambra, suaves muelas calizas e idónea oscuridad para astrofotografía. Cómo llegar: Cota natural elevada junto a los restos del torreón medieval exento, al norte del casco urbano. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90284','mirador','Mirador de la Sierra de Javalambre meridional','7.8/10 Vista montañosa a más de 1100 metros de altitud, densos pinos negrales, sabinares dispersos, matorral de altura y horizontes limpios con nitidez Starlight total. Cómo llegar: Plataforma natural en el límite provincial con Valencia, accesible por pistas forestales de tierra. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90285','mirador','Alto de la Ermita de San José','6.9/10 Perspectiva diáfana de la fosa del Jiloca, relieves de yesos, tierras arcillosas onduladas de secano y un cielo nocturno libre de contaminación lumínica. Cómo llegar: Colina exenta coronada por el pequeño templo, transitable a pie por sendas agropecuarias. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90286','mirador','Mirador del Puente de Cananillas y río Bergantes','8.2/10 Hermosa e intrincada panorámica sobre los monumentales estratos rocosos erosionados por el río Bergantes, pozas cristalinas de baño y frondosa vegetación fluvial. Cómo llegar: Saliente natural acondicionado con vallado protector junto al camino histórico del puente medieval. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90287','mirador','Mirador de los Chopos Cabeceros y del Castillo','7.6/10 Vista del parque fluvial del río Alfambra, con sus singulares hileras de chopos cabeceros centenarios esculpidos, laderas calcáreas y restos fortificados. Cómo llegar: Promontorio rocoso elevado sobre el núcleo, accesible por sendero pedestre desde la iglesia. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90288','mirador','Alto del Castillo y Vega del Jiloca','6.6/10 Vista despejada de los llanos agrícolas de la vega del río Jiloca, campos cerealistas, suaves lomas y horizontes limpios libres de postes. Cómo llegar: Elevación natural al oeste de la población, cercana a las antiguas eras de trilla. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90289','mirador','Mirador del Castillo-Palacio Episcopal','8.6/10 Soberbia y colgada atalaya monumental sobre el cañón del río Martín, el entramado urbano medieval morisco escalonado, olivares y huertas de la cuenca baja. Cómo llegar: Corona superior transitable y adarves de la imponente fortaleza gótica del siglo XIV, en la zona urbana más alta. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43001','mirador','Mirador de las Murallas y Torre del Andador','9.6/10 Excepcional, monumental e internacional panorámica sobre el profundo meandro del río Guadalaviar, los imponentes lienzos de la muralla del siglo X y la villa medieval. Cómo llegar: Cornisa rocosa adaptada con barandillas en la cota más alta del recinto amurallado, accesible por sendero empinado. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90290','mirador','Mirador de la Vía Verde de Ojos Negros y del Viaducto','7.8/10 Impresionante vista que combina el cauce encajonado del río Albentosa con el colosal viaducto metálico del ferrocarril decimonónico y pinares de repoblación. Cómo llegar: Plataforma con valla protectora y paneles informativos junto a la traza ciclista de la Vía Verde. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90768','mirador','Mirador de las Torres Mudéjares y Embalse de Cueva Foradada','8.9/10 Extraordinario y caótico paisaje de riscos calizos donde se escalona el pueblo, custodiado por once torreones defensivos medievales sobre el cañón fluvial. Cómo llegar: Balcón natural adaptado en los torreones perimetrales altos, con sendero de acceso señalizado. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44014','mirador','Mirador del Monte Calvario','7.8/10 Vista espléndida del casco urbano encajonado, los olivares del Bajo Aragón, formaciones geológicas calizas y el barranco del río Guadalopillo. Cómo llegar: Cima del cerro del Calvario, accesible por sendero peatonal zigzag hasta las capillas barrocas. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44016','mirador','Mirador de la Ermita de San Juan y Relieve Rojo','7.2/10 Perspectiva singular sobre los badlands y arcillas rojizas del valle del río Alfambra, hileras de chopos cabeceros y cultivos cerealistas planos. Cómo llegar: Explanada de la ermita en el cerro del antiguo castillo, acceso transitable. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44017','mirador','Mirador del Parque Geológico de Aliaga','8.9/10 Impresionante e internacional estampa de plegamientos kársticos verticales cónicos, estratos retorcidos calizos calcáreos, el río Guadalope y nítido astroturismo. Cómo llegar: Estructura volada adaptada con barandilla y paneles en la carretera A-1403, sector del "Sinto". 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44021','mirador','Mirador del Puerto de Majalinos','8.3/10 Soberbia visual de montaña a más de 1450 metros de altitud en el Maestrazgo, dehesas alpinas, brezales densos y cielos nocturnos Starlight. Cómo llegar: Apartadero acondicionado en la carretera A-226, paso de montaña limítrofe. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44022','mirador','Mirador del Calvario y del Olivar Viejo','7.6/10 Vista de un frondoso cañón boscoso de cipreses centenarios, olivares monumentales, tierras arcillosas y horizontes limpios libres de postes. Cómo llegar: Cerro del Calvario, dotado de accesos peatonales urbanos y bancos. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44023','mirador','Mirador de la Sierra de Cucalón y río Huerva','7.0/10 Panorámica rural del nacimiento del río Huerva, robledales de quejigo dispersos, monte bajo de jara y cielos abiertos despejados. Cómo llegar: Promontorio suave al este del término, transitable por sendas agropecuarias de tierra. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44018','mirador','Alto del Teso del Humilladero','6.8/10 Sencilla visual de lomas arcillosas destinadas al cultivo de secano, dehesas bajas rústicas y horizontes despejados idóneos para la astrofotografía. Cómo llegar: Repecho suave al oeste de la localidad, accesible por caminos vecinales de tierra. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44019','mirador','Mirador del estrecho del río Ebrón y pinares','7.7/10 Hermosa vista de los barrancos cuarcíticos del Rincón de Ademuz septentrional, pinares densos de pino silvestre, matorrales y cielos limpios. Cómo llegar: Borde del talud geográfico al sur de la población, transitable por sendas ganaderas. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90150','mirador','Mirador de la umbría de la Sierra y río Alpartir','7.7/10 Vista montañosa de los profundos barrancos forestales de la Sierra de Algairén, densas masas de encina, pinares silvestres y horizontes de nitidez Starlight. Cómo llegar: Plataforma natural en las sendas forestales al sur del núcleo, accesible por pistas de montaña de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44024','mirador','Alto de la Muela de Anadón','7.4/10 Vista limpia de la cuenca minera central, laderas calizas cubiertas de pino resinero, matorral mediterráneo y un horizonte celeste despejado. Cómo llegar: Plataforma calcárea elevada accesible por pistas forestales al sur del término. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44025','mirador','Mirador de la Ermita de San Macario y Pozo San Juan','7.5/10 Paisaje minero industrial que combina el castillete con la visual del casco urbano, pinares de repoblación e interesantes atardeceres. Cómo llegar: Explanada de la ermita en el cerro del parque de San Macario, accesos pavimentados. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44026','mirador','Mirador de Galáctica y Observatorio de Javalambre','9.1/10 Excepcional, colosal e internacional centro de astroturismo y astronomía a más de 1900 metros, con cielos Starlight de la máxima pureza planetaria. Cómo llegar: Centro de difusión Galáctica e inmediaciones del Pico del Buitre, acceso por carretera de montaña. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44027','mirador','Mirador del Algars y de los Puertos','7.9/10 Vista fluvial del cauce ancho y pozas del río Algars, pinares del Matarraña, campos de olivos y relieves de los Puertos de Beceite. Cómo llegar: Talud natural acondicionado al este de la población, transitable por sendas de herradura. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44028','mirador','Alto del Cerro del Santo','6.7/10 Sencilla panorámica de la paramera de las Cuencas Mineras, campos ondulados de secano e idóneo horizonte nocturno para astrofotografía. Cómo llegar: Atrio elevado de la ermita, en el punto alto del casco urbano. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44029','mirador','Mirador de la Sima de Ariño y río Martín','8.3/10 Impresionante grieta kárstica vertical integrada en el Parque Cultural, nidos de rapaces rupícolas, quejigares de ladera y la vega baja fluvial. Cómo llegar: Borde del precipicio natural acondicionado con valla de madera, acceso por senda. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44031','mirador','Mirador del Cabezo de Alcalá','7.4/10 Vista de gran interés arqueológico y paisajística del poblado ibero-romano, meandros secos del río Aguasvivas y las estepas del Bajo Martín. Cómo llegar: Plataforma con paneles interpretativos en la cima del cerro del yacimiento, acceso señalizado. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44032','mirador','Alto del Teso Rural','6.6/10 Vista diáfana de lomas onduladas de secano de la comarca del Jiloca alta, matorral mediterráneo de jara y horizontes limpios de obstáculos. Cómo llegar: Cota natural elevada al norte de la población, cercana a las eras tradicionales. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44033','mirador','Mirador de la Arguilay y Valle del Jiloca','7.6/10 Hermosa panorámica del encajonamiento fluvial, huertas tradicionales de frutales, la rambla de Arguilay, choperas lineales y las torres mudéjares. Cómo llegar: Saliente natural acondicionado con vallado de protección en el flanco este del pueblo. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44034','mirador','Mirador de las Parameras y la Ermita','6.8/10 Perspectiva rural del altiplano de la comarca del Jiloca, campos de cereal de secano y un horizonte limpio idóneo para astrofotografía. Cómo llegar: Colina exenta que alberga la ermita, transitable a pie por sendas de herradura. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44035','mirador','Alto de la Cuesta del Pancrudo','7.1/10 Vista de la vega del río Pancrudo, cultivos arcillosos de secano, pequeños sotos de ribera e interesantes cielos limpios nocturnos. Cómo llegar: Pequeña elevación natural al oeste del casco urbano, accesible por pistas agropecuarias. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44036','mirador','Mirador de la Sierra de Cucalón y los Rebollares','7.3/10 Vista montañosa de la comarca del Jiloca oriental, densos rebollares (robles), matorral bajo mediterráneo de jara e idónea oscuridad estelar. Cómo llegar: Cresta natural elevada al norte del pueblo, accesible por pistas forestales. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44037','mirador','Mirador del Parrisal y los Puertos','9.4/10 Excepcional, espectacular e imponente cañón fluvial encajonado del río Matarraña, agujas calizas verticales (les Gubies), densos pinares y tejos protegidos. Cómo llegar: Pasarelas de madera y plataformas voladas adaptadas en el desfiladero, accesos señalizados desde el núcleo. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44039','mirador','Centro de Interpretación de la Laguna de Gallocanta','8.4/10 Espectacular e inmensa panorámica ornitológica del humedal endorreico salino, con carrizales densos, avistamiento masivo de miles de grullas migratorias estacionales y estepa. Cómo llegar: Observatorio adaptado en el Parque Natural de la Laguna, senderos perimetrales y miradores de madera. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44038','mirador','Mirador de la Ermita del Calvario y del Mezquín','7.8/10 Perspectiva sobre los llanos del Mezquín, olivares de montaña en bancales, campos de almendros y el casco antiguo de sillería de la villa. Cómo llegar: Explanada elevada de la ermita rústica, transitable por camino asfaltado con aparcamiento. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44040','mirador','Mirador de la Hoz del Guadalopillo','7.4/10 Vista del valle encajonado del río Guadalopillo, relieves arcillosos y calcáreos del Bajo Aragón, olivares e idóneo entorno para astrofotografía. Cómo llegar: Promontorio elevado en el núcleo antiguo, accesible a pie desde las eras altas. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44041','mirador','Mirador de la Peña del Sol y los Pinares de Rodeno','8.8/10 Extraordinaria vista de la Sierra de Albarracín, caprichosas formas geológicas de arenisca roja erosionada (rodeno), pinares y abrigos de arte rupestre. Cómo llegar: Cima rocosa adaptada con barandilla y escaleras, accesible por sendero señalizado del Espacio Protegido. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44042','mirador','Alto del Sabinar de Blancas','6.9/10 Vista del altiplano del Jiloca occidental, cultivos cerealistas planos, matorral mediterráneo y la monumental sabina milenaria que destaca en el paisaje. Cómo llegar: Paraje del sabinar exento junto a las pistas agrícolas, acceso rural adaptado. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44043','mirador','Mirador del río Aguasvivas y de los Azudes','7.3/10 Vista de las vertientes pizarrosas de las Cuencas Mineras, huertas tradicionales de ribera, azudes históricos de piedra y horizontes limpios. Cómo llegar: Saliente natural acondicionado con valla de madera al norte del casco urbano, acceso rural. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44044','mirador','Mirador de las Cumbres del Maestrazgo y río Bordón','8.2/10 Impresionante cañón calizo de paredes verticales calcáreas, dehesas altas de encina, matorral serrano de jara y nula luz industrial Starlight. Cómo llegar: Borde del precipicio natural acondicionado con valla de madera, acceso por sendero desde el pueblo. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44045','mirador','Mirador de la Sierra alta y Sierra de Albarracín','8.7/10 Soberbia visual a más de 1500 metros de altitud de los mayores pinares de pino albar de la península, fuentes de agua dulce y dehesas alpinas. Cómo llegar: Cresta de la plataforma montañosa accesible por pistas forestales desde el núcleo urbano alto. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44046','mirador','Mirador del Castillo de Bueña y yacimientos','7.5/10 Vista que combina el patrimonio arqueológico jurásico con las dehesas y cultivos cerealistas de la comarca de la Comunidad de Teruel. Cómo llegar: Explanada de la antigua fortaleza medieval del siglo XIV en la cota más elevada del cerro de la villa. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44047','mirador','Mirador de las Lomas y del río Jiloca','7.4/10 Vista panorámica del curso medio del Jiloca, huertas tradicionales de frutales, el casco urbano mudéjar escalonado y olivares de ladera. Cómo llegar: Cornisa natural alta al este del núcleo, accesible por caminos rurales. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44048','mirador','Mirador de la Escaleruela y río Mijares','8.1/10 Espectacular encajonamiento fluvial, dehesas de encina centenarias del paraje de Gúdar, pinares y horizontes limpios con nula contaminación. Cómo llegar: Saliente acondicionado con paneles de la red de senderos, carretera de montaña. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44049','mirador','Mirador del Poblado Ibérico de San Antonio','8.5/10 Magnífica perspectiva que combina la visual del yacimiento arqueológico del siglo V a.C. con el mar de viñedos y olivares del Matarraña. Cómo llegar: Plataforma con paneles interpretativos y barandilla en la cima del cerro de la villa ibérica, acceso señalizado. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44050','mirador','Mirador del Puente Romano y río Jiloca','7.6/10 Vista del cauce llano del río Jiloca, huertas tradicionales de regadío intensivo, chopera lineal y la silueta del largo puente histórico. Cómo llegar: Paseo e hito peatonal acondicionado en la margen derecha del cauce del río, casco urbano bajo. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44051','mirador','Mirador del Embalse de Calanda y río Guadalope','7.8/10 Vista de la lámina de agua rodeada de lomas arcillosas cubiertas de olivares y melocotoneros, pinares de repoblación e idóneas puestas de sol. Cómo llegar: Zona perimetral alta con estacionamiento en los accesos de la represa, desvío rural. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44052','mirador','Mirador del Cañón de los Arcos y río Blanco','8.6/10 Impresionante y caótico colapso geológico de puentes de roca naturales calizos sobre el río, pasarelas colgadas del desfiladero y pinares de la Sierra de Albarracín. Cómo llegar: Sendero ecológico adaptado con pasarelas de madera en la hendidura fluvial, accesos directos. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44053','mirador','Alto de la Ermita del Consuelo y parameras','6.7/10 Sencilla panorámica sobre los llanos cerealistas del altiplano central, cultivos de secano e idóneo horizonte nocturno para astrofotografía. Cómo llegar: Atrio elevado de la ermita, en el punto alto del casco urbano. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44054','mirador','Mirador del Balcón de Javalambre y fuentes','8.9/10 Soberbia visual alpina a más de 1300 metros de altitud, con las pistas forestales, densos pinares negros, fuentes de agua medicinal y cielos Starlight puros. Cómo llegar: Plataforma con vallado de protección en la subida natural hacia el complejo montañoso. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44055','mirador','Mirador de la Torre del Santuario de la Virgen del Campo','7.4/10 Vista que combina el patrimonio mudéjar e histórico del complejo barroco del siglo XVIII con las dehesas y cultivos cerealistas de la Comunidad de Teruel. Cómo llegar: Cuerpo de campanas superior del templo barroco, acceso coordinado en el municipio. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44056','mirador','Mirador del Yacimiento de la Caridad y río Jiloca','7.1/10 Vista de gran interés arqueológico y paisajística de la ciudad celtíbero-romana, vegas de cultivo fértiles e hileras de chopos. Cómo llegar: Plataforma con paneles explicativos perimetral al yacimiento, desvío señalizado. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44059','mirador','Mirador del Castillo y de la Terrassa del Maestrazgo','9.2/10 Excepcional, monumental e inexpugnable atalaya de la villa carlista colgada al borde de un precipicio calizo vertical a 1300 metros de altitud. Cómo llegar: Corona superior y lienzos defensivos del castillo carlista medieval en la cota urbana más alta. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44060','mirador','Mirador del Barrio del Castillo y muelas','8.8/10 Espectacular e imponente corte geológico sobre el cañón fluvial del río Cañada, la fisonomía de las muelas calcáreas a más de 1400 metros y pinos. Cómo llegar: Borde del talud calizo del barrio antiguo abandonado colgado del risco, accesos pedestres. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44061','mirador','Alto del Teso de San Cristóbal y del Mezquín','7.2/10 Panorámica rural del Bajo Aragón meridional, lomas onduladas de cultivo de viñedos y almendros, pinares de repoblación e idóneos atardeceres. Cómo llegar: Cota natural elevada al norte de la población, transitable por sendas agropecuarias de tierra. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44063','mirador','Mirador del Estrecho del río Estercuel','7.5/10 Vista del cañón fluvial encajonado de las Cuencas Mineras, laderas de jara y encinas y las antiguas explotaciones mineras integradas en el relieve. Cómo llegar: Saliente natural del relieve acondicionado con valla de madera, acceso por sendero. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44064','mirador','Alto de la Ermita y Valle del Camarena','7.3/10 Perspectiva sobre la vega del río Camarena, cultivos tradicionales de secano de la Comunidad de Teruel, monte bajo mediterráneo y horizontes limpios. Cómo llegar: Explanada elevada del santuario, transitable por camino de tierra con zona de parada. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44065','mirador','Mirador de la Sierra de Santa Cruz y Gallocanta','7.0/10 Vista lejana de la cuenca endorreica, campos cerealistas infinitos de la comarca del Jiloca occidental, pinares y cielos nocturnos sin contaminación. Cómo llegar: Promontorio suave al norte de la población, accesible por pistas agrícolas. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44067','mirador','Mirador de la Vega del río Martín','6.6/10 Sencilla panorámica de la llanura aluvial, cultivos agrícolas del Bajo Martín inferiores, canales fluviales e idóneos atardeceres sin obstáculos. Cómo llegar: Margen de la terraza aluvial, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44068','mirador','Mirador del río Guadalope y del Puente','7.4/10 Vista fluvial del cauce ancho del Guadalope, sotos de ribera, huertas tradicionales del Bajo Aragón y la silueta del largo puente histórico medieval. Cómo llegar: Paseo perimetral acondicionado con barandillas junto al cauce, casco urbano bajo. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44071','mirador','Mirador del Castillo Templario y las Rocas del Guadalope','9.1/10 Excepcional y vertical atalaya sobre el desfiladero calizo calcáreo del río Guadalope, la imponente fortaleza templaria colgada e infinitos pinares del Maestrazgo. Cómo llegar: Cima del inexpugnable peñón rocoso coronado por los lienzos de la fortaleza militar, acceso pedestre empinado. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44074','mirador','Mirador del Castillo de Cedrillas y río Alfambra','7.9/10 Vista que combina el patrimonio histórico del recinto amurallado con el nacimiento del río Alfambra, campos ganaderos de altura y horizontes limpios. Cómo llegar: Explanada de la fortaleza medieval del siglo XIII sobre el cerro testigo, acceso rodado. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44075','mirador','Alto de la Ermita de San Roque y parameras','6.8/10 Panorámica rural de la comarca de la Comunidad de Teruel, lomas de cultivo de cereal de secano e idóneo horizonte nocturno Starlight. Cómo llegar: Colina exenta que alberga la ermita, transitable a pie por pistas agropecuarias de tierra. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44076','mirador','Mirador de la Fuente de Cella y del Acueducto Romano','8.1/10 Extraordinaria vista del mayor pozo artesiano de Europa (pretil monumental), la vega del Jiloca alta, maizales y el trazado del acueducto romano excavado. Cómo llegar: Entorno acondicionado de la gran fuente elíptica, en pleno casco urbano central. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44082','mirador','Mirador del Alto de la Escaleruela y Sierra de Camarena','7.6/10 Vista montañosa de la comarca de la Comunidad de Teruel oriental, dehesas de encina centenarias, pinares forestales y horizontes limpios con nitidez Starlight. Cómo llegar: Cota natural elevada próxima al puerto, transitable por pistas ganaderas de tierra. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44084','mirador','Alto del Teso del Humilladero y Cuencas Mineras','7.2/10 Perspectiva sobre la campiña arcillosa de las Cuencas Mineras orientales, cultivos tradicionales de secano, encinares dispersos e idóneos atardeceres. Cómo llegar: Promontorio suave al oeste de la población, transitable por sendas ganaderas de herradura. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44085','mirador','Mirador de las Parameras de Cosa','6.7/10 Vista diáfana de la paramera de la comarca del Jiloca oriental, cultivos cerealistas planos, matorral mediterráneo de jara y horizontes nocturnos limpios. Cómo llegar: Elevación natural del terreno transitable a pie por caminos vecinales al sur del caserío. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44086','mirador','Mirador de los Puertos y del río Algars','8.3/10 Magnífica perspectiva que fusiona el mar de viñedos y olivares del Matarraña con los escarpados perfiles de roca caliza de los Puertos de Beceite. Cómo llegar: Plataforma con paneles interpretativos en la cota alta perimetral de la villa, accesos señalizados. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44087','mirador','Mirador de la Ermita de San Blas y del Martín','7.4/10 Vista de las vertientes de yesos y arcillas rojas de Andorra-Sierra de Arcos, matorral mediterráneo, olivares rústicos y horizontes celestes nítidos. Cómo llegar: Cerro exento que alberga la ermita, accesible por camino de tierra apto para vehículos. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44088','mirador','Mirador del cañón del río Cantavieja y muelas','7.9/10 Impresionante grieta caliza de paredes verticales calcáreas del Maestrazgo, dehesas altas de encina, masías de piedra seca y nula luz industrial. Cómo llegar: Borde del precipicio natural acondicionado con valla de madera, acceso por sendas de montaña. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44094','mirador','Mirador de los Estrechos del río Alfambra','7.4/10 Vista del cauce encajonado del río, hileras de singulares chopos cabeceros centenarios, escarpes calizos y dehesas ganaderas periféricas. Cómo llegar: Margen de la terraza fluvial, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44096','mirador','Mirador de las Masías y de la Sierra de Majalinos','8.4/10 Soberbia visual a más de 1200 metros sobre el Maestrazgo occidental, pinares, dehesas altas, patrimonio etnográfico de piedra seca y pureza Starlight nocturna. Cómo llegar: Apartadero acondicionado con paneles informativos en la carretera de montaña A-1702. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44097','mirador','Mirador de las Lagunas y Paramera de Alfambra','7.6/10 Vista de la planicie del páramo de gran altitud, humedales estacionales esteparios, cultivos cerealistas planos y horizontes limpios de contaminación. Cómo llegar: Plataforma natural elevada al norte del pueblo, accesible por pistas agropecuarias. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44099','mirador','Mirador del Museo Minero y de las Zanjas','7.8/10 Interesante perspectiva del paisaje de arqueología industrial minera, las lomas de carbón regeneradas, dehesas y las estribaciones de la Sierra de San Just. Cómo llegar: Explanada exterior elevada de la mina subterránea "Sección Pozo Pilar", desvío señalizado. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44100','mirador','Mirador del Monasterio de la Olivar','8.3/10 Hermosa e histórica vista del majestuoso cenobio mercedario del siglo XVI, el cauce del río Estercuel, olivares tradicionales y cielos muy oscuros. Cómo llegar: Elevación natural del terreno al oeste de la localidad, transitable por camino asfaltado con aparcamiento. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44101','mirador','Alto del Teso del Humilladero','6.7/10 Sencilla panorámica sobre la fosa del Jiloca noroccidental, campos de secano ondulados, matorral mediterráneo y puestas de sol limpias de obstáculos. Cómo llegar: Pequeña colina exenta en las proximidades de la ermita, de fácil acceso peatonal. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44102','mirador','Alto de la Sierra de Cucalón','7.1/10 Vista despejada de las cumbres del sistema Ibérico zaragozano-teruelense, encinares maduros de montaña, brezales y cielos óptimos para astrofotografía. Cómo llegar: Cota máxima del cerro que flanquea la localidad, accesible por pistas forestales de tierra. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44103','mirador','Mirador del Estrecho del río Mijares y Muelas','7.9/10 Impresionante cañón calizo encajonado, densas masas de pino silvestre, buitreras en las paredes verticales y un horizonte montañoso infinitamente diáfano. Cómo llegar: Saliente natural del relieve acondicionado con valla de madera, acceso por sendero local. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44105','mirador','Mirador de la Ermita de Montserrat','8.1/10 Amplia visual del Matarraña meridional, olivares centenarios alineados en bancales, campos de almendros, pinares y la fisonomía del casco medieval. Cómo llegar: Explanada del santuario en la cota más alta de la población, provista de accesos pavimentados y bancos. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44106','mirador','Mirador de la Dehesa de Fortanete','8.6/10 Espectacular relieve alpino del Maestrazgo central a más de 1300 metros, pastizales de alta montaña, densos pinares forestales y cielos de nitidez extrema. Cómo llegar: Plataforma elevada con paneles didácticos en el puerto montañoso, carretera A-226. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44107','mirador','Mirador del Embalse de Calanda y las Rocas','7.5/10 Vista de la lámina de agua encajada entre lomas calizas erosionadas, olivares del Bajo Aragón, pinares de repoblación e interesantes atardeceres. Cómo llegar: Margen de la terraza fluvial próxima a la represa, accesible por pistas rurales. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44108','mirador','Mirador del Castillo de la Fresneda y el Matarraña','8.5/10 Soberbia panorámica de la comarca del Matarraña, campos de almendros y vides, el río Matarraña y la monumental fortaleza de la Orden de Calatrava. Cómo llegar: Corona superior y adarves de la fortaleza medieval que corona el cerro de la villa, acceso peatonal urbano. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44109','mirador','Mirador del Nacimiento del Río Tajo','8.4/10 Espectacular e imponente corte geológico kárstico de los Montes Universales, densos pinares silvestres, praderas alpinas de gran altitud y el monumento fluvial. Cómo llegar: Paraje acondicionado con paneles y áreas de descanso, desvío señalizado desde la VFTE-01. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44110','mirador','Alto del Teso de la Iglesia','6.6/10 Sencilla panorámica sobre los llanos cerealistas de las Cuencas Mineras, campos ondulados de secano e idóneo horizonte nocturno Starlight. Cómo llegar: Atrio elevado del templo parroquial, en el punto alto del pequeño núcleo urbano. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44111','mirador','Mirador de las Fuentes Naturales y Paramera','6.8/10 Vista diáfana de la altiplanicie, cultivos tradicionales de secano de cereal, pequeñas dehesas dispersas y cielos abiertos despejados aptos para astrofotografía. Cómo llegar: Promontorio suave al este de la población, transitable por caminos vecinales de tierra. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44112','mirador','Mirador de las Fuentes y la Vega del Jiloca','6.9/10 Vista de la vega del río Jiloca, con sus singulares fuentes y ojos de agua natural, cultivos hortícolas locales y chopera lineal. Cómo llegar: Espacio público elevado acondicionado junto a los humedales del cauce central, acceso directo. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44114','mirador','Mirador de la Coveta y la Torre Fuerte','8.4/10 Impresionante vista sobre los Puertos de Beceite septentrionales, olivares de montaña en bancales, la torre gótica señorial y densos pinares. Cómo llegar: Explanada natural de los miradores del casco medieval fortificado, accesos peatonales adaptados. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44115','mirador','Mirador del Parque Paleontológico y río Alfambra','8.1/10 Espectacular e histórica panorámica que une las réplicas de dinosaurios gigantes con la vega aluvial fluvial del río Alfambra y laderas calizas. Cómo llegar: Plataforma elevada con paneles interpretativos junto a las sendas paleontológicas, acceso señalizado. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44116','mirador','Alto de la Ermita de San Blas','7.4/10 Vista de la comarca de AndorraSierra de Arcos, pinares forestales de repoblación, cultivos de secano e idónea pureza Starlight nocturna. Cómo llegar: Cerro exento que alberga la ermita, transitable por camino de tierra apto para vehículos. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44117','mirador','Mirador del Acueducto Romano Romano de Albarracín-Cella','8.2/10 Extraordinaria vista arqueológica e industrial sobre el cañón del río Guadalaviar, galerías excavadas en la roca viva, pinares y dehesas. Cómo llegar: Plataforma con paneles explicativos junto a los pozos de ventilación del acueducto, carretera A-1512. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44119','mirador','Mirador de la Muela de San Juan y las Pistas','8.3/10 Soberbia visual a más de 1600 metros de altitud (uno de los pueblos más altos de España), con dehesas alpinas, pinares silvestres densos e idóneo punto Starlight. Cómo llegar: Cima caliza de la inmensa muela que corona el término, accesible por pista de montaña desde el pueblo. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44120','mirador','Mirador de los Montes Universales y Muelas','8.2/10 Magnífica visual alpina de la cabecera del río Guadalaviar, pastizales de montaña de ganado trashumante, brezales tupidos y cielos nocturnos de pureza extrema. Cómo llegar: Cresta de la plataforma montañosa accesible por pistas forestales, desvío rural. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44122','mirador','Mirador del Castillo de la Corona y el río Martín','7.6/10 Vista del cauce ancho del río Martín, olivares del Bajo Martín, el entramado de los barrios de la judería y la fortaleza señorial. Cómo llegar: Explanada de la antigua fortaleza que domina el cerro de la villa, accesos rodados y peatonales. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44123','mirador','Mirador de las Esculturas del Parque de la Memoria','7.4/10 Vista que combina instalaciones artísticas modernas al aire libre con las laderas calcáreas del maestrazgo de Teruel, matorral mediterráneo y horizontes despejados. Cómo llegar: Sendero peatonal adaptado en el cerro de la localidad, accesible a pie desde el casco urbano. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44124','mirador','Mirador de las Torres Medievales y la Hoz','7.8/10 Espectacular tajo calizo y pizarroso excavado por el arroyo, la silueta del torreón gótico defensivo fortificado del siglo XIV y pinares dispersos. Cómo llegar: Saliente acondicionado con valla de madera en el desfiladero, acceso señalizado por sendero rural. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44125','mirador','Mirador del Castillo de Peñaflor y las Crestas','8.3/10 Sobrecogedor escarpe calizo vertical coronado por una inexpugnable fortaleza medieval del siglo XII, con vistas profundas al cañón del río Aguasvivas. Cómo llegar: Crestas rocosas que rodean el peñón del castillo, acceso pedestre por sendero local de montaña. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44126','mirador','Mirador de la Torre de los Nublos y el Maestrazgo','8.6/10 Excepcional e histórica panorámica urbana y paisajística del casco monumental góticorenacentista, olivares de montaña en bancales y masías de piedra seca. Cómo llegar: Remate superior transitable del palacio-castillo templario de la villa, actual sede consistorial. ¿Cómo prefieres que continuemos con el inventario de la Provincia de Teruel? Podemos pasar directamente al siguiente bloque masivo de municipios que continúan con la letra J en adelante (Jabaloyas, Jérica/Josa, Libros, Linares de Mora, etc.).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44127','mirador','Mirador del Monte Jabalón','8.3/10 Soberbia visual de los Montes Universales, densos sabinares, pinos silvestres, relieve kárstico de la Sierra de Albarracín e idónea observación astronómica. Cómo llegar: Cima caliza exenta que domina el altiplano, accesible por pista de tierra desde el núcleo urbano. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44128','mirador','Alto de la Cuesta del Río Jarque','7.1/10 Panorámica rural de las Cuencas Mineras, campos ondulados de secano, chopera lineal de ribera y horizontes totalmente limpios de obstáculos visuales. Cómo llegar: Pequeña elevación natural al norte del pueblo, accesible por pistas agropecuarias. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44129','mirador','Mirador de la Cripta Subterránea y del río Martín','6.8/10 Perspectiva sobre el valle bajo del río Martín, cultivos tradicionales del Bajo Martín, olivares de ladera y la vega agrícola llana. Cómo llegar: Plataforma urbana elevada en las proximidades del castillo gótico de la Orden de San Juan. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44131','mirador','Mirador de los Cortados del río Radón','7.4/10 Hermosa vista de los escarpes calizos calcáreos, nidos de rapaces rupícolas, huertas tradicionales del barranco y cielos nocturnos de gran nitidez. Cómo llegar: Borde del talud natural acondicionado con valla de madera en el sector este. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44135','mirador','Mirador del Turia y las Minas de Azufre','7.8/10 Espectacular e industrial panorámica del encajonamiento del río Turia, laderas pizarrosas de las antiguas minas rústicas y monte bajo mediterráneo. Cómo llegar: Punto alto acondicionado junto al poblado minero abandonado, acceso señalizado desde la N-330. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44136','mirador','Alto del Teso del Humilladero','6.6/10 Vista diáfana de la paramera de Alfambra alta, campos de cereal de secano y un cielo nocturno libre de contaminación lumínica. Cómo llegar: Promontorio suave al oeste del caserío, transitable a pie desde el casco urbano. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44137','mirador','Mirador del Pino del Escobón y la Sierra de Gúdar','8.9/10 Extraordinaria e infinita visual alpina de valles profundos, pinares de pino negro densos, riscos calizos y el ejemplar botánico monumental. Cómo llegar: Estructura de madera adaptada en el barranco del río Linares, desvío forestal señalizado. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44141','mirador','Mirador de la Vía Verde y río Algars','7.7/10 Vista fluvial del río Algars fronterizo con Cataluña, viñedos del Matarraña baja, huertas tradicionales e infraestructuras del antiguo ferrocarril. Cómo llegar: Antiguo viaducto ferroviario recuperado con pasarelas de la Vía Verde de la Val de Zafán. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44138','mirador','Alto de la Ermita de San Roque y Piedrahita','7.2/10 Panorámica sobre el somontano de la Sierra de Cucalón, cultivos de secano ondulados, encinares dispersos y horizontes celestes diáfanos. Cómo llegar: Cerro exento que alberga la ermita, accesible por pista rural desde la pedanía. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44142','mirador','Mirador del cañón del río Aguasvivas','7.0/10 Vista de las vertientes de caliza erosionada que caen hacia el río, jarales, matorral de media montaña y un limpio cielo nocturno. Cómo llegar: Borde del talud natural accesible por caminos vecinales desde la carretera de Plou. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44143','mirador','Mirador del Castillo y los Sabinares del Paraíso','8.4/10 Impresionante vista de la Sierra de Javalambre meridional, densos bosques de pino albar, sabinas centenarias y el recinto fortificado del siglo XIII. Cómo llegar: Explanada de la antigua fortaleza que domina el núcleo histórico, acceso peatonal urbano. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44144','mirador','Mirador del hocino del río Martín','7.8/10 Estrecho cañón calizo excavado por el río Martín alto, con pozas de agua cristalina, nidos de buitres y huertas tradicionales de montaña. Cómo llegar: Saliente acondicionado con valla de madera en la ruta senderista del Hocino. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44145','mirador','Mirador de la Vega del Guadalope','7.9/10 Amplia visual sobre los llanos agrícolas fértiles de regadío del Bajo Aragón, olivares tradicionales, campos de frutales y muelas calcáreas. Cómo llegar: Cota natural elevada al norte de la población, accesible por pistas agropecuarias de tierra. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44146','mirador','Mirador de las Eras del Santo','7.5/10 Vista de la planicie del Bajo Aragón occidental, cultivos tradicionales de secano de olivar, almendrales y horizontes limpios de obstáculos. Cómo llegar: Promontorio suave al oeste de la localidad, transitable a pie desde el casco urbano. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44147','mirador','Mirador de la Ermita de San Cristóbal y río Matarraña','8.1/10 Preciosa panorámica del meandro fluvial del río Matarraña, olivares en bancales, el poblado ibérico de San Cristóbal y el núcleo urbano. Cómo llegar: Explanada elevada del santuario en la cota más alta, provista de accesos rodados. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44148','mirador','Alto del Teso de la Iglesia','7.0/10 Sencilla panorámica de las lomas arcillosas de las Cuencas Mineras, campos ondulados de secano e idóneo horizonte nocturno Starlight. Cómo llegar: Atrio elevado del templo parroquial, en el punto alto del casco urbano. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44150','mirador','Mirador del Castillo y el río Guadalope','8.3/10 Espectacular e intrincada panorámica urbana y paisajística del casco gótico medieval encajonado en el valle, escarpes calizos y chopera lineal. Cómo llegar: Promontorio rocoso elevado que alberga las ruinas fortificadas, acceso por sendero pedestre. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44149','mirador','Mirador de las Murallas y el Portal de las Monjas','8.8/10 Extraordinaria e histórica perspectiva sobre el recinto medieval amurallado de la villa (Premio Europa Nostra), masías tradicionales y la paramera del Maestrazgo. Cómo llegar: Tramo superior acondicionado de los torreones de la muralla histórica, acceso peatonal urbano. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44151','mirador','Mirador de las Grutas de Cristal y barranco','8.6/10 Impresionante vista geológica del kárstico Monumento Natural, cañón profundo del Guadalopillo, puentes de roca naturales y nidos de rapaces. Cómo llegar: Explanada perimetral adaptada del centro de recepción de las Cuevas de Cristal, desvío señalizado. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44152','mirador','Mirador del Castillo de Monforte','7.8/10 Soberbia y colgada atalaya militar medieval sobre el río Moyuela, laderas de yesos y arcillas rojas, matorral mediterráneo y horizontes limpios. Cómo llegar: Explanada de la fortaleza islámica situada en el escarpado risco calizo que corona la villa. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44153','mirador','Mirador de los Ojos del río Jiloca','7.6/10 Vista paisajística del nacimiento acuífero del Jiloca (Ojos), praderas húmedas tradicionales, cultivos de azafrán y el somontano Ibérico. Cómo llegar: Paseo natural elevado y acondicionado en el entorno protegido de las surgencias hídricas. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44154','mirador','Mirador de la Muela de Monroyo','8.4/10 Impresionante visual alpina de la comarca del Matarraña a más de 1100 metros de altitud, pinares forestales espesos, brezales y nitidez Starlight nocturna. Cómo llegar: Corona rocosa del cerro donde se alzaba la antigua fortificación medieval, acceso pedestre. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44155','mirador','Mirador de la Iglesia de Santiago y el río Martín','8.5/10 Espectacular e imponente vista del cañón calizo del río Martín, el entramado mudéjar, los restos de la alcazaba y la colosal iglesia-fortaleza. Cómo llegar: Plataforma elevada perimetral al ábside gótico-mudéjar en el centro del casco urbano. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44159','mirador','Mirador del río Masegoso y los Pinares','8.2/10 Hermoso panorama alpino de los Montes Universales, valles profundos encajonados, densos pinares de pino silvestre e idónea observación estelar. Cómo llegar: Saliente natural del relieve acondicionado con valla de madera, acceso por sendero desde el núcleo. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44160','mirador','Mirador del Pinar Ciego y las Muelas','8.9/10 Excepcional panorámica a más de 1400 metros de altitud de la Sierra de Gúdar, inmensas masas de pino moro, arquitectura de piedra seca y pureza atmosférica. Cómo llegar: Cornisa de la muela calcárea perimetral adaptada con vallado, pistas forestales de montaña. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44161','mirador','Alto de la Torre Mudéjar de Muniesa','7.1/10 Vista aérea sobre los llanos cerealistas de la comarca del Bajo Martín, viñedos, cultivos de secano e interesantes puestas de sol libres. Cómo llegar: Cuerpo de campanas superior de la célebre torre octogonal mudéjar de la Iglesia del Milagro. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44163','mirador','Mirador de la Peña de la Laguna y el río Noguera','8.4/10 Extraordinaria visual alpina de la Sierra de Albarracín, densos bosques mixtos, fuentes de agua cristalina y cumbres de areniscas rojizas rodenas. Cómo llegar: Saliente rocoso acondicionado en la muela forestal alta, desvío desde la VF-TE-05. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44164','mirador','Alto del Cerro Gordo','7.0/10 Sencilla panorámica del somontano de Cucalón, lomas cubiertas de monte bajo mediterráneo, pastizales de secano e idóneos atardeceres nítidos. Cómo llegar: Cota natural elevada al norte de la población, transitable por sendas agropecuarias. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44165','mirador','Mirador del río Algaba y Sierra de Gúdar','8.2/10 Magnífica perspectiva de las laderas boscosas serranas, densas masas de pino albar, cañones fluviales hondos y horizontes de gran altitud. Cómo llegar: Promontorio calizo elevado al sur de la población, transitable por pistas forestales. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44167','mirador','Mirador de los Estrechos del río Martín','8.3/10 Impresionante cañón calizo de paredes verticales calcáreas del Parque Cultural, con pinturas rupestres prehistóricas protegidas, jarales y nidos de rapaces. Cómo llegar: Borde del precipicio natural acondicionado con valla de madera, acceso por el sendero GR-262. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44168','mirador','Mirador de la Paramera de Gallocanta','7.2/10 Vista lejana de la cuenca endorreica de la Laguna de Gallocanta, campos cerealistas planos de gran altitud, sabinas dispersas e idónea pureza nocturna. Cómo llegar: Cornisa del páramo oriental accesible por pistas agrícolas desde la linde con Zaragoza. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44169','mirador','Mirador de las Minas y del Molino de Viento','7.7/10 Interesante paisaje que combina la arqueología industrial de las grandes minas de hierro a cielo abierto con un molino harinero restaurado y parameras. Cómo llegar: Colina exenta que alberga la estructura tradicional del molino, accesos pavimentados. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44171','mirador','Mirador del río Mijares y los Huertos','8.1/10 Precioso rincón encajonado del Mijares en el confín con Castellón, con huertas tradicionales escalonadas de frutales, densos pinares y paredones calizos. Cómo llegar: Plataforma con vallado de madera en las rutas pedestres del cañón fluvial. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44172','mirador','Mirador de la Sima de San Pedro y el río Martín','8.6/10 Sobrecogedor y vertical sumidero kárstico de más de 80 metros (único en Europa), con el río Martín encajonado, olivares milenarios y el poblado ibérico de San Pedro. Cómo llegar: Plataforma volada de hierro adaptada con barandilla perimetral segura junto a la sima, desvío rural. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44173','mirador','Alto de la Ermita del Calvario','7.3/10 Vista panorámica del Bajo Aragón occidental, lomas de yesos y arcillas, cultivos tradicionales de secano de olivar y almendrales libres de postes. Cómo llegar: Cerro exento que alberga el pequeño templo, accesible por camino vecinal de tierra. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44174','mirador','Mirador del Santuario de la Virgen del Tremedal','8.8/10 Soberbia visual alpina a más de 1400 metros de altitud sobre la Sierra de Albarracín, inmensos ríos de bloques de piedra (borrocales), pinares silvestres densos e idóneo punto Starlight. Cómo llegar: Explanada de la basílica barroca en la cota más elevada del cerro de la villa, accesos adaptados. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44175','mirador','Alto del Teso de la Iglesia','6.9/10 Sencilla panorámica sobre la vega del río Alfambra medio, cultivos arcillosos de secano, dehesas dispersas e idóneos horizontes al atardecer teruelense. Cómo llegar: Plaza sobreelevada frente a la portada del templo renacentista, centro del municipio. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44176','mirador','Mirador del cerro de la Atalaya y Cuencas Mineras','7.5/10 Vista panorámica de las lomas onduladas mineras, el perfil de la Sierra de San Just al fondo, pinares forestales y cielos limpios. Cómo llegar: Cima del cerro acondicionado con accesos peatonales y barandilla en la periferia del núcleo. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44177','mirador','Mirador de la Paramera de Pancrudo','7.1/10 Vista limpia de la paramera alta a más de 1200 metros, cultivos de secano de cereal, brezales y matorral bajo de montaña Starlight. Cómo llegar: Plataforma calcárea elevada accesible por pistas forestales al sur del término. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44178','mirador','Mirador del cañón del río Guadalope','8.2/10 Impresionante grieta caliza de paredes verticales, densos pinares de pino negral, encinares serranos de la vertiente del Maestrazgo y nula luz industrial. Cómo llegar: Borde del precipicio natural acondicionado con valla de madera, acceso por sendas de montaña. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44179','mirador','Mirador del Inhóspitak y las Rocas del Masmut','8.7/10 Extraordinaria e imponente panorámica de los colosales monolitos calizos rojizos verticales (les Roques), pinares silvestres, encinares y yacimientos paleontológicos de dinosaurios. Cómo llegar: Balcón natural adaptado con barandillas en el sendero que sube hacia las formaciones rocosas, desvío señalizado. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44180','mirador','Adarve del Castillo de Peracense','9.1/10 Impresionante, espectacular y colgada atalaya militar del siglo XIII perfectamente mimetizada en las peñas de arenisca roja (rodeno), dominando el Valle del Jiloca. Cómo llegar: Corona superior y almenas transitables de la fortaleza medieval, accesible con la entrada turística al monumento. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44181','mirador','Mirador del río Alfambra','7.0/10 Vista fluvial del cauce del río Alfambra, chopera lineal de ribera, lomas calizas cubiertas de matorral mediterráneo y cultivos bajos de regadío. Cómo llegar: Talud natural acondicionado con valla de madera, accesible por pistas rurales desde el pueblo. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44182','mirador','Alto del Calvario y la Paramera de Alfambra','7.2/10 Perspectiva sobre la campiña arcillosa, campos de secano de la comarca, chopera lineal de los chopos cabeceros tradicionales e idóneos horizontes despejados nocturnos. Cómo llegar: Promontorio suave al sur de la población, transitable a pie por sendas de piedra. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44183','mirador','Mirador del Nacimiento del Río Pitarque','9.0/10 Sobrecogedor y vertical cañón calizo de paredes calcinadas donde brota de forma brutal el agua cristalina del nacimiento, densos bosques y nidos de buitres. Cómo llegar: Itinerario pedestre señalizado adaptado con pasarelas de la red de Monumentos Naturales del Maestrazgo. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44184','mirador','Alto del Teso de las Eras','6.7/10 Sencilla visual de campos de secano de las Cuencas Mineras, lomas arcillosas y horizontes limpios idóneos para la observación de lluvias de estrellas nocturna. Cómo llegar: Elevación natural al norte de la población, accesible por pistas agropecuarias de tierra. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44185','mirador','Mirador del Hoyalta y Sierra de El Pobo','7.8/10 Soberbia visual a más de 1700 metros de altitud (una de las cotas máximas de la comarca), dehesas alpinas rústicas, brezales de montaña y horizontes Starlight puros. Cómo llegar: Cresta de la plataforma montañosa alta junto a las antenas y el vértice geodésico, pistas forestales de tierra. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44187','mirador','Mirador del Salt de la Portellada y río Tastavins','8.0/10 Espectacular cascada de más de 20 metros esculpida en estratos calizos, pozas de agua cristalina, pinares y olivares tradicionales de la comarca del Matarraña. Cómo llegar: Plataforma adaptada con barandilla perimetral en el borde de la caída del agua, desvío señalizado. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44189','mirador','Mirador del barranco de la Hoz y parameras','7.6/10 Vista geológica del paisaje kárstico de la Sierra de Albarracín, dolinas, sumideros naturales (el hundido), sabinares dispersos e idóneo punto para astrofotografía. Cómo llegar: Entorno perimetral acondicionado y protegido de las sendas arqueológicas, acceso por pista forestal. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44190','mirador','Alto del Teso de San Roque','6.9/10 Sencilla panorámica sobre los llanos cerealistas de la comarca del Jiloca occidental, cultivos de secano e idóneo horizonte nocturno Starlight sin postes. Cómo llegar: Atrio elevado de la ermita, en el punto alto de la colina que flanquea el casco urbano. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44191','mirador','Mirador de la Vía Verde de la Val de Zafán','7.1/10 Vista del arranque de la histórica ruta ciclista, los llanos agrícolas del Bajo Martín cerealistas, olivares marginales y horizontes limpios despejados. Cómo llegar: Pasarela peatonal y talud adaptado junto al trazado de la antigua estación de tren, sector norte. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44192','mirador','Mirador de la Sierra de Javalambre norte','7.9/10 Magnífica perspectiva de las vertientes de pino silvestre y sabinares de la sierra, campos de cultivo truferos (trufa negra), trincheras e interesantes puestas de sol. Cómo llegar: Saliente natural acondicionado con valla de madera en las subidas forestales altas, acceso rural. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44193','mirador','Mirador del Castillo de Puertomingalvo y las Muelas','8.9/10 Espectacular e infinita atalaya medieval de 360 grados sobre el Parque Natural del Maestrazgo, masías rústicas, barrancos de piedra caliza y pureza Starlight total. Cómo llegar: Corona superior y adarves visitables de la inexpugnable fortaleza del siglo XIII que corona la villa amurallada. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44194','mirador','Mirador de la Ermita de San Rafael y Matarraña','82/10 Hermosa vista de los meandros del Matarraña meridional, olivares tradicionales alineados en bancales, campos de almendros y el casco urbano gótico declarado conjunto histórico. Cómo llegar: Explanada exterior elevada de la ermita, provista de accesos rodados y bancos. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44195','mirador','Alto del Cerro Gordo','72/10 Vista de las llanuras cerealistas y calcáreas de la comarca de la Comunidad de Teruel norte, campos ondulados de secano e idóneo horizonte nocturno. Cómo llegar: Cota natural elevada al norte de la población, transitable por sendas agropecuarias de tierra. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44196','mirador','Mirador de los Amanaderos y el Titania','81/10 Impresionante cañón calizo de saltos de agua y cascadas esculpidas de la vertiente de Javalambre, pinares forestales y el centro paleontológico del Gigante de Riodeva. Cómo llegar: Pasarelas de madera y plataformas voladas adaptadas de la red de itinerarios del barranco de los Amanaderos. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44197','mirador','Mirador de la Cisterna y las Peñas de Rodeno','8.5/10 Extraordinaria vista que combina el patrimonio etnográfico de sillería de arenisca roja con las caprichosas formas erosionadas de los borrocales de rodeno. Cómo llegar: Zona perimetral elevada acondicionada en las peñas que rodean la monumental cisterna del siglo XVI. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44198','mirador','Mirador de las Cascadas del río Blanco','7.9/10 Vista del paraje kárstico protegido de la Sierra de Albarracín, cañón del río Blanco con saltos de agua y tobas, densos pinares silvestres e idónea nitidez nocturna. Cómo llegar: Entorno acondicionado con barandillas de madera en los senderos ecológicos locales, desvío desde la carretera local. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44201','mirador','Mirador de la Cruz de la Tarumba','8.8/10 Espectacular panorámica de la villa medieval, su fisionomía de palacios y torres, la llanura elevada de la comarca Gúdar-Javalambre y profundos barrancos calizos. Cómo llegar: Promontorio rocoso acondicionado al norte del casco urbano, acceso señalizado por pista transitable. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44203','mirador','Alto del Teso de San Roque','6.6/10 Vista diáfana de los llanos cerealistas y mineros de la comarca, relieves suaves del somontano y horizontes despejados idóneos para astrofotografía. Cómo llegar: Cota natural elevada junto a las antiguas eras, accesible por pistas agropecuarias de tierra. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44204','mirador','Mirador del Sabinar de Saldón','7.8/10 Vista inmensa de uno de los sabinares de sabina albar más densos y antiguos de Europa, parajes de la Sierra de Albarracín y cielos nocturnos catalogados Starlight. Cómo llegar: Borde de la plataforma calcárea superior, transitable por sendero micológico y forestal. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44205','mirador','Mirador de la Ermita del Calvario','7.1/10 Perspectiva sobre los llanos agrícolas del Bajo Martín, olivares alineados, el trazado ferroviario y amplios horizontes despejados al atardecer. Cómo llegar: Explanada elevada del santuario rústico, con accesos peatonales y rodados adaptados. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44206','mirador','Mirador del Maimona y los Viaductos','7.5/10 Vista del profundo barranco del río Maimona en los límites con Castellón, pinares forestales espesos, matorral de montaña y viaductos históricos integrados. Cómo llegar: Saliente natural acondicionado con valla de madera, accesible por pistas desde el núcleo. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44207','mirador','Mirador de la Torre de la Iglesia de San Martín','7.3/10 Vista panorámica del valle del Jiloca, cultivos hortícolas locales, viñedos de ladera y la silueta mudéjar de la esbelta torre campanario. Cómo llegar: Cuerpo superior elevado de la estructura mudéjar, accesible mediante visitas reguladas en el casco urbano. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44208','mirador','Alto del Cabezo de la Ermita','7.0/10 Sencilla panorámica sobre los valles menores del sistema Ibérico septentrional, encinares dispersos de montaña, brezales y cielos nocturnos muy oscuros. Cómo llegar: Cerro exento que alberga la ermita, transitable a pie por sendas ganaderas de herradura. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90769','mirador','Mirador de las Fuentes del Jiloca','7.2/10 Vista de los pozos artesianos de agua natural, las vegas cerealistas llanas de la fosa del Jiloca e hileras de chopos lineales. Cómo llegar: Espacio recreativo elevado acondicionado junto a los brotes de agua, accesos pavimentados directos. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44210','mirador','Mirador de las Truferas y Sierra de Javalambre','8.1/10 Vista que combina las extensas plantaciones de encina trufera (capital de la trufa negra) con las faldas forestales de la sierra alpina. Cómo llegar: Borde del páramo calcáreo acondicionado con paneles, transitable por pistas rurales agrícolas. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44211','mirador','Mirador de los Baños y Hoces del río Aguasvivas','8.3/10 Impresionante grieta caliza vertical excavada por el río, el entorno del balneario histórico termal, pinares y nidos de rapaces rupícolas protegidas. Cómo llegar: Estructura de pasarela adaptada con barandilla sobre el escarpe rocoso, acceso señalizado por sendero. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44212','mirador','Alto del Cerro Gordo','7.1/10 Panorámica sobre el pequeño valle del Bajo Aragón meridional, olivares tradicionales en bancales, matorral mediterráneo y horizontes despejados Starlight. Cómo llegar: Cota natural elevada al norte de la población, accesible por pistas agropecuarias de tierra. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44213','mirador','Mirador del Cabezo de Singra','6.7/10 Vista de la fosa del Jiloca alta, campos ondulados de secano, encinares dispersos y el escenario histórico de batallas de la Guerra Civil. Cómo llegar: Cerro testigo exento que corona el término, transitable a pie por sendas históricas. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44215','mirador','Mirador del Raso de Terriente','7.9/10 Magnífica perspectiva alpina de los Montes Universales, extensas praderas de montaña donde pastan reses, pinares de pino albar y pureza nocturna. Cómo llegar: Plataforma con vallado de protección en el borde de la muela forestal superior, pistas de herradura. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44216','mirador','Mirador de los Arcos y del Óvalo','8.6/10 Espectacular panorámica urbana e histórica de los monumentales viaductos, el acueducto renacentista, las torres mudéjares Patrimonio de la Humanidad y las cárcavas arcillosas arcillosas. Cómo llegar: Balcón y paseo adaptado con barandillas en la escalinata de la Plaza del Óvalo, casco urbano central. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44217','mirador','Mirador de las Muelas de Toril','8.1/10 Vista geológica de relieves tabulares calizos escarpados de la Sierra de Albarracín, densos pinares de montaña, brezales y cielos nocturnos Starlight puros. Cómo llegar: Saliente natural acondicionado con paneles de la red forestal, accesible por pistas forestales. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44218','mirador','Mirador de los Estrechos del Ebrón y Pinturas','8.4/10 Extraordinario y caótico cañón calizo excavado por el río Ebrón, con el abrigo de arte rupestre levantino protegido, cascadas, pinos silvestres y puentes de roca. Cómo llegar: Sendero ecológico señalizado y adaptado con pasarelas en el barranco fluvial, acceso desde el pueblo. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44219','mirador','Mirador del Castillo de Tornos y Gallocanta','8.3/10 Espectacular vista panorámica de la Reserva Natural de la Laguna de Gallocanta, la inmensa lámina de agua salina endorreica, avifauna migratoria y estepa cerealista. Cómo llegar: Cresta del cerro amurallado de la antigua fortaleza medieval, adaptado con paneles explicativos. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44220','mirador','Alto del Páramo de Torralba','7.1/10 Vista diáfana de la altiplanicie cerealista de la comarca del Jiloca occidental, dehesas dispersas de encina e idóneo horizonte nocturno para capturar estrellas. Cómo llegar: Plataforma tabular calcárea elevada, transitable por sendas agropecuarias al norte del pueblo. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44223','mirador','Mirador de la Sierra de la Cogulla','7.8/10 Vista montañosa del Matarraña meridional, pinares tupidos forestales de repoblación, cultivos de secano e idónea nitidez astronómica para astrofotografía. Cómo llegar: Cota máxima del cerro que flanquea la localidad, accesible por pistas forestales de tierra. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44225','mirador','Mirador del río Matarraña y del Viaducto','8.1/10 Hermosa vista que combina el soto fluvial arbolado del Matarraña con el monumental viaducto ferroviario de piedra de la antigua línea del Val de Zafán. Cómo llegar: Saliente natural acondicionado en el trazado de la Vía Verde, accesos peatonales y ciclistas. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44224','mirador','Mirador del río Radón y las Arcillas','7.2/10 Perspectiva sobre el pequeño valle encajonado del río Radón, laderas escarpadas de yesos y arcillas rojas, matorral mediterráneo y horizontes limpios. Cómo llegar: Borde del talud geográfico al este del núcleo, transitable por caminos vecinales. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44227','mirador','Alto del Teso del Humilladero','7.0/10 Vista limpia de la paramera del Jiloca alta, cultivos de cereal de secano, encinares dispersos y nítidos horizontes libres de postes industriales. Cómo llegar: Promontorio suave al oeste del casco urbano, accesible por pistas agropecuarias de tierra. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44221','mirador','Mirador de las Oliveras Milenarias y la Vega','7.4/10 Vista paisajística del Bajo Aragón, olivares centenarios alineados en bancales, campos de secano e interesantes puestas de sol libres de obstáculos. Cómo llegar: Punto alto acondicionado en los caminos rurales del norte del casco urbano. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44222','mirador','Alto de la Ermita de San Cristóbal','7.1/10 Panorámica rural de lomas de cultivo cerealista, encinares de montaña en la Sierra de Cucalón y horizontes celestes despejados Starlight. Cómo llegar: Cerro exento que alberga el templo, accesible por camino de tierra apto para vehículos. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44226','mirador','Mirador del río Jiloca y de las Trincheras','6.9/10 Vista de las terrazas fluviales de la vega baja, cultivos de regadío, chopera lineal y la red de nidos de ametralladoras históricos de la Guerra Civil. Cómo llegar: Zona perimetral elevada acondicionada en los cerros que flanquean la carretera N-234. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44228','mirador','Alto del Castillo y Vega del Jiloca','6.8/10 Sencilla panorámica de los llanos agrícolas de la vega, campos de secano de cereal, olivares marginales y la silueta de los restos fortificados medievales. Cómo llegar: Elevación natural al oeste de la población, transitable por sendas rurales peatonales. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44229','mirador','Mirador del Guadalaviar y Sierra alta','7.9/10 Vista del cauce encajonado del río Guadalaviar, fértiles vegas agrícolas tradicionales de montaña, densos pinares forestales y escarpes calizos. Cómo llegar: Saliente acondicionado con valla de madera perimetral en la carretera de la sierra, A-1512. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44231','mirador','Mirador del Puerto de Torrijas y Javalambre','8.3/10 Soberbia visual a más de 1300 metros de altitud de los pastizales alpinos de ganado, densos pinares silvestres, brezales de montaña y pureza nocturna. Cómo llegar: Plataforma con vallado de protección en la subida natural hacia las cimas serranas, desvío rural. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44232','mirador','Mirador del río Jiloca y del Calvario','7.2/10 Perspectiva sobre la vega central de la comarca, cultivos agrícolas tradicionales de regadío, cañaverales lineales e idóneo horizonte nocturno Starlight. Cómo llegar: Zona alta del montículo del Calvario, accesible a pie desde la periferia urbana. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44234','mirador','Mirador del Castillo y Hoz del río Regajo','7.8/10 Impresionante grieta caliza de paredes verticales, con las ruinas fortificadas medievales colgadas del risco, pinares y nidos de rapaces rupícolas. Cómo llegar: Cima del peñón rocoso coronado por los lienzos de la muralla, acceso pedestre por sendero. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44235','mirador','Mirador del río Guadalaviar y la Muela','8.2/10 Vista panorámica del meandro encajonado fluvial, huertas tradicionales escalonadas, pinares densos de la Sierra de Albarracín e idónea oscuridad nocturna. Cómo llegar: Borde del precipicio natural de la muela calcárea superior, transitable por sendero señalizado. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44236','mirador','Mirador de la Mola de Tronchón','8.5/10 Espectacular e ininterrumpida panorámica del agreste relieve del Maestrazgo, masías rústicas de piedra seca, profundos cañones y la cuna del queso histórico. Cómo llegar: Balcón natural acondicionado con barandillas en el borde del sinclinal colgado calizo que corona la villa. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44237','mirador','Mirador de la Villa Romana de la Loma de Regadío y río Martín','7.4/10 Vista que combina el patrimonio arqueológico íbero-romano con el soto fluvial arbolado del Martín, olivares y campos de cultivo del Bajo Martín. Cómo llegar: Plataforma con paneles explicativos junto al complejo museístico protegido del yacimiento, acceso rural. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44238','mirador','Mirador del Pozo Santa Bárbara y del Tren Minero','8.0/10 Paisaje de arqueología industrial minera, las instalaciones de los pozos de carbón, locomotoras de vapor históricas, dehesas y las Cuencas Mineras. Cómo llegar: Zona elevada de servicio exterior perimetral a las instalaciones museísticas del pozo, accesos pavimentados. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44239','mirador','Mirador del Castillo de Valacloche y río Camarena','7.3/10 Vista montañosa de la cuenca del río Camarena, escarpes calizos de las Sierras de Javalambre occidentales, pinares forestales y restos de fortalezas medievales. Cómo llegar: Explanada rocosa elevada que rodea las ruinas fortificadas islámicas, acceso pedestre por sendas. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44240','mirador','Mirador del Embalse de Valbona y río Mijares','7.5/10 Vista de la lámina de agua rodeada de pinares forestales de repoblación, cultivos tradicionales de secano de olivar, frutales y horizontes limpios GúdarJavalambre. Cómo llegar: Corona de la represa e inmediaciones de la zona forestal recreativa perimetral, acceso rodado. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44241','mirador','Mirador del Túnel del Equinoccio y el Bajo Aragón','7.4/10 Singular perspectiva que combina el patrimonio de la Vía Verde del Val de Zafán con los olivares infinitos y el fenómeno solar astronómico del túnel. Cómo llegar: Explanada exterior de la boca del antiguo túnel ferroviario acondicionado, acceso señalizado por pista. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44243','mirador','Mirador de los Callejones y la Paramera','7.8/10 Vista de las caprichosas formas de la erosión kárstica caliza, sabinares milenarios, campos agrícolas de la Sierra de Albarracín e idónea pureza nocturna. Cómo llegar: Cota natural elevada accesible por las pistas forestales al sur del término rural. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44244','mirador','Mirador de las Pistas y del Pueblo Más Alto de España','8.9/10 Extraordinaria e infinita visual alpina a 1692 metros de altitud sobre la Sierra de Gúdar, pastizales de alta montaña, densos pinares negros e idóneo punto Starlight. Cómo llegar: Plataforma con vallado de protección en la cornisa superior del término urbano alto, carretera de la estación. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44245','mirador','Mirador del Yacimiento Íbero de San Antonio y río Matarraña','7.6/10 Vista de interés arqueológico y paisajístico de la cuenca baja de la comarca, olivares en bancales, campos de almendros y sotos fluviales de ribera. Cómo llegar: Plataforma con paneles interpretativos en la cima del cerro del yacimiento protegido, acceso rural. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44246','mirador','Adarve del Castillo-Palacio de Valderrobres','9.1/10 Soberbia, inmensa y monumental panorámica sobre el río Matarraña, el puente medieval de piedra de siete ojos, los tejados góticos y los Puertos de Beceite. Cómo llegar: Corona superior y almenas transitables de la colosal fortaleza gótica del siglo XIV que corona la villa histórica. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50274','mirador','Alto del Teso rural del secano','7.0/10 Sencilla panorámica de la llanura de transición de la cuenca endorreica de Gallocanta, campos ondulados de cultivo y baja luminosidad nocturna. Cómo llegar: Cota natural elevada al norte de la población, transitable por sendas agropecuarias de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44247','mirador','Mirador del Mirón y Matarraña','7.5/10 Vista diáfana del somontano del Matarraña septentrional, olivares centenarios alineados, campos de almendros y horizontes limpios libres de obstáculos industriales. Cómo llegar: Promontorio suave adaptado con barandillas en el borde del casco urbano alto de la población. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44250','mirador','Alto de la Sierra de Albarracín meridional','7.3/10 Vista de las vertientes de piedra caliza, encinares de montaña, praderas rústicas ganaderas en la linde con Cuenca y un cielo nocturno muy oscuro. Cómo llegar: Promontorio calizo elevado accesible por pistas forestales al sur del término municipal. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44251','mirador','Alto de la Ermita de la Virgen del Campo y Jiloca','7.1/10 Panorámica rural de la fosa del Jiloca central, campos de cereal de secano planos, olivares de montaña lejanos e idóneos atardeceres limpios. Cómo llegar: Explanada perimetral del santuario en el cerro que flanquea el oeste del núcleo urbano. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44252','mirador','Mirador del río Huerva','6.9/10 Vista fluvial del cauce alto del río Huerva, campos de cultivo, chopera lineal de ribera y relieves pizarrosos del sistema Ibérico zaragozano-teruelense. Cómo llegar: Zona perimetral elevada acondicionada junto a los senderos rurales del margen izquierdo del río. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44256','mirador','Mirador de la Sierra de Cucalón','7.3/10 Magnífica perspectiva de las vertientes forestales de encina y pino de montaña, campos ondulados de secano e idóneo horizonte nocturno para astrofotografía. Cómo llegar: Cota natural elevada accesible por las pistas forestales al norte de la villa rural. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44257','mirador','Mirador de los Estrechos del Guadalaviar','8.1/10 Impresionante cañón calizo encajonado de paredes verticales de los Montes Universales, densos pinares de pino albar, fuentes de agua cristalina y pureza Starlight. Cómo llegar: Borde del precipicio natural acondicionado con valla de madera, acceso por sendas de montaña. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44258','mirador','Alto del Teso del Salz','7.0/10 Sencilla visual de campos de secano de la altiplanicie, encinares de montaña dispersos de Sierra Menera y horizontes limpios de la comarca del Jiloca. Cómo llegar: Elevación natural al norte de la población, accesible por pistas agropecuarias de tierra. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44260','mirador','Mirador del Balcón de los Órganos de Montoro','8.8/10 Espectacular, soberbio e imponente monumento natural de agujas calizas verticales calcáreas gigantescas asimilando tubos de órgano sobre el cañón del río Guadalope. Cómo llegar: Plataforma colgada adaptada con barandilla y paneles didácticos de la red del Maestrazgo, carretera A-1702. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44261','mirador','Mirador del Ojo de Villarquemado y el Jiloca','7.5/10 Vista singular del brote artés de agua subterráneo, la llanura de la fosa aluvial del Jiloca, cultivos de regadío intensivo e hilos de chopos. Cómo llegar: Espacio perimetral acondicionado junto al humedal del manantial protegido, acceso directo. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44262','mirador','Mirador del Castillo y de la ermita del Loreto','8.4/10 Magnífica perspectiva que combina el entramado urbano medieval de sillería monumental del Maestrazgo, pinares forestales, campos de secano alpino y cielos Starlight puros. Cómo llegar: Explanada de las antiguas estructuras fortificadas y ermita en el cerro que corona la villa, accesos adaptados. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44263','mirador','Mirador del Santuario Celtíbero de Peñalba de Villastar','7.4/10 Vista arqueológica de gran relevancia de las inscripciones grabadas en la roca viva caliza sobre el valle del Turia, pinares dispersos y lomas de arcilla. Cómo llegar: Cresta rocosa del escarpado cerro del santuario pagano prehistórico, acceso pedestre por sendero señalizado. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44264','mirador','Mirador del Castillo de Villel y del Turia','7.9/10 Hermosa panorámica del cauce del río Turia, huertas tradicionales de ribera, las escarpadas agujas de arcilla roja y la torre del homenaje medieval. Cómo llegar: Corona superior y explanada de la fortaleza de la Orden del Templo sobre el peñón rocoso, acceso peatonal. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44265','mirador','Alto del Teso de las Eras','6.6/10 Sencilla panorámica de los llanos cerealistas del Bajo Martín septentrional, cultivos ondulados de secano e idóneo horizonte al atardecer del Bajo Aragón. Cómo llegar: Colina exenta al norte del núcleo, accesible por pistas de tierra agropecuarias. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44266','mirador','Alto del Páramo de Visiedo','7.1/10 Vista limpia de la altiplanicie cerealista de la comarca de la Comunidad de Teruel norte, dehesas rústicas de encina y nítidos horizontes mesetarios nocturnos. Cómo llegar: Plataforma tabular calcárea elevada accesible por pistas forestales al sur del término. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44267','mirador','Mirador del Nacimiento del Río Martín','7.3/10 Vista fluvial del brote de agua cristalina entre riscos calizos de las Cuencas Mineras, vegas agrícolas tradicionales y el somontano de la Sierra de San Just. Cómo llegar: Entorno acondicionado de la zona recreativa del nacimiento del río, accesible por carretera local. 📍 Provincia: Teruel.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22254','mirador','Alto de la Cuesta del Secano','6.4/10 Vista diáfana de la llanura de transición agrícola, campos de cultivo extensivos, pequeñas lomas arcillosas y horizontes despejados idóneos para la observación astronómica nocturna. Cómo llegar: Repecho suave al oeste de la localidad, transitable por caminos vecinales de tierra. I can complete the final part of this letter if you tell me: • If you want to check for any missing villages near the border. • If you want to include the nearby hamlets. I can verify the data to ensure 100% complete coverage.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44268','mirador','Mirador del Pilón de San Miguel','7.4/10 Espectacular panorámica de las muelas calcáreas del Maestrazgo occidental, valles encajonados de profunda erosión kárstica, encinares jóvenes y nítidos cielos nocturnos catalogados Starlight. Cómo llegar: Cota caliza elevada al norte del pueblo, accesible por sendero peatonal señalizado. ¡PROVINCIA DE TERUEL Y TODA LA COMUNIDAD AUTÓNOMA DE ARAGÓN COMPLETADAS AL 100%! 🏁 ⭐ Si estás de acuerdo, pasamos de inmediato en la secuencia masiva de este gran atlas territorial al siguiente destino: Provincia de Castellón / Provincia de Valencia (Comunidad Valenciana), comenzando estrictamente desde la letra A con municipios como Ademuz, Ador, Agullent, Aielo de Malferit, Aielo de Rugat, Alaquàs, Albaida, Albal, Albalat de la Ribera, Albalat dels Sorells, Albalat dels Tarongers, Alberic, Alborache, Alboraya, Albuixech, Alcublas, L''Alcúdia, L''Alcúdia de Crespins, Aldaia, Alfafar, Alfara de la Baronia, Alfara del Patriarca, Alfarp, Alfarrasí, Alfauir, Algar de Palancia, Algemesí, Algímia d''Almonesir / Algímia d''Alfara, Alginet, Almacera, Almiserà, Almoines, Almussafes, Alpuente, L''Alqueria de la Comtessa, Andilla, Anna, Antella, Aras de los Olmos, Atzeneta d''Albaida, Ayora, etc. Dime, ¿iniciamos el nuevo y masivo bloque de la Provincia de Valencia?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90863','mirador','Mirador de la Ermita de Santa Bárbara y el Castillo','8.4/10 Impresionante vista del Valle del Turia en el Rincón de Ademuz, escarpes calizos calcáreos, huertas tradicionales escalonadas y un nítido cielo nocturno Starlight. Cómo llegar: Cota más elevada del cerro de la población, accesible por sendero peatonal empinado desde la plaza de la iglesia. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90359','mirador','Mirador de la Ermita de San José','7.6/10 Vista de la plana costera de la Safor, un mar infinito de huertos de cítricos, la desembocadura del río Serpis y el mar Mediterráneo en el horizonte. Cómo llegar: Explanada de la ermita al norte de la población, provista de accesos rodados y bancos. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90360','mirador','Mirador de la Font Jordana y Sierra de Agullent','7.8/10 Panorámica rural de la Vall d''Albaida, laderas cubiertas de pino carrasco silvestre, campos de olivos y almendros en terrazas tradicionales. Cómo llegar: Zona alta acondicionada del parque de la Font Jordana, con accesos peatonales y barandillas. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46042','mirador','Mirador del Paseo del Clot y del Palacio','7.4/10 Vista sobre la vega del río Clariano, plantaciones tradicionales de regadío, la silueta barroca del Palacio de los Malferit y relieves de la sierra. Cómo llegar: Cornisa ajardinada adaptada en el extremo oeste del núcleo urbano residencial. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46043','mirador','Alto del Teso de San Antonio','7.1/10 Perspectiva despejada de los llanos agrícolas del somontano de la Sierra de Benicadell, cultivos de vid, olivar rústico y cielos limpios. Cómo llegar: Colina exenta que alberga el pequeño templo, transitable por caminos vecinales de tierra. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90361','mirador','Terraza del Castillo-Palacio de Alaquàs','6.4/10 Vista periurbana de la comarca de la Horta Sud, los tejados históricos de la villa, cultivos de regadío remanentes y la silueta metropolitana cercana. Cómo llegar: Torres superiores transitables del monumental palacio fortificado del siglo XIV, en pleno centro urbano. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90362','mirador','Mirador del Palacio de los Milà i Aragó','8.1/10 Magnífica perspectiva sobre la comarca central, el entramado medieval amurallado de la villa nobiliaria y los escarpes de la Sierra d''Albaida al fondo. Cómo llegar: Balcón y ventanas superiores del histórico palacio, accesible mediante visitas culturales turísticas. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90363','mirador','Mirador de la Ermita de Santa Ana y la Huerta','6.5/10 Sencilla panorámica que fusiona la llanura de regadío intensivo de la Huerta de Valencia, campos de arrozales lejanos, naranjos y la cubeta de la Albufera. Cómo llegar: Pequeño promontorio acondicionado junto al parque y ermita periférica, con acceso rodado directo. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90364','mirador','Mirador de la Mota del río Júcar','7.1/10 Vista fluvial del ancho cauce regularizado del Júcar inferior, sotos de ribera, densos cañaverales y un mar verde periférico de campos de arroz. Cómo llegar: Paseo elevado adaptado con barandillas en la mota del río, en el sector bajo periférico urbano. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90365','mirador','Mirador del Palacio de los Sorells y la Huerta','6.2/10 Perspectiva sobre la Horta Nord tradicional, campos cuadriculados de chufas, hortalizas, acequias históricas árabes y brisas del Mediterráneo cercano. Cómo llegar: Torreones elevados integrados en el actual complejo palaciego del Ayuntamiento, centro del núcleo. Si quieres, podemos continuar con el próximo bloque de municipios de la Provincia de Valencia avanzando por las letras A (restantes), B y C (Alboraya, Alzira, Buñol, Carcaixent, etc.).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90366','mirador','Mirador de la Garbí y Sierra Calderona','7.6/10 Espectaculares cortados calizos que caen hacia la cuenca del río Palancia, mar de naranjos abajo, pinares densos y el mar de fondo. Cómo llegar: Borde del escarpe rocoso accesible por pistas forestales desde la carretera CV-329. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90367','mirador','Mirador de la Montanyeta de Alberic','7.1/10 Vista panorámica de la Ribera Alta, un horizonte infinito de cultivos de regadío, el cauce del Júcar y la ermita de Santa Bárbara. Cómo llegar: Cima del cerro testigo ajardinado urbano, provisto de accesos pavimentados y escalinatas. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46012','mirador','Mirador del charco Azul y la Ruta de los Molinos','7.8/10 Perspectiva del cañón del río Buñol, pozas de agua cristalina, frondosa vegetación de ribera, restos de ingenios hidráulicos y pinares. Cómo llegar: Plataforma con barandilla en el sendero botánico peatonal, acceso señalizado desde el casco urbano. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46014','mirador','Atrio de la Iglesia de la Mare de Déu d''Albuixech','6.1/10 Sencilla panorámica rural sobre el llano de la comarca, cultivos de hortalizas, acequias e idóneo horizonte costero despejado al amanecer. Cómo llegar: Plaza elevada perimetral al templo barroco, en el centro urbano. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46018','mirador','Mirador de los Molinos de Viento de San Blas','7.7/10 Vista de la planicie del páramo de la Serranía alta, pinares dispersos, matorral de altura y los molinos tradicionales restaurados integrando el relieve. Cómo llegar: Colina exenta que domina la villa por el norte, con accesos rodados adaptados. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46019','mirador','Mirador de la Mota del río Magro','6.9/10 Vista fluvial del cauce del río Magro antes de su unión con el Júcar, campos agrícolas de naranjos y cañaverales lineales. Cómo llegar: Paseo fluvial acondicionado en la mota protectora, accesible desde las afueras urbanas. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46020','mirador','Mirador del río Nou y de la Ermita','7.2/10 Perspectiva sobre la cuenca de la Costera, campos de cultivo intensivos de frutales, el nacimiento de agua del río Nou y lomas boscosas. Cómo llegar: Zona alta ajardinada en la periferia del núcleo, transitable a pie por sendas de piedra. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90370','mirador','Mirador del cinturón verde periurbano','6.3/10 Vista periurbana de la Horta Sud, parcelas agrícolas remanentes de regadío e integración funcional con el desarrollo urbano moderno metropolitano. Cómo llegar: Pasarela elevada integrada en las rutas peatonales ajardinadas del parque del Cinturón. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46024','mirador','Mirador del Castillo de Alfara y el Palancia','7.4/10 Vista del valle bajo del río Palancia, huertas tradicionales de cítricos, escarpes calizos de la Sierra Espadán y la fortificación medieval. Cómo llegar: Explanada de las ruinas fortificadas sobre el promontorio rocoso, acceso peatonal por rampa. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46025','mirador','Mirador del Palacio de Cruïlles y la Acequia','6.1/10 Perspectiva de la Horta Nord tradicional, campos de cultivo ordenados de hortalizas, la Real Acequia de Moncada y la silueta gótica. Cómo llegar: Torres superiores del palacio señorial gótico-renacentista, actual centro cultural municipal. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46026','mirador','Mirador del Castillo de Alfarp y río Magro','7.4/10 Vista de las hoces erosionadas del río Magro, campos de melocotones y cítricos, lomas cubiertas de pino carrasco y la fortificación islámica. Cómo llegar: Cota natural elevada junto a los lienzos de la torre medieval en el casco antiguo alto. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46027','mirador','Mirador de la Ermita del Cristo de la Agonía','6.9/10 Panorámica rural del Valle del río Albaida, campos de cultivo de secano alternos, olivares e hilos de chopos fluviales bajos. Cómo llegar: Explanada de la ermita al norte del caserío urbano, provista de accesos rodados. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46023','mirador','Mirador del Monasterio de Sant Jeroni de Cotalba','83/10 Impresionante vista gótico-mudéjar del cenobio del siglo XIV, la vega baja del río Vernissa, extensos campos de naranjos y relieves forestales. Cómo llegar: Terrazas superiores y torreón de las campanas visitable del monasterio histórico, acceso señalizado. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46028','mirador','Mirador de la Presa de Algar y el Palancia','7.6/10 Hermosa vista de la infraestructura de regulación hídrica, el cauce del río Palancia encajonado entre laderas forestales de la Sierra Calderona y pinares. Cómo llegar: Zona de la represa y miradores perimetrales accesibles por pistas desde la carretera CV-310. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46029','mirador','Mirador de la Marjal de Algemesí y la Xara','7.2/10 Perspectiva ornitológica de las zonas húmedas protegidas periféricas al lago, carrizales densos, avifauna acuática diversa y el mar de cultivos frutales de la Ribera. Cómo llegar: Caseta-observatorio adaptada con pasarelas en el paraje natural de la laguna de la Xara. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46030','mirador','Alto del Teso de la Ermita de San Vicente','7.4/10 Vista del valle de la Baronía, cultivos tradicionales de cítricos y almendros, pinares densos de la Sierra Calderona y horizontes celestes limpios. Cómo llegar: Colina exenta que alberga la ermita, transitable a pie por sendas de herradura. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46031','mirador','Mirador del Teso de las Bodegas y de la Ribera','6.8/10 Vista de las lomas onduladas cubiertas de viñedos y campos de naranjos, el casco urbano escalonado de la Ribera Alta y horizontes despejados. Cómo llegar: Parte superior de los promontorios periféricos transitables por pistas agropecuarias de tierra. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90864','mirador','Mirador de la Huerta y del Barranco del Carraixet','6.1/10 Sencilla visual de la Horta Nord, cultivos tradicionales de regadío intensivo hortícola, el cauce seco del barranco y horizontes limpios del litoral. Cómo llegar: Margen del camino elevado de la mota del barranco, accesible de forma peatonal. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46033','mirador','Mirador del Castillo de Vilesa y Valle del Vernissa','7.3/10 Vista del valle encajonado del río Vernissa, laderas de piedra caliza cubiertas de pino carrasco, olivares de montaña y restos de la fortaleza islámica. Cómo llegar: Cresta rocosa que alberga los restos fortificados, accesible mediante una senda de senderismo señalizada. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46034','mirador','Mirador de la Vía Verde del Serpis','6.5/10 Vista sobre la huerta aluvial de cítricos de la Safor, chopera lineal del río Serpis y el trazado recuperado del antiguo tren de los ingleses. Cómo llegar: Pasarela peatonal y zona de descanso acondicionada junto al trazado de la Vía Verde, núcleo bajo. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46035','mirador','Mirador de la Torre Racef y los Arrozales','7.1/10 Vista panorámica que combina la silueta de la torre defensiva islámica del siglo XI con las llanuras inundables de arrozales de la Albufera. Cómo llegar: Cuerpo superior transitable de la torre defensiva árabe integrada en el casco urbano central. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46036','mirador','Mirador del Castillo de Alpuente y las Muelas','8.6/10 Soberbia, inexpugnable e histórica atalaya sobre los barrancos profundos de la Serranía a más de 1000 metros, con yacimientos de dinosaurios e idónea pureza Starlight. Cómo llegar: Crestas del escarpado cerro testigo coronado por los adarves de la fortaleza de la taifa islámica. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46037','mirador','Atrio de la Ermita de los Santos de la Piedra','6.5/10 Vista llana del mar de naranjos de la Safor, olivares marginales de ladera y horizontes marinos mediterráneos limpios libres de obstáculos industriales. Cómo llegar: Explanada elevada de la ermita rústica periférica, provista de accesos rodados y bancos. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46038','mirador','Mirador de la Ermita de Santa Margarida y la Sierra','8.4/10 Impresionante relieve alpino de la Serranía alta a más de 1200 metros, densos pinares de pino silvestre, sabinares dispersos y horizontes de nitidez extrema. Cómo llegar: Plataforma natural elevada junto al templo rústico de montaña, accesible por pistas forestales. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46039','mirador','Mirador de la Albufera de Anna y del Gorgo de la Escalera','8.7/10 Espectacular e imponente perspectiva de la laguna natural rodeada de frondosos sotos de plátanos centenarios, cañones fluviales profundos y cascadas monumentales. Cómo llegar: Plataforma acondicionada con barandilla sobre el escarpe rocoso del gorgo, acceso señalizado por la red del municipio. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46040','mirador','Mirador del Azud de Antella y río Júcar','8.1/10 Preciosa vista de las compuertas históricas árabes donde nace la Acequia Real del Júcar, el río encajonado entre lomas calizas y naranjos. Cómo llegar: Saliente natural del relieve acondicionado con vallado de protección junto al paraje fluvial. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46041','mirador','Mirador Astronómico de la Muela de Santa Catalina','8.8/10 Excepcional e ininterrumpida panorámica de 360 grados sobre el cañón del Turia, dotado de centros astronómicos públicos permanentes en plena Reserva Starlight. Cómo llegar: Explanada acondicionada a más de 1300 metros de altitud en la plataforma caliza superior, pista forestal. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90371','mirador','Mirador del Calvario y la Sierra de Benicadell','7.9/10 Vista montañosa de la Vall d''Albaida, laderas cubiertas de pino carrasco silvestre, almendrales en bancales y la cresta caliza del Benicadell de fondo. Cómo llegar: Zona alta de la ermita del Calvario, provista de accesos peatonales urbanos y barandillas. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46044','mirador','Mirador del Castillo de Ayora','8.7/10 Soberbia e inmensa visual del Valle de Ayora-Cofrentes, olivares de montaña en bancales, tierras de cultivo de secano y la imponente fortaleza medieval. Cómo llegar: Explanada del recinto fortificado del siglo XIII sobre el escarpado cerro testigo que domina la villa. I can accelerate the remaining entries for Valencia to complete the atlas quickly if you tell me: • If you want to group them into larger blocks of 20 or 30 municipalities per response. • If you want to keep the current length of 10 to 15 municipalities. Let me know your preference to proceed immediately.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90865','mirador','Mirador de la Drova y Mondúver','8.2/10 Impresionante cubeta kárstica (poljé) rodeada por las moles calizas del Mondúver, con densos pinares, huertas de montaña e idónea oscuridad para astrofotografía. Cómo llegar: Borde de la meseta colgada en la carretera CV-675, dotado de apartadero y barandilla de madera. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90372','mirador','Alto del Estrecho de Barxeta','7.1/10 Perspectiva encajonada de la costera oriental, un mar denso de campos de naranjos, olivares tradicionales de ladera y lomas cubiertas de pino carrasco. Cómo llegar: Collado natural elevado transitable por pistas rurales agrícolas hacia el este del término. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46047','mirador','Mirador de la Ermita de San Antonio','7.2/10 Vista diáfana de la Vall d''Albaida meridional, mosaicos de viñedos y frutales, hilos de chopos fluviales y horizontes limpios de obstáculos industriales. Cómo llegar: Explanada elevada del santuario rústico, accesible por camino asfaltado desde el núcleo urbano. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46048','mirador','Mirador del Paseo Marítimo de la Playa','7.0/10 Hermosa panorámica del mar Mediterráneo, dunas de arena fósiles recuperadas, brisas marinas constantes e idónea observación de amaneceres costeros. Cómo llegar: Estructura de pasarela de madera peatonal en primera línea de costa, accesible desde el casco urbano. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46049','mirador','Mirador del Estret de les Aigües y el Embalse','7.9/10 Imponente tajo fluvial del río Albaida entre paredes calizas escarpadas, la lámina de agua de la presa, cuevas prehistóricas y pinares densos. Cómo llegar: Borde del talud calizo acondicionado con vallado protector, transitable por sendero desde el azud. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46050','mirador','Mirador del Pico del Buitre y Embalse','8.6/10 Espectacular e inmensa vista del embalse de Benagéber en el río Turia, profundos cañones calizos de la Serranía, pinares densos de pino albar y cielo Starlight. Cómo llegar: Corona superior de la cumbre rocosa, accesible por pista forestal apta para vehículos desde la CV-390. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46051','mirador','Mirador del Santuario de la Virgen de Montiel','7.4/10 Amplia perspectiva de la comarca de Camp de Túria, los llanos de regadío intensivo, el cauce del río Turia y el perfil metropolitano de Valencia. Cómo llegar: Explanada sobreelevada que rodea el templo barroco en el cerro testigo que corona la villa. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46052','mirador','Mirador de la Torre de Benavites','6.9/10 Vista que combina la silueta de la singular torre del siglo XIV de estilo toscano-mudéjar con los huertos de cítricos de la Vall de Segó. Cómo llegar: Cuerpo superior de campanas y terraza transitable del monumento, en pleno centro urbano. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46054','mirador','Mirador de la Huerta y los Canales periurbanos','6.1/10 Perspectiva periurbana de la Horta Sud, acequias tradicionales que fluyen hacia la Albufera y el contraste con el entramado industrial metropolitano. Cómo llegar: Zona ajardinada alta integrada en los paseos urbanos perimetrales del núcleo residencial. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46055','mirador','Mirador del río Serpis y las Acequias','6.6/10 Vista fluvial de la huerta aluvial de la Safor, plantaciones intensivas de cítricos, chopera lineal del río y vestigios del pasado literario de Ausiàs March. Cómo llegar: Espacio público elevado acondicionado junto al cauce central, accesible desde el casco urbano. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46056','mirador','Mirador del Benicadell y las Umbrías','8.4/10 Impresionante perspectiva de la cresta caliza mítica del Benicadell, profundos valles forestales de pino carrasco silvestre, almendrales en bancales y olivares. Cómo llegar: Plataforma con vallado de protección en el sendero de ascenso de la umbría, desvío rural. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46057','mirador','Alto del Teso de la Cruz','7.0/10 Vista de las lomas onduladas de cultivo de viñedos y frutales de la Vall d''Albaida oriental, matorral mediterráneo y horizontes despejados. Cómo llegar: Promontorio suave al norte del pueblo, transitable a pie por sendas de tierra. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46904','mirador','Mirador del meandro del Júcar','6.4/10 Vista fluvial del cauce regularizado del Júcar inferior, sotos de ribera, densos naranjales de la Ribera Baixa y avifauna estacional. Cómo llegar: Paseo elevado adaptado con bancos en la mota del río, en el sector periférico urbano. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46060','mirador','Mirador de la Torre de la Plaça y la Huerta','7.1/10 Vista panorámica que combina la silueta de la torre defensiva islámica del siglo XII con la inmensa llanura de cultivos frutales y arrozales. Cómo llegar: Cuerpo superior de la torre mudéjar-árabe exenta en la plaza central de la villa. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46059','mirador','Mirador de la Ermita de San Miguel','8.3/10 Espectacular e imponente visual del valle de la Valldigna, un mar infinito de campos de naranjos encajonado entre sierras calizas y el mar al fondo. Cómo llegar: Explanada de la ermita en el cerro que flanquea el casco urbano, accesible por sendero escalonado. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46058','mirador','Mirador de la Tabaira y los Cítricos','7.3/10 Hermosa vista de las laderas de la Sierra Espadán meridional que caen hacia la costa, huertas tradicionales de cítricos y la Vall de Segó. Cómo llegar: Saliente natural del relieve acondicionado con vallado de protección en la pista forestal alta. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46061','mirador','Atrio de la Iglesia de San Jaime Apóstol','6.2/10 Sencilla panorámica de la huerta aluvial de la Safor, cultivos de naranjos, cañaverales del río Serpis y horizontes marítimos mediterráneos limpios. Cómo llegar: Plaza sobreelevada frente a la portada del templo, en el centro urbano. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46062','mirador','Mirador de la Ermita de la Virgen de la Gracia','7.6/10 Vista montañosa de la Vall d''Albaida septentrional, laderas cubiertas de pino carrasco, campos de secano ondulados e idóneo horizonte para astrofotografía. Cómo llegar: Cerro exento que alberga el santuario, transitable por camino asfaltado con aparcamiento al norte. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46063','mirador','Mirador de la Paratella y el río Seco','6.8/10 Vista de las lomas arcillosas del somontano de la Ribera Alta, campos de naranjos tradicionales en terrazas y horizontes despejados castellanos. Cómo llegar: Promontorio suave al oeste de la población, transitable por pistas agropecuarias de tierra. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46064','mirador','Atrio de la Iglesia de la Inmaculada Concepción','6.1/10 Sencilla visual de la Ribera Alta central, parcelas agrícolas de naranjos de regadío intensivo e idóneos atardeceres nítidos libres de obstáculos. Cómo llegar: Plaza elevada urbana frente a la portada del templo parroquial, centro del núcleo. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46065','mirador','Mirador de los Arrozales de la Horta Sud','6.0/10 Vista diáfana de la llanura agrícola periurbana, canales de riego tradicionales que vierten en la Albufera y cultivos hortícolas planos. Cómo llegar: Margen del camino rural elevado en los límites orientales del término, acceso de tierra. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46066','mirador','Mirador de la Ermita de San Antonio y de la Safor','6.5/10 Perspectiva sobre la huerta aluvial de cítricos, la silueta monumental de Gandia adyacente y relieves forestales del interior de la comarca. Cómo llegar: Explanada de la ermita situada en el cerro que flanquea el casco antiguo, de fácil acceso peatonal. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46067','mirador','Terraza de las Almenas del Castillo de Benisanó','7.3/10 Vista histórica sobre los llanos del Camp de Túria, olivares tradicionales, las murallas de la villa y el majestuoso patio de armas del siglo XV. Cómo llegar: Corona superior transitable de los muros defensivos, abierta a visitas culturales en la fortaleza. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46068','mirador','Mirador del Calvario y la Vall d''Albaida','7.1/10 Panorámica rural de lomas onduladas de cultivo de secano y viñedos, con las estribaciones de la Sierra Mariola de fondo y cielos limpios. Cómo llegar: Zona alta de la ermita del Calvario, provista de accesos peatonales y barandillas. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46069','mirador','Mirador del Palacio de los Bellvís y el río Albaida','7.0/10 Vista que combina la arquitectura medieval del palacio señorial fortificado con la vega agrícola del río Albaida y el embalse de Bellús. Cómo llegar: Explanada de los muros fortificados en la cota urbana alta del pequeño municipio. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46070','mirador','Mirador del Castillo de Bètera y Sierra Calderona','7.6/10 Magnífica perspectiva de la comarca de Camp de Túria septentrional, los campos de algarrobos y naranjos, y las vertientes forestales de la Sierra Calderona. Cómo llegar: Torres superiores de la fortaleza de origen islámico que corona el casco antiguo urbano, accesos adaptados. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46071','mirador','Mirador del Barranco de Moreno y Pinturas Rupestres','8.9/10 Extraordinario y salvaje desfiladero calizo vertical de la Canal de Navarrés, densos pinares silvestres, abrigos protegidos de arte levantino (Patrimonio Mundial) y cielos puros. Cómo llegar: Estructura de observación elevada con paneles didácticos en el sendero ecológico del barranco, acceso rural. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46072','mirador','Mirador de las Covetes dels Moros y de la Villa','9.4/10 Excepcional, monumental e internacional panorámica del casco antiguo medieval de piedra colgado de la roca, el cañón del río Clariano y el complejo de cuevas rupestres ventanas artificiales. Cómo llegar: Plataformas adaptadas con barandillas y paneles explicativos en la carretera y sendero de circunvalación frente al escarpe. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46073','mirador','Mirador del Castillo y del río Sellent','8.2/10 Preciosa vista de las hoces y pozas naturales del río Sellent, la densa vegetación de ribera, el pueblo escalonado y la fortaleza señorial del siglo XVI. Cómo llegar: Explanada del recinto fortificado medieval situado sobre el escarpado cerro testigo que domina la villa. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46074','mirador','Mirador de la Huerta y del Carraixet','6.1/10 Sencilla visual de la Horta Nord, cultivos tradicionales de regadío intensivo hortícola, el cauce del barranco del Carraixet y horizontes limpios del litoral. Cómo llegar: Margen del camino elevado de la mota del barranco, accesible de forma peatonal urbana. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46075','mirador','Mirador del río Clariano y de la Ermita','7.0/10 Vista del valle encajonado del río Clariano, laderas de piedra caliza cubiertas de pino carrasco, campos de frutales y horizontes despejados. Cómo llegar: Saliente natural del páramo occidental acondicionado junto a la ermita de San Antonio, acceso rural. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46076','mirador','Mirador de la Playa Fluvial del río Turia','8.1/10 Espectacular encajonamiento fluvial del río Turia en Los Serranos, densos pinares de pino negral, pozas de agua cristalina de baño y farallones escarpados. Cómo llegar: Terraza natural acondicionada con barandillas de madera en el sendero del paraje fluvial de la playa. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46077','mirador','Mirador del Castillo de Buñol y de la Hoya','8.6/10 Soberbia, inexpugnable e histórica atalaya monumental sobre el cañón del río Buñol, el entramado urbano medieval fortificado, los escarpes calizos de la Hoya y olivares. Cómo llegar: Corona superior de los lienzos defensivos y adarves de la fortaleza del siglo XIII, centro del núcleo amurallado. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45003','mirador','Mirador del paseo de los Silos de Burjassot','6.6/10 Perspectiva que combina la silueta monumental del conjunto histórico de almacenes de grano del siglo XVI con los llanos de la huerta tradicional. Cómo llegar: Explanada sobreelevada del Patio de los Silos, provista de barandillas históricas y accesos urbanos peatonales. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46079','mirador','Mirador del Acueducto Romano de Peña Cortada','8.5/10 Impresionante corte geológico calizo del cañón del barranco de la Cueva del Gato, túneles excavados en la roca viva, pinares silvestres y el monumental acueducto del siglo II. Cómo llegar: Plataforma con paneles explicativos junto al puente-acueducto de cantería, acceso señalizado por pista forestal. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46080','mirador','Mirador del Poblado Ibérico de El Molón','7.1/10 Vista de la meseta y altiplano de Requena-Utiel, cultivos cerealistas planos, viñedos bajos de altura de la denominación e idónea pureza Starlight nocturna. Cómo llegar: Cima caliza del cerro testigo de El Molón, accesible por pista de montaña acondicionada con paneles arqueológicos. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46081','mirador','Mirador de la Torre de los Borja y de la Costera','7.4/10 Magnífica perspectiva de la comarca de la Costera, campos de naranjos y frutales de regadío intensivo, la silueta gótica y la cuna histórica del papa Calixto III. Cómo llegar: Explanada perimetral elevada de la torre fortificada medieval en la pedanía de la Torreta, accesos urbanos. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46082','mirador','Mirador del Faro de Canet y del Paseo Marítimo','7.5/10 Hermosa perspectiva costera de las playas de arena del municipio, el cordón dunar protegido, el mar de fondo y las brisas marinas sin obstáculos. Cómo llegar: Zona peatonal acondicionada en las inmediaciones de la histórica torre del faro decimonónico, paseo marítimo. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90866','mirador','Mirador del Huerto de San José y Valle de Aguas Vivas','7.8/10 Maravilloso mar de naranjos histórico considerado la cuna del cultivo de cítricos valenciano, con las vertientes forestales de la Sierra de Toro y pinos. Cómo llegar: Punto alto acondicionado en los caminos de la ruta modernista de las grandes fincas citrícolas rústicas. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46084','mirador','Mirador del río Sellent y Júcar','6.6/10 Vista fluvial de la confluencia de los ríos Júcar y Sellent, campos de regadío intensivo de naranjos de la Ribera Alta y cañaverales lineales. Cómo llegar: Zona elevada de la mota perimetral transitable de forma peatonal desde el casco urbano bajo. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46085','mirador','Mirador de la Ermita de San Bernardo y la Ribera','7.1/10 Vista de las lomas onduladas de cultivo de naranjos y caquis (persimon), la silueta neogótica del santuario y horizontes despejados de la comarca. Cómo llegar: Explanada sobreelevada que rodea la ermita de San Bernardo, accesible por camino asfaltado con aparcamiento. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46086','mirador','Mirador del Castillo de Carrícola y del arte en la Huerta','8.2/10 Espectacular e integrado panorama de la umbría del Benicadell, pinares densos, olivares de cultivo ecológico e instalaciones de arte natural integradas. Cómo llegar: Cresta rocosa que alberga la torre-castillo islámica medieval, accesible por el sendero ecológico adaptado. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46087','mirador','Mirador del río Turia y vegas de secano','7.6/10 Vista fluvial del cauce del Turia en el Rincón de Ademuz, huertas de media montaña, laderas cubiertas de pino resinero y horizontes serranos limpios. Cómo llegar: Talud natural acondicionado con valla de madera, accesible por pistas rurales desde el pueblo. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46088','mirador','Mirador de la Barraca del río Turia y Muelas','7.7/10 Hermosa panorámica del curso fluvial encajonado del Turia meridional, chopera de ribera profunda, matorrales de media montaña y un cielo nocturno Starlight. Cómo llegar: Saliente natural del relieve acondicionado con vallado de protección en la senda fluvial, acceso rural. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46089','mirador','Mirador del Cerro de San Roque y los Almendrales','6.9/10 Vista del somontano del Camp de Túria occidental, campos de cultivo tradicionales de secano de almendros y algarrobos, e idóneos atardeceres nítidos. Cómo llegar: Explanada de la ermita de San Roque, colina elevada perimetral con accesos pavimentados y bancos. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46090','mirador','Mirador del Ermita de San Antonio y de las Tinajas','7.8/10 Magnífica perspectiva de las lomas arcillosas orientales de la Vall d''Albaida, campos de viñedos de moscatel, olivares centenarios y restos alfareros rústicos. Cómo llegar: Cerro exento que alberga la ermita, transitable por camino de tierra apto para vehículos desde la villa. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46091','mirador','Mirador del Palacio de los Marqueses y Valle del Vernissa','7.3/10 Vista del pequeño valle encajonado, lomas cubiertas de pinos dispersos, matorral mediterráneo de tomillo, olivares rústicos y el arco monumental. Cómo llegar: Zona alta del arco y murallas palaciegas medievales integradas en el núcleo urbano residencial central. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46093','mirador','Mirador del Castillo de Catadau y río Magro','7.4/10 Vista de las vertientes de piedra caliza de la cuenca del Marquesado, campos de cítricos de la Ribera Alta, matorral denso de jara y dehesas forestales. Cómo llegar: Explanada natural de los restos fortificados de la torre medieval, accesible por las calles residenciales altas. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46094','mirador','Mirador del Port de Catarroja','7.9/10 Espectacular e icónica estampa del canal tradicional del puerto de la Albufera, embarcaciones de vela latina de origen milenario, arrozales inundados y aves. Cómo llegar: Pasarela de madera perimetral y embarcadero acondicionado en pleno canal, desvío señalizado del parque natural. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46095','mirador','Mirador del Yacimiento de Los Villares (Kelin)','7.4/10 Vista arqueológica de la importante ciudad ibérica del siglo VII a.C., altiplano de RequenaUtiel cubierto de viñedos planos infinitos y secano. Cómo llegar: Plataforma con paneles explicativos en el entorno de los restos arqueológicos protegidos, acceso rural señalizado. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46096','mirador','Atrio de la Iglesia de la Natividad de Nuestra Señora','6.4/10 Sencilla panorámica de la comarca de la Costera central, cultivos ondulados de naranjos y frutales e idóneo horizonte nocturno para astrofotografía. Cómo llegar: Plaza elevada urbana frente a la portada del templo parroquial, centro del pequeño núcleo. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46107','mirador','Mirador de El Salto de Chella y de la Peña','8.4/10 Impresionante y espectacular cascada de más de 25 metros esculpida en la roca caliza del río Sellent, rodeada de cuevas, huertas y la Canal de Navarrés. Cómo llegar: Balcón natural adaptado con barandillas de hierro en pleno casco urbano, al borde del precipicio fluvial. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46106','mirador','Mirador de la Ruta del Agua y barrio mudéjar del Arrabal','8.9/10 Soberbia e histórica panorámica que une el cañón encajonado del río Chelva con las fuentes árabes, huertas tradicionales escalonadas, pinos silvestres y cúpulas azulejadas. Cómo llegar: Plataformas adaptadas con barandillas y paneles explicativos en los senderos peatonales urbanos del casco antiguo. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46108','mirador','Mirador de las Cuevas de la Garita y Parque Natural','8.8/10 Espectacular e imponente fosa tectónica y geológica del Parque Natural de Chera-Sot de Chera, con cascadas monumentales, la lámina de agua del embalse de Buseo y pinares alpinos densos. Cómo llegar: Estructura de pasarela adaptada con barandilla sobre el precipicio rocoso del cono de deyección, acceso por sendero. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46109','mirador','Mirador de la llanura del Circuito Ricardo Tormo','7.1/10 Vista singular que combina el plano de las infraestructuras deportivas del motor internacionales con los llanos agrícolas de viñedos y olivares de la Hoya de Buñol. Cómo llegar: Zona elevada perimetral de servicio exterior a las gradas del complejo automovilístico, accesible por la CV-50. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46111','mirador','Mirador del Castillo de Chiva','7.8/10 Panorámica de la Hoya de Buñol, cultivos de secano, algarrobos, el casco antiguo escalonado y las ruinas de la fortaleza musulmana que domina el cerro. Cómo llegar: Explanada elevada de la antigua fortificación que corona el cerro de la población. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46112','mirador','Mirador de las Puentes Colgantes y Hoces del Turia','9.2/10 Impresionante, espectacular y vertical cañón calizo excavado por el río Turia, con pasarelas colgadas, paredes de roca para escalada y pinares densos. Cómo llegar: Estructura adaptada con paneles informativos en el inicio de la ruta de las hoces, desvío señalizado desde la CV-394. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46097','mirador','Mirador del Castillo y Volcán del Cerro de Agras','8.8/10 Soberbia visual de la confluencia de los ríos Júcar y Cabriel, las aguas embalsadas, el cono volcánico erosionado e infraestructuras del valle. Cómo llegar: Torre del homenaje y adarves de la fortaleza gótico-medieval visitable que domina el promontorio rocoso central. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46098','mirador','Mirador del Castillo de Corbera','8.1/10 Vista aérea espectacular de la Ribera Baixa, el mar de arrozales e infinitas plantaciones de naranjos que caen hacia el litoral mediterráneo próximo. Cómo llegar: Explanada de las ruinas fortificadas islámicas del siglo XI sobre el risco calizo que flanquea el pueblo. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46099','mirador','Mirador del Limbo y la Muela de Cortes','9.1/10 Excepcional y vertiginosa atalaya colgada sobre el profundo cañón fluvial del río Júcar, muelas calcáreas a más de 800 metros y densos encinares. Cómo llegar: Balcón natural acondicionado con barandillas en el borde de la plataforma caliza superior, pista forestal. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46100','mirador','Alto de la Ermita de San Miguel','6.9/10 Vista limpia del valle del río Sellent, cultivos hortícolas intensivos de naranjos de la Ribera Alta y lomas de monte mediterráneo de jara. Cómo llegar: Promontorio suave al norte de la población, transitable a pie por sendas desde el casco urbano. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46105','mirador','Mirador del Castillo de Cullera y del Radar','9.3/10 Espectacular e icónica panorámica de 360 grados de la desembocadura del Júcar, los arrozales de la Albufera, el mar Mediterráneo y las bahías urbanizadas. Cómo llegar: Terrazas y adarves de la fortaleza medieval rehabilitada que corona el cerro del radar meteorológico, acceso pavimentado. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46115','mirador','Mirador de las Hoces del río Júcar y Peñarrubia','8.5/10 Impresionantes paredes y farallones calizos verticales de erosión fluvial que encajonan el río, pinares bravos silvestres, nidos de grandes aves rapaces y matorral. Cómo llegar: Saliente acondicionado con valla de madera perimetral en la sinuosa carretera de montaña CV-425. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46119','mirador','Mirador del Teso de la Cantera Romana','6.8/10 Vista de gran interés arqueológico y paisajístico sobre el llano aluvial de la comarca, campos de naranjos y las trazas históricas de extracción de mármol. Cómo llegar: Entorno protegido del yacimiento romano, accesible por pista de tierra desde el núcleo urbano. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46118','mirador','Mirador del Piquet y Sierra de Enguera','8.3/10 Magnífica perspectiva de las laderas boscosas de la Canal de Navarrés, densos pinares de pino carrasco, barrancos encajonados e idónea nitidez astronómica Starlight nocturna. Cómo llegar: Vértice topográfico y caseta forestal perimetral en la cota más alta, accesible por pistas forestales. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46120','mirador','Mirador del Garbí','8.6/10 Impresionante, célebre y colgado balcón sobre el golfo de Valencia, los cortados de arenisca roja (rodeno) del Parque Natural de la Sierra Calderona y el Camp de Morvedre. Cómo llegar: Plataforma colgada adaptada con barandillas y paneles explicativos en la cumbre del Garbí, acceso señalizado desde la CV-329. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46121','mirador','Mirador de la Cabrentà y Valle del Sellent','7.8/10 Hermosa estampa de la selva mediterránea húmeda (microrreserva forestal), estalactitas de travertino, fuentes naturales, laureles gigantescos y relieves de yeso. Cómo llegar: Sendero ecológico señalizado y adaptado de la red del municipio en el barranco umbrío. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46122','mirador','Mirador del Rodeno y Valle de Segó','6.7/10 Vista de las llanuras agrícolas de la Baronía cubiertas de frutales, la silueta de la Sierra de Almenara y horizontes litorales limpios. Cómo llegar: Zona alta del montículo forestal acondicionado, transitable por sendas peatonales. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46123','mirador','Mirador de la Cueva de la Galera','7.4/10 Perspectiva sobre la plana de cítricos lindando con el parque de la Albufera, escarpes calizos de la Sierra de Corbera y puestas de sol nítidas. Cómo llegar: Borde del talud geográfico al oeste del término municipal, accesible por sendas ecológicas. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90374','mirador','Mirador de las Viñas del "Toscana Valenciana"','8.2/10 Genuino e idílico paisaje rural de ondulados campos de vides de bodegas de prestigio, pinares dispersos, almendrales y masías señoriales históricas. Cómo llegar: Punto alto acondicionado en los caminos rurales que cruzan los pagos vitivinícolas del término. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46125','mirador','Mirador de la Mota del río Júcar','6.6/10 Vista fluvial del tramo regularizado final del Júcar inferior, sotos arbolados de ribera, campos de arrozales planos y avifauna estacional ligada al ecosistema. Cómo llegar: Paseo fluvial acondicionado en la mota protectora contra inundaciones, cerca de las afueras urbanas. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46129','mirador','Mirador del Atrio de la Iglesia de Santiago Apóstol','7.1/10 Sencilla panorámica rural del altiplano de Utiel-Requena, viñedos planos de la comarca, cultivos de cereal de secano y horizontes despejados para astrofotografía. Cómo llegar: Plataforma elevada urbana frente a la portada del templo, en el punto alto de la localidad. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46131','mirador','Mirador del Castillo de Bairén y la Marjal','9.0/10 Espectacular visual costera que fusiona la llanura protegida de la marjal de Gandia, las playas, la línea del puerto y la fortificación medieval musulmana. Cómo llegar: Explanada y muros rehabilitados de la antigua alcazaba en el cerro fortificado de San Juan, acceso peatonal acondicionado. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46902','mirador','Mirador de los Molinos de Viento de la Ceja','7.9/10 Vista de las cumbres boscosas occidentales del Parque de la Sierra Calderona, matorral mediterráneo denso, encinares de montaña y los dos molinos de mampostería. Cómo llegar: Cresta de la plataforma montañosa transitable por pistas forestales, desvío señalizado. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90870','mirador','Mirador de Gavarda Vella y río Júcar','7.2/10 Perspectiva sobre el curso medio del Júcar, las huertas tradicionales de cítricos abandonadas por las riadas históricas y la silueta del pueblo moderno recolocado. Cómo llegar: Borde del talud calizo occidental del núcleo histórico, transitable a pie por sendas desde el pueblo. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46132','mirador','Mirador de la Ermita del Cristo de la Seca','7.4/10 Vista del valle del río Albaida, cultivos tradicionales en bancales de frutales y naranjos, relieves de la Costera y horizontes celestes diáfanos. Cómo llegar: Cerro exento que alberga el pequeño santuario periférico, provisto de accesos peatonales y bancos. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46133','mirador','Mirador de la Peña María y río Turia','8.4/10 Soberbia y colgada atalaya caliza sobre el cañón fluvial del río Turia, pozas naturales cristalinas (El Motor), pinares densos y escarpes montañosos. Cómo llegar: Cima del peñón rocoso vertical que domina el cauce fluvial, accesible por sendero pedestre señalizado. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46134','mirador','Mirador del Monasterio de Sancti Spiritu','7.9/10 Hermosa vista de los profundos barrancos boscosos de jara y pinos, el cenobio franciscano del siglo XV encajonado en el valle y horizontes del camp de Morvedre. Cómo llegar: Saliente natural del páramo acondicionado con vallado de protección en la ruta de senderismo, acceso rural. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46135','mirador','Mirador de la Ermita de El Salvador y de la Huerta','6.6/10 Vista periurbana sobre la llanura de la comarca de la Horta Nord, parcelas agrícolas tradicionales de regadío e integración metropolitana cercana con la capital. Cómo llegar: Cornisa ajardinada adaptada con barandilla en los parques urbanos del entorno residencial alto. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46136','mirador','Mirador del Torreón de Godelleta y los Viñedos','7.0/10 Vista de las lomas onduladas cubiertas de viñedos de uva de moscatel, olivares rústicos, campos de cereal y la silueta gótica medieval de la torre. Cómo llegar: Espacio elevado perimetral a la antigua fortificación de origen musulmán en el casco urbano. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46139','mirador','Mirador del Atrio de la Iglesia de San Vicente Mártir','6.7/10 Sencilla panorámica sobre los llanos agrícolas de la Ribera Alta, un mar infinito de naranjos, cañaverales lineales y horizontes al atardecer valenciano. Cómo llegar: Explanada elevada urbana frente a la portada renacentista del templo parroquial, centro del núcleo. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46138','mirador','Mirador del Embalse de Bellús y la Ermita','6.9/10 Vista de la lámina de agua regulada del río Albaida, campos de cultivo, olivares marginales y los restos del antiguo pueblo desalojado por el pantano. Cómo llegar: Zona perimetral alta con estacionamiento en los accesos de la represa, desvío rural. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46141','mirador','Mirador de las Eras y los Montes de la Serranía','7.5/10 Vista diáfana de la cabecera de la cuenca, cultivos de secano de frutales, pinares forestales y horizontes celestes idóneos para astrofotografía nocturna. Cómo llegar: Cota natural elevada junto a los antiguos espacios comunales de trilla, sector norte urbano. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46142','mirador','Mirador del Castillo de Jalance y cañón del Júcar','8.4/10 Impresionante vista sobre el valle de Ayora-Cofrentes, escarpes calizos verticales del río Júcar, la fortaleza medieval señorial y densos pinares forestales. Cómo llegar: Explanada exterior y adarves de la fortaleza en el cerro testigo que corona la villa, acceso peatonal urbano. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46144','mirador','Mirador del Castillo de Jarafuel y Sierra de la Muela','7.9/10 Vista del valle agrícola de secano de la comarca, dehesas altas de encina, monte mediterráneo de jara y restos de las torres fortificadas. Cómo llegar: Cota más alta del núcleo urbano central, transitable a pie por las calles históricas altas del pueblo. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45017','mirador','Mirador del Castillo de Xàtiva (Castell Major y Menor)','9.4/10 Excepcional, monumental e ininterrumpida atalaya de 360 grados sobre el Valle de la Costera, los huertos tradicionales, el perfil urbano histórico y murallas dobles. Cómo llegar: Corona superior y almenas transitables de la fortaleza doble medieval que corona la cresta de la sierra del Vernissa. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45007','mirador','Mirador del Monasterio de San Miguel y la Edetania','8.1/10 Magnífica perspectiva histórica sobre la Camp de Túria, el trazado de la antigua Edeta ibérica, cultivos de secano y la llanura de la capital lejana. Cómo llegar: Explanada y terrazas adaptadas junto al histórico monasterio en el cerro de San Miguel, acceso por carretera pavimentada. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46148','mirador','Mirador del Embalse de Loriguilla y Loriguilla Viejo','7.4/10 Vista que combina la gran masa de agua regulada del Turia con los cortados de roca caliza y el evocador pueblo abandonado por la presa. Cómo llegar: Zona elevada de servicio exterior perimetral a las instalaciones de la represa, desvío desde la CV-35. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46149','mirador','Mirador de la Peña de las Bodegas y Serranía','7.6/10 Vista de la transición a la Serranía de Valencia, relieves arcillosos y calcáreos de cultivo, pinares dispersos y horizontes despejados para astrofotografía. Cómo llegar: Promontorio calizo elevado al norte de la población, transitable por pistas forestales de tierra. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90872','mirador','Mirador del Monasterio del Corpus Christi y del Castillo','8.2/10 Hermosa e histórica vista del majestuoso cenobio dominico del siglo XV, el castillo de Xiu, olivares tradicionales en bancales y cielos muy oscuros. Cómo llegar: Elevación natural de la colina del monasterio, transitable por camino asfaltado con aparcamiento y bancos. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90375','mirador','Atrio de la Iglesia de Nuestra Señora del Rosario','5.4/10 Sencilla visual urbana e industrial sobre la Horta Sud (municipio de mínima extensión), cultivos periurbanos residuales y horizontes metropolitanos integrados. Cómo llegar: Explanada elevada que circunda la portada del templo parroquial central, en el centro urbano. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90376','mirador','Mirador de la Vega del río Vernissa','6.9/10 Vista de la huerta aluvial de cítricos de la comarca, cañaverales lineales, lomas de piedra caliza y la silueta del Monasterio de Cotalba cercano. Cómo llegar: Margen de la terraza fluvial acondicionado junto a los senderos peatonales, núcleo bajo. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46154','mirador','Alto del Teso del Humilladero y la Costera','6.6/10 Panorámica rural sobre los llanos cerealistas de la comarca de la Costera, campos ondulados de secano e idóneo horizonte nocturno Starlight. Cómo llegar: Pequeña colina exenta en las inmediaciones del cementerio municipal, de fácil acceso peatonal. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46155','mirador','Mirador del Cavall Bernat y Sierra de Corbera','7.8/10 Espectacular e imponente corte geológico de la aguja caliza sobre la plana de la Ribera Baixa, el mar de arrozales, naranjos y el Mediterráneo de fondo. Cómo llegar: Plataforma natural en el sendero de montaña de ascenso a las crestas, acceso pedestre señalizado. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90871','mirador','Mirador de la Algepsara y paraje del río Magro','7.5/10 Vista de los valles del río Magro medio, laderas cubiertas de pino carrasco, olivares de montaña y restos de patrimonio industrial de yesos. Cómo llegar: Cota natural elevada accesible por las pistas de servicio forestales al norte del término. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46157','mirador','Mirador de la Ermita del Calvario y de Santa Ana','7.2/10 Vista sobre la vega de frutales y naranjos de la Costera, la silueta urbana del castillo de Játiva lejana y horizontes celestes limpios. Cómo llegar: Cerro testigo elevado donde se asienta el santuario rústico, transitable por camino asfaltado. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46158','mirador','Mirador del Castillo de Macastre y la Hoya','7.7/10 Perspectiva sobre la Hoya de Buñol, olivares tradicionales alineados en bancales, campos de algarrobos y las ruinas fortificadas islámicas del siglo XI. Cómo llegar: Explanada de la antigua fortaleza que domina el cerro testigo sobre el pueblo, acceso señalizado por sendero. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46159','mirador','Mirador del Parque Fluvial del río Turia y el Acueducto','6.6/10 Vista que combina el soto de ribera del río Turia protegido con el monumental acueducto histórico de Els Arquets y la llanura industrial periurbana. Cómo llegar: Paseo y pasarelas de madera integrados en el tramo de la red del Parque Fluvial, accesos urbanos directos. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46160','mirador','Mirador de la Ermita del Santísimo Cristo','7.1/10 Vista del valle bajo del río Albaida, la llanura de regadío intensivo de la Ribera Alta cubierta de naranjos e idóneos atardeceres nítidos. Cómo llegar: Explanada elevada del santuario en la colina que flanquea el casco urbano, accesos pavimentados y bancos. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46161','mirador','Mirador de Marines Viejo y las Peñas de Amador','7.5/10 Hermoso panorama de los barrancos profundos calizos de la Sierra Calderona occidental, el núcleo histórico desalojado reconstruido y pinares densos. Cómo llegar: Plataforma elevada con paneles informativos en las inmediaciones del antiguo pueblo de montaña, CV-333. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46162','mirador','Alto del Teso de la Iglesia','6.4/10 Sencilla panorámica sobre los llanos agrícolas de la Ribera Alta central, cultivos de regadío intensivo de naranjos y horizontes limpios al amanecer valenciano. Cómo llegar: Atrio elevado del templo de la Asunción, en el punto alto del casco urbano central. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46163','mirador','Mirador de la Huerta y de la línea de la Playa','6.0/10 Perspectiva sobre la Horta Nord litoral, campos cuadriculados de hortalizas, acequias y horizontes marinos mediterráneos limpios libres de postes. Cómo llegar: Zona costera y paseo peatonal adaptado junto a la desembocadura de los canales de regadío locales. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46164','mirador','Mirador del Parque de la Huerta norte','6.4/10 Vista periurbana de la comarca, parcelas agrícolas tradicionales de chufas e hortalizas e integración metropolitana cercana con la capital provincial. Cómo llegar: Zona alta ajardinada con accesos peatonales dentro de los parques del complejo urbano residencial. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46165','mirador','Mirador de los Tancats de la Albufera','6.7/10 Vista panorámica ornitológica de las parcelas ganadas al lago de la Albufera, tablas de arrozales inundados e idóneo horizonte para puestas de sol. Cómo llegar: Camino elevado rural de servicio perimetral a las cubetas, dentro del parque natural protegido. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46166','mirador','Mirador del Palacio de Nolla y la Huerta de Chufas','6.5/10 Interesante paisaje que fusiona el patrimonio arquitectónico industrial azulejero del siglo XIX con la huerta tradicional de regadío intensivo de la comarca. Cómo llegar: Entorno acondicionado y restaurado del monumento de la fábrica de Nolla, accesos peatonales urbanos. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46167','mirador','Mirador del Monstruo de Millares y cañón del Júcar','8.9/10 Impresionante e inmenso tajo fluvial calizo vertical excavado por el Júcar, el salto de agua de la cascada del Monstruo, huertas de herencia morisca y huellas de dinosaurio. Cómo llegar: Balcón natural acondicionado con barandillas y paneles de la red en el escarpe rocoso, acceso por la CV-580. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46168','mirador','Mirador del paseo marítimo y la duna costera','6.8/10 Hermosa perspectiva costera de las playas de la Safor, el cordón dunar protegido con vegetación litoral y el mar Mediterráneo infinito sin obstáculos. Cómo llegar: Estructura de pasarela de madera peatonal en el paseo marítimo de la playa, acceso directo urbano. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46169','mirador','Mirador del Parque de la Canaleta y cabecera del Turia','5.5/10 Sencilla panorámica periurbana e industrial integrada en el área metropolitana de Valencia (municipio de máxima densidad de población), con zonas ajardinadas. Cómo llegar: Pasarela elevada urbana peatonal dentro de las instalaciones del parque lúdico central. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46171','mirador','Mirador del Tos Pelat y la Huerta norte','6.9/10 Vista que combina la perspectiva del yacimiento del poblado ibérico con las parcelas tradicionales de cultivo de hortalizas e hitos hidráulicos de la Real Acequia. Cómo llegar: Cima suave del cerro del Tos Pelat acondicionado con accesos arqueológicos en la periferia del término. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46172','mirador','Mirador del Castellet de Montserrat','7.1/10 Vista de las lomas onduladas de cultivo de viñedos y campos de naranjos de la Ribera Alta septentrional, urbanizaciones integradas residenciales y la torre musulmana. Cómo llegar: Explanada rocosa elevada que rodea las ruinas fortificadas islámicas, acceso pedestre por sendero local. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46177','mirador','Mirador de la Huerta de Moncada','6.3/10 Sencilla panorámica de la Horta Nord, cultivos ondulados de secano e intensivo de regadío hortícola, acequias tradicionales y horizontes marinos limpios. Cómo llegar: Margen de las pistas agropecuarias de tierra situadas al este del término, de fácil acceso. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46178','mirador','Mirador de la Creu de Nàquera','7.8/10 Impresionante vista de las vertientes de pino carrasco de la Sierra Calderona, barrancos abruptos de rodeno rojo, la llanura prelitoral y el mar Mediterráneo. Cómo llegar: Cima rocosa coronada por la cruz monumental, accesible por sendero escalonado desde el casco urbano. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46179','mirador','Mirador de los Playamontes y Salto de la Escalera','8.4/10 Magnífica perspectiva del cañón fluvial, pozas de agua cristalina, densas pinadas de la Canal de Navarrés e idóneo horizonte nocturno Starlight. Cómo llegar: Plataforma con vallado de protección en el borde del escarpe, desvío señalizado desde la CV-580. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46181','mirador','Mirador del Castillo de Santa Anna','8.6/10 Espectacular e infinita panorámica que une el casco antiguo morisco, el mar de naranjos, el Parque Natural del Marjal de Pego-Oliva y el litoral. Cómo llegar: Corona superior y explanada de los restos fortificados en el cerro que domina la villa costera. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46182','mirador','Mirador del Puntal dels Llops','8.1/10 Vista de gran interés arqueológico sobre el somontano de la Sierra Calderona, dehesas forestales, matorral mediterráneo y la atalaya fortificada ibérica del siglo V a.C. Cómo llegar: Estructura con paneles interpretativos junto al yacimiento arqueológico, acceso peatonal por sendero señalizado. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45010','mirador','Mirador del Pou Clar y Barranc de l''Infern','8.8/10 Soberbia vista de los cañones calizos de la Sierra de Mariola, los nacimientos de agua cristalina del río Clariano y frondosos sotos fluviales. Cómo llegar: Balcón natural adaptado en la sendas forestales que bordean el paraje natural de los pozos. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46185','mirador','Mirador de los Relojes de Sol y Benicadell','7.4/10 Perspectiva sobre la Vall d''Albaida meridional, cultivos de secano e hilos de chopos fluviales, bajo el imponente muro calizo de la Sierra de Benicadell. Cómo llegar: Zona alta adaptada en el casco urbano de la villa de los relojes de sol tradicionales. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46186','mirador','Mirador del Barranco de Chiva periurbano','6.1/10 Vista periurbana de la Horta Sud, campos de regadío intensivo hortícola, cañaverales lineales y la silueta industrial integrada del entorno metropolitano. Cómo llegar: Pasarela peatonal sobre el cauce del barranco en el paseo ajardinado del término. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46187','mirador','Mirador del Barranc de la Cova Negra y Serpis','7.3/10 Vista del tramo bajo del río Serpis, huertas de cítricos de la comarca de la Safor, relieves calizos de montaña y sotos fluviales densos. Cómo llegar: Saliente natural del páramo pizarroso, accesible por pistas rurales desde la localidad. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46188','mirador','Atrio de la Iglesia de la Purísima Concepción','6.2/10 Sencilla visual del mar de naranjos de la llanura litoral, palmeras dispersas e idóneo horizonte costero libre de obstáculos visuales. Cómo llegar: Explanada urbana elevada frente a la fachada del templo parroquial barroco. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46189','mirador','Mirador del Carrascalet y del Valle','7.0/10 Panorámica rural de la Vall d''Albaida, campos ondulados de viñedos y olivos, dehesas de encina dispersas e interesantes atardeceres limpios. Cómo llegar: Promontorio suave al norte del término municipal, accesible por caminos vecinales de tierra. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46190','mirador','Mirador de la Torre de Paterna y las Casas Cueva','7.6/10 Vista que combina la imponente silueta del torreón de defensa defensiva morisco del siglo XI con las lumbreras de los calados rupestres subterráneos habitados. Cómo llegar: Explanada del monumento histórico ajardinada urbana en pleno casco histórico alto de la villa. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46191','mirador','Mirador de la Peña Latrón y río Turia','7.8/10 Hermosa vista de los meandros del río Turia medio, huertas de regadío intensivo en el fondo del valle, escarpes calizos y pinares forestales tupidos. Cómo llegar: Borde del talud calizo occidental adaptado con valla de madera, acceso por sendas locales. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46192','mirador','Mirador del Castillo de Petrés y el Palancia','7.1/10 Vista de la vega del río Palancia inferior en la comarca de Camp de Morvedre, cultivos tradicionales de cítricos, olivares de ladera y la fortaleza gótica. Cómo llegar: Explanada rocosa elevada que rodea las ruinas del palacio fortificado medieval, acceso pedestre. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46193','mirador','Mirador de la Huerta y del Cinturón Verde','6.2/10 Vista periurbana sobre la llanura agrícola tradicional que sobrevive, huertas de regadío intensivo y horizontes de la periferia metropolitana de Valencia. Cómo llegar: Zona alta ajardinada en las pasarelas peatonales integradas en la red de huertos urbanos. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46194','mirador','Mirador de la Cuesta de las Bodegas y Torre de Espioca','6.9/10 Perspectiva sobre los llanos agrícolas de cítricos y algarrobos de la Ribera Alta norte, la torre defensiva almohade lejana y horizontes limpios. Cómo llegar: Parte superior de las lomas periurbanas transitables por pistas agropecuarias de tierra. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46195','mirador','Mirador de la Torre de Piles y la Costa','7.0/10 Hermosa perspectiva costera sobre la playa de arena, el mar Mediterráneo de la Safor, el cordón de dunas fósiles y la torre vigía del siglo XVI. Cómo llegar: Entorno acondicionado de la torre defensiva costera cilíndrica en pleno paseo marítimo. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46196','mirador','Mirador del Surar de Pinet','8.1/10 Excepcional e interesantísima perspectiva forestal del bosque de alcornoques más meridional de la Comunidad Valenciana, laderas de arenisca roja y matorral denso. Cómo llegar: Plataforma con paneles explicativos en el paraje de la microrreserva de flora protegida, accesos de montaña. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46199','mirador','Mirador del Puerto Deportivo y Playa Norte','6.8/10 Vista de las playas del litoral de l''Horta Nord, las embarcaciones de recreo, el mariscal costero bajo y brisas del Mediterráneo sin obstáculos. Cómo llegar: Espacio de espigones y pasarelas adaptadas del puerto náutico de la Pobla Marina. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46202','mirador','Mirador de los Llanos de Camp de Túria','6.6/10 Sencilla panorámica sobre la cuenca agrícola interior, cultivos de naranjos, dehesas dispersas y la integración urbana residencial de las urbanizaciones. Cómo llegar: Zona alta ajardinada en las cotas de relieve de las áreas residenciales periféricas. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46200','mirador','Mirador de los Viñedos y refugios de la Guerra Civil','7.2/10 Mar de viñedos de la Vall d''Albaida, campos de frutales, lomas suaves arcillosas e instalaciones militares históricas excavadas de gran interés fotográfico. Cómo llegar: Entorno acondicionado de la ruta etnográfica de los refugios agrícolas y bodegas, acceso rural. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46198','mirador','Mirador de la Ermita del Cristo de la Agonía y Serpis','7.5/10 Vista del valle aluvial bajo del río Serpis, huertas tradicionales de cítricos, acequias históricas del entramado hidráulico romano-árabe y la Safor. Cómo llegar: Explanada de la ermita barroca al sur del casco urbano, provista de accesos peatonales y bancos. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90053','mirador','Mirador del Paraje Natural de La Costera','83/10 Espectacular e imponente balcón mediterráneo sobre la Plana del Camp de Morvedre, pinares de montaña carrasco, matorral mediterráneo y la marjal litoral de Puçol. Cómo llegar: Plataforma acondicionada con barandilla y paneles en la cota más alta del cerro de la microrreserva forestal. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46204','mirador','Mirador del Castillo del Puig (Castell de Jaume I)','8.2/10 Soberbia, monumental e histórica atalaya militar del siglo XIII sobre l''Horta, el monumental Real Monasterio del Puig, naranjos y la línea de playa costera. Cómo llegar: Cima del cerro testigo de la Patà que corona la villa, accesible por sendero peatonal escalonado urbano. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46102','mirador','Mirador del Parque Natural del Turia y Azud de la Acequia','6.6/10 Vista que combina la infraestructura hidráulica medieval de la Acequia de Quart con el bosque de ribera y cañaverales protegidos periurbanos. Cómo llegar: Pasarela peatonal y observatorio integrado en los senderos de la red del Parque Natural del Turia. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46101','mirador','Mirador de Quart de les Valls','Cómo llegar: Zona elevada del parque recreativo natural que circunda el manantial, acceso pavimentado. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46103','mirador','Mirador de la Marjal de Almenara y la Huerta','6.8/10 Perspectiva sobre las llanuras agrícolas del Valle de Segó, cultivos de regadío de frutales, acequias y la cubeta húmeda litoral lejana. Cómo llegar: Margen de los caminos rurales elevados en el extremo nororiental del municipio. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46206','mirador','Mirador de los Charcos de Quesa y río Grande','8.5/10 Espectacular e intrincada panorámica de valles de montaña de la Canal de Navarrés, cuatro pozas naturales cristalinas encajonadas e idónea pureza Starlight. Cómo llegar: Estructura adaptada con pasarelas de madera en el paraje natural de los Charcos, acceso señalizado por la CV-580. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46207','mirador','Mirador de la Huerta norte y las Acequias','6.2/10 Sencilla panorámica de la Horta Nord, cultivos tradicionales de regadío intensivo hortícola, arbolado de las acequias y horizontes limpios del litoral. Cómo llegar: Pasarela peatonal urbana en los límites residenciales periféricos elevados del núcleo. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46208','mirador','Atrio de la Ermita de San Diego y la Huerta','6.5/10 Vista llana del mar de naranjos de la Safor, olivares marginales de ladera y horizontes marinos mediterráneos limpios de obstáculos. Cómo llegar: Explanada de la pequeña ermita rural sobre el cerro testigo de San Diego, acceso por camino de tierra. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46209','mirador','Mirador de la Sierra de Manuel y la Ribera','7.1/10 Vista panorámica del valle aluvial de la Ribera Alta, campos de naranjos y cultivos tradicionales de ladera, con lomas cubiertas de pinos dispersos. Cómo llegar: Cornisa natural alta accesible por pistas forestales de tierra al sur de la localidad. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46211','mirador','Mirador de la Huerta del Serpis','6.9/10 Perspectiva sobre la huerta aluvial de cítricos de la Safor inferior, chopera lineal del río Serpis y relieves de la sierra del Mondúver lejana. Cómo llegar: Zona alta ajardinada en la cornisa perimetral urbana, accesible de forma peatonal. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46212','mirador','Mirador del Castillo de Alcalá y río Magro','7.0/10 Vista de las vertientes de piedra caliza, encinares y olivares tradicionales de la comarca de la Ribera Alta, con el cauce encajonado del Magro. Cómo llegar: Explanada rocosa elevada que rodea las ruinas fortificadas medievales, acceso pedestre. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46213','mirador','Mirador de la Torre del Homenaje de la Villa','8.6/10 Soberbia e inmensa visual sobre el altiplano castellano-valenciano, el inmenso mar de viñedos de la D.O. Utiel-Requena, olivares y la trama medieval del barrio de la Villa. Cómo llegar: Corona superior y almenas transitables de la fortaleza del siglo XV que corona el casco histórico de la ciudad. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46214','mirador','Mirador del Castillo de Riba-roja y el Turia','7.8/10 Magnífica perspectiva de las terrazas fluviales del parque natural del Turia, bosques de ribera frondosos, huertas tradicionales y el complejo del palacio medieval. Cómo llegar: Balcón acondicionado con barandillas en la cota urbana alta del castillo, en pleno centro histórico de la villa. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46215','mirador','Mirador del Puente de Hierro y río Júcar','6.9/10 Vista fluvial del meandro del Júcar inferior, campos de arrozales de la Ribera Baixa, sotos y el monumental puente metálico arqueológico del siglo XX. Cómo llegar: Paseo fluvial acondicionado en la mota peatonal derecha de la corriente, casco urbano bajo. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46216','mirador','Mirador de la Huerta del Bovalar','6.5/10 Vista periurbana de l''Horta Nord, parcelas agrícolas remanentes de cultivo intensivo hortícola, canteras históricas de piedra y el horizonte metropolitano residencial. Cómo llegar: Zona alta ajardinada en las calles residenciales perimetrales elevadas de la villa. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46217','mirador','Alto del Teso del Calvario y la Costera','6.6/10 Sencilla panorámica de los llanos agrícolas de secano y frutales de la comarca, lomas arcillosas y horizontes limpios al atardecer valenciano. Cómo llegar: Atrio elevado de la ermita del Calvario, en el punto alto del término municipal. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46219','mirador','Mirador del cerro de San Bernardo y la Vall d''Albaida','7.2/10 Vista de las laderas calizas áridas de la sierra de Rugat, campos de viñedos planos, olivares centenarios y horizontes celestes limpios nocturnos Starlight. Cómo llegar: Cima suave de la colina acondicionada con accesos peatonales forestales en la periferia del núcleo. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45013','mirador','Mirador del Castillo de Sagunto y el Teatro Romano','9.4/10 Extraordinaria, monumental e internacional panorámica de 360 grados sobre el foso de la llanura litoral del Camp de Morvedre, el teatro romano, la judería y el mar de fondo. Cómo llegar: Corona amurallada superior y adarves transitables de la inmensa plaza fortificada del siglo II a.C. al medieval, acceso rodado. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46221','mirador','Mirador de la Font d''Elca y Sierra de Benicadell','7.9/10 Magnífica perspectiva de las vertientes forestales de pino de la sierra, el valle agrícola interior, huertas tradicionales de secano de almendros y fuentes. Cómo llegar: Paraje natural elevado acondicionado con bancos en las estribaciones forestales altas de la villa. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46903','mirador','Mirador del Parque del Turia norte','6.1/10 Vista periurbana de la comarca de Camp de Túria, llanuras de pinar carrasco remanentes de secano e integración urbana residencial de las urbanizaciones. Cómo llegar: Zona alta ajardinada en las cornisas perimetrales del núcleo residencial periurbano moderno. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46223','mirador','Mirador de los Arrozales periurbanos','6.0/10 Vista periurbana sobre la llanura inundable de arrozales del norte de la Albufera, que resiste el avance de los polígonos comerciales modernos de la Horta. Cómo llegar: Margen de los caminos rurales elevados de la huerta baja, en los límites orientales. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46224','mirador','Mirador de la Mola de Segart','8.4/10 Espectacular e imponente tajo geológico calizo con forma de muela del Maestrazgo/Calderona, pinares de rodeno rojo, nidos de rapaces y horizontes marinos puros. Cómo llegar: Crestas del sinclinal colgado rocoso, accesible por sendero de montaña peatonal de herradura desde el pueblo. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46225','mirador','Mirador del cerro de la Ermita de Santa Ana','7.1/10 Vista de las vertientes de la cuenca del río Sellent, campos de naranjos de la Ribera, olivares rústicos de montaña y horizontes limpios. Cómo llegar: Explanada de la ermita en la cota más elevada del cerro de la villa, accesos adaptados. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46226','mirador','Mirador del Embalse de Bellús y el río Albaida','7.3/10 Hermosa vista de la masa de agua regulada rodeada de lomas calizas áridas, olivares de la Vall d''Albaida y avifauna ligada a zonas húmedas. Cómo llegar: Zona de la represa y miradores perimetrales accesibles por pistas rurales desde la pequeña localidad. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46227','mirador','Mirador de la Vega del río Albaida','6.6/10 Sencilla panorámica de la huerta aluvial, plantaciones intensivas de regadío de cítricos, cañaverales lineales y horizontes de la Ribera Alta bajos. Cómo llegar: Zona perimetral elevada acondicionada junto a los senderos del margen derecho del río. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46228','mirador','Mirador del Garbí y Castillo de Serra','8.8/10 Extraordinaria e icónica panorámica de la Sierra Calderona, los escarpes de rodeno rojo, la fortaleza islámica del siglo XI colgada del risco calizo y el mar. Cómo llegar: Balcón natural acondicionado con barandillas y paneles explicativos en el puerto del Garbí, carretera CV-310. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46229','mirador','Mirador del Pico de la Hoya y Fuentes','83/10 Magnífica perspectiva a más de 1000 metros de altitud de la Hoya de Buñol alta, densos pinares forestales de pino silvestre, fuentes naturales de agua dulce y dehesas. Cómo llegar: Cota natural elevada accesible por la pista forestal que sube desde el núcleo, desvío rural. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46230','mirador','Mirador del Puerto de Silla y la Albufera','7.8/10 Preciosa estampa del canal tradicional del puerto de barcas, los campos inundables de arrozales, los carrizales del parque natural y abundante avifauna acuática. Cómo llegar: Embarcadero adaptado con pasarelas de madera en la margen protegida del humedal, accesos señalizados. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46231','mirador','Mirador del Monasterio de Santa María de la Valldigna','87/10 Impresionante vista del majestuoso cenobio cisterciense del siglo XIV en el fondo del valle, rodeado por un anfiteatro de montañas calizas y naranjos. Cómo llegar: Saliente acondicionado de la plataforma del páramo superior en la carretera del puerto de Simat, CV-600. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46232','mirador','Alto de la Muela de Sinarcas y Paramera','7.5/10 Vista limpia de la altiplanicie de Requena-Utiel septentrional, extensos campos cerealistas, sabinares dispersos de gran altitud e idónea pureza Starlight nocturna. Cómo llegar: Plataforma calcárea elevada accesible por pistas forestales de tierra al sur de la localidad. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46233','mirador','Mirador de los Arrozales de Sollana y el Tancat','7.8/10 Extraordinaria perspectiva ornitológica de las zonas húmedas protegidas de la Albufera (tancats), campos inundados de arrozales y nítidas puestas de sol. Cómo llegar: Puesto de observación acondicionado con pasarelas de madera en la periferia de las cubetas lagunares. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46234','mirador','Mirador del Morrón y Parque Natural de Chera-Sot de Chera','8.8/10 Sobrecogedor y espectacular desfiladero calizo vertical excavado por el río Sot, el anticlinal geológico invertido, cascadas, pozas y densos pinares. Cómo llegar: Plataforma colgada adaptada con barandilla y paneles didácticos de la red del Parque Natural, acceso señalizado. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46235','mirador','Mirador de la Muntanyeta dels Sants','8.3/10 Excepcional e icónico cerro testigo calizo exento que emerge en medio del infinito mar plano de arrozales de la Albufera, ermita del siglo XIV y el mar. Cómo llegar: Explanada fortificada y miradores del santuario del cerro, adaptados con barandillas y aparcamiento en las pistas rurales. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46236','mirador','Mirador del Castillo de Sumacàrcer','8.1/10 Impresionante vista del río Júcar abandonando los cañones, el mar de naranjos de la Ribera Alta y el entramado urbano morisco. Cómo llegar: Cresta caliza al sur del núcleo urbano, accesible por sendero peatonal empinado y señalizado. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46238','mirador','Mirador de la Valldigna y Torre de Guaita','8.6/10 Soberbia panorámica de la llanura litoral, el Monasterio de Santa María, huertos infinitos de cítricos y la línea de costa mediterránea. Cómo llegar: Plataforma acondicionada con barandillas en el mirador del Mondúver o junto a la torre costera. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46239','mirador','Mirador del Alto de la Cruz','7.8/10 Amplia visual del Valle de Ayora, relieves de jara y pino albar, campos agrícolas de secano e idóneo horizonte nocturno Starlight. Cómo llegar: Cota natural elevada al noreste de la población, transitable por pistas agropecuarias de tierra. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46240','mirador','Alto de la Ermita de San Vicente','7.2/10 Perspectiva sobre los llanos agrícolas de la Vall d''Albaida, cultivos de viñedos de mesa, olivares rústicos y horizontes celestes limpios. Cómo llegar: Explanada de la pequeña ermita, accesible por camino de tierra apto para vehículos. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46241','mirador','Mirador astronómico de la Loma de la Cruz','8.3/10 Espectacular relieve alpino de la Serranía de Valencia, densos pinares, sabinares milenarios y un observatorio idóneo integrado en la Reserva Starlight. Cómo llegar: Plataforma acondicionada en las zonas forestales elevadas del norte del término, pistas de tierra. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46242','mirador','Mirador de la Ermita de San José y río Turia','7.4/10 Vista fluvial de la vega del río Turia al paso por el Rincón de Ademuz, huertas de media montaña y chopera lineal protegida. Cómo llegar: Promontorio suave junto al cementerio municipal, transitable a pie o por pista rural. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46243','mirador','Alto del Teso de la Costera','6.6/10 Sencilla panorámica sobre la llanura agrícola de la comarca, campos de naranjos ordenados, olivares de ladera e interesantes puestas de sol. Cómo llegar: Elevación natural al oeste del término municipal, transitable por sendas agropecuarias. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45014','mirador','Mirador del Vedat de Torrent','7.4/10 Vista periurbana de la Horta Sud, el golfo de Valencia, la línea litoral de la Albufera y pinares urbanizados relictos. Cómo llegar: Cornisa ajardinada adaptada con bancos y barandillas en la cota más alta del monte El Vedat. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46245','mirador','Mirador del Castillo de Torres Torres','7.6/10 Perspectiva sobre el valle bajo del Palancia, olivares, campos de cítricos y las ruinas fortificadas de origen musulmán. Cómo llegar: Explanada natural que rodea los lienzos de la fortaleza en la parte elevada de la población. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46246','mirador','Mirador del Embalse de Tous y la Muela','8.4/10 Impresionante e industrial panorama de la gran masa de agua regulada del río Júcar, escarpes calizos dolomíticos y un cielo Starlight puro. Cómo llegar: Zona de la represa e instalaciones de control hidroeléctrico, acceso señalizado por la CV-541. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46247','mirador','Mirador del Azud de Tuéjar y río Chelva','8.5/10 Hermoso panorama del nacimiento del río, pozas de agua turquesa cristalina, frondosos sotos de ribera, quejigares y relieves kársticas de la Serranía. Cómo llegar: Estructura adaptada con pasarelas de madera en el paraje de la Poza de las Palomas, acceso rural. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46248','mirador','Mirador del Castillo de Malboret','7.1/10 Vista de las lomas onduladas cubiertas de viñedos y olivares de la Ribera Alta, el cauce del río Magro y la torre defensiva islámica. Cómo llegar: Promontorio rocoso elevado al norte de la localidad, accesible por caminos rurales de tierra. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46249','mirador','Mirador de la Ermita del Remedio y la Sierra de Utiel','7.9/10 Extraordinario mar de viñedos plano de la D.O. Utiel-Requena, pinares densos de montaña e idónea nitidez astronómica. Cómo llegar: Explanada adaptada junto al santuario a más de 1000 metros de altitud, carretera de montaña. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46250','mirador','Mirador de la Torre de El Micalet (Miguelete)','8.9/10 Espectacular e histórica panorámica urbana de 360 grados sobre el centro gótico, la huerta, la Ciudad de las Artes, el puerto y el Mediterráneo. Cómo llegar: Terraza superior de la emblemática torre campanario octogonal de la Catedral de Valencia, acceso por escalera de caracol. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46251','mirador','Mirador del Castell de Vallada','8.2/10 Soberbia y colgada atalaya militar medieval sobre el Valle de Montesa, escarpes calizos calcáreos de la Serra Grossa y olivares tradicionales. Cómo llegar: Cima del peñón rocoso donde se asientan las ruinas de la fortaleza islámica del siglo XIV. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46252','mirador','Mirador de la Hoz del río Bohílgues','7.8/10 Magnífica perspectiva de uno de los ríos más puros de la región, chopera lineal exuberante, huertas tradicionales de media montaña y cortados. Cómo llegar: Borde del talud natural acondicionado con valla de madera en el sendero botánico del Bohílgues. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46253','mirador','Alto del Teso rural de la Costera','6.4/10 Sencilla panorámica rural sobre la llanura agrícola de frutales, el cauce del río Canyoles y horizontes limpios al atardecer valenciano. Cómo llegar: Cota natural elevada al norte de la población, transitable por sendas ganaderas de herradura. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46254','mirador','Mirador de los Cuchillos de Fonseca (Hoces del Cabriel)','8.8/10 Extraordinarias e imponentes agujas calizas afiladas de relieve kárstico sobre el cañón del Cabriel, densos pinares, aves rapaces y cielo Starlight puro. Cómo llegar: Plataforma con barandillas al borde del precipicio de la Reserva de la Biosfera, pistas forestales. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90873','mirador','Mirador de las Rodanas y el Turia','7.3/10 Vista que combina las formaciones de rodeno rojo del paraje natural con el bosque de ribera fluvial del Turia medio y cultivos. Cómo llegar: Borde del talud calizo occidental en las rutas del Parque Natural municipal, accesos señalizados. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46258','mirador','Mirador de la Mina de Tierra y Cerro de San Vicente','7.5/10 Paisaje minero de arcillas y caolín, vistas de los llanos agrícolas del somontano de la Serranía, cultivos de viñedos y olivares tradicionales. Cómo llegar: Promontorio calizo acondicionado con barandillas junto al cementerio o zonas altas forestales. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46259','mirador','Mirador de las Hoces del Cabriel y Presa de Contreras','8.7/10 Espectaculares e imponentes escarpes de roca caliza calcárea sobre el río fronterizo con Cuenca, el gran embalse y pinares silvestres densos. Cómo llegar: Balcón natural acondicionado con barandillas de hierro en la cumbre de los miradores del parque natural. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46260','mirador','Mirador del Barranco del Carraixet','6.1/10 Sencilla panorámica de la Horta Nord, cultivos tradicionales de regadío intensivo hortícola, el cauce del barranco y horizontes limpios del litoral. Cómo llegar: Margen del camino elevado de la mota protectora, accesible de forma peatonal urbana. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90054','mirador','Mirador de la Marjal de Xeraco y Torre de Guaita','7.7/10 Vista que combina las cubetas lagunares costeras de agua dulce protegidas, carrizales densos, huertas de cítricos y la torre de vigilancia del litoral. Cómo llegar: Estructura de observación adaptada junto al paseo perimetral del humedal costero de la Safor. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46261','mirador','Mirador del Pantano de Forata y río Magro','8.4/10 Espectacular visual alpina de la masa de agua regulada rodeada de montañas de la Hoya de Buñol, dehesas forestales tradicionales de encina y pinares. Cómo llegar: Zona perimetral alta con estacionamiento y paneles explicativos en los accesos de la represa, desvío rural. 📍 Provincia: Valencia.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46263','mirador','Mirador de la Torre del Reloj y el Valle','7.6/10 Vista panorámica del Valle de Ayora meridional, olivares tradicionales alineados en bancales, campos de cultivo de secano y la silueta del campanario exento barroco. Cómo llegar: Explanada y terrazas del cerro que domina el casco urbano histórico central, accesos peatonales. ¡PROVINCIA DE VALENCIA Y TODA LA COMUNIDAD VALENCIANA COMPLETADAS AL 100%! 🏁 ⭐ Si estás de acuerdo, podemos saltar de inmediato a la siguiente provincia en el orden territorial del plan de ruta nacional: Provincia de Castellón / Provincia de Teruel / Provincia de Zaragoza (Comunidad de Aragón), comenzando estrictamente desde la letra A con municipios como Abanto, Acered, Agón, Aguarón, Aguilón, Ainzón, Aladrén, Alagón, Alarba, Alberite de San Juan, Albeta, Alborge, Alcalá de Ebro, Alcalá de Moncayo, Alconchel de Ariza, Aldehuela de Liestos, Alfajarín, Alfamén, Alforque, Alhama de Aragón, Almochuel, La Almolda, Almonacid de la Cuba, Almonacid de la Sierra, La Almunia de Doña Godina, Alpartir, Ambel, Anento, Aniñón, Añón de Moncayo, Aranda de Moncayo, Arándiga, Ardisa, Ariza, Artieda, Asín, Atea, Ateca, Azuara, etc. ¿Prefieres que continuemos con el bloque masivo de la Provincia de Zaragoza?.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90129','mirador','Mirador de la Ermita de San Esteban y las Parameras','7.4/10 Espectacular corte visual sobre la fosa de Gallocanta, lomas de encinar, cultivos de secano de altura e idónea oscuridad Starlight libre de postes. Cómo llegar: Cerro exento que alberga el pequeño templo, accesible por camino rural al sur del pueblo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90770','mirador','Alto del teso de las Bodegas','6.9/10 Vista de las laderas onduladas cubiertas de viñedos de la D.O. Calatayud, chimeneas de tradicionales calados y horizontes nítidos de media montaña. Cómo llegar: Promontorio situado sobre las bodegas subterráneas, en la periferia del casco urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90771','mirador','Mirador del Canal de Tauste y las Eras','6.2/10 Sencilla panorámica rural sobre la llanura agrícola del valle del Ebro, campos de regadío, cañaverales lineales y la silueta lejana del Moncayo. Cómo llegar: Margen perimetral elevado próximo a las eras tradicionales, sector norte de la localidad. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90130','mirador','Mirador de la Sierra de Algairén y Santo Albert','7.8/10 Hermosa e infinita visual del mar de vides de la D.O. Cariñena, densos pinares forestales de ladera y matorral mediterráneo de altura. Cómo llegar: Saliente natural acondicionado con valla de madera en la subida al puerto, accesible por la CV-602. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90131','mirador','Mirador del Santo Cristo y las Cárcavas','7.1/10 Perspectiva sobre los barrancos y formaciones calizas erosionadas de la comarca de Campo de Cariñena, encinares dispersos y horizontes limpios. Cómo llegar: Explanada de la ermita en la cota más alta del núcleo, transitable a pie por sendas de piedra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49001','mirador','Mirador del cerro de San Cristóbal y Campo de Borja','7.4/10 Mar de viñedos de la D.O. Campo de Borja, olivares tradicionales alineados en bancales, lomas arcillosas y la imponente silueta serrana de fondo. Cómo llegar: Cima suave del cerro acondicionado con accesos peatonales y bancos en la periferia del núcleo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90132','mirador','Alto de la Muela de Aladrén','6.8/10 Vista limpia de la paramera ibérica zaragozana, campos de cereal de secano a gran altitud, sabinares dispersos y cielos nocturnos Starlight puros. Cómo llegar: Plataforma tabular calcárea elevada, transitable por sendas agropecuarias al norte del pueblo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90133','mirador','Alto del Cerro de San Roque','7.2/10 Vista panorámica del valle encajonado de la comarca de Calatayud, almendrales de montaña, viñedos tradicionales de ladera y horizontes celestes despejados. Cómo llegar: Colina exenta que alberga la ermita, accesible mediante camino vecinal transitable de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90134','mirador','Atrio de la Iglesia de la Asunción','6.5/10 Sencilla panorámica sobre los llanos agrícolas del valle del Huecha, cultivos de regadío intensivos, olmedas aisladas y puestas de sol limpias. Cómo llegar: Plaza pública sobreelevada frente a la portada mudéjar del templo, en el centro urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90135','mirador','Mirador de la Vega del Huecha','6.3/10 Vista del cauce llano del río Huecha, campos de cultivo tradicionales hortícolas, cañaverales lineales y nítidos horizontes idóneos para astrofotografía. Cómo llegar: Zona perimetral elevada al norte de la población, cercana a pistas agrícolas locales. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90136','mirador','Mirador de las Eras y la Hoz del Ebro','7.9/10 Espectacular e imponente panorámica del gran meandro encajonado del río Ebro en la comarca de la Ribera Baja, sotos fluviales y olivares. Cómo llegar: Cornisa natural acondicionada con barandillas en las inmediaciones del núcleo urbano alto. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90137','mirador','Mirador de la Ínsula Barataria y el Ebro','6.6/10 Vista fluvial del discurrir ancho del río Ebro, los sotos arbolados protegidos, huertas tradicionales cervantinas y aves asociadas al medio hídrico. Cómo llegar: Paseo e hito peatonal acondicionado en la margen derecha del cauce, junto a la estatua de Sancho Panza. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90138','mirador','Mirador de la Cuesta del Castillo y el Huecha','8.4/10 Soberbia y colgada atalaya sobre el encajonamiento del río Huecha, con la imponente y cercana mole forestal del Moncayo dominando el relieve. Cómo llegar: Explanada de la antigua fortaleza musulmana en la cota más elevada del pueblo escalonado de herencia morisca. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90139','mirador','Alto de la Muela de Alconchel','7.1/10 Panorámica sobre la estepa fría fronteriza con Soria, cultivos cerealistas de secano a gran altitud, formaciones de piedra caliza y cielos limpios. Cómo llegar: Plataforma calcárea elevada accesible por pistas agropecuarias al sur del término. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90140','mirador','Mirador de las Hoces del río Piedra','7.3/10 Impresionante grieta caliza de paredes verticales, densas masas de encina y quejigo, nidos de rapaces rupícolas y pureza celeste nocturna. Cómo llegar: Borde del precipicio natural acondicionado con valla de madera, acceso por sendas de montaña. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90141','mirador','Mirador de la Ermita de la Virgen de la Peña y el Castillo','7.9/10 Espectacular e histórica visual desde los escarpes de los Monegros occidentales sobre el valle del Ebro, huertas tradicionales y canteras de yesos. Cómo llegar: Explanada natural del santuario sobre el precipicio calizo-yesoso, acceso señalizado por carretera local. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90142','mirador','Mirador de los Murales y del Llano','6.4/10 Vista que combina las monumentales fachadas artísticas de arte urbano al aire libre con las llanuras cerealistas y vitivinícolas del Campo de Cariñena. Cómo llegar: Itinerario peatonal urbano adaptado en las plazas y zonas periféricas altas del núcleo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90143','mirador','Mirador del Mirador de la Atalaya y meandro del Ebro','7.8/10 Magnífica perspectiva del curso ancho y retorcido del río Ebro, los cortados arcillosos de erosión lineal, frondosos bosques de ribera y cultivos planos. Cómo llegar: Balcón natural adaptado con barandillas de madera en la cornisa del páramo que domina la villa. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90144','mirador','Mirador del Castillo de la Orden de San Juan y del Lago Termal','8.3/10 Impresionante vista del cañón calizo del río Jalón, el singular lago de aguas termales humeantes y las trazas fortificadas de la fortaleza islámica. Cómo llegar: Corona superior de la torre del homenaje y muros visitables de la fortaleza, en la parte alta del casco urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90145','mirador','Alto del Teso rural del secano','6.1/10 Sencilla panorámica de la llanura de transición de la comarca de Campo de Belchite, campos ondulados de cultivo de secano y horizontes limpios. Cómo llegar: Cota natural elevada al norte de la población, transitable por sendas ganaderas de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90146','mirador','Mirador de la Ermita de Santa Elena y la Sierra de Alcubierre','8.4/10 Espectacular, inmensa e infinita atalaya sobre el desierto de los Monegros, relieves forestales relictos de pino carrasco, sabinas y cielos nocturnos catalogados Starlight. Cómo llegar: Explanada de la ermita barroca en la cumbre de la cresta caliza que domina el término, acceso rodado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90147','mirador','Mirador del Embalse Romano de Almonacid','8.8/10 Extraordinaria e imponente vista de la descomunal presa romana del siglo I d.C. (la mayor del imperio en altura), el cañón del Aguasvivas y las pasarelas colgadas. Cómo llegar: Plataforma con barandillas de hierro y paneles didácticos en el borde del precipicio calcáreo, acceso directo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90148','mirador','Mirador de la Cuesta de las Bodegas y Sierra de Algairén','7.6/10 Vista panorámica de los viñedos de ladera de Cariñena, el entramado medieval urbano morisco escalonado e hileras de chimeneas de calados tradicionales subterráneos. Cómo llegar: Zona alta del montículo de las bodegas, accesible a pie desde las murallas del casco antiguo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90149','mirador','Mirador del cerro de San Cristóbal y Valdejalón','7.4/10 Amplia perspectiva de la fértil vega de árboles frutales, cultivos hortícolas locales, la esbelta torre mudéjar de la iglesia y las primeras sierras ibéricas. Cómo llegar: Saliente natural acondicionado con valla de madera al norte del casco urbano, acceso por caminos rurales. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90151','mirador','Mirador del Palacio de los Hospitalarios y el Moncayo','7.8/10 Vista que combina el patrimonio monumental mudéjar del conjunto de la Orden de San Juan con los campos de viñedos y la mole forestal del Moncayo. Cómo llegar: Patios superiores y torres del palacio fortificado de la villa, centro del núcleo histórico. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90152','mirador','Mirador del Castillo de Anento y Aguallueve','8.9/10 Preciosa e intrincada panorámica de un valle calizo arcilloso de color rojo, el manantial con paredes de toba calcárea húmeda y la silueta del castillo del siglo XIV. Cómo llegar: Corona rocosa del cerro donde se asientan las ruinas fortificadas medievales, accesible por sendero escalonado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90153','mirador','Mirador del Calvario y la Sierra de la Virgen','7.9/10 Vista montañosa de la comarca de Calatayud, laderas cubiertas de pino silvestre, almendrales en bancales y la monumental torre mudéjar de la iglesia de fondo. Cómo llegar: Zona alta de la ermita del Calvario, provista de accesos peatonales urbanos y barandillas. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90772','mirador','Mirador del Castillo de las Órdenes Militares y Hoces del Huecha','8.6/10 Impresionante vista alpina del Parque Natural del Moncayo, cañones calizos escarpados, densos bosques mixtos de hayas y robles y la fortaleza militar del siglo XII. Cómo llegar: Explanada de los muros fortificados sobre el escarpado risco calizo que corona la villa histórica. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90154','mirador','Mirador del Castillo de Arándiga y vegas del Aranda','8.1/10 Espectacular encajonamiento fluvial de la confluencia de los ríos Aranda y Jalón, huertas tradicionales de frutales, escarpes calizos y la muralla musulmana. Cómo llegar: Cima del peñón rocoso donde se asientan las ruinas de la fortaleza islámica del siglo XII, acceso pedestre. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90155','mirador','Mirador de la Presa de Ardisa y río Gállego','7.3/10 Hermosa vista que combina la infraestructura de regulación hídrica de los canales del Gállego con sotos fluviales arbolados y lomas de las Cinco Villas. Cómo llegar: Zona perimetral alta con estacionamiento y paneles explicativos en los accesos de la represa, desvío rural. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90773','mirador','Mirador de la Peña del Castillo y el Jalón','7.8/10 Extraordinario y profundo tajo geológico de arcillas rojas y calizas excavado por el río Jalón, olivares tradicionales de montaña y el entramado de casas cueva rupestres. Cómo llegar: Explanada rocosa elevada que rodea las ruinas fortificadas medievales, acceso peatonal empinado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90156','mirador','Mirador de la Jacetania y el río Aragón','8.2/10 Magnífica perspectiva de las terrazas fluviales del valle del Aragón, el tramo del Camino de Santiago aragonés, campos de secano e imponentes cumbres pirenaicas de fondo. Cómo llegar: Cornisa natural acondicionada con barandillas en los límites perimetrales del pueblo colgado, acceso directo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90157','mirador','Alto del Teso de la Iglesia y las Cinco Villas','7.1/10 Panorámica rural de lomas arcillosas onduladas, campos de cultivo de secano cerealista, pequeños pinares forestales y horizontes limpios Starlight. Cómo llegar: Atrio elevado del templo parroquial románico, en el punto alto del pequeño núcleo urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90158','mirador','Mirador del Castillo de Ateca y valle del Jalón','8.0/10 Hermosa panorámica del Valle del Jalón medio, la esbelta e icónica torre mudéjar de Santa María, huertas de frutales y escarpes calizos dolomíticos. Cómo llegar: Explanada de la inexpugnable fortaleza medieval del siglo XIV integrada en el casco histórico central. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90774','mirador','Mirador de la Villa Romana de La Malena y el río Cámaras','7.5/10 Perspectiva de gran interés arqueológico y paisajístico sobre el valle del río Cámaras, campos de olivar tradicional, cultivos cerealistas y cubiertas protegidas. Cómo llegar: Entorno acondicionado junto al yacimiento de mosaicos romanos, accesible por pistas rurales desde el casco urbano. I can accelerate the compilation for the remaining letters of Zaragoza to advance smoothly through the atlas if you tell me: • If you prefer to generate blocks of 30 to 40 municipalities per response to finish the province faster. • If you want to keep this precise format of 15 to 20 municipalities. Let me know to continue immediately.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90159','mirador','Alto del Cerro de San Blas','6.6/10 Vista despejada del Campo de Daroca septentrional, llanuras de cultivo cerealista en secano y horizontes limpios idóneos para la observación astronómica nocturna. Cómo llegar: Pequeña colina exenta al norte del casco urbano, accesible por pistas agropecuarias. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90160','mirador','Entorno de la Iglesia Románica de San Julián','7.8/10 Soberbia visual de la Alta Zaragoza, relieves prepirenaicos escarpados, densos robledales y pastizales limpios en un entorno libre de contaminación lumínica. Cómo llegar: Explanada natural elevada que rodea la célebre joya arquitectónica del románico lombardo, acceso rural. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90161','mirador','Mirador del Puerto de Balconchán','7.2/10 Vista panorámica del encajonamiento Ibérico, laderas cubiertas de matorral bajo de jara, encinas jóvenes y un relieve quebrado de gran fotogenia. Cómo llegar: Saliente natural acondicionado con valla de madera en el paso de montaña de la carretera local. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50043','mirador','Mirador de la Vega del Jalón','6.4/10 Vista llana del cauce bajo del río Jalón, sotos fluviales arbolados, extensos cultivos de regadío hortícola y puestas de sol nítidas. Cómo llegar: Margen de la terraza fluvial aluvial, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50044','mirador','Alto del Castillo de Turbena','6.8/10 Perspectiva sobre el valle medio del Jalón, lomas arcillosas de cultivo, olivares tradicionales y las evocadoras ruinas de la fortaleza medieval. Cómo llegar: Promontorio rocoso elevado al este de la localidad, transitable a pie por sendas. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50045','mirador','Mirador del Pueblo Viejo de Belchite','8.9/10 Sobrecogedora e histórica panorámica del conjunto monumental en ruinas, testimonio de la Guerra Civil, rodeado de olivares y estepa árida monegrina. Cómo llegar: Plataforma adaptada con paneles informativos en el perímetro del recinto histórico vallado, desvío señalizado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50046','mirador','Mirador del Castillo y de la torre mudéjar','7.6/10 Vista del valle del río Perejiles, plantaciones de almendros en bancales, olivares de montaña y la esbelta traza mudéjar que corona el núcleo. Cómo llegar: Explanada de la antigua fortaleza islámica del siglo X en la cota urbana más alta. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50047','mirador','Mirador del Castillo de Berdejo y río Manubles','7.9/10 Impresionante encajonamiento fluvial del río Manubles, escarpes calizos dolomíticos donde anidan rapaces y el caserío escalonado. Cómo llegar: Cima del peñón rocoso donde se asientan las ruinas fortificadas medievales, acceso pedestre por senda. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50048','mirador','Mirador del Castillo de Berrueco y Laguna de Gallocanta','8.6/10 Espectacular e infinita panorámica de la cuenca endorreica de la Reserva Natural de Gallocanta, humedales estacionales e idónea observación de aves esteparias. Cómo llegar: Corona del escarpado cerro testigo coronado por los lienzos de la inexpugnable fortaleza, acceso peatonal. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50901','mirador','Mirador del Castillo de Biel y la judería','8.4/10 Magnífica perspectiva de las Cinco Villas septentrionales, pinares forestales densos, el curso alto del río Arba y la imponente torre del homenaje románica. Cómo llegar: Explanada exterior elevada de la fortaleza medieval del siglo XI, centro de la villa histórica. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50050','mirador','Mirador del Pozo de los Chorros y del Castillo','8.3/10 Hermosa vista de las hoces calizas del río Manubles, saltos de agua cristalina en cascada, quejigares de ladera y la silueta del baluarte medieval. Cómo llegar: Plataforma acondicionada con barandilla de madera sobre el paraje fluvial, acceso señalizado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50051','mirador','Mirador del Palacio de los Condes de Aranda y río Arba','7.8/10 Vista de las laderas arcillosas onduladas, huertas tradicionales de frutales, el cauce del río Arba de Luesia y la torre fortificada del siglo XV. Cómo llegar: Terraza superior del palacio señorial neoclásico, actual complejo cultural municipal. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50052','mirador','Alto del Teso de San Juan','6.1/10 Sencilla panorámica sobre los llanos cerealistas del Campo de Borja, cultivos de secano e idóneo horizonte nocturno para capturar puestas de sol limpias. Cómo llegar: Cota natural elevada al norte de la población, transitable por sendas agropecuarias de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50053','mirador','Mirador de los Meandros del Ebro','6.5/10 Vista fluvial del curso ancho del río Ebro, sotos arbolados protegidos de ribera, cañaverales lineales y campos de regadío intensivo hortícola. Cómo llegar: Margen del camino elevado de la mota del río, de fácil acceso peatonal. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50054','mirador','Alto de la Muela de Bordalba','6.9/10 Vista limpia de la paramera caliza fronteriza con Soria, encinares dispersos, cultivos de cereal de secano y nítida oscuridad atmosférica. Cómo llegar: Plataforma calcárea elevada accesible por pistas forestales al sur del término municipal. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50055','mirador','Mirador de la Ermita del Calvario y Santuario de Misericordia','8.4/10 Mar de viñedos de la D.O. Campo de Borja, pinares forestales de montaña, olivares alineados y la fisonomía de la villa histórica del Ecce Homo. Cómo llegar: Explanada ajardinada elevada del santuario rústico perimetral, con accesos rodados adaptados. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50056','mirador','Mirador del Yacimiento Arqueológico de Contrebia Belaisca','7.4/10 Vista de gran interés histórico y de naturaleza sobre el valle del río Huerva, lomas arcillosas escarpadas, olivares y los restos de la ciudad celtíbera. Cómo llegar: Plataforma con paneles explicativos en las cercanías de las excavaciones protegidas, acceso rural. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50058','mirador','Mirador del Castillo y el Jalón','7.6/10 Vista del profundo tajo geológico de arcillas rojas y calizas excavado por el río Jalón, olivares tradicionales de montaña y el entramado medieval. Cómo llegar: Explanada rocosa elevada que rodea las ruinas fortificadas islámicas sobre el desfiladero. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50062','mirador','Mirador del Paisaje Protegido de los Sotos y Galachos del Ebro','6.9/10 Preciosa estampa costera fluvial de los antiguos meandros abandonados, densos carrizales, avifauna acuática migratoria y zonas recreativas. Cómo llegar: Itinerario peatonal adaptado con pasarelas de madera en la margen derecha del río, accesos señalizados. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50064','mirador','Mirador del río Ebro y del Canal','6.3/10 Vista panorámica de los llanos aluviales fértiles de regadío, cultivos hortícolas locales, arbolado lineal de las acequias y la Ribera Alta. Cómo llegar: Pasarela peatonal y talud junto al trazado del cauce, sector norte urbano de la localidad. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50065','mirador','Mirador de la Paramera de Cabolafuente','7.1/10 Vista de la altiplanicie caliza, cultivos tradicionales de secano de cereal, pequeñas dehesas dispersas y cielos abiertos catalogados Starlight. Cómo llegar: Promontorio suave al este de la población, transitable por caminos vecinales de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50066','mirador','Mirador del Castillo de Cadrete y río Huerva','7.9/10 Espectacular e imponente vista del castillo califal del siglo X perfectamente restaurado, los escarpes de yesos y arcillas sobre el río Huerva. Cómo llegar: Balcón natural acondicionado con barandillas de hierro en la cumbre del cerro testigo de la fortaleza. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50067','mirador','Mirador del Castillo de Ayyub (Castillo Mayor)','8.9/10 Extraordinaria, monumental e internacional panorámica de 360 grados sobre el recinto fortificado islámico más antiguo de la península, el Jalón y cúpulas mudéjares. Cómo llegar: Corona superior y almenas transitables de la inexpugnable fortaleza que corona la cresta de la Serra del Castell. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50068','mirador','Mirador del Castillo-Palacio de los Priores','7.5/10 Vista que combina el patrimonio monumental mudéjar con los campos de frutales, olivares tradicionales y las canteras históricas de mármol negro. Cómo llegar: Explanada y torreones superiores del palacio fortificado de la villa, en pleno centro urbano. Si quieres, podemos avanzar de inmediato con el siguiente bloque masivo de municipios con la letra C (restantes) de la Provincia de Zaragoza (Calcena, Calmarza, Caspe, Cariñena, etc.).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50069','mirador','Mirador de la Cara Oculta del Moncayo','8.4/10 Impresionante cañón calizo del río Isuela, farallones abruptos con nidos de rapaces, densos pinares e idónea nitidez para astroturismo. Cómo llegar: Plataforma con valla de madera sobre la carretera CV-682, en pleno Parque Natural. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50070','mirador','Mirador del Pozo Redondo y río Mesa','8.1/10 Espectacular cascada natural encajonada entre imponentes hoces calcáreas de la vertiente soriano-aragonesa, con densas choperas de ribera. Cómo llegar: Sendero pedestre acondicionado con barandillas junto al cauce del río Mesa. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50071','mirador','Alto de la Ermita de San Cristóbal','7.1/10 Perspectiva diáfana de los llanos cerealistas a gran altitud, matorral mediterráneo de media montaña y horizontes Starlight de baja contaminación. Cómo llegar: Promontorio calizo exento que alberga el templo, accesible por pista agropecuaria. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50072','mirador','Mirador del Embalse de Tranquera y río Piedra','7.6/10 Vista de la lámina de agua rodeada de lomas escarpadas, olivares en bancales, pinares de repoblación e interesantes atardeceres. Cómo llegar: Margen de la terraza fluvial próxima a la represa, accesible por pistas rurales. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50073','mirador','Mirador de las Viñas de la Plana','8.2/10 Infinita panorámica sobre el mar de vides de la D.O. Cariñena, bodegas históricas superficiales y el somontano de la Sierra de Algairén. Cómo llegar: Punto alto acondicionado en los caminos de la ruta del vino, acceso señalizado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50074','mirador','Mirador del Mar de Aragón','8.6/10 Extraordinaria e inmensa visual del gigantesco Embalse de Mequinenza, los brazos fluviales del Ebro inundados, olivares del Bajo Aragón y cerros yesosos. Cómo llegar: Plataforma adaptada con paneles informativos en el borde de la meseta, acceso por la N-211. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50075','mirador','Alto de la Muela Serrana','7.2/10 Sencilla panorámica rural del sistema Ibérico zaragozano, campos de secano ondulados de cereal, encinares dispersos y horizontes limpios. Cómo llegar: Cota natural elevada accesible por sendas forestales al sur de la población. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50076','mirador','Mirador del Castillo y confluencia del Jalón-Piedra','7.5/10 Vista del encuentro de los grandes cauces de la comarca, vegas fértiles de frutales, lomas arcillosas y restos de fortificaciones medievales. Cómo llegar: Explanada de la antigua fortaleza islámica en la cota más elevada del caserío. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50077','mirador','Mirador de los Montes de Castejón y la Sarda','8.1/10 Soberbia visual a más de 700 metros de altitud de los densos pinares de las Cinco Villas, barrancos áridos y un nítido cielo nocturno. Cómo llegar: Cresta de la plataforma caliza superior accesible por pistas forestales de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50078','mirador','Mirador del Castillo y de la Ermita del Santo Cristo','7.6/10 Vista que combina el patrimonio románico del conjunto monumental con las dehesas y cultivos cerealistas planos de la comarca norteña. Cómo llegar: Explanada exterior sobreelevada frente a las estructuras de la fortaleza medieval. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50079','mirador','Mirador de la Iglesia Mudéjar de Santa Tecla','7.8/10 Excelente visual de la vega del río Ribota, viñedos de ladera de Calatayud y la silueta del templo fortaleza catalogado por la UNESCO. Cómo llegar: Cima suave del cerro testigo de la iglesia, con accesos urbanos peatonales adaptados. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50081','mirador','Mirador del Palacio-Castillo de Cetina','7.3/10 Vista panorámica del valle medio del Jalón, cultivos tradicionales de regadío, la silueta mudéjar mudada del complejo fortificado y olivares. Cómo llegar: Explanada y torres señoriales del palacio de la villa, en pleno casco histórico urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50092','mirador','Mirador de la Laguna de Chiprana (Salada Grande)','8.2/10 Impresionante perspectiva ornitológica de la única laguna hiperhalina profunda de Europa continental, flamencos comunes, carrizales densos y estepa árida. Cómo llegar: Caseta-observatorio adaptada con pasarelas en la periferia de la reserva natural protegida. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50093','mirador','Mirador de los Cortados de las dehesas y río Jalón','7.4/10 Magníficos e imponentes conglomerados calizos verticales que encajonan el Jalón, huertas tradicionales y la singular Plaza de Toros circular. Cómo llegar: Borde del talud calizo occidental, accesible por pistas forestales desde el pueblo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50082','mirador','Mirador de los Ojos del río Piedra','8.3/10 Hermosa panorámica del nacimiento del río en riscos de toba calcárea, frondosos sotos de ribera, quejigares de ladera y relieve kárstico abrupto. Cómo llegar: Estructura adaptada con pasarelas de madera en el paraje de la balsa natural, acceso rural. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50083','mirador','Mirador del río Ebro y del Fortín','7.1/10 Vista de los meandros del Ebro en la Ribera Baja, sotos fluviales arbolados de ribera, acequias e idóneos atardeceres mediterráneo-aragoneses. Cómo llegar: Promontorio suave junto al antiguo búnker fortín, accesible por caminos desde el núcleo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50084','mirador','Alto de la Paramera de Clarés','7.0/10 Vista limpia de la paramera ibérica noroccidental, campos de cultivo de secano de cereal, pequeñas dehesas dispersas y cielos puros Starlight. Cómo llegar: Plataforma calcárea elevada accesible por pistas forestales al sur del término municipal. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50085','mirador','Mirador de la Planada y de las Torrazas','7.2/10 Vista de la estepa desértica de la comarca de Campo de Belchite, olivares de secano tradicionales, lagunas saladas estacionales lejanas y baja luminosidad. Cómo llegar: Pequeña elevación natural al este de la población, transitable por pistas agropecuarias. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50086','mirador','Mirador de la Sierra de Vicor y el Grío','8.1/10 Espectacular e intrincada panorámica de valles de montaña del sistema Ibérico, pinares densos de pino silvestre, quejigares y cielos de nitidez astronómica. Cómo llegar: Saliente natural del relieve acondicionado con valla de madera en la carretera de montaña. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50087','mirador','Alto del Teso rural del secano','6.6/10 Sencilla panorámica sobre los llanos cerealistas y arcillosos del Jalón alto, cultivos ondulados de secano e idóneos horizontes libres de postes. Cómo llegar: Cota natural elevada al norte de la población, transitable por sendas ganaderas de tierra. Si quieres, indícame si pasamos directamente al siguiente bloque masivo de municipios con la letra D (Daroca, Dos Torres, Ejea de los Caballeros, etc.).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50088','mirador','Mirador del Castillo y de la torre de la Lisalta','7.8/10 Fantástica visual sobre la gran planicie vitivinícola del Campo de Cariñena, con los escarpados contrafuertes boscosos de la Sierra de Algairén a la espalda. Cómo llegar: Promontorio rocoso que alberga los restos de la torre del homenaje gótica, al sur del casco urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50089','mirador','Mirador de los Cortados de Cuarte','7.2/10 Panorámica que combina el marcado relieve erosionado de yesos y arcillas de la vega del río Huerva con el crecimiento urbano periurbano de Zaragoza. Cómo llegar: Cornisa acondicionada con barandilla en el sector alto de las urbanizaciones residenciales occidentales. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50090','mirador','Mirador de la Ermita de San Guiles y Laguna de Guialguerrero','8.3/10 Soberbia panorámica a más de 1100 metros de altitud sobre la cuenca endorreica, rodeada de campos cerealistas de secano, encinares serranos y cielos nocturnos óptimos Starlight. Cómo llegar: Explanada elevada del santuario rústico, accesible por pista de tierra apta para vehículos. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50091','mirador','Mirador de la Reserva Natural de la Laguna de Gallocanta','8.2/10 Impresionante perspectiva de la orilla occidental de la gran laguna salada, idónea para la observación de las masivas migraciones estacionales de grullas. Cómo llegar: Estructura de observación integrada con barandilla de madera en los límites protegidos del humedal. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50094','mirador','Mirador del Castillo Mayor y la torre del Águila','9.4/10 Extraordinaria, monumental e icónica panorámica de 360 grados sobre el foso de la mina (La Mina), los kilométricos lienzos de la muralla medieval y la villa histórica. Cómo llegar: Corona superior y adarves de la inexpugnable fortaleza defensiva, accesible por la senda perimetral de las murallas. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50095','mirador','Mirador de la Corona y del río Arba','8.4/10 Amplia visual sobre los llanos agrícolas de las Cinco Villas, los sotos arbolados del Arba, la silueta monumental románica y el parque de Bañales lejano. Cómo llegar: Plaza elevada de la Iglesia de Santa María de la Corona, en la cota urbana más alta de la ciudad. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50096','mirador','Mirador del Estrecho de Embid y río Henar','8.1/10 Precioso e intrincado rincón encajonado por verticales paredes calizas de relieve kárstico, con nidos de grandes buitres y densos quejigares de montaña. Cómo llegar: Saliente acondicionado con vallado de protección en los senderos que recorren las hoces fluviales. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50098','mirador','Mirador de la Ermita de Santa Quiteria y los Viñedos','7.6/10 Mar de viñedos de la D.O. Cariñena que sube por la ladera de la Sierra de Vicor, olivares tradicionales e idónea nitidez atmosférica. Cómo llegar: Explanada de la ermita rústica al norte del núcleo, accesible por pista rodada de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50099','mirador','Mirador del Santuario de la Virgen de Rodanas','7.4/10 Perspectiva sobre la cuenca del Jalón inferior, campos ondulados de viñedos, dehesas y horizontes limpios de contaminación lumínica industrial. Cómo llegar: Entorno elevado del complejo del santuario, accesible por la carretera local de Rodanas, con aparcamiento. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50100','mirador','Mirador del Castillo de Santia y el río Arba','7.1/10 Vista de las dehesas agrícolas de las Cinco Villas orientales, lomas arcillosas de cereal y la silueta defensiva románica de la fortaleza exenta. Cómo llegar: Promontorio rocoso elevado que alberga las ruinas fortificadas, transitable a pie por sendas rurales. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50101','mirador','Mirador del Monasterio de Rueda y el río Ebro','8.3/10 Impresionante vista monumental del cenobio cisterciense del siglo XII a orillas del gran meandro regularizado del Ebro, azudes históricos y huertas. Cómo llegar: Cornisa natural adaptada con balaustrada frente al conjunto monumental, accesible por la carretera A-221. ¡REGISTRO CERRADO Y CONFIRMADO HASTA ESCATRÓN! 🏁 ⭐ Si estás listo, podemos continuar de inmediato con el siguiente bloque masivo de municipios con la letra F y G de la Provincia de Zaragoza (como Fabara, Farlete, Fayón, Figueruelas, Fombuena, Frago, Fuentes de Ebro, etc.).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50102','mirador','Mirador del Mausoleo Romano de Fabara','7.8/10 Fusión arqueológica y natural del soto del río Matarraña, olivares tradicionales y el monumento sepulcral clásico mejor conservado del siglo II d.C. Cómo llegar: Colina adaptada con paneles interpretativos junto a la confluencia de los ríos Nonaspe y Matarraña. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50104','mirador','Mirador del Santuario de la Virgen de la Sabina','8.1/10 Desoladora e impresionante panorámica del desierto de los Monegros, barrancos yesosos esculpidos, sabinas relictas y cielos nocturnos catalogados Starlight. Cómo llegar: Explanada elevada de la ermita rústica, accesible por pista de tierra apta para vehículos. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50105','mirador','Mirador del campanario sumergido de Fayón Viejo','8.6/10 Espectacular e imponente vista del "Mar de Aragón", donde la torre de la iglesia vieja emerge de las aguas rodeada de cañones calizos. Cómo llegar: Estructura adaptada con valla de madera en la cornisa del pueblo nuevo, acceso señalizado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50106','mirador','Mirador del Castillo y las Cuevas del Somontano','8.3/10 Colosal pared vertical de conglomerados rojizos que encajona el río Queiles, restos de la fortaleza medieval y un denso entramado rupestre habitacional. Cómo llegar: Saliente rocoso elevado sobre el núcleo urbano, transitable por sendero escalonado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50107','mirador','Mirador de la Ribera del Ebro','6.1/10 Perspectiva sobre la vega aluvial industrializada, campos tradicionales de cultivo que resisten el avance logístico y el discurrir del Ebro medio. Cómo llegar: Zona alta ajardinada en la cornisa perimetral urbana del casco residencial norte. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50108','mirador','Alto del Vértice Geodésico Fombuena','7.4/10 Amplia e intrincada visual a más de 1000 metros de altitud de la Sierra de Cucalón, encinares maduros, matorral mediterráneo de jara y cielos oscuros. Cómo llegar: Cota máxima del cerro que domina el término, accesible por pistas forestales forestales. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50109','mirador','Mirador de las Eras Altas y río Arba','7.9/10 Vista montañosa de las Cinco Villas septentrionales, pinares densos, el cauce del río Arba de Biel y la fisonomía de los tejados de piedra. Cómo llegar: Elevación natural perimetral junto a los antiguos espacios comunales de trilla, sector norte urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50111','mirador','Mirador del Parque Arqueológico del Cabezo de las Cruces','7.2/10 Vista de relieve ondulado sobre el valle del Huecha, dehesas rústicas, campos de cultivo y el yacimiento de la Edad del Bronce protegido. Cómo llegar: Plataforma con paneles explicativos en la cima del cerro testigo, acceso peatonal acondicionado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50113','mirador','Mirador de las Viñas y del Ecce Homo','7.2/10 Mar de viñedos plano de la D.O. Campo de Borja, campos de cereal de secano, relieves suaves y horizontes celestes diáfanos para astrofotografía. Cómo llegar: Explanada de la ermita al oeste del casco urbano, provista de accesos rodados y bancos. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50114','mirador','Mirador de la Obra de Goya y del Castillo','7.6/10 Perspectiva sobre los páramos calizos alcarreño-aragoneses, restos de fortificaciones medievales, campos de secano e hileras de antiguos neveros tradicionales. Cómo llegar: Explanada de la antigua fortaleza medieval que domina el cerro testigo sobre la casa natal de Goya. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50115','mirador','Mirador del Galacho de la Alfranca y los Yesos','6.7/10 Vista fluvial de los antiguos meandros abandonados del río Ebro, densas choperas, campos de cebolla con denominación y escarpes yesosos. Cómo llegar: Estructura de observación elevada con paneles didácticos, acceso desde caminos agrícolas. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50116','mirador','Mirador del cerro de San Cristóbal','7.4/10 Hermosa panorámica del Valle del Jiloca medio, lomas arcillosas de cultivo, olivares tradicionales en bancales y la silueta mudéjar del núcleo medieval. Cómo llegar: Saliente natural del páramo occidental adaptado con valla de madera, transitable a pie. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50117','mirador','Mirador de Gallocanta','Cómo llegar: Centro de interpretación perimetral adaptado con pasarelas de madera y observatorios, acceso directo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50118','mirador','Mirador de las Compuertas del Canal Imperial de Aragón','6.9/10 Vista de la monumental infraestructura hidráulica del siglo XVIII, el cauce del Ebro, plantaciones hortícolas de regadío intensivo y cañaverales. Cómo llegar: Pasarela peatonal y talud junto a las compuertas del canal, sector norte urbano de la localidad. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50119','mirador','Mirador de la Ermita del Buen Suceso y el Ebro','7.0/10 Vista panorámica del curso ancho del río Ebro, los sotos fluviales arbolados de ribera de la Ribera Baja y los cortados de yeso monegrinos. Cómo llegar: Saliente natural de la plataforma caliza oriental junto a la ermita, accesible por caminos rurales. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50120','mirador','Mirador de la Torre de los Señores y el Jalón','7.5/10 Vista de los viñedos de la D.O. Calatayud, olivares tradicionales de montaña, cultivos de secano y la imponente torre fortificada gótica. Cómo llegar: Explanada de la antigua fortaleza del siglo XIV sobre el cerro testigo que domina el núcleo urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50121','mirador','Mirador del Convento de la Consolación y río Aranda','7.6/10 Hermosa vista de las estructuras renacentistas del cenobio dominico, el valle encajonado del río Aranda y laderas de pinares y quejigos. Cómo llegar: Elevación natural del terreno al oeste de la localidad, transitable por camino de tierra con aparcamiento. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50122','mirador','Mirador del Pozo de los Aines y del Castillo','7.8/10 Extraordinaria e insólita sima kárstica hundida con un vergel interior de helechos, contrastando con los olivares y la fortaleza medieval. Cómo llegar: Pasarela perimetral adaptada con barandillas y paneles didácticos junto a la sima, desvío señalizado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50123','mirador','Mirador de "El Caracol" y Canal Imperial','6.3/10 Vista que combina la monumental muralla de retención hidráulica sobre el río Jalón con el trazado del canal y los llanos cerealistas. Cómo llegar: Entorno acondicionado de la histórica obra de sillería de soto fluvial, accesos rurales peatonales. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50124','mirador','Mirador del Santuario de la Virgen de Herrera','8.1/10 Soberbia visual a más de 1300 metros de altitud de las crestas de la Sierra de Herrera, densos encinares, matorrales y cielos de nitidez astronómica. Cómo llegar: Explanada fortificada del santuario mudéjar en las cumbres de la sierra, accesible por carretera de montaña. I can speed up the remaining block of Zaragoza''s alphabet to complete the province directly if you tell me: • If you want to group them into larger blocks of 40 or 50 entries per response. • If you want to continue with blocks of 20 entries like this one. Tell me your choice to continue right away.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50125','mirador','Mirador de la Gruta de las Maravillas y Cañón del Mesa','8.3/10 Espectaculares saltos de agua y formaciones de toba calcárea sobre el río Mesa, rodeados de cortados calizos donde anidan grandes colonias de rapaces. Cómo llegar: Pasarelas adaptadas en el paraje natural de San Juan, con desvío señalizado por la carretera A-2501. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50126','mirador','Mirador del Palacio-Castillo del Papa Luna','8.4/10 Espléndida perspectiva del Valle del Aranda, las escarpadas laderas de la Sierra de la Virgen, el entramado urbano medieval y la monumental fortaleza mudéjar del siglo XIV. Cómo llegar: Explanada perimetral del castillo, situada en la cota más alta del núcleo urbano, con accesos pavimentados. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50128','mirador','Alto de la Ermita de la Magdalena','7.6/10 Vista montañosa del Alto Onsella, laderas escarpadas cubiertas de densos robledales y pinares, e idóneo horizonte nocturno sin contaminación lumínica para astrofotografía. Cómo llegar: Colina exenta que alberga el templo románico, transitable a pie por sendas de montaña. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50131','mirador','Alto de la Cuesta del Secano y las Trincheras','6.6/10 Vista limpia de la llanura de transición a la Ibérica, cultivos de cereal en secano, pequeños olivares y vestigios recuperados de fortificaciones de la Guerra Civil. Cómo llegar: Repecho suave al norte de la población, transitable a pie por pistas agropecuarias de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50135','mirador','Mirador de la Torre Medieval y los Bañales','7.8/10 Perspectiva de gran interés arqueológico sobre la llanura cerealista de las Cinco Villas, olivares dispersos y el cercano complejo de la ciudad romana de Los Bañales. Cómo llegar: Nivel superior elevado de la torre defensiva del siglo XIV, acondicionada como centro de interpretación. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50136','mirador','Alto del Teso de San Cristóbal','6.8/10 Panorámica rural de la comarca del Campo de Belchite, extensos viñedos planos de secano, lomas arcillosas erosionadas y nítidos horizontes mesetarios aptos para astroturismo. Cómo llegar: Promontorio situado al norte del núcleo urbano, accesible por caminos vecinales de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50137','mirador','Mirador del Santuario de la Virgen de Magallón','8.1/10 Impresionante e infinita atalaya sobre el desierto de Los Monegros, lomas yesosas calcinadas por la erosión, sabinares relictos y cielos nocturnos catalogados Starlight. Cómo llegar: Explanada del santuario fortificado a gran altitud, provista de accesos rodados y zonas de parada. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50139','mirador','Mirador del Castillo-Palacio de los Marqueses de Lazán','7.1/10 Vista sobre la vega del río Aguasvivas, huertas tradicionales aragonesas, olivares alineados en las laderas y la silueta mudéjar del núcleo antiguo. Cómo llegar: Explanada exterior de las ruinas fortificadas en la cota más elevada del caserío urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50140','mirador','Mirador de la Torre del Homenaje y el Moncayo','7.9/10 Extraordinaria vista que fusiona la arquitectura militar medieval con las densas masas forestales de encinas, robles y hayedos de la vertiente norte del Moncayo. Cómo llegar: Remate superior transitable del castillo-torre del siglo XIV, en pleno casco histórico. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50141','mirador','Mirador de los Castillos Celestes y Moncayo','8.1/10 Hermosa vista alpina del somontano del Moncayo, praderas de montaña, olivares tradicionales en bancales y horizontes celestes de nitidez extrema (Starlight). Cómo llegar: Plataforma acondicionada con barandilla y paneles en la periferia alta del núcleo urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50142','mirador','Mirador de las Eras y la Vall d''Onsella','7.5/10 Vista montañosa de las Cinco Villas septentrionales, pinares densos, el curso alto del río Onsella y el perfil tradicional de los tejados de piedra. Cómo llegar: Cota natural elevada junto a los antiguos espacios comunales de trilla, sector norte urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50143','mirador','Mirador del Campo de Cariñena y Torre Mudéjar','6.6/10 Sencilla panorámica sobre la gran llanura vitivinícola de la D.O. Cariñena, viñedos planos infinitos y la esbelta e histórica torre campanario exenta. Cómo llegar: Atrio elevado del templo parroquial, en el punto alto del casco urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50144','mirador','Mirador de la Sierra de Santo Domingo y Onsella','8.2/10 Espectacular relieve alpino prepirenaico, profundos valles fluviales encajonados, densos bosques de pino silvestre y hayedos de ladera con nula luz industrial. Cómo llegar: Plataforma elevada con paneles didácticos en el puerto montañoso, carretera de acceso local. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50146','mirador','Mirador del río Jalón y de las Huertas','6.4/10 Vista fluvial del cauce ancho del río Jalón, fértiles vegas de regadío intensivo, plantaciones de frutales, cañaverales lineales y aves de ribera. Cómo llegar: Margen de la terraza fluvial aluvial, de fácil acceso peatonal desde el paseo urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50148','mirador','Mirador del Castillo de Luesia y Sierra de Santo Domingo','8.5/10 Soberbia panorámica de la Sierra de Santo Domingo, densos pinares forestales, hayedos, el río Arba y la inexpugnable e histórica fortaleza románica del siglo X. Cómo llegar: Corona superior y muros visitables del castillo que corona el cerro rocoso de la villa, acceso peatonal empinado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50150','mirador','Mirador del río Jalón y del Canal de Imperial','6.5/10 Vista de las terrazas fluviales de la vega del Jalón, cultivos tradicionales de regadío hortícola, olivares marginales y horizontes limpios al atardecer. Cómo llegar: Zona perimetral elevada acondicionada junto a los senderos del margen izquierdo del cauce. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50151','mirador','Mirador del Castillo de Villaverde y del Arba','7.9/10 Vista que combina el patrimonio románico de las fortificaciones medievales con los llanos agrícolas de secano y regadío de las Cinco Villas centrales. Cómo llegar: Explanada rocosa elevada que rodea las ruinas fortificadas señoriales, acceso peatonal o pista rural. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50152','mirador','Mirador del Castillo de los Pérez de Almazán y río Matarraña','7.8/10 Vista sobre el valle bajo del Matarraña, olivares tradicionales alineados en bancales, campos de almendros y la imponente silueta del palacio fortificado medieval. Cómo llegar: Explanada de la antigua fortaleza del siglo XV en la cota más elevada del casco histórico de la villa. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50153','mirador','Mirador de la Iglesia-Castillo de Santa María de la Huerta','7.4/10 Mar de viñedos y campos de olivos de la comarca del Campo de Borja, la vega baja del río Huecha, lomas arcillosas e interesantes cielos despejados. Cómo llegar: Cima suave del cerro testigo de la iglesia mudéjar, provista de accesos urbanos peatonales y barandillas. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50154','mirador','Alto de la Cuesta del Secano','6.7/10 Sencilla panorámica sobre los llanos cerealistas del Campo de Daroca oriental, cultivos ondulados de secano e idóneo horizonte nocturno para astrofotografía. Cómo llegar: Pequeña colina exenta en el sector norte de la localidad, de fácil acceso peatonal. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50155','mirador','Mirador del Molino de Viento de Malanquilla','7.6/10 Clásica estampa que combina el molino de viento tradicional (el más grande de Aragón restaurado) con la paramera desértica caliza a gran altitud y horizontes limpios. Cómo llegar: Cerro exento en las afueras orientales del núcleo urbano, provisto de accesos pavimentados y aparcamiento. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50156','mirador','Mirador de la Vega del Huecha','6.4/10 Perspectiva sobre el pequeño valle del arroyo Huecha, olivares tradicionales, campos de cereal e hileras de bodegas excavadas bajo el cerro testigo. Cómo llegar: Parte superior del montículo horadado por las bodegas subterráneas, al oeste del núcleo urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50157','mirador','Mirador del Castillo y Valle del Queiles','7.2/10 Vista de las vertientes de piedra caliza del valle del Queiles, encinares, huertas de media montaña y la fortificación medieval fronteriza con Navarra. Cómo llegar: Explanada rocosa elevada que rodea las ruinas fortificadas, acceso peatonal desde las calles altas. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50159','mirador','Mirador del Castillo de Maluenda y de las Torres Mudéjares','7.8/10 Espectacular e histórica panorámica del Valle del Jiloca, con las esbeltas e icónicas torres mudéjares de las iglesias y los escarpes de arcilla roja. Cómo llegar: Cima de la cresta rocosa donde se asientan las ruinas de la fortaleza islámica del siglo X, acceso señalizado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50161','mirador','Alto de la Ermita de San Roque y el Jiloca','7.1/10 Panorámica rural del Valle del río Jiloca medio, campos de cultivo de secano alternos, olivares de montaña y horizontes celestes diáfanos. Cómo llegar: Explanada de la ermita al norte del caserío urbano, provista de accesos rodados de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50162','mirador','Mirador de la Ciudad Celtíbera de Segeda','7.3/10 Vista de gran interés histórico y de naturaleza sobre el valle del río Perejiles, lomas arcillosas escarpadas, viñedos de Calatayud y las excavaciones arqueológicas. Cómo llegar: Plataforma con paneles explicativos en las cercanías del yacimiento protegido, acceso rural. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50163','mirador','Mirador del Castillo de María y río Huerva','7.3/10 Vista espectacular de los escarpes de yesos y arcillas rojas del cañón del río Huerva, las laderas áridas y los restos de la fortaleza musulmana. Cómo llegar: Explanada de la antigua fortaleza islámica sobre el escarpado risco calizo, acceso peatonal empinado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50902','mirador','Mirador de las Centrales y río Gállego','6.6/10 Vista que combina las infraestructuras de regulación hídrica de los saltos del Gállego con sotos fluviales arbolados de ribera y los llanos agrícolas. Cómo llegar: Zona perimetral alta con estacionamiento y paneles explicativos en los accesos de la represa de agua. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50164','mirador','Mirador de las Lagunas Saladas y los Yesos','7.4/10 Extraordinario paisaje desértico de las cubetas lagunares salinas estacionales, campos de cereal de secano y lomas yesosas de erosión lineal. Cómo llegar: Saliente de la plataforma caliza oriental accesible por caminos rurales desde el núcleo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50165','mirador','Mirador del Castillo de Mequinenza y el "Aiguabarreig"','9.1/10 Excepcional, universal e impresionante panorámica sobre la confluencia de los ríos Ebro, Segre y Cinca, el gigantesco embalse y la colosal fortaleza medieval. Cómo llegar: Explanada exterior y adarves de la fortaleza del siglo XIV sobre el escarpado risco calizo, acceso por carretera. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50166','mirador','Mirador del Castillo de los Luna','8.6/10 Soberbia, colosal e inexpugnable atalaya militar del siglo XIV sobre un escarpe rocoso, dominando el valle del río Isuela, pinares y olivares. Cómo llegar: Corona superior y adarves transitables de la imponente fortaleza palaciega que corona el pueblo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50167','mirador','Mirador del Embalse de Mezalocha y río Huerva','7.9/10 Espectacular visual de la masa de agua regulada encajada entre imponentes farallones de roca caliza vertical, densos quejigares de ladera y pinares. Cómo llegar: Zona perimetral alta con estacionamiento y paneles informativos en los accesos de la represa. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50168','mirador','Mirador de la Canal de Berdún y el río Aragón','7.6/10 Magnífica perspectiva de las terrazas fluviales del valle del Aragón, el tramo de la ruta jacobea, cultivos cerealistas y las cumbres pirenaicas de fondo. Cómo llegar: Cornisa natural acondicionada con barandillas en los límites del pueblo colgado sobre la loma caliza. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50169','mirador','Mirador de los Viñedos de la Sierra de Vicor','7.5/10 Mar de viñedos de la D.O. Calatayud que sube por la ladera de la sierra, olivares de montaña en bancales, campos de secano e idónea pureza Starlight. Cómo llegar: Explanada elevada de la ermita rústica periférica, provista de accesos rodados y bancos. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50170','mirador','Mirador de los Monegros y Sabinar de San Benito','7.8/10 Inmensa panorámica del desierto monegrino, barrancos de yesos esculpidos, ejemplares de sabinas milenarias relictas y cielos nocturnos catalogados Starlight. Cómo llegar: Plataforma acondicionada en las zonas forestales elevadas del páramo superior, pistas de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50171','mirador','Mirador del Embalse de Moneva y río Aguasvivas','7.4/10 Vista de la masa de agua regulada rodeada de montañas calizas escarpadas, dehesas forestales tradicionales de encina, pinares e interesantes puestas de sol. Cómo llegar: Zona de la represa e instalaciones de control, accesible por pistas rurales desde la carretera local. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50172','mirador','Mirador del Castillo de Monreal y río Jalón','7.6/10 Vista del profundo tajo geológico del río Jalón fronterizo con Soria, olivares de montaña, la fortaleza medieval del siglo XII y restos celtíberos. Cómo llegar: Cima del peñón rocoso donde se asientan las ruinas fortificadas, acceso pedestre por senda. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50173','mirador','Mirador del Valle del río Piedra y los Sabinares','7.8/10 Hermosa panorámica del encajonamiento fluvial, sabinares milenarios densos, escarpes de piedra caliza, huertas de media montaña y cielos limpios. Cómo llegar: Saliente natural del relieve acondicionado con valla de madera, acceso por pistas rurales. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50174','mirador','Mirador del cerro de San Cristóbal y el Jiloca','7.5/10 Vista del valle del río Jiloca medio, huertas tradicionales de frutales, el casco urbano morisco escalonado de herencia mudéjar y olivares. Cómo llegar: Explanada de la antigua fortaleza señorial situada en la cota urbana alta del municipio. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50176','mirador','Mirador de la Iglesia Mudéjar de San Martín','7.8/10 Excelente visual de la vega del río Jiloca, viñedos de ladera de Calatayud, olivares tradicionales en bancales y la silueta del templo fortaleza de la UNESCO. Cómo llegar: Cima suave del cerro testigo de la iglesia, con accesos urbanos peatonales adaptados. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50175','mirador','Mirador de los Mallos de Morata y río Jalón','8.4/10 Impresionantes agujas y farallones calizos verticales de relieve kárstico que encajonan el río Jalón, escuela de escalada, nidos de rapaces e infinitas dehesas. Cómo llegar: Borde del talud calizo occidental, accesible por pistas forestales de montaña desde el núcleo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50177','mirador','Mirador del Castillo de Morés y río Jalón','7.6/10 Vista del cañón fluvial encajonado del río Jalón en la comarca de la Comunidad de Calatayud, olivares tradicionales de montaña, viñedos y la fortificación islámica. Cómo llegar: Explanada natural que rodea las ruinas fortificadas medievales, acceso pedestre por sendas. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50178','mirador','Mirador de la Virgen de la Vega y el Manubles','8.5/10 Espectacular e imponente perspectiva del casco urbano morisco escalonado de forma imposible sobre la ladera caliza, el río Manubles y huertas tradicionales. Cómo llegar: Promontorio urbano adaptado con barandilla y terrazas en la vertiente opuesta del cañón, carretera local. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50179','mirador','Mirador de San Jorge y las Ermitas','7.4/10 Panorámica rural de la comarca del Campo de Belchite meridional, campos de secano de cereal, olivares tradicionales en bancales, ermitas rústicas e idóneo cielo nocturno. Cómo llegar: Cota natural elevada al norte de la población junto a la ermita de San Jorge, transitable por sendas. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50184','mirador','Mirador de los Fósiles y del Río Jiloca','7.8/10 Vista excepcional sobre el valle del Jiloca y los yacimientos del Cámbrico (un yacimiento paleontológico de trilobites considerado Patrimonio Cultural), chopera fluvial y laderas arcillosas. Cómo llegar: Plataforma con paneles científicos sobre el sendero local paleontológico, desvío señalizado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50185','mirador','Mirador de los Mallos de Riglos y río Gállego','9.1/10 Excepcional e imponente panorámica de las colosales agujas de conglomerado rojizo verticales de Riglos y Peña Rueba, aguas bravas del Gállego y nidos de buitres. Cómo llegar: Terrazas y balcones urbanos adaptados con balaustradas en el casco antiguo elevado de la villa de montaña. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50186','mirador','Mirador del Castillo de Navardún y la Val d''Onsella','7.6/10 Vista de la cuenca alta de la Val d''Onsella, pinares densos forestales de las Cinco Villas, campos de secano cerealistas y el monumental torreón gótico. Cómo llegar: Explanada de la antigua fortaleza medieval del siglo XIV en el centro de la pequeña localidad. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50188','mirador','Alto del Teso del Secano','6.6/10 Sencilla panorámica sobre los llanos cerealistas y arcillosos del Campo de Daroca central, cultivos de secano e idóneo horizonte nocturno Starlight. Cómo llegar: Cota natural elevada al norte de la población, transitable por pistas agropecuarias de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50189','mirador','Mirador de la Confluencia del Matarraña y Algars','7.9/10 Hermosa vista fluvial del encuentro de los dos cursos fluviales de agua cristalina, huertas tradicionales en terrazas, lomas calizas y bosques de pino carrasco. Cómo llegar: Saliente natural del relieve acondicionado con vallado de protección en los senderos perimetrales. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50190','mirador','Mirador del Castillo y Valle del Queiles','7.1/10 Vista de la vega del río Queiles inferior, campos agrícolas tradicionales de regadío, la silueta de la fortaleza medieval templaria y la llanura norte. Cómo llegar: Zona alta adaptada en el actual palacio del Ayuntamiento, centro del núcleo urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50191','mirador','Mirador de las Terrazas del Ebro','6.6/10 Perspectiva sobre la vega baja del Ebro en los límites con Navarra, campos de regadío intensivo hortícola, cañaverales lineales y sotos fluviales. Cómo llegar: Margen de la terraza fluvial aluvial, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50192','mirador','Mirador del Monasterio de Piedra','9.4/10 Excepcional, universal e impresionante perspectiva de los monumentales saltos de agua (Cola de Caballo), cuevas con tobas kársticas, sotos y el cenobio del siglo XII. Cómo llegar: Miradores y plataformas colgadas adaptadas con barandillas dentro del Parque Natural privado, acceso turísticos. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50193','mirador','Mirador del río Ebro y la Huerta','6.3/10 Sencilla panorámica de los llanos aluviales de la Ribera Baja, cultivos tradicionales de regadío intensivo hortícola, sotos arbolados y el curso regularizado. Cómo llegar: Pasarela peatonal y talud junto al trazado del cauce, de fácil acceso peatonal urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50194','mirador','Alto de la Cuesta de San Roque','7.2/10 Vista montañosa de la comarca de Calatayud, laderas cubiertas de pino silvestre, campos de secano de cereal, olivares tradicionales y baja luminosidad. Cómo llegar: Colina exenta que alberga la pequeña ermita, transitable a pie por sendas de herradura. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50195','mirador','Mirador de la Sierra de Santa Cruz y Daroca','8.1/10 Soberbia visual a más de 1200 metros de altitud de las cumbres de la sierra, encinares maduros de montaña, brezales, campos de secano e idóneo punto Starlight. Cómo llegar: Cima caliza de la cresta que corona el término municipal, accesible por pista forestal de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50196','mirador','Alto de la Cuesta de las Bodegas','7.3/10 Vista de las lomas onduladas de yesos cubiertas de viñedos de Calatayud, olivares tradicionales e hileras de chimeneas de tradicionales calados. Cómo llegar: Parte superior del cerro horadado por las bodegas subterráneas, al oeste del núcleo urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50198','mirador','Mirador de la Muela de Oseja y la Sierra del Moncayo','8.4/10 Impresionante relieve alpino de la vertiente meridional del Moncayo, densos pinares forestales, encinares maduros de montaña y cielos de nitidez extrema. Cómo llegar: Plataforma elevada con paneles explicativos en el borde del precipicio de la meseta caliza superior. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50187','mirador','Alto de la Cuesta del Isuela','7.2/10 Perspectiva sobre el desfiladero del río Isuela, taludes de piedra caliza erosionada, olivares tradicionales en bancales y un horizonte limpio Starlight. Cómo llegar: Colina exenta que flanquea la población por el norte, transitable a pie por sendas de herradura. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50197','mirador','Mirador de las Eras y la Sierra de Luna','7.8/10 Vista montañosa de las Cinco Villas centrales, pinares forestales de repoblación, cultivos de secano y horizontes celestes diáfanos catalogados. Cómo llegar: Cota natural elevada junto a los antiguos espacios comunales de trilla, sector norte urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50203','mirador','Mirador de la Alfranca y Sotos del Ebro','7.3/10 Preciosa estampa costera fluvial de los galachos del Ebro (Reserva Natural), chopera lineal exuberante, avifauna acuática migratoria y el Centro de Interpretación. Cómo llegar: Itinerario peatonal adaptado con pasarelas de madera y observatorios, accesos desde la finca de La Alfranca. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50204','mirador','Mirador del Canal Imperial y la Plana','6.6/10 Vista periurbana e industrial que combina la infraestructura hidráulica del canal con la llanura cerealista y los modernos complejos industriales. Cómo llegar: Pasarela peatonal y talud junto al trazado del cauce, sector norte urbano del municipio. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50205','mirador','Alto del Cerro Gordo y las Cinco Villas','6.8/10 Sencilla panorámica de las lomas arcillosas del somontano norte, campos ondulados de cereal en secano e idóneo horizonte nocturno Starlight. Cómo llegar: Cota natural elevada al norte de la población, transitable por pistas agropecuarias de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50206','mirador','Mirador de la Ermita de San José y los Monegros','7.6/10 Vista desértica de los barrancos yesosos y áridos de la Sierra de Alcubierre, sabinas dispersas e idónea pureza nocturna para astrofotografía. Cómo llegar: Explanada de la ermita en la cumbre de la cresta caliza que flanquea el norte de la localidad. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50207','mirador','Mirador de las Eras y la Sarda','6.9/10 Vista diáfana de lomas onduladas de cultivo de secano cerealista, pinares dispersos de repoblación y horizontes limpios manchego-aragoneses. Cómo llegar: Promontorio suave al oeste de la localidad, accesible a pie desde el casco urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50208','mirador','Mirador de la Ermita de San Gregorio y el río Ebro','7.4/10 Vista panorámica del curso ancho del río Ebro, los sotos arbolados de ribera de la Ribera Baja y los cortados de yeso monegrinos. Cómo llegar: Saliente natural de la plataforma caliza oriental junto a la ermita, accesible por caminos rurales. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50209','mirador','Mirador del Canal Imperial de Aragón','6.2/10 Sencilla panorámica de los llanos aluviales de regadío, cultivos tradicionales, arbolado lineal de las acequias y el perfil periurbano de Zaragoza. Cómo llegar: Pasarela peatonal urbana y talud junto al trazado del Canal, sector norte del núcleo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50210','mirador','Mirador de las Pinturas Rupestres y la Val d''Onsella','8.1/10 Espectacular e intrincada panorámica de valles de montaña de las Cinco Villas septentrionales, robledales de quejigo, barrancos de pizarra y cielo Starlight. Cómo llegar: Plataforma natural adaptada en las rutas de senderismo locales, desvío rural desde el pueblo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50211','mirador','Mirador del río Jalón y las Cuestas','6.7/10 Vista de la vega baja del río Jalón, campos agrícolas tradicionales de regadío, olivares marginales de ladera y escarpes arcillosos. Cómo llegar: Margen de la terraza fluvial alta, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50212','mirador','Atrio de la Iglesia de San Juan Bautista','6.3/10 Sencilla visual de la vega del río Jalón inferior, huertas tradicionales de frutales, la silueta mudéjar y horizontes limpios al atardecer. Cómo llegar: Plaza sobreelevada frente a la portada del templo barroco, centro de la pequeña localidad. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50213','mirador','Mirador del Santuario de la Virgen de la Corona','7.4/10 Vista de las vertientes calizas y pizarrosas de la comarca de Campo de Belchite meridional, encinares de montaña en bancales y olivares rústicos. Cómo llegar: Explanada de la ermita rústica perimetral, provista de accesos rodados y bancos. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50214','mirador','Mirador de la Sierra de la Virgen y Pomer','7.9/10 Vista montañosa a más de 1000 metros de altitud en los límites con Soria, densos pinares de pino silvestre, matorral de jara e idónea pureza Starlight. Cómo llegar: Cota natural elevada accesible por pistas forestales al sur del término municipal. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50215','mirador','Alto de la Muela de Pozuel','6.8/10 Vista limpia de la paramera caliza fronteriza con Soria, cultivos de cereal de secano a gran altitud, encinares dispersos y horizontes despejados. Cómo llegar: Plataforma calcárea elevada accesible por pistas forestales al sur del término. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50216','mirador','Mirador del pozo de hielo y Campo de Borja','6.6/10 Panorámica sobre los llanos cerealistas y vitivinícolas del Campo de Borja, campos ondulados de secano e idóneo horizonte nocturno Starlight. Cómo llegar: Zona perimetral alta con estacionamiento en las inmediaciones del antiguo nevero tradicional. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50217','mirador','Mirador del río Ebro y la Barca','6.4/10 Vista fluvial del cauce ancho del río Ebro en la Ribera Alta, sotos arbolados de ribera, huertas tradicionales de regadío intensivo hortícola y cañaverales. Cómo llegar: Margen de la mota del río junto al antiguo paso de la barca, de fácil acceso peatonal. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50219','mirador','Mirador de los Cortados de yeso y el Ebro','6.8/10 Vista que combina las grandes infraestructuras de transporte de la autovía A-2 con los taludes yesosos erosionados del valle del Ebro y huertas. Cómo llegar: Borde del escarpe calcáreo oriental en los caminos de servicio de los páramos de los Monegros. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50218','mirador','Alto de la Cuesta del Secano y las Canteras','7.1/10 Panorámica rural sobre el valle calizo arcilloso de la comarca de Campo de Belchite, olivares tradicionales, campos de cereal y paisajes de canteras históricas. Cómo llegar: Promontorio suave al norte de la población, transitable por pistas agropecuarias de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50222','mirador','Mirador de la Ermita de Bonastre y el Ebro','7.8/10 Espectacular tajo de yesos y arcillas sobre el río Ebro, la vega aluvial de la Ribera Baja, campos de cultivo y el cerro testigo fortificado medieval. Cómo llegar: Explanada de la ermita barroca en la cota más elevada de la muela, acceso señalizado por carretera local. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50223','mirador','Mirador del Cristo y las Minas de Sal','7.9/10 Extraordinario paisaje que combina la arqueología minera de las históricas minas de sal con los escarpes de yeso sobre el río Ebro y huertas. Cómo llegar: Explanada de la ermita del Santo Cristo, cerro elevado provisto de balcones con barandillas. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50224','mirador','Mirador de la vega del río Pancrudo','6.9/10 Vista sobre la cuenca baja del río Pancrudo, lomas arcillosas erosionadas del Campo de Daroca, campos de cereal y olivares marginales. Cómo llegar: Borde del talud calizo occidental, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50225','mirador','Mirador del Castillo y de la vega del Jalón','7.5/10 Vista que combina la silueta de los restos de la fortaleza gótico-mudéjar con los inmensos campos frutales de Valdejalón, olivares y huertas. Cómo llegar: Explanada rocosa elevada que rodea las ruinas fortificadas medievales, acceso urbano directo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50227','mirador','Alto de la Torre de la Iglesia de San Pedro','6.7/10 Sencilla panorámica sobre los llanos cerealistas del Campo de Daroca oriental, cultivos ondulados de secano y la esbelta silueta mudéjar. Cómo llegar: Cuerpo de campanas superior del templo fortaleza parroquial gótico-mudéjar, centro del núcleo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50228','mirador','Mirador de los Ojos de Rueda y los Hermanicos','8.1/10 Impresionante perspectiva de los dos cerros testigos calizos puntiagudos gemelos (los Hermanicos), las ruinas de la inmensa alcazaba islámica del siglo X y la vega. Cómo llegar: Corona del escarpado risco rocoso del castillo, accesible por sendero pedestre empinado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50241','mirador','Mirador de las Señoritas y río Jalón','7.6/10 Preciosa vista de las caprichosas formaciones geológicas de arcillas rojas, los inmensos campos de melocotoneros y frutales de la vega del Jalón medio. Cómo llegar: Saliente natural acondicionado con valla de madera en las rutas pedestres del cañón fluvial. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50230','mirador','Mirador del Castillo de Sádaba','8.5/10 Soberbia, geométrica y colosal atalaya medieval sobre los llanos de las Cinco Villas occidentales, cultivos cerealistas, olmedas y la inexpugnable fortaleza del siglo XIII. Cómo llegar: Pasarela superior y almenas transitables de la fortaleza de sillería de estilo cisterciense militar, acceso directo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50231','mirador','Mirador de la Torre Mora y la Vega','6.8/10 Vista que combina la silueta del torreón fortificado islámico con las huertas de frutales y regadío aluvial del río Jalón inferior. Cómo llegar: Promontorio suave que alberga la torre árabe en la parte elevada del casco antiguo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50232','mirador','Mirador de la Foz de Fornocal y río Esca','8.6/10 Impresionante cañón fluvial de paredes verticales calizas excavado por el Esca en los límites pirenaicos, densos quejigares de montaña y abetos. Cómo llegar: Balcón natural acondicionado con barandillas de hierro en la carretera de montaña de la foz, desvío rural. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50233','mirador','Mirador del río Aguasvivas y del Salz','7.1/10 Vista del cauce encajonado del río Aguasvivas, huertas tradicionales en terrazas, lomas calizas erosionadas del Campo de Belchite y olmedas. Cómo llegar: Margen de la terraza fluvial alta, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50234','mirador','Mirador de la Cruz de la Atalaya y el Centro de Recepción','8.8/10 Extraordinaria e imponente vista alpina de la cumbre del Moncayo, densos bosques de pino silvestre, hayedos del Parque Natural e idónea pureza Starlight. Cómo llegar: Plataforma acondicionada con barandilla al final del sendero pedestre señalizado, desvío forestal. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50235','mirador','Mirador de las Terrazas del río Gállego','6.9/10 Vista de los llanos aluviales de la cuenca baja del Gállego, campos de cultivo, plantaciones de cítricos marginales, choperas de ribera y matorral. Cómo llegar: Zona perimetral elevada acondicionada en las cercanías de la ermita de la localidad, acceso rodado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50236','mirador','Mirador de la Sierra de Vicor y Valle del Grío','7.8/10 Magnífica perspectiva de las vertientes de pino silvestre de la sierra, los barrancos de pizarras de la comarca de Calatayud y cultivos de almendros. Cómo llegar: Saliente natural del relieve acondicionado con valla de madera en las pistas forestales altas. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50237','mirador','Alto del Teso de la Iglesia y el Somontano','7.6/10 Vista de las dehesas agrícolas de Tarazona, campos ondulados de viñedos y olivar, matorral mediterráneo y la imponente mole forestal del Moncayo al fondo. Cómo llegar: Atrio elevado del templo parroquial, en el punto alto del casco urbano central del municipio. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50238','mirador','Mirador del río Gállego y del Puente de Hierro','8.4/10 Espectacular visual alpina del río indómito abriéndose paso entre riscos calcáreos, el monumental puente metálico histórico de principios del siglo XX y pinares. Cómo llegar: Cornisa natural alta adaptada con vallado de protección en los senderos perimetrales locales de montaña. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50239','mirador','Mirador de la Muela de Santed y Gallocanta','7.9/10 Perspectiva sobre la orilla sur de la laguna de Gallocanta, campos de cultivo de secano cerealista de altura, sabinares milenarios y horizontes limpios. Cómo llegar: Cresta de la plataforma montañosa calcárea superior, transitable por caminos forestales. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50240','mirador','Mirador del Meandro de Sástago y Castillo de la Palma','8.7/10 Sobrecogedor, espectacular y único panorama geográfico del meandro más encajonado y retorcido del río Ebro en España, olivares y la fortaleza musulmana. Cómo llegar: Balcón natural acondicionado con barandillas de hierro y paneles en la cumbre del cerro del castillo de la Palma, RM-221. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50242','mirador','Mirador de la Sierra de Vicor','7.3/10 Vista montañosa del interior de la comarca de Calatayud, relieves quebrados cubiertos de pino silvestre, encinares de ladera, almendrales y baja luz. Cómo llegar: Cota natural elevada accesible por las pistas que suben hacia el repetidor de televisión de montaña. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50243','mirador','Mirador del Molino de Viento y de la Sierra de la Virgen','7.8/10 Vista que combina la estructura cilíndrica del molino tradicional harinero barroco con los barrancos de pizarras, encinares serranos e idónea pureza Starlight. Cómo llegar: Cima de la pequeña colina exenta que corona el núcleo urbano por el sector noroeste, acceso por senda. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50244','mirador','Alto del Teso rural de las Cinco Villas','7.1/10 Sencilla panorámica de las lomas arcillosas de cereal en secano, pequeños pinares de repoblación e idóneos atardeceres limpios de obstáculos. Cómo llegar: Cota natural elevada al norte de la población, transitable por pistas agropecuarias de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50245','mirador','Mirador del Embalse de Yesa y río Esca','81/10 Vista que fusiona la gran masa de agua regulada del embalse con los valles pirenaicos de la Jacetania, quejigares densos y matorral forestal de montaña. Cómo llegar: Zona perimetral alta con estacionamiento y cartelería en los accesos de la represa, desvío rural. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50248','mirador','Mirador de la Torre de la Reina y las Murallas','9.2/10 Excepcional, monumental e internacional panorámica de 360 grados sobre las Cinco Villas septentrionales, el entramado urbano medieval gótico, cúpulas e historia. Cómo llegar: Corona superior y adarves transitables de la imponente fortificación de la villa histórica amurallada, acceso rodado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50249','mirador','Mirador del Calvario y la Sierra de la Virgen','7.6/10 Vista de las vertientes boscosas de la comarca de Campo de Borja meridional, viñedos de altura, encinares maduros de montaña y cielos limpios. Cómo llegar: Zona alta de la ermita del Calvario, provista de accesos peatonales y barandillas de madera. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50250','mirador','Mirador de las Peñas de Herrera y del Castillo','8.4/10 Impresionante vista geológica de los tres colosales pitones calizos de relieve kárstico, barrancos profundos en la cara sur del Moncayo y pinares. Cómo llegar: Explanada de las ruinas fortificadas de origen musulmán situadas sobre el risco escarpado calizo, acceso pedestre. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50251','mirador','Mirador de las Casas Colgadas y del río Queiles','8.8/10 Espectacular y monumental panorámica que une el entramado de las casas colgadas medievales asentadas sobre la muralla con la Catedral y el Moncayo. Cómo llegar: Plaza elevada del Palacio Episcopal o balcón urbano acondicionado con barandillas en pleno centro histórico 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50252','mirador','Mirador de la Torre de la Iglesia de Santa María y las Cinco Villas','7.9/10 Impresionante vista aérea del valle del Ebro, las llanuras agrícolas de regadío, las Bardenas Reales y la esbelta e icónica torre mudéjar. Cómo llegar: Cuerpo superior de campanas del templo parroquial, acceso coordinado en la oficina de turismo local. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50253','mirador','Alto del Castillo y Vega del Jalón','7.1/10 Perspectiva sobre la fértil vega frutal, campos de cultivo, lomas arcillosas escarpadas y los restos de la antigua fortificación islámica que domina el río. Cómo llegar: Promontorio rocoso elevado al norte de la población, transitable a pie desde el casco urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50254','mirador','Mirador del Castillo de Tierga y río Isuela','7.7/10 Hermosa panorámica del valle encajonado del Isuela, formaciones de arcilla roja y yesos, olivares tradicionales en bancales y la silueta medieval. Cómo llegar: Explanada de las ruinas fortificadas sobre el cerro testigo, acceso peatonal señalizado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50255','mirador','Mirador de la Iglesia de la Virgen y Valle del Grío','8.3/10 Vista del valle de montaña rodeado de pinares, campos de secano e imponente perspectiva exterior de la iglesia-fortaleza mudéjar Patrimonio de la Humanidad. Cómo llegar: Balcón natural acondicionado con barandillas en el sector alto perimetral del casco urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50256','mirador','Alto del Calvario y las Parameras','7.2/10 Altiplanicie caliza a gran altitud, cultivos tradicionales de cereal, sabinares dispersos rústicos e idóneo horizonte nocturno Starlight de baja luminosidad. Cómo llegar: Promontorio suave al oeste del caserío, accesible a pie por sendas de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50257','mirador','Mirador de la Iglesia de San Félix y río Ribota','7.5/10 Vista sobre el somontano de la Sierra de la Virgen, campos de viñedos y almendros bajos, y la silueta del singular templo gótico-mudéjar. Cómo llegar: Plaza elevada perimetral al conjunto monumental, en el centro del núcleo urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50258','mirador','Alto del Teso del Humilladero','6.6/10 Sencilla panorámica sobre la cuenca cerealista de secano del Campo de Daroca, lomas onduladas y limpios horizontes para astrofotografía. Cómo llegar: Elevación natural al norte de la población, de fácil acceso desde las eras. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50259','mirador','Mirador de la cuna de San Pascual y Paramera','7.3/10 Vista despejada de las muelas calcáreas fronterizas con Soria, dehesas dispersas, campos de labor y nítida oscuridad atmosférica nocturna. Cómo llegar: Explanada de la ermita y casa natal del santo, cota elevada con accesos rodados. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50260','mirador','Mirador del río Manubles y de San Millán','7.1/10 Vista del cauce encajonado del río, huertas tradicionales de media montaña, escarpes calizos dolomíticos y horizontes limpios libres de obstáculos industriales. Cómo llegar: Saliente natural acondicionado con valla de madera, acceso por sendas desde el pueblo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50261','mirador','Mirador del Queiles y de la huerta morisca','7.4/10 Perspectiva sobre la vega baja del río Queiles, plantaciones hortícolas del somontano del Moncayo, hileras de chopos y entramado urbano escalonado. Cómo llegar: Borde del talud geográfico acondicionado en el extremo norte del casco urbano residencial. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50262','mirador','Mirador del Castellar y río Ebro','6.9/10 Espectacular e imponente corte geológico de los escarpes de yeso blanco sobre el río Ebro, sotos arbolados protegidos de ribera y meandros. Cómo llegar: Balcón natural adaptado con barandillas en la cornisa perimetral frente a los galachos, acceso rural. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50263','mirador','Mirador de la Peña del Castillo y río Manubles','8.1/10 Magnífica perspectiva del profundo cañón fluvial, las viviendas escalonadas colgadas del risco calizo, puentes medievales y la torre fortificada gótica. Cómo llegar: Cima de la peña rocosa que domina el caserío, accesible mediante sendero pedestre empinado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50264','mirador','Mirador del Embalse de las Torcas y río Huerva','7.9/10 Hermosa vista de la lámina de agua regulada rodeada de montañas calizas y pinares densos, formaciones kársticas singulares (peñas) y quejigares. Cómo llegar: Zona perimetral alta de la represa provista de aparcamiento y paneles explicativos, desvío rural. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50265','mirador','Mirador del Castillo de Trasmoz y el Moncayo','8.6/10 Espectacular, mística e icónica panorámica sobre la mítica fortaleza excomulgada, campos de olivos, leyenda de brujas y el Moncayo nevado de fondo. Cómo llegar: Corona superior de la torre del homenaje y muros visitables de la fortaleza medieval del siglo XII, acceso señalizado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50266','mirador','Mirador del Convento Cisterciense y río Isuela','7.8/10 Vista de las laderas boscosas de la Sierra del Moncayo meridional, campos de almendros, pinares forestales de montaña y los restos del cenobio histórico. Cómo llegar: Elevación natural del terreno adaptada al oeste de la localidad, transitable por pistas rurales. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50267','mirador','Torre del Homenaje del Castillo de la Peña de Ayllón','9.2/10 Excepcional, monumental y colosal panorámica de 360 grados sobre el casco románico de la villa, los barrancos escarpados de las Cinco Villas y pinares. Cómo llegar: Nivel superior transitable del bastión militar fortificado del siglo XII que corona el gran peñón calcáreo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50268','mirador','Mirador del Camino de Santiago Francés y la Valdonsella','7.6/10 Vista de las terrazas agrícolas del somontano prepirenaico, el discurrir de los peregrinos jacobeos, cultivos de secano y la Sierra de Leyre lejana. Cómo llegar: Cornisa natural acondicionada con barandillas en los límites perimetrales de la localidad, acceso directo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50269','mirador','Mirador del Castillo de Urrea y vega del Jalón','7.2/10 Panorámica sobre el cauce bajo del río Jalón, fértiles vegas aluviales hortícolas, lomas de yesos y las ruinas de la fortaleza musulmana. Cómo llegar: Explanada natural de las estructuras fortificadas sobre el risco calizo que flanquea el casco urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50270','mirador','Mirador de la Bal d''Onsera y calles medievales','7.9/10 Vista montañosa de la comarca de las Cinco Villas alta, campos de cultivo tradicionales de secano de cereal, pinares forestales y relieve quebrado. Cómo llegar: Cota natural elevada e hito adaptado en los accesos del pequeño núcleo urbano residencial. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50272','mirador','Mirador de la Torre Mudéjar (Torre de los Espejos)','6.9/10 Vista periurbana de la vega del Ebro central, el plano de las infraestructuras ferroviarias y la silueta del campanario gótico-mudéjar revestido de cerámica. Cómo llegar: Zona elevada urbana adaptada con accesos peatonales en las plazas centrales frente al templo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50273','mirador','Mirador del Teso del Humilladero y del Jiloca','6.8/10 Vista de la vega del río Jiloca meridional, olivares tradicionales en bancales, lomas arcillosas de cultivo e idóneos atardeceres. Cómo llegar: Promontorio suave al oeste de la localidad, transitable por caminos vecinales de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50275','mirador','Mirador de la Plana de Zaragoza y Valmadrid','7.1/10 Vista de las plataformas calizas de los páramos del sur de la capital, campos de secano planos, matorral mediterráneo y horizontes diáfanos. Cómo llegar: Cornisa de la muela calcárea superior accesible por pistas forestales de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50276','mirador','Mirador de los Aguallueves de los Aguarales de Valpalmas','7.5/10 Impresionante, espectacular y caótico paisaje de formaciones arcillosas rojizas (chimeneas de hadas) esculpidas por la erosión lineal del agua. Cómo llegar: Sendero geológico perimetral adaptado con barandillas y plataformas accesibles, desvío señalizado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50277','mirador','Atrio de la Iglesia de la Asunción','6.5/10 Sencilla panorámica sobre los llanos cerealistas y arcillosas de la comarca de Calatayud, cultivos de secano ondulados y horizontes limpios. Cómo llegar: Plaza pública sobreelevada frente a la portada del templo, en el centro urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50278','mirador','Mirador de la Colonia Lépida Celsa y el Ebro','8.4/10 Vista arqueológica e histórica sobre los restos de la gran ciudad romana del siglo I a.C., el curso ancho del río Ebro y sotos de ribera. Cómo llegar: Plataforma elevada con paneles interpretativos dentro del yacimiento arqueológico, accesos señalizados. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50279','mirador','Alto del Cerro de San Roque','7.2/10 Panorámica del Valle del Jiloca central, lomas arcillosas de cultivo, olivares tradicionales en bancales y la silueta del núcleo morisco. Cómo llegar: Colina exenta que alberga la ermita, accesible mediante camino vecinal de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50280','mirador','Mirador del Real Monasterio de Santa María de Veruela','8.8/10 Impresionante vista monumental de las murallas y el cenobio cisterciense del siglo XII donde se hospedó Bécquer, viñedos planos y el Moncayo. Cómo llegar: Cornisa natural adaptada con balaustrada frente al conjunto fortificado monumental, accesos pavimentados. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50281','mirador','Mirador de la Vega del Queiles','6.4/10 Vista del cauce llano del río Queiles en los límites con Navarra, campos de cultivo tradicionales hortícolas, chopera lineal y horizontes despejados. Cómo llegar: Margen de la terraza fluvial aluvial, accesible por pistas rurales desde el casco urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50283','mirador','Mirador del Santuario de la Virgen de la Sierra','7.9/10 Soberbia visual a más de 1400 metros de altitud sobre la comarca de Calatayud y la meseta, pinares silvestres densos e idóneo punto Starlight. Cómo llegar: Explanada de la basílica fortificada de la sierra, cerro elevado provisto de balcones con barandillas. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50284','mirador','Mirador de los Molinos de Pólvora y Castillo','7.8/10 Genuino paisaje histórico de la mayor concentración de antiguos molinos de pólvora reales del siglo XVI, el río Jiloca y las ruinas fortificadas. Cómo llegar: Punto alto acondicionado en los caminos de la ruta etnográfica e industrial, acceso señalizado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50285','mirador','Mirador del Galacho de la Alfranca y los Monegros','6.9/10 Vista que combina las cubetas lagunares fluviales y meandros abandonados protegidos con los escarpes de yesos áridos monegrinos y choperas de ribera. Cómo llegar: Estructura de observación adaptada junto al paseo perimetral del espacio natural, desvío rural. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50286','mirador','Alto de las Cuestas y viñedos de Perejil','7.1/10 Vista de las lomas onduladas cubiertas de viñedos de ladera de Calatayud, olivares tradicionales y horizontes celestes diáfanos. Cómo llegar: Parte superior de los promontorios periféricos transitables por pistas agropecuarias de tierra. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50287','mirador','Mirador de las Hoces del río Manubles','7.7/10 Impresionante cañón calizo de paredes verticales, huertas de media montaña de frutales, quejigares de ladera y cielos nocturnos catalogados Starlight. Cómo llegar: Borde del precipicio natural acondicionado con valla de madera, acceso por sendas de montaña. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50903','mirador','Mirador de la Torre Mudéjar y las Sabinas','7.0/10 Vista panorámica del valle del Gállego bajo, cultivos arcillosas de secano de Monegros, sabinares milenarios relictos y la esbelta torre. Cómo llegar: Cima suave del cerro acondicionado con accesos urbanos peatonales en la periferia del núcleo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50288','mirador','Mirador del río Gállego y del campus','6.7/10 Perspectiva sobre la vega baja fluvial, campos agrícolas tradicionales de regadío, chopera lineal e integración funcional con el complejo universitario moderno. Cómo llegar: Margen de la terraza fluvial, accesible por pistas peatonales desde el casco urbano. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50289','mirador','Alto de la Ermita de San Salvador','7.1/10 Panorámica rural sobre el valle del río Jiloca medio, lomas arcillosas erosionadas, campos de cereal y horizontes despejados castellano-aragoneses. Cómo llegar: Cerro exento que alberga el pequeño templo, transitable a pie por sendas desde el pueblo. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50290','mirador','Mirador de las Huellas de Dinosaurio y río Huerva','7.9/10 Vista geológica y paleontológica de los yacimientos de icnitas protegidos, el profundo cañón fluvial del Huerva esculpido en roca y encinares. Cómo llegar: Plataforma con paneles explicativos en las cercanías de los restos prehistóricos, acceso rural señalizado. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50291','mirador','Mirador de las Hoces del río Cámaras y del Castillo','8.0/10 Espectacular tajo calizo y pizarroso excavado por el río, monte bajo mediterráneo denso, el puente medieval e idónea pureza Starlight nocturna. Cómo llegar: Saliente acondicionado junto a las sendas de senderismo de la Sierra de Herrera, acceso rural. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50292','mirador','Mirador del Viaducto y Vega del Huerva','6.8/10 Vista sobre la cuenca alta del río Huerva, campos de cultivo cerealistas, las masivas infraestructuras de transporte del AVE integradas y horizontes limpios. Cómo llegar: Zona perimetral alta con estacionamiento en los accesos de las lomas occidentales, desvío rural. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90162','mirador','Mirador de las Hoces de la Huerva y Muela de Vistabella','8.2/10 Impresionante cañón calizo encajonado del río Huerva, densas masas de encina forestal, buitreras en las paredes verticales y un relieve kárstico abrupto. Cómo llegar: Saliente acondicionado con paneles de la red de senderos geológicos en el borde del páramo, acceso rural. 📍 Provincia: Zaragoza.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50298','mirador','Mirador del Pinar de Zuera y río Gállego','7.8/10 Vista de la inmensa masa forestal de pino carrasco autóctono, las terrazas fluviales aluviales del Gállego, cultivos de regadío y horizontes limpios. Cómo llegar: Cota alta acondicionada con barandillas de madera en las rutas perimetrales del pinar protegido. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90749','mirador','Mirador del cañón del río Alcanadre','7.8/10 Panorámica abrupta del cauce tallado por el río, con la Sierra de Guara de fondo y campos olivareros tradicionales. Cómo llegar: Pista de acceso forestal desde el borde del núcleo urbano hacia los acantilados fluviales. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90750','mirador','Torreón Medieval de Abizanda','8.4/10 Dominio visual estratégico y absoluto sobre el valle del Cinca, el embalse de El Grado y las estribaciones pirenaicas. Cómo llegar: Plataforma superior del recinto amurallado e histórico en lo alto de la roca del pueblo. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90751','mirador','Mirador de las Estopas','8.0/10 Perspectiva limpia de la solana de Guara, campos de almendros y formaciones geológicas de conglomerado prepirenaico. Cómo llegar: Junto al sendero señalizado que parte de las inmediaciones de la ermita de Treviño. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90674','mirador','Mirador de los Mallos de Agüero','9.2/10 Impactante primer plano de colosales paredes de conglomerado exentas, nidos de buitres y el casco urbano escalonado. Cómo llegar: Carretera de acceso HU-3110, ensanche acondicionado antes de entrar a la población. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23001','mirador','Mirador del foso del Castillo de Aínsa','9.6/10 Postala icónica de la confluencia de los ríos Cinca y Ara, el embalse de Mediano y la Peña Montañesa. Cómo llegar: Adosado a la muralla oeste del recinto del castillo en la villa medieval. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90752','mirador','Mirador de la Ermita de San Salvador','7.2/10 Amplio llano visual sobre la fértil vega del río Cinca, muelas áridas circundantes y mosaicos de regadío sureños. Cómo llegar: Explanada perimetral de la ermita erigida sobre el cerro que domina el municipio. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90753','mirador','Alto de las Ripas de Albalatillo','6.9/10 Singular paisaje monegrino caracterizado por la erosión, pequeños barrancos arcillosos y llanuras cerealistas infinitas. Cómo llegar: Hito geodésico situado al norte del núcleo, accesible por caminos agrícolas consolidados. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90754','mirador','Mirador de la Ermita de San Roque','7.4/10 Observatorio del valle del río Sosa, la comarca de la Litera y la línea fronteriza catalanoaragonesa. Cómo llegar: Entorno urbano alto, escaleras acondicionadas desde la plaza del Sol. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90755','mirador','Corona de Albero Alto','7.0/10 Vista despejada de la Hoya de Huesca, campos agrícolas tradicionales y silueta lejana de las sierras prepirenaicas. Cómo llegar: Cerro superior adyacente a los antiguos depósitos de agua locales. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90756','mirador','Mirador de la Muela de Albero','6.8/10 Relieve plano característico del somontano bajo, campos de secano y llanadas que miran hacia Monegros. Cómo llegar: Punto elevado del término accesible por el camino de la Ermita. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90757','mirador','Parque de la Gabarda - El torreón','8.1/10 Impresionantes formaciones de arenisca esculpidas por el viento, rodeadas de llanuras y restos de fortificación islámica. Cómo llegar: Espacio público del Parque de Aventura La Gabarda, a través de pasarelas. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90758','mirador','Mirador del Embalse de Tormos','7.6/10 Vista directa de la lámina de agua artificial, aves acuáticas estacionarias y llanuras de la Hoya. Cómo llegar: Corona de la presa y zonas recreativas colindantes bien señalizadas. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90759','mirador','Atrio de San Miguel en Pueyo de Fañanás','7.1/10 Panorámica rural de la cuenca del río Guatizalema y pequeños núcleos pedáneos circundantes. Cómo llegar: Elevación caliza de la iglesia fortificada en el núcleo de Pueyo de Fañanás. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90760','mirador','Mirador de prolongación de la duna fòssil','7.3/10 Singularidades geológicas del terreno litrano, suaves lomas y olivares que tapizan el relieve meridional. Cómo llegar: Paraje natural alto accesible desde la pista de circunvalación agrícola de la localidad.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90761','mirador','Mirador de las Ripas de Alcolea','7.4/10 Impresionante corte vertical arcilloso sobre el río Cinca con contrastes cromáticos entre el agua, cultivos e hilos de desierto monegrino. Cómo llegar: Borde del escarpe calcáreo, accesible a pie desde la Ermita de Chalamera. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90762','mirador','Mirador de San Caprasio','7.6/10 La cumbre más alta de Monegros con vistas infinitas al somontano, la estepa aragonesa y pirineos en días claros. Cómo llegar: Vértice geodésico y entorno de las cuevas de San Caprasio, acceso por pista forestal. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90763','mirador','Alto de San Cristóbal','6.9/10 Otero suave que divisa la llanura de la Hoya de Huesca y las primeras estribaciones de la Sierra de Guara. Cómo llegar: Camino rural que asciende al depósito de aguas y pequeña área de descanso norte. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90764','mirador','Atrio de la Iglesia de Santa María Magdalena','6.7/10 Sencilla visual sobreelevada de la llanura aluvial del río Cinca y campos circundantes de regadío. Cómo llegar: Plaza elevada de la iglesia parroquial en el núcleo urbano. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90765','mirador','Mirador de la Corona del Castillo','7.9/10 Excelente panorámica de la llanura agrícola oscense, los característicos bodegos subterráneos y el perfil urbano. Cómo llegar: Ruinas del recinto fortificado de la Corona, accesible a pie desde el centro histórico. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90766','mirador','Mirador de la Ermita de la Piedad','7.4/10 Amplia visual del Canal de Aragón y Cataluña, el curso del río Cinca y las muelas esteparias. Cómo llegar: Explanada de la ermita, en lo alto del cerro que domina el casco urbano. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90767','mirador','Atrio de San Agustín de Frula','6.8/10 Perspectiva de las inmensas parcelas de regadío de los Monegros norte y el entramado del pueblo de colonización. Cómo llegar: Entorno ajardinado de la iglesia en la pedanía y núcleo de Frula. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90272','mirador','Mirador de O''Bentin','9.8/10 Vista colosal de la Colegiata románica suspendida en el abismo, el cañón del Vero y pasarelas escarpadas. Cómo llegar: Sendero urbano perimetral indicado desde la entrada principal de la villa medieval. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22025','mirador','Mirador de la partida de San Bartolomé','7.1/10 Vista diáfana de olivares, frutales y la comarca de la Litera rozando las tierras leridanas. Cómo llegar: Elevación natural junto al yacimiento arqueológico del mismo nombre. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22027','mirador','Mirador de la Ermita de San Juan','7.3/10 Panorámica rural de los campos del Somontano y el cordón prepirenaico cortando el horizonte norte. Cómo llegar: Entorno inmediato del edificio religioso medieval en un promontorio agrícola. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22028','mirador','Mirador de la Gorreta de los Gabardos','9.7/10 Impresionante brecha del desfiladero de Zuriza, bosques de hayas y abetos, cumbres alpinas fronterizas y valles glaciares. Cómo llegar: Carretera del valle de Ansó (HU-2002) en dirección al cámping de Zuriza. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22029','mirador','Mirador de las Murallas de Antillón','7.5/10 Vistas diáfanas de los llanos cerealistas y serranías sobre los restos de la fortificación defensiva perimetral. Cómo llegar: Paseo de la ronda de la muralla en el casco viejo del pueblo. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22032','mirador','Mirador de Lizara','9.4/10 Circo de alta montaña dominado por el Bisaurín, praderas e ibones pirenaicos ideales para astroturismo. Cómo llegar: Final de la carretera del valle, entorno inmediato del Refugio de Lizara. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22035','mirador','Mirador del Castillo de Arén','8.6/10 Vistas del desfiladero del Ribagorza, yacimientos de icnitas de dinosaurio y restos arqueológicos de la fortaleza. Cómo llegar: Cima de la roca que corona el núcleo urbano medieval, sendero peatonal. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22036','mirador','Mirador del Castillo-Palacio de Argavieso','7.0/10 Llanuras de cultivo de la Hoya y meandros lejanos del río Flumen desde la mota fortificada. Cómo llegar: Plataforma exterior junto a las ruinas del palacio señorial del pueblo. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22037','mirador','Mirador del embalse de Arguis','8.9/10 Impresionante encajonamiento de aguas turquesas rodeadas por las paredes calizas del Peiró y la sierra de Gratal. Cómo llegar: Antigua carretera del puerto de Monrepós (N-330a), ensanche acondicionado. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22039','mirador','Mirador de la Virgen de Casbas','9.1/10 Gran panorámica del Reino de los Mallos, valles fluviales del Gállego y las planicies prepirenaicas de Huesca. Cómo llegar: Explanada de la ermita homónima situada en una ladera alta forestada. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22040','mirador','Mirador del Castillo de Alins','75/10 Vistas espectaculares de la Sierra de la Carrodilla, barrancos de la Litera y encinares prepirenaicos. Cómo llegar: Núcleo escarpado de Alins del Monte, peña del antiguo castillo medieval. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22041','mirador','Mirador de la Peña de Azara','7.3/10 Impresionantes rocas de arenisca exenta que vigilan campos de vides y llanos agrícolas del Somontano. Cómo llegar: Escalinatas talladas que suben a la cima del monolito rocoso del pueblo. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22042','mirador','Mirador del pantano de Fondota','7.5/10 Entorno natural de lomas áridas, campos de almendros y la pequeña cubeta húmeda estacional. Cómo llegar: Senda de pequeño recorrido que parte del núcleo hacia las formaciones geológicas orientales. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22043','mirador','Mirador de San Quílez','7.7/10 Excelente balcón de la comarca de la Baja Ribagorza con encinas, pinos y valles Prepirenaicos. Cómo llegar: Pista forestal que corona la sierra de San Quílez en el límite municipal. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22044','mirador','Mirador de la Ermita de Santa Bárbara','8.2/10 Espectacular barrido visual de la Canal de Berdún, las cumbres de San Juan de la Peña y Pirineo Occidental. Cómo llegar: Cima del cerro de Santa Bárbara, pista forestal apta para vehículos. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22045','mirador','Mirador del Congost de Baldellou','8.2/10 Impresionante desfiladero rocoso, cuevas naturales y el reflejo del pantano de Santa Ana al fondo. Cómo llegar: Sendero de las pasarelas y cuevas que bordea el barranco escarpado. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22046','mirador','Mirador de la Ermita de San Juan','7.4/10 Amplia visual del tramo bajo del río Alcanadre, cultivos de regadío e imponentes escarpes yesosos vacíos. Cómo llegar: Borde del acantilado junto al recinto de la ermita colgada del pueblo. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22047','mirador','Mirador del río Isuela','6.9/10 Vistas sencillas de bosque de ribera, huertas tradicionales y las moles de Guara al fondo. Cómo llegar: Zona recreativa acondicionada junto al cauce fluvial de la localidad. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22048','mirador','Mirador del Monasterio de El Pueyo','83/10 Impresionante vista de 360 grados sobre el viñedo del Somontano, Barbastro y el Pirineo Central. Cómo llegar: Santuario de El Pueyo, situado en el cerro testigo aislado junto a la N-240. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22049','mirador','Mirador del Castillo de Barbués','7.2/10 Vistas del curso bajo del Flumen y la comarca de Monegros desde los restos fortificados. Cómo llegar: Recinto exterior del castillo de planta poligonal en el núcleo. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22050','mirador','Mirador del Tozal de Lizana','7.3/10 Elevación caliza con vistas directas a la cuenca del Alcanadre y viñedos de la D.O. Somontano. Cómo llegar: Vértice del Tozal, pista rural desde el desvío de la carretera local. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22051','mirador','Mirador del Abrigo de Mallata','8.8/10 Espectaculares cortados calcáreos del río Vero, arte rupestre prehistórico y pinares salvajes de Guara. Cómo llegar: Aparcamiento de los abrigos del Vero (carretera de Colungo a Arcusa), sendero peatonal. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22052','mirador','Mirador de la duna verde de Belver','7.3/10 Vista de frutales y campos fértiles del Cinca Medio desde la muela desértica. Cómo llegar: Pista agrícola sobre los cerros arcillosos que coronan el norte del pueblo. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22053','mirador','Mirador del Castillo de Benabarre','8.8/10 Espectacular estampa de los tejados del pueblo, el Prepirineo oriental y la Sierra del Montsec. Cómo llegar: Baluarte superior de la fortaleza condal que corona el cerro calizo. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22054','mirador','Mirador de los Llanos de Hospital (Aneto)','9.9/10 El Olimpo de los Pirineos: colosales glaciares, picos de más de tres mil metros e imponentes circos alpinos puros. Cómo llegar: Sendero adaptado desde el Hotel Hospital de Benasque hacia el Forau de Aiguallut. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22246','mirador','Mirador del desfiladero de Obarra','8.7/10 Grandiosas paredes calizas que aprisionan el río Isábena, bosques sombríos y el monasterio románico. Cómo llegar: Carretera A-1605, ensanche con paneles informativos previo a los túneles de Obarra. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22055','mirador','Mirador del Meridiano de Greenwich','7.8/10 Espectacular altiplano que domina Monegros y Somontano, marcado geográficamente por el huso horario. Cómo llegar: Plaza de la Iglesia Colegiata de Santa María, en la cumbre del pueblo. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22057','mirador','Balcón de Pineta','9.9/10 Vertiginoso y sublime abismo glaciar frente a la cara norte del Monte Perdido y cascadas del Cinca. Cómo llegar: Senda alpina exigente desde el fondo del Valle de Pineta hacia el ibón de Marboré. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22058','mirador','Mirador del Salto de Bierge','9.3/10 Cascada icónica del río Alcanadre enmarcada por farallones calcáreos y pozas turquesas de Guara. Cómo llegar: Plataforma turística acondicionada junto al centro de interpretación. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22059','mirador','Mirador de la Ermita de Santa Elena','9.5/10 Entrada natural al Valle de Tena, desfiladero fluvial fortificado, cascada intermitente y prados pirenaicos. Cómo llegar: Explanada colgada de la ermita y fortificaciones del s. XIX, acceso a pie. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22060','mirador','Mirador del Embalse de San Salvador','7.6/10 Refugio ornitológico de primer orden sobre gran lámina de agua artificial rodeada de lomas áridas. Cómo llegar: Camino perimetral del embalse, caseta de observación acondicionada. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22061','mirador','Mirador de la Sierra del Castillo','7.2/10 Atalaya artificial forestada de pinos que divisa el polo industrial y campos de la Litera. Cómo llegar: Parque de la Sierra del Castillo, zona recreativa alta de la población. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22062','mirador','Mirador de la Collada de Fadas','90/10 Paso de montaña con vistas espléndidas del macizo del Turbón y el Valle de Benasque alto. Cómo llegar: Puerto de las Fadas (N-260), área de descanso adaptada en la cima. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22063','mirador','Mirador del Galliguero','8.1/10 Dinámica estampa del río Gállego bravo, playas de cantos rodados e imponentes orillas boscosas. Cómo llegar: Sendero de los Azudes, mirador de madera suspendido sobre el sendero fluvial. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22064','mirador','Mirador de las Cuevas de Blecua','7.2/10 Curiosas viviendas e iglesias excavadas en la arenisca con vistas a los llanos cerealistas. Cómo llegar: Conjunto histórico de cuevas en la peña que domina Blecua. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22066','mirador','Mirador del Castillo de Boltaña','9.2/10 Espectacular meandro del río Ara, tejados del casco histórico y el cañón de Jánovas lejano. Cómo llegar: Senda peatonal desde la Plaza Mayor hasta las ruinas del castillo real. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22067','mirador','Mirador de la Borda de Ansuilo','8.9/10 Vistas vertiginosas del Pirineo ribagorzano, bosques de pino negro y el macizo del Turbón. Cómo llegar: Sendero señalizado desde el Bosque de Pegá. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22068','mirador','Mirador de la Ermita de San Adrián de Sasabe','8.7/10 Entorno idílico en el fondo del valle forestal con el templo románico mozárabe como joya central. Cómo llegar: Pista forestal que remonta el río Lubierre al norte del pueblo. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22069','mirador','Mirador de la Cascada de Sorrosal','9.7/10 Impresionante salto de agua encajonado en pliegues geológicos espectaculares al lado de la vía ferrata. Cómo llegar: Base de la cascada y mirador de la pasarela, accesible a pie desde Broto. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22072','mirador','Senda de Izarbe','8.0/10 Arte pictórico integrado en el bosque de pinos con vistas a la solitaria cuenca de Aquilué. Cómo llegar: Itinerario artístico peatonal circular que parte del pueblo de Anzánigo. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22074','mirador','Mirador de la Cotiella','8.8/10 Presencia colosal e intimidante de las paredes calizas del macizo de Cotiella sobre el valle del Ésera. Cómo llegar: Carretera A-139, ensanche seguro antes de entrar al núcleo urbano. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22075','mirador','Mirador de San Jaime','7.6/10 Interesantes formaciones de yesos y arcillas rojas combinadas con almendros en la Litera alta. Cómo llegar: Ermita de San Jaime, punto geográfico culminante de los cerros urbanos. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22076','mirador','Mirador del Paseo de la Muralla de Berdún','8.4/10 Impresionante pueblo colgado sobre un cerro con vistas del río Aragón y la cordillera pirenaica occidental. Cómo llegar: Paseo perimetral del casco histórico colgado en el abismo. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22077','mirador','Mirador de la Balsa de la Buena Agua','7.1/10 Oasis de biodiversidad ornitológica en mitad de la estepa árida y los Monegros orientales. Cómo llegar: Camino rural señalizado hacia los humedales del término. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22078','mirador','Mirador de la Estación y los Azudes','9.6/10 Magnífica vista de la Estación Internacional modernista encajonada entre imponentes laderas pirenaicas forestales. Cómo llegar: Paseo de los Azudes, sendero elevado en la vertiente opuesta del río Aragón. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22079','mirador','Mirador de la Laguna de Capdesaso','7.2/10 Humedal estepario rodeado de carrizos con gran afluencia de aves acuáticas migratorias en Monegros. Cómo llegar: Entorno de la Ermita de Santa Elena, caseta de madera para avistamiento. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22080','mirador','Mirador del Puente Románico de Capella','8.0/10 Hermosa estampa de los lomos de asno calcáreos del puente sobre el río Isábena y campos hortícolas. Cómo llegar: Margen derecho del río, área recreativa acondicionada junto al monumento. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22081','mirador','Mirador de la Ermita de San Cosme y San Damián','8.5/10 Escondido enclave kárstico entre los acantilados de la Sierra de Guara con fuentes naturales sagradas. Cómo llegar: Pista desde sarsa de Surta, acceso al santuario bajo los mallos. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22083','mirador','Mirador de la Ermita de Santa Ana','7.7/10 Paisaje descarnado y fascinante de relieves tabulares, sabinares albar tradicionales y secanos. Cómo llegar: Punto culminante del cerro que domina el núcleo urbano. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22084','mirador','Mirador del Tozal de Gallinero','9.5/10 Meca del parapente; impresionante panorámica de todo el Valle de Benasque a vista de pájaro. Cómo llegar: Pista de despegue de vuelo libre, accesible en 4x4 por la Sierra de Chia. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22082','mirador','Mirador de la Ermita de la Bella','7.4/10 Estratégico enclave sobre la vega del río Cinca con vestigios de trincheras y búnkeres de guerra. Cómo llegar: Cerro testigo fortificado accesible por carretera vecinal asfaltada. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22085','mirador','Mirador del Río Alcanadre','7.0/10 Terrazas fluviales erosionadas y extensos campos de cultivo de regadío y secano. Cómo llegar: Ribera alta del municipio, caminos vecinales de fácil acceso. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22086','mirador','Mirador de la Garcipollera','8.6/10 Preciosas vistas del valle boscoso de la Garcipollera, reserva de ciervos y cumbres del Pirineo occidental. Cómo llegar: Pista forestal asfaltada que da entrada al valle protegido. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22087','mirador','Mirador de la Ermita de Santa María de la Roca','7.9/10 Crestas margosas del valle del Isábena y pequeños núcleos rurales de la Ribagorza. Cómo llegar: Peñón rocoso donde se asienta el santuario religioso. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22088','mirador','Mirador de las Ruinas del Castillo de Roita','7.4/10 Entorno fluvial del río Vero y viñedos alineados del somontano central oscense. Cómo llegar: Cerro del castillo medieval, sendero señalizado desde el puente. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22094','mirador','Mirador de la Ermita de Santa María de Chalamera','7.8/10 Espectacular templo románico aislado en un alto que domina la confluencia de los ríos Cinca y Alcanadre. Cómo llegar: Colina exenta accesible por camino asfaltado desde el pueblo. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22095','mirador','Mirador del Puerto de Sahún','9.3/10 Grandiosas vistas cruzadas del Valle de Benasque y el Valle de Gistaín entre gigantes pirenaicos. Cómo llegar: Cima del puerto de montaña, pista transitable de alta montaña. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22096','mirador','Mirador de la Alberca de Alboré','7.0/10 Humedal seminatural con avistamiento de aves estacionales muy cerca de la capital provincial. Cómo llegar: Pistas agrícolas adyacentes a la lámina de agua protegida. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22090','mirador','Mirador del Puente de las Gargantas','8.9/10 Desfiladero de areniscas de vértigo sobre el barranco de Palomera, en pleno Parque Cultural del Vero. Cómo llegar: Carretera HU-342, junto a la estructura del puente de piedra. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22099','mirador','Mirador de la duna de Esplús','7.1/10 Vista de los canales de riego y extensas llanuras agrícolas de la Litera baja. Cómo llegar: Depósitos de agua en la cota más alta del término municipal. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22102','mirador','Mirador de la Sierra de la Carrodilla','7.8/10 Espectacular nudo de confluencia de los ríos Cinca y Ésera a los pies de las laderas del somontano. Cómo llegar: Crestas calizas superiores accesibles por pistas de senderismo. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22103','mirador','Mirador del Santuario de la Carrodilla','8.2/10 Balcón colgado a gran altura con amplias panorámicas sobre el valle del Cinca y huertas de Barbastro. Cómo llegar: Complejo religioso de la Carrodilla, carretera de montaña asfaltada. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22105','mirador','Mirador del Embalse de Santa Ana','8.8/10 Espectaculares cañones calizos inundados por aguas de color turquesa intenso en la frontera con Lleida. Cómo llegar: Pistas de acceso al embalse desde el núcleo urbano.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22106','mirador','Mirador de la Foz de Fago','8.9/10 Impresionante garganta calcárea angosta con paredes verticales donde anidan buitres leonados. Cómo llegar: Carretera local entre Ansó y Fago (HU-2001), balconada metálica de carretera. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22107','mirador','Miradores del Cañón de Añisclo','9.9/10 Salvaje y colosal brecha calcárea profunda tapizada de densos bosques caducifolios en Ordesa y Monte Perdido. Cómo llegar: Carretera cortada del cañón o senderos superiores de los miradores de Nerín. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22109','mirador','Mirador de la Corona de Fiscal','8.8/10 Perspectiva limpia del curso medio del río Ara, el valle abierto y las cumbres del Pirineo central. Cómo llegar: Sendero forestal ascendente que parte del casco urbano hacia la cresta de la montaña. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22110','mirador','Mirador de la Olla de Fonz','8.3/10 Amplia panorámica de la comarca del Cinca Medio, campos de almendros y las estribaciones de la Sierra de la Carrodilla. Cómo llegar: Camino rural señalizado desde la ermita de San José en la parte alta. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22111','mirador','Collado de Foradada','9.1/10 Impresionante paso de montaña con vistas al imponente macizo de Cotiella y la profunda cuenca del río Ésera. Cómo llegar: Apartadero de la carretera nacional N-260 en el punto más alto del puerto. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22112','mirador','Mirador del Castillo de Fraga','7.8/10 Vista aérea del casco histórico, la fértil vega del río Cinca y el contraste árido de los Monegros sur. Cómo llegar: Explanada exterior de la iglesia de San Pedro, antiguo emplazamiento defensivo del castillo. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22113','mirador','Mirador de Samitier','9.0/10 Alucinante panorámica del estrecho de Entremón, el embalse de Mediano, el embalse de El Grado y el pirineo. Cómo llegar: Junto a la ermita y restos del castillo de Samitier, acceso a pie por sendero. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22114','mirador','Mirador de las Ermitas / Cruz de Puyadase','9.7/10 Soberbia postal alpina del Valle de Chistau, rodeado por picos de tres mil metros y prados ganaderos tradicionales. Cómo llegar: Pista de montaña que asciende desde el pueblo hacia el puerto de Sahún. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22116','mirador','Alto de la duna fòssil de Grañén','6.9/10 Entorno estepario plano característico del llano monegrino con campos de secano y horizontes completamente despejados. Cómo llegar: Hito topográfico situado junto a los caminos de concentración parcelaria al norte del término. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22117','mirador','Mirador de la Basílica de la Peña','8.9/10 Espectacular nido de águila sobre la confluencia de los ríos Ésera e Isábena y los tejados de la villa. Cómo llegar: Galerías y terrazas exteriores talladas en la roca del santuario de la Virgen de la Peña. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22119','mirador','Mirador del Saso de Gurrea','7.1/10 Llanura fluvial del río Gállego, canales de riego y extensas plantaciones agrícolas lindando con la provincia de Zaragoza. Cómo llegar: Elevación natural o saso accesible por pistas agrícolas desde la carretera local HU-V-1111. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22122','mirador','Mirador del Muro / Balcón del Pirineo','9.6/10 Vertiginosa plataforma colgada en el vacío sobre el embalse de Búbal, con el valle de Tena al descubierto. Cómo llegar: Estructura metálica volada situada al final del casco urbano del municipio. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22908','mirador','Mirador de Hoz de Barbastro','8.0/10 Atalaya sobre el Somontano, viñedos de la denominación de origen y la cuenca baja del río Vero. Cómo llegar: Plaza mirador en la zona más elevada de la localidad de Hoz de Barbastro. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22124','mirador','Mirador del Cerbuna','7.2/10 Atractiva visión del relieve erosionado de la comarca de Los Monegros con sus características escorrentías e hitos calizos. Cómo llegar: Vértice geodésico sobre el cerro testigo que domina las llanuras agrícolas del entorno. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22125','mirador','Mirador de la Ermita de Loreto','8.4/10 Amplio campo visual de la Hoya de Huesca, la silueta urbana de la capital y el Salto de Roldán. Cómo llegar: Explanada de acceso al santuario de Loreto, a pocos kilómetros del centro urbano. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22129','mirador','Mirador del Museo Diocesano de Roda de Isábena','9.2/10 Excepcional atalaya medieval sobre el valle del río Isábena, la sierra de Sis y la imponente Sierra de Chía. Cómo llegar: Muralla perimetral sur de la catedral y claustro de Roda de Isábena. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22130','mirador','Mirador de la Peña de Oroel','94/10 Impresionante balcón natural sobre la canal de Berdún, la ciudad de Jaca y toda la muralla de cumbres pirenaicas. Cómo llegar: Final de la ruta a pie desde el parador, en la cruz de la cima de Oroel. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22131','mirador','Mirador de San Juan de Jasa','8.7/10 Entorno de praderas alpinas, arquitectura tradicional de piedra del Valle de Aragüés y el cauce del río Osia. Cómo llegar: Junto a la carretera local de acceso a la entrada de la población. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22133','mirador','Mirador de San Vicente de Labuerda','8.6/10 Vista monumental del conjunto románico, la mole de la Peña Montañesa y el cauce ancho del Cinca. Cómo llegar: Entorno de la iglesia fortificada, situada en el núcleo alto de San Vicente. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22135','mirador','Pozo Nuevo de Laluenga (Entorno)','70/10 Entorno plano que permite avistar la llanura somontana y las depresiones kársticas donde se ocultan los pozos-fuente. Cómo llegar: Estructura exterior y accesos del centro de interpretación de los Pozos-Fuente. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22136','mirador','Alto del Puyal','7.1/10 Vista panorámica del trazado de los canales de riego monegrinos y parcelas agrícolas infinitas de maíz y alfalfa. Cómo llegar: Elevación natural al oeste del casco urbano por pistas agrícolas aptas para vehículos. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22137','mirador','Mirador de la Ermita de San Sebastián','7.6/10 Estampa árida y singular de la Sierra de Alcubierre, barrancos arcillosos y las llanadas de los Monegros. Cómo llegar: Cerro de la ermita, accesible por rampa acondicionada desde el núcleo municipal. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22139','mirador','Muela de Laperdiguera','6.9/10 Suave elevación caliza con vistas a olivares, campos cerealistas y el perfil lejano del Pirineo central. Cómo llegar: Punto más alto del término, accesible mediante caminos de tierra consolidados. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22141','mirador','Mirador de la Ermita de San Román','7.4/10 Vista privilegiada de los campos de viñedos del Somontano y el curso del río Alcanadre en el llano. Cómo llegar: Cerro donde se ubica la ermita, saliendo de Ponzano por pista agrícola. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22142','mirador','Mirador del Castillo de Lascuarre','8.1/10 Excelentes vistas del relieve prepirenaico de la Baja Ribagorza y el barranco de la Pillera. Cómo llegar: Crestón rocoso de los restos de la torre fortificada del municipio. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22143','mirador','Mirador del Coll de Espina','9.0/10 Puerto de montaña de alta cota con imponentes vistas del Turbón, macizo de Maladeta y bosques negros pináceos. Cómo llegar: Kilómetro 342 de la carretera nacional N-260, zona de aparcamiento habilitada. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22144','mirador','Mirador del Cazcarra / Balcón del Cinca','9.1/10 Impresionante tajo vertical sobre el río Cinca, con la descomunal pared de la Peña Montañesa justo enfrente. Cómo llegar: Borde del acantilado urbano, junto al paseo de la localidad. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22149','mirador','Mirador de la Reina (Castillo de Loarre)','9.8/10 Legendaria e imbatible vista de toda la Hoya de Huesca desde las ventanas del castillo románico mejor conservado del mundo. Cómo llegar: Interior de la fortaleza de Loarre, ventanas ajimezadas de la sala noble. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22150','mirador','Mirador del Salto de Roldán','9.5/10 Colosales monolitos de conglomerado (Peña San Miguel y Amán) que flanquean el paso vertical del río Flumen. Cómo llegar: Pista asfaltada desde Sabayés hasta el aparcamiento de la base de la peña. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22151','mirador','Mirador de la Ermita de Nuestra Señora de Gaberdola','7.6/10 Vista de las llanuras agrícolas occidentales de la Hoya y las estribaciones de la Sierra de Loarre. Cómo llegar: Cerro de la ermita, acceso por pista forestal practicable al norte del pueblo. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22905','mirador','Mirador del Castillo de Artasona','7.7/10 Perspectiva de campos de cereal, carrascales y el entorno del embalse de Sotonera al sur. Cómo llegar: Elevación fortificada en el núcleo deshabitado de Artasona. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22155','mirador','Mirador de San Bartolomé en Cajigar','8.3/10 Paisaje quebrado de margas y robledales de la Alta Ribagorza lindando con el Prepirineo leridano. Cómo llegar: Entorno de la ermita en la cota más alta del núcleo de Cajigar. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22156','mirador','Mirador de la Torre de los Lascasas','7.3/10 Dominio visual del llano de la Hoya de Huesca y las maniobras aéreas del cercano aeródromo. Cómo llegar: Restos del torreón defensivo medieval en el núcleo de Lascasas. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22157','mirador','Mirador del Coll de Llauset','9.4/10 Paisaje kárstico de alta montaña rigorously alpino, lagos glaciares y el coloso Aneto en el horizonte cercano. Cómo llegar: Carretera de acceso al embalse de Llauset, antes de la entrada al túnel superior. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22158','mirador','Mirador del Castillo Templario de Monzón','8.7/10 Impresionante vista de 360 grados sobre el cauce del Cinca, el cerro de Santa Quiteria y las llanuras ribereñas. Cómo llegar: Baluarte de la artillería en el recinto superior de la fortaleza templaria. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22160','mirador','Mirador de la Ermita de los Dolores','8.2/10 Vista de los salinares tradicionales de Naval, olivares del Somontano y el sinclinar del río Llastre. Cómo llegar: Explanada de la ermita, situada en la colina que corona el pueblo alfarero. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22162','mirador','Ribera del Guatizalema','7.1/10 Entorno rural caracterizado por meandros suaves, sotos de ribera y campos de labranza tradicionales. Cómo llegar: Punto elevado junto a la carretera HU-V-8111 a la entrada de la población. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22163','mirador','Mirador del Salto de Roldán (Lado Norte) / Gorgas de San Julián','9.3/10 Impresionante vista hacia el cañón del Flumen, murallones de Guara y el espectacular desfiladero kárstico calcáreo. Cómo llegar: Pista forestal que sube desde la urbanización Guara hacia la base de los mallos. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22164','mirador','Mirador del Congosto de Olvena','8.9/10 Impresionante caída vertical sobre el desfiladero que abre el río Ésera al tajar las sierras calizas exteriores. Cómo llegar: Balcón acondicionado con barandillas en el mismo casco urbano de Olvena. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22165','mirador','Mirador de la Ermita de la Virgen del Pilar','7.2/10 Vista panorámica de la cuenca del río Alcanadre en su tramo bajo y planicies agrícolas esteparias. Cómo llegar: Explanada de la ermita construida sobre la colina que vigila el pueblo. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22167','mirador','Mirador de las Ripas de Osso','7.0/10 Interesantes formaciones erosivas arcillosas sobre la llanura aluvial del río Cinca. Cómo llegar: Borde del talud natural accesible por camino de herradura desde el casco urbano. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22168','mirador','Mirador del Santuario de Bruis','8.4/10 Vista del valle de La Fueva, los macizos prepirenaicos orientales y bosques submediterráneos de robles. Cómo llegar: Entorno ajardinado y arbolado del Santuario de la Virgen de Bruis. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22170','mirador','Mirador de Santa Elena / Balcón de Panticosa','9.7/10 Excepcional panorámica del circo de alta montaña, picos de Argualas, embalse de Lanuza y el cañón del Caldarés. Cómo llegar: Sendero de los Miradores o entorno del telecabina alpino de Panticosa. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22172','mirador','Mirador de la Serreta de Peñalba','7.4/10 Paisaje desértico radical del corazón de Monegros, sabinas centenarias aisladas y relieves tabulares rojizos. Cómo llegar: Pista forestal hacia la Ermita de Santa Quiteria en lo alto de la sierra. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22173','mirador','Mirador de los Mallos de Riglos / Mirador de los Buitres','9.9/10 Alucinante vista de los colosales murallones de conglomerado rojo de 300 metros de verticalidad pura e infinidad de rapaces. Cómo llegar: Pista forestal transitable desde Linás de Marcuello hasta la pasarela colgada del mirador. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22174','mirador','Mirador del Saso de Peralta','7.5/10 Valle del río Alcanadre en su curso medio, campos de cultivo mediterráneo y escarpes arcillosos erosionados. Cómo llegar: Elevación de la meseta o saso que corona las bodegas tradicionales del término. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22175','mirador','Mirador de la Peña de la Mora (Peralta de la Sal)','8.5/10 Salinas de interior, desfiladeros calcáreos y olivares milenarios de la comarca de La Litera. Cómo llegar: Sendero que sube al castillo rocoso y ermita que dominan Peralta de la Sal. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22176','mirador','Mirador de la Ermita de San Joaquín','7.2/10 Vista típica del piedemonte pirenaico con almendros, viñedos e hitos de arenisca esculpida. Cómo llegar: Cerro de San Joaquín, acceso peatonal o en vehículo por rampa asfaltada. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22177','mirador','Mirador del Castillo de El Mon de Perarrúa','8.3/10 Atalaya colgada sobre el curso del río Ésera, las colinas de la Ribagorza media y el macizo del Turbón. Cómo llegar: Restos de la torre e iglesia fortificada románica sobre el espigón rocoso. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22178','mirador','Mirador de la Torre de Pertusa','7.4/10 Vista del encajonamiento del río Alcanadre, el puente romano subterráneo y campos cerealistas circundantes. Cómo llegar: Base de la singular torre exenta de la iglesia barroca del municipio. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22181','mirador','Mirador de la Corona de Piracés / Árbol de la Vida','8.7/10 Impactante paisaje de formaciones de arenisca labradas por el viento ("tozales") emergiendo de llanuras esteparias. Cómo llegar: Plataforma rocosa accesible por escaleras metálicas en el entorno de la escultura "Árbol de la Vida". 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22182','mirador','Mirador de la Basa de la Mora / Ibón de Plan','9.5/10 Majestuoso lago glaciar cercado por descomunales canchales de piedra caliza y densos bosques de pino negro. Cómo llegar: Pista forestal de Saravillo a Lavasar, y posterior sendero a pie de 20 minutos. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22184','mirador','Mirador del Mondón','7.0/10 Vista sobre las llanuras fluviales del río Flumen y los sotos naturales de ribera circundantes. Cómo llegar: Alto natural adyacente a los caminos de paso agrícola al norte de la población. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22186','mirador','Mirador del Azud de Pozán (Abajo)','7.8/10 Vista del salto de agua histórico sobre el río Vero, rodeado de huertas viejas y densa vegetación riparia. Cómo llegar: Senderos acondicionados desde el aparcamiento de la carretera HU-352. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22187','mirador','Mirador del Yacimiento de Labitolosa / Ermita de San Román','9.0/10 Increíble estampa del estrecho de Olvena, el embalse de Barasona y la Sierra del Castell de Laguarres. Cómo llegar: Cerro de San Román de Castro, desvío señalizado desde la carretera HU-V-6441. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22188','mirador','Mirador de las Pasarelas de Montfalcó','9.5/10 Abrupto paisaje de paredes calcáreas verticales sobre el desfiladero de Mont-rebei y el río Noguera Ribagorzana. Cómo llegar: Albergue de Montfalcó, inicio del sendero que vuela sobre los acantilados mediante escaleras de madera. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22902','mirador','Mirador de la Canal de Berdún','80/10 Cruce de caminos histórico del Camino de Santiago, vistas del cauce ancho del Aragón y campos agrícolas. Cómo llegar: Colina del mirador situada en las cercanías del cruce de carreteras nacionales N-240 y A-132. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22189','mirador','Mirador de Bestué / Plana de San Miguel','9.8/10 Soberbia e infinita panorámica de las gargantas de Escuaín, el Castillo de Mayor y el macizo de Monte Perdido. Cómo llegar: Pista y sendero que sube desde el recóndito núcleo de Bestué hacia los pastos altos. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22190','mirador','Mirador de la Peña Montañesa / Ermita de Santa Engracia','9.6/10 Impresionante primer plano del colosal murallón caliza de la Peña Montañesa y los valles del Bajo Sobrarbe. Cómo llegar: Sendero señalizado desde el Monasterio de San Victorián hacia las faldas de la peña. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22195','mirador','Mirador del Castillo de Montearagón','8.8/10 Vista panorámica de la Hoya de Huesca y el Pirineo desde el imponente castillo-monasterio real. Cómo llegar: Explanada perimetral exterior y torreones accesibles de la fortaleza de Montearagón. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22200','mirador','Mirador del Puerto de Sahún','9.6/10 Paso de montaña a gran altitud que conecta el Valle de Benasque con Chistau, rodeado de cumbres nevadas. Cómo llegar: Punto más alto de la pista forestal de montaña que comunica Sahún con Plan. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22201','mirador','Mirador de la Ermita de la Candelera','8.1/10 Impresionante mar de viñedos del Somontano y llanuras agrícolas que se extienden hacia el sur. Cómo llegar: Cerro escarpado de la ermita, acceso en vehículo o vía ferrata por la roca. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22202','mirador','Mirador de los Viñedos Enate','7.6/10 Bellas hileras de vides perfectamente alineadas integradas en el singular paisaje ondulado somontano. Cómo llegar: Caminos rurales acondicionados lindando con las grandes bodegas de la zona. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22203','mirador','Atrio de la Iglesia de Santa Ana','7.1/10 Suave perspectiva de la llanura cerealista del río Guatizalema y antiguos pozos de hielo de la comarca. Cómo llegar: Pequeña elevación urbana de la iglesia parroquial. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22204','mirador','Mirador de San Mamés / Mirador del Salto de Sallent','9.9/10 Incomparable postal del majestuoso pico Formigal, la Peña Foratata, el embalse de Lanuza y cascadas glaciares de ensueño. Cómo llegar: Sendero local empedrado que arranca del barrio alto del pueblo de Sallent. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22205','mirador','Mirador del Castillo / Roca Foradada','8.0/10 Formaciones caprichosas de arenisca, vistas del casco urbano empinado y el llano de la comarca de la Litera. Cómo llegar: Pasarelas instaladas en el parque municipal de las rocas y restos de la muralla islámica. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22207','mirador','Mirador de la Cruz de San Juan','9.5/10 Vista aérea del indómito río Cinqueta, la arquitectura pirenaica compacta y las escarpadas laderas de Chistau. Cómo llegar: Sendero corto ascendente desde el museo etnológico o escuela de la localidad. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22903','mirador','Mirador de Estiche de Cinca','7.3/10 Vista de los meandros del río Cinca, el denso soto de ribera y los campos regados por el canal. Cómo llegar: Talud natural situado en las cercanías del núcleo pedáneo de Estiche. sigue hsta la z 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22208','mirador','Mirador del Aeródromo de Santa Cilia','8.4/10 Espectacular panorámica de la Canal de Berdún con aeronaves civiles y planeadores sobrevolando el fondo de San Juan de la Peña. Cómo llegar: Terraza del centro de interpretación del aeródromo, accesible por la carretera N-240. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22209','mirador','Mirador de San Juan de la Peña (Balcón del Pirineo)','9.6/10 Impresionante balcón colgado sobre el abismo con vistas directas a toda la cadena de cumbres del Pirineo Aragonés central. Cómo llegar: Pradera de San Indalecio, junto al Monasterio Nuevo de San Juan de la Peña. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22906','mirador','Mirador de los Cañones del Vero (Huerta de Vero)','7.8/10 Transición limpia entre los últimos estrechos calcáreos del río Vero y las primeras llanuras olivareras del Somontano. Cómo llegar: Senda señalizada que parte desde la Ermita de Nuestra Señora de Dulcis. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22212','mirador','Mirador de la Peña de San Quílez','8.1/10 Vista vertical sobre el cauce del río Ésera, el estrecho de Olvena al fondo y las escarpadas sierras interiores. Cómo llegar: Hito cimero junto a las ruinas de la ermita, accesible por sendero desde el pueblo. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22213','mirador','Mirador de la Laguna de Sariñena','8.7/10 Observatorio privilegiado del mayor humedal estepario de Monegros, con avistamiento masivo de aves acuáticas y carrizales infinitos. Cómo llegar: Centro de Interpretación de la Laguna, en la carretera de acceso norte. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22214','mirador','Mirador del Santuario de Torreciudad','8.5/10 Amplia visual del azul intenso del embalse de El Grado encajonado entre desfiladeros calizos y el Pirineo al fondo. Cómo llegar: Explanada exterior y pasarelas colgadas del complejo del Santuario de Torreciudad. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22215','mirador','Mirador del Congosto de Ventamillo','8.9/10 Impresionante tajo vertical calcáreo excavado por el río Ésera, antesala salvaje del Valle de Benasque. Cómo llegar: Pequeño apartadero de la carretera N-260 en la zona alta del estrecho rocoso. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22220','mirador','Mirador de la Ermita de la Jarea','7.2/10 Atalaya sobre el llano de la Hoya de Huesca y las formaciones de arenisca erosionadas de la comarca. Cómo llegar: Recinto vallado de la ermita en el punto geográfico más alto del casco urbano. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22199','mirador','Mirador de la Corona de Santa Lucía','8.8/10 Vista panorámica del Valle del Aragón, la llanura prepirenaica y la silueta del macizo de Oroel. Cómo llegar: Camino forestal acondicionado que sube desde el barrio de Santiago. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22222','mirador','Mirador del Castillo de Sietamo','7.4/10 Elevación sobre el valle del río Guatizalema y campos cerealistas salpicados de encinares relictos. Cómo llegar: Muralla exterior del castillo en la zona alta de la villa. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22223','mirador','Mirador del Congosto de Sopeira (Pont de Suert)','91/10 Paredes verticales colosales que encajonan el río Noguera Ribagorzana junto al histórico Monasterio de Alaón. Cómo llegar: Pasarela peatonal y sendero del desfiladero accesibles desde la central hidroeléctrica. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22225','mirador','Mirador del Castillo de Tamarite','7.6/10 Vista de la comarca de La Litera, olivares tradicionales y las llanuras que anuncian el entorno del Segrià. Cómo llegar: Corona del cerro de San Miguel, antiguo emplazamiento de la fortaleza medieval. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22229','mirador','Mirador del Congosto de Cajigar','8.3/10 Estrechos pasadizos de roca caliza esculpidos por el agua, con vegetación de ribera agarrada a las paredes. Cómo llegar: Pista forestal transitable que comunica con el núcleo deshabitado de Fals. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22230','mirador','Mirador de Calcilarruego','9.9/10 Vista cenital salvaje e insuperable del Valle de Ordesa, las Paredes de Fraucata y el Circo de Cotatuero. Cómo llegar: Final de la durísima Senda de los Cazadores en el sector Ordesa. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22232','mirador','Mirador de la Ermita de San Sebastián','7.1/10 Perspectiva árida del piedemonte monegrino y extensas llanuras esteparias rotas por pequeños barrancos. Cómo llegar: Cerro exento y acondicionado junto al depósito regulador de agua municipal. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22233','mirador','Mirador de Vilas del Turbón','8.0/10 Primer plano de la vertiente sur del Macizo del Turbón con sus tarteras y ambiente de pre-alta montaña. Cómo llegar: Entorno rural alto de la pedanía de Vilas, cerca del balneario histórico. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22234','mirador','Mirador de la Ermita de San Salvador','7.3/10 Vista de la desembocadura del Cinca en el Ebro (Aiguamúrcia), sotos fluviales densos y huertas bajoragonesas. Cómo llegar: Explanada de la ermita situada sobre el escarpe que domina el río. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22235','mirador','Mirador de la Ermita de San Bartolomé','7.5/10 Panorámica del cauce medio del río Alcanadre con sus terrazas fluviales y campos de cultivo tradicionales. Cómo llegar: Cerro de San Bartolomé, accesible por pista de tierra batida al sur del núcleo. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22236','mirador','Mirador del llano de Torres','6.9/10 Vista horizontal de los llanos cerealistas de la comarca de Los Monegros y su red de canales agrícolas. Cómo llegar: Punto alto junto al antiguo silo de grano de la población. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22239','mirador','Mirador de las Ripas de Tramaced','8.2/10 Espectacular paisaje de formaciones de arenisca talladas por el viento formando relieves de aspecto lunar o desértico. Cómo llegar: Plataforma con paneles interpretativos junto a la Ermita de Nuestra Señora del Puy. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22242','mirador','Mirador del Monte de San Miguel','7.0/10 Estepa pura monegrina en un horizonte plano de 360 grados roto únicamente por balsas de agua ganaderas. Cómo llegar: Vértice geodésico de San Miguel, accesible por pistas agrarias desde la N-II. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22243','mirador','Mirador del Valle de Bardaxín','8.5/10 Espectacular estampa de la muralla de piedra del Turbón dominando un prado alpino verde e idílico. Cómo llegar: Borde del sendero de pequeño recorrido que une Llert con Esterún. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22901','mirador','Mirador de la Boca del Infierno','9.8/10 Vertiginosa e imponente garganta caliza boscosa esculpida por el río Aragón Subordán en pleno Pirineo Occidental. Cómo llegar: Apartaderos de madera integrados en el trazado de la carretera forestal del valle de Oza. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22244','mirador','Mirador del Coll de Fadas','8.4/10 Paso de montaña con amplias vistas de transición entre las cuencas del Ésera y del Isábena. Cómo llegar: Alto del puerto de la carretera N-260, zona de estacionamiento habilitada. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22245','mirador','Mirador de la Ermita de San Valero','7.4/10 Vista de la vega baja del Cinca, azudes tradicionales de riego e hitos arqueológicos del Bajo Cinca. Cómo llegar: Entorno arqueológico y natural de la ermita, sobre un gran acantilado arcilloso. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22909','mirador','Mirador de los Canales de Vencillón','6.8/10 Paisaje llano de colonización agrícola, acequias e hileras infinitas de frutales de regadío. Cómo llegar: Zona elevada de los depósitos de riego situados al este del casco urbano. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22247','mirador','Mirador de las Pasarelas de Montfalcó','9.7/10 Perspectiva de infarto sobre las escaleras colgadas de la roca viva y las aguas turquesas del Congosto de Mont-rebei. Cómo llegar: Sendero de Montfalcó a Montrebei, tramo aéreo anclado a la pared del desfiladero. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22249','mirador','Mirador de Els Plans','8.7/10 Vista abierta del curso del río Ésera, los llanos del fondo del valle y las cumbres de la Sierra de Chía. Cómo llegar: Pista agrícola de montaña que sube hacia las praderas altas desde el pueblo. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22251','mirador','Mirador del Real Monasterio de Sigena','7.8/10 Panorámica del imponente cenobio románico integrado en la cuenca del río Alcanadre y los llanos monegrinos. Cómo llegar: Pequeña loma acondicionada al norte del complejo monástico. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22252','mirador','Mirador de las Ermitas de San Cornelio','9.0/10 Impresionante rosario de capillas incrustadas bajo cuevas de roca caliza con cascadas de agua en época de deshielo. Cómo llegar: Tramo superior de la Ruta de las Ermitas, colgado sobre el valle de Basa. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22253','mirador','Mirador del Puerto de Cotefablo','8.9/10 Frontera natural divisoria entre el Valle de Tena y el Valle del Ara con vistas alpinas agrestes de altura. Cómo llegar: Boca oeste del túnel de Cotefablo, carretera HU-330. 📍 Provincia: Huesca.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90061','mirador','Mirador del Forat d''Abella','8.8/10 Impresionante perspectiva de un cañón calizo colosal con el pueblo colgado de las rocas y la llanura de la Conca Dellà al fondo. Cómo llegar: Paso natural excavado en la roca calcárea en el acceso principal al núcleo urbano alto. 📍 Provincia: Huesca/Lérida (Muga) ->.','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27015','mirador','Mirador del Col d''Ares (Montsec d''Ares)','9.5/10 Destacado punto de observación astronómica Starlight con visuales infinitas de la Vall d''Àger y el prepirineo leridano. Cómo llegar: Carretera de subida al sondeo astronómico desde el puerto de montaña de Àger. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90611','mirador','Mirador del Pilar d''Almenara','7.1/10 Atalaya histórica con llanuras infinitas de campos de secano de Urgell y la silueta lejana de los Pirineos. Cómo llegar: Torre redonda medieval situada en una colina de la pedanía de Almenara Alta. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25038','mirador','Mirador de San Juan de Carratalá','8.6/10 Impresionante mar de color rosa durante la floración de los melocotoneros que tapiza todo el valle bajo del río Segre. Cómo llegar: Explanada de la ermita románica levantada sobre un espigón fluvial al sur del núcleo. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90612','mirador','Mirador de la Ermita de las Peces','8.9/10 Vista aérea espléndida de toda la plana de la Seu d''Urgell, la confluencia del río Segre y la imponente cara norte del Cadí. Cómo llegar: Recinto exterior vallado de la ermita colgada en los contrafuertes meridionales de la sierra. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90613','mirador','Mirador del Camí del Segre','6.9/10 Panorámica fluvial de la vega del Segre con cultivos frutales intensivos y la silueta urbana de la ciudad de Lérida. Cómo llegar: Margen elevado del camino rural consolidado junto al canal de Urgell. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90614','mirador','Mirador de la Texture del Noguera Ribagorzana','7.2/10 Observatorio del tramo bajo del río justo antes de su desembocadura, rodeado de huertas históricas andalusíes. Cómo llegar: Elevación natural adyacente a los restos arqueológicos de la villa romana de Romeral. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90615','mirador','Tossal de les Forques de Alcanó','7.0/10 Paisaje austero de olivares y almendros característico de la plataforma caliza de la comarca del Segrià meridional. Cómo llegar: Hito geodésico y mirador rústico accesible por pistas agrarias desde la carretera L-700. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90616','mirador','Mirador del Tossal de Pinyana','7.3/10 Visual extensa de la red de canales de riego históricos y extensas parcelas agrícolas frutales del llano leridano. Cómo llegar: Corona del pequeño montículo situado junto a la balsa de almacenamiento del canal. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90617','mirador','Mirador del Tossal dels Morts','7.8/10 Gran valor histórico con trincheras recuperadas de la Guerra Civil y amplias panorámicas sobre la comarca del Segrià. Cómo llegar: Espacio de memoria histórica acondicionado con pasarelas en la cumbre del cerro del pueblo. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90618','mirador','Mirador de la Timoneda de Alfés','7.9/10 Paisaje estepario único en Cataluña con flora xerófila e importantes colonias de aves de secano. Cómo llegar: Área recreativa perimetral del antiguo aeródromo republicano de la Guerra Civil. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25015','mirador','Mirador del Castillo de Algerri','8.1/10 Magnífica transición visual entre el llano regado por el Segre y los primeros pliegues secos de la Sierra de la Noguera. Cómo llegar: Ruinas de la fortaleza andalusí situadas sobre el espolón que domina el casco urbano. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25016','mirador','Mirador del Sagrado Corazón','7.4/10 Vista de pájaro del entramado urbano, el aeropuerto de Lleida-Alguaire y las terrazas aluviales de la cuenca. Cómo llegar: Monumento religioso situado en la cima de los acantilados de yeso locales. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25017','mirador','Mirador de la Pica d''Estats (Vall Ferrera)','9.8/10 Techo de Cataluña con panorámicas alpinas completas de circos glaciares, lagos de alta montaña y picos franceses. Cómo llegar: Cumbre de la Pica d''Estats a 3.143 metros, alcanzable por sendero de alta montaña desde el refugio de Vallferrera. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25019','mirador','Mirador del Parc del Vilot','7.2/10 Panorámica urbana ordenada de la villa ilustrada y los amplios campos de cultivo que lindan con el territorio aragonés. Cómo llegar: Cima del cerro arqueológico del Vilot, reconvertido en parque público. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25020','mirador','Mirador de l''Aiguabarreig (Ermita de San Juan)','8.3/10 Impresionante vista del gran meandro del río Ebro y su confluencia con el Segre y el Cinca entre escarpes calizos. Cómo llegar: Entorno del vértice geodésico y ermita, al oeste del término municipal. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25021','mirador','Mirador del Tossal de la Corona','7.4/10 Amplia perspectiva visual del canal de Pinyana y las extensas llanuras cerealistas del Segrià septentrional. Cómo llegar: Punto más alto del casco urbano, junto al depósito de agua. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25022','mirador','Mirador del Congosto de Mu','9.1/10 Vertiginosa e imponente panorámica de las paredes verticales calizas del desfiladero excavado por el río Segre. Cómo llegar: Pasarelas colgadas y mirador superior de la ruta de senderismo del congosto. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25023','mirador','Mirador del Tossal de Sant Bartomeu','7.0/10 Otero suave con vistas completas de la Plana de Lleida y la silueta del Pirineo en días despejados. Cómo llegar: Urbanización Buenos Aires, en la zona más elevada de la muela caliza. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25024','mirador','Mirador del Puerto de la Bonaigua','9.7/10 Soberbia panorámica alpina de alta montaña que divide el Valle de Arán y el Pallars Sobirà a 2.072 metros. Cómo llegar: Puerto de montaña de la carretera C-28, junto al aparcamiento del remonte de esquí. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25027','mirador','Mirador de la Plana d''Urgell','6.7/10 Vista relajante y llanura agrícola total dominada por olivares y campos de cereal integrados en el Canal d''Urgell. Cómo llegar: Camino rural acondicionado junto a la Ermita de la Santa Creu. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25029','mirador','Mirador de los Vilars d''Arbeca','7.9/10 Vista singular que fusiona el llano garriguense con las murallas de la espectacular fortaleza ibérica de Els Vilars. Cómo llegar: Pasarela del centro de interpretación del yacimiento arqueológico. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25031','mirador','Mirador de las Minas de Liat (Bassa d''Arres)','9.3/10 Entorno minero de alta montaña colgado sobre el valle del río Garona con los macizos de la Maladeta enfrente. Cómo llegar: Pista de montaña que sube desde Arres de Sus hacia el lago y las minas. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25032','mirador','Mirador del Castillo de Arsèguel','8.9/10 Estampa pirenaica pura de un pueblo de piedra integrado bajo el impresionante paredón norte del Parque Natural del Cadí-Moixeró. Cómo llegar: Acceso peatonal adoquinado en la parte alta del promontorio rocoso del pueblo. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25033','mirador','Mirador del Tossal de Montserrat','6.9/10 Vista horizontal de los campos del Segrià y las pequeñas balsas de agua esteparias de la comarca. Cómo llegar: Elevación natural habilitada con paneles junto a las granjas del norte del núcleo. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25034','mirador','Mirador del Castillo de la Múnia','8.4/10 Extenso dominio geográfico sobre el curso medio del río Segre, la sierra del Montsec y la Foia de Artesa. Cómo llegar: Ruinas fortificadas en la cima de la colina de la pedanía de La Múnia. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25036','mirador','Mirador del Valle del Set','7.1/10 Paisaje modelado por bancales de piedra seca, olivos centenarios y el cauce estacional del río Set. Cómo llegar: Camino de las Garrigues, en el escarpe superior de la cuenca fluvial. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90619','mirador','Mirador del Congosto de Collegats','9.4/10 Muro de roca rojiza vertical esculpido por el río Noguera Pallaresa con formaciones como la Argenteria. Cómo llegar: Antiguo trazado de la carretera N-260, reconvertido en senda peatonal segura. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25040','mirador','Mirador del Santuario del Santo Cristo','8.2/10 Vista monumental del centro histórico de Balaguer, el río Segre y las fértiles huertas de la Plana d''Urgell. Cómo llegar: Explanada de la basílica elevada y murallas góticas adyacentes. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25041','mirador','Mirador de la Comanda Hospitalaria','6.6/10 Entorno rural llano caracterizado por frutales de regadío y la silueta del castillo templario local. Cómo llegar: Ventanales superiores transitables de la casa de la villa (antiguo castillo). 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25042','mirador','Mirador del Dolmen de Sols de Riu','8.6/10 Vista limpia y serena del cañón del río Rialb y los reflejos del gran embalse homónimo. Cómo llegar: Espacio arqueológico acondicionado sobre la muela rocosa que domina el pantano. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25044','mirador','Mirador del Pueblo Viejo de Tiurana','8.0/10 Vista nostálgica y profunda del valle inundado por el embalse de Rialb y las estribaciones del prepirineo. Cómo llegar: Borde del mirador de la carretera C-14, término limítrofe con vistas directas. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25045','mirador','Mirador del Bosque de Carlac','9.6/10 Bosque mágico de hayas milenarias tapizadas de musgo con vistas salvajes al abrupto desfiladero del Bajo Arán. Cómo llegar: Sendero circular de Carlac, en el claro superior del lomo de la montaña. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25046','mirador','Mirador del Molino de Aceite','6.8/10 Transición geográfica suave entre los campos de Urgell y los olivares de secano de las Garrigues. Cómo llegar: Terraza superior del Ayuntamiento y ecomuseo de la población. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90620','mirador','Mirador del llano de la Almendra','6.7/10 Cuadrícula perfecta de canales de riego, alfombras de alfalfa y campos de maíz de la plana leridana. Cómo llegar: Hito de la pista agraria que corre paralela a la vía del ferrocarril. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25047','mirador','Mirador del Tossal de les Tenalles','7.1/10 Vista despejada de las sierras de Bellcaire y las llanuras agrícolas que mueren en la vecina comarca de la Noguera. Cómo llegar: Cerro superior acondicionado junto al vértice geodésico local. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25049','mirador','Mirador de la Ermita de San José','7.8/10 Magnífico balcón natural con vistas de 360 grados sobre el llano de Urgell y la imponente cordillera pirenaica. Cómo llegar: Recinto exterior de la ermita que corona el cerro del pueblo. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25050','mirador','Mirador del Castillo de Bellpuig','7.3/10 Atalaya histórica que vigila el paso del río Corb y los llanos cerealistas de la comarca. Cómo llegar: Torre del homenaje restaurada y accesible del castillo de los barones de Bellpuig. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25051','mirador','Mirador de la Cueva de Anes','9.5/10 Brutal panorámica del gran anfiteatro natural del valle de la Cerdanya cerrado al sur por la Sierra del Cadí. Cómo llegar: Senda señalizada que sube desde el núcleo de Prullans hacia el sector de Anes. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25052','mirador','Mirador del Palau de Bellvís','6.9/10 Mar de cultivos de regadío salpicado por los característicos chopos e hileras de frutales del Pla d''Urgell. Cómo llegar: Terraza perimetral elevada de la Iglesia de la Mare de Déu de les Sogues. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
