INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25064','mirador','Mirador de la Mare de Déu de Ceuró','7.8/10 Paisaje forestal idílico del Solsonès con valles de pinos y pequeñas explotaciones agrícolas de montaña. Cómo llegar: Entorno natural de la iglesia románica de Ceuró, junto al acantilado sobre el río Ribera Salada. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25070','mirador','Mirador de la Panera (Tossal de les Santes)','7.2/10 Vista limpia de la comarca del Urgell y la cuenca del río Corb con sus hileras de chopos. Cómo llegar: Cerro de las Santes, equipado con un banco panorámico y panel explicativo. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
