INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25077','mirador','Mirador del Tossal de Remolins','9.1/10 Espectacular nido de águilas sobre la cola del embalse de Oliana, los acantilados de Valldan y el yacimiento paleolítico. Cómo llegar: Senda de montaña que parte de la carretera de San Lorenzo de Morunys. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
