INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25079','mirador','Mirador de la Ermita del Castillo (Santa María)','80/10 Espléndido balcón natural sobre la Plana de Urgell con un fondo dominado por los Pirineos nevados en invierno. Cómo llegar: Exterior de la iglesia románica de Santa María del Castell, en lo alto del pueblo. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
