INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25121','mirador','Mirador de Garona y Castillo de Pijoan','8.7/10 Vista encajonada del Bajo Arán con el curso del río Garona e hileras de densos bosques atlánticos. Cómo llegar: Ruinas de la torre del homenaje, accesibles por sendero urbano empinado. 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25122','mirador','Mirador del Campanario de Linyola','6.9/10 Vista cenital de la plana d''Urgell, la silueta de los silos agrícolas y los canales artificiales de riego. Cómo llegar: Plataforma superior del campanario de la iglesia de Santa María (acceso bajo petición local). 📍 Provincia: Lérida (Lleida).','inventario_miradores_pdf');
